    // A game asking to be opened again (PSP resolution change): the Intent that started it.
    static final String EXTRA_RELAUNCH_GAME = "com.example.minigba.RELAUNCH_GAME";

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        relaunchGameIfAsked(intent);
        relaunchX360IfAsked(intent);
        importPresetIfOpened(intent);
    }

    // A .mepreset opened from a messenger or file app: read it into the preset list and say
    // where to apply it (that happens in a game, where the result shows at once).
    private void importPresetIfOpened(Intent intent) {
        if (intent == null || !Intent.ACTION_VIEW.equals(intent.getAction()) || intent.getData() == null) {
            return;
        }
        final Uri uri = intent.getData();
        intent.setData(null);
        intent.setAction(null);
        try (java.io.InputStream in = getContentResolver().openInputStream(uri)) {
            if (in == null) throw new java.io.IOException("파일을 열 수 없어요");
            Presets.Preset preset = Presets.importZip(this, in);
            new AppDialog.Builder(this)
                    .setTitle("꾸미기 프리셋을 받았어요")
                    .setMessage("\"" + preset.name + "\"\n" + preset.summary() + "\n\n프리셋 목록에 넣었어요. 게임을 켠 뒤 메뉴 › 설정 › 꾸미기 프리셋에서 \"적용\"을 누르면 그 자리에서 바뀌어요.")
                    .setPositiveButton("확인", null)
                    .show();
        } catch (java.io.IOException | RuntimeException e) {
            showMessage("프리셋을 가져오지 못했어요: " + e.getMessage());
        }
    }

    // The game closes in its own process, which must be gone before the game opens again,
    // or the new game would start in the process that is about to end (its engine, still
    // saving the last state, cannot be set up twice in one process: Citra asserts).
    private void relaunchGameIfAsked(Intent intent) {
        final Intent game = intent == null ? null : intent.getParcelableExtra(EXTRA_RELAUNCH_GAME);
        if (game == null) {
            return;
        }
        intent.removeExtra(EXTRA_RELAUNCH_GAME);
        afterGameProcessEnds(() -> {
            game.setComponent(new android.content.ComponentName(this, GameActivity.class));
            startActivity(game);
        });
    }

    /** Runs the action once the game process is gone (or after 15 seconds), on the UI thread. */
    private void afterGameProcessEnds(final Runnable action) {
        final String gameProcess = getPackageName() + ":game";
        final android.app.ActivityManager manager = (android.app.ActivityManager) getSystemService(ACTIVITY_SERVICE);
        if (!gameProcessAlive(manager, gameProcess)) {
            action.run();
            return;
        }
        final Dialog waiting = progressCard(RoundIconView.EXIT, Color.rgb(107, 114, 128), "이전 게임을 닫는 중", "저장을 마치고 바로 켜요…");
        new Thread(() -> {
            for (int tries = 0; tries < 150 && gameProcessAlive(manager, gameProcess); tries++) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    return;
                }
            }
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) {
                    return;
                }
                waiting.dismiss();
                action.run();
            });
        }, "await-game-process").start();
    }

    private static boolean gameProcessAlive(android.app.ActivityManager manager, String gameProcess) {
        java.util.List<android.app.ActivityManager.RunningAppProcessInfo> processes = manager == null ? null : manager.getRunningAppProcesses();
        if (processes != null) {
            for (android.app.ActivityManager.RunningAppProcessInfo process : processes) {
                if (gameProcess.equals(process.processName)) {
                    return true;
                }
            }
        }
        return false;
    }

    @Override
    protected void onCreate(Bundle bundle) {
        super.onCreate(bundle);
        Theme.update(this);
        CrashReports.installJavaHandler(this);
        registerDownloadReceiver();
        new Thread(() -> AppUpdate.cleanOldApks(getApplicationContext(), settingsPrefs()), "apk-cleanup").start();
        cloudAutoBackup(false);
        autoLinkFolders();
        relaunchGameIfAsked(getIntent());
        importPresetIfOpened(getIntent());
        ensureDownloadFolder();
        moveMasterSystemRoms();
        new Thread(() -> copyXbiosExamples(getApplicationContext(), false), "xbios-examples").start();
        // Keep the open mode across rotation and other activity recreation.
        String restoredMode = bundle == null ? null : bundle.getString(STATE_MODE);
        this.pendingBiosSource = bundle == null ? null : bundle.getString(STATE_BIOS_SOURCE);
        this.pendingFolderMode = bundle == null ? null : bundle.getString(STATE_FOLDER_MODE);
        if (restoredMode != null) {
            showHome(restoredMode);
            return;
        }
        String savedMode = settingsPrefs().getString(PREF_MODE, null);
        if (savedMode != null && settingsPrefs().getBoolean(PREF_REMEMBER_MODE, false)) {
            showHome(savedMode);
        } else {
            showModePicker();
        }
        moveArcadeGamesToBetterCores();
    }

    private static long folderSize(File file) {
        if (file.isFile()) {
            return file.length();
        }
        long size = 0;
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                size += folderSize(child);
            }
        }
        return size;
    }

    private static void deleteRecursively(File file) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursively(child);
            }
        }
        if (file.exists() && !file.delete()) {
            file.deleteOnExit();
        }
    }

    @Override
    protected void onSaveInstanceState(Bundle bundle) {
        super.onSaveInstanceState(bundle);
        if (this.currentMode != null) {
            bundle.putString(STATE_MODE, this.currentMode);
        }
        if (this.pendingBiosSource != null) {
            bundle.putString(STATE_BIOS_SOURCE, this.pendingBiosSource);
        }
        if (this.pendingFolderMode != null) {
            bundle.putString(STATE_FOLDER_MODE, this.pendingFolderMode);
        }
    }

    @Override
    public void onBackPressed() {
        // Without "remember mode" the picker is the app's start screen, so back returns to it.
        if (this.currentMode != null && !settingsPrefs().getBoolean(PREF_REMEMBER_MODE, false)) {
            showModePicker();
            return;
        }
        super.onBackPressed();
    }

