    // Three tiles a row.
    private void addTileGrid(LinearLayout parent, List<Integer> indexes, java.util.Map<String, Integer> counts, String current,
                             java.util.function.Consumer<String> onPick, Runnable onChanged) {
        addTileGrid(parent, indexes, counts, current, onPick, onChanged, null);
    }

    // Cubes to a row: 3, or 5 in the landscape 모드 변경 sheet while it is open (0.0.410).
    private int tileColumns = 3;

    private void addTileGrid(LinearLayout parent, List<Integer> indexes, java.util.Map<String, Integer> counts, String current,
                             java.util.function.Consumer<String> onPick, Runnable onChanged, java.util.Map<String, Long> played) {
        List<String> favorites = favoriteModes();
        LinearLayout row = null;
        final int columns = Math.max(3, this.tileColumns);
        for (int k = 0; k < indexes.size(); k++) {
            if (k % columns == 0) {
                row = new LinearLayout(this);
                row.setOrientation(0);
                LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(-1, -2);
                rowParams.setMargins(0, k == 0 ? 0 : dp(10), 0, 0);
                parent.addView(row, rowParams);
            }
            int index = indexes.get(k);
            String mode = MODE_IDS[index];
            Integer count = counts.get(mode);
            Long last = played == null ? null : played.get(mode);
            View tile = createModeTile(index, count == null ? 0 : count, favorites.contains(mode), mode.equals(current), () -> onPick.accept(mode), onChanged,
                    last == null || last <= 0 ? null : playedAgo(last));
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, -1, 1.0f);
            params.setMargins(k % columns == 0 ? 0 : dp(10), 0, 0, 0);
            row.addView(tile, params);
        }
        if (row != null) {
            // The empty places get invisible tiles: a row of one or two is then measured like a
            // full one (with plain spacers its tiles came out 0 tall and could not be seen).
            for (int fill = indexes.size() % columns; fill != 0 && fill < columns; fill++) {
                SquareLayout empty = new SquareLayout(this);
                empty.setVisibility(View.INVISIBLE);
                LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, -1, 1.0f);
                params.setMargins(dp(10), 0, 0, 0);
                row.addView(empty, params);
            }
        }
    }

    // Every console's games, for search: {lower-case name, name, mode, path}. Built once a
    // browser is open, off the main thread (titles may read file headers).
    private List<String[]> gameIndex;

    private List<String[]> buildGameIndex() {
        List<String[]> list = new ArrayList<>();
        for (String mode : MODE_IDS) {
            File[] files = romDirFor(mode).listFiles(this::isRomFile);
            if (files == null) {
                continue;
            }
            for (File file : files) {
                if (isHiddenGame(file)) continue;  // 목록에서 숨기기 (0.0.390)
                String name;
                try {
                    name = displayGameNameFor(file);
                } catch (RuntimeException e) {
                    name = baseNameWithoutExtension(file.getName());
                }
                list.add(new String[]{(name + " " + file.getName()).toLowerCase(Locale.ROOT), name, mode, file.getAbsolutePath()});
            }
        }
        Collections.sort(list, (a, b) -> a[1].compareToIgnoreCase(b[1]));
        return list;
    }

    private static final String PREF_HOME_TAB = "home_tab";
    private static final String PREF_HOME_SORT = "home_sort";

    private static boolean isHangul(String text) {
        return !text.isEmpty() && text.charAt(0) >= '\uAC00' && text.charAt(0) <= '\uD7A3';
    }

    // When a console's games were last played (0 never).
    private long lastPlayed(String mode) {
        File[] files = cachedModeGames(mode);
        long last = 0;
        if (files != null) {
            for (File file : files) {
                last = Math.max(last, romPrefs().getLong(PREF_RECENT_PREFIX + file.getName(), 0L));
            }
        }
        return last;
    }

    private static String playedAgo(long when) {
        long minutes = Math.max(0, (System.currentTimeMillis() - when) / 60000);
        if (minutes < 60) {
            return "방금";
        }
        long days = minutes / (60 * 24);
        if (days < 1) {
            return "오늘";
        }
        if (days < 2) {
            return "어제";
        }
        if (days < 7) {
            return days + "일 전";
        }
        if (days < 30) {
            return days / 7 + "주 전";
        }
        return Math.max(1, days / 30) + "달 전";
    }

    // [전체 | ★ 즐겨찾기] and the sort button under the search box.
    private LinearLayout browserBar(boolean favTab, String sort, int favorites, Runnable onChanged) {
        final int teal = Color.rgb(14, 116, 144);
        LinearLayout bar = new LinearLayout(this);
        bar.setGravity(16);
        bar.setPadding(0, dp(10), 0, dp(10));
        LinearLayout segment = new LinearLayout(this);
        segment.setPadding(dp(3), dp(3), dp(3), dp(3));
        segment.setBackground(rounded(Color.rgb(226, 232, 240), dp(12)));
        String[] labels = {"전체 " + MODE_IDS.length, "★ 즐겨찾기 " + favorites};
        for (int k = 0; k < 2; k++) {
            final int tab = k;
            boolean on = (k == 1) == favTab;
            TextView button = new TextView(this);
            button.setText(labels[k]);
            button.setTextSize(12.5f);
            button.setTypeface(Typeface.DEFAULT_BOLD);
            button.setTextColor(Theme.text(on ? teal : Color.rgb(100, 116, 139)));
            button.setPadding(dp(12), dp(6), dp(12), dp(6));
            if (on) {
                button.setBackground(rounded(Color.WHITE, dp(10)));
                button.setElevation(dp(1));
            }
            button.setOnClickListener(view -> {
                settingsPrefs().edit().putInt(PREF_HOME_TAB, tab).apply();
                onChanged.run();
            });
            segment.addView(button);
        }
        bar.addView(segment);
        bar.addView(new View(this), new LinearLayout.LayoutParams(0, 1, 1.0f));
        final TextView sortButton = new TextView(this);
        sortButton.setText(sortLabel(sort) + "  ▾");
        sortButton.setTextSize(12.5f);
        sortButton.setTypeface(Typeface.DEFAULT_BOLD);
        sortButton.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        sortButton.setPadding(dp(11), dp(7), dp(11), dp(7));
        GradientDrawable sortBox = rounded(Color.WHITE, dp(12));
        sortBox.setStroke(Math.max(1, dp(1)), Theme.line(Color.rgb(226, 232, 240)));
        sortButton.setBackground(sortBox);
        sortButton.setOnClickListener(view -> showSortMenu(sortButton, sort, onChanged));
        bar.addView(sortButton);
        return bar;
    }

    private static String sortLabel(String sort) {
        return "recent".equals(sort) ? "🕒 최근 플레이" : "name".equals(sort) ? "가 이름순" : "▦ 기본 순서";
    }

    private void showSortMenu(View anchor, String sort, Runnable onChanged) {
        final int teal = Color.rgb(14, 116, 144);
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        panel.setPadding(dp(6), dp(6), dp(6), dp(6));
        panel.setBackground(rounded(Color.WHITE, dp(16)));
        panel.setElevation(dp(8));
        TextView head = new TextView(this);
        head.setText("정렬");
        head.setTextSize(11.0f);
        head.setTypeface(Typeface.DEFAULT_BOLD);
        head.setTextColor(Theme.text(Color.rgb(148, 163, 184)));
        head.setPadding(dp(10), dp(6), dp(10), dp(4));
        panel.addView(head);
        final android.widget.PopupWindow popup = new android.widget.PopupWindow(panel, dp(200), -2, true);
        popup.setBackgroundDrawable(new ColorDrawable(0));
        popup.setElevation(dp(8));
        for (String key : new String[]{"recent", "name", "default"}) {
            boolean on = key.equals(sort);
            LinearLayout item = new LinearLayout(this);
            item.setGravity(16);
            item.setPadding(dp(12), dp(11), dp(12), dp(11));
            if (on) {
                item.setBackground(rounded(Color.rgb(236, 254, 255), dp(10)));
            }
            TextView label = new TextView(this);
            label.setText(sortLabel(key));
            label.setTextSize(13.5f);
            label.setTypeface(Typeface.DEFAULT_BOLD);
            label.setTextColor(Theme.text(on ? teal : Color.rgb(55, 65, 81)));
            item.addView(label, new LinearLayout.LayoutParams(0, -2, 1.0f));
            if (on) {
                TextView check = new TextView(this);
                check.setText("✓");
                check.setTextColor(Theme.text(teal));
                check.setTypeface(Typeface.DEFAULT_BOLD);
                item.addView(check);
            }
            item.setOnClickListener(view -> {
                popup.dismiss();
                settingsPrefs().edit().putString(PREF_HOME_SORT, key).apply();
                onChanged.run();
            });
            panel.addView(item, new LinearLayout.LayoutParams(-1, -2));
        }
        popup.showAsDropDown(anchor, -dp(200) + anchor.getWidth(), dp(4));
    }

    // The search box, [전체 | 즐겨찾기] with a sort, and the consoles in one view; onPick opens a
    // console, onGame starts a game.
    private LinearLayout createModeBrowser(String current, java.util.function.Consumer<String> onPick, java.util.function.Consumer<File> onGame) {
        LinearLayout browser = new LinearLayout(this);
        browser.setOrientation(1);
        EditText search = new EditText(this);
        search.setHint("게임기 · 게임 이름 검색");
        search.setSingleLine(true);
        search.setTextSize(14.0f);
        search.setTextColor(Theme.text(Color.rgb(17, 24, 39)));
        search.setHintTextColor(Theme.text(Color.rgb(156, 163, 175)));
        search.setPadding(dp(14), 0, dp(14), 0);
        search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);
        GradientDrawable box = rounded(Color.WHITE, dp(14));
        box.setStroke(dp(1), Theme.line(Color.rgb(229, 231, 235)));
        search.setBackground(box);
        search.setCompoundDrawablePadding(dp(8));
        browser.addView(search, new LinearLayout.LayoutParams(-1, dp(44)));
        LinearLayout content = new LinearLayout(this);
        content.setOrientation(1);
        browser.addView(content, new LinearLayout.LayoutParams(-1, -2));
        java.util.Map<String, Integer> counts = new HashMap<>();
        java.util.Map<String, Long> played = new HashMap<>();
        for (String mode : MODE_IDS) {
            counts.put(mode, romCount(mode));
            played.put(mode, lastPlayed(mode));
        }
        final Runnable[] render = new Runnable[1];
        render[0] = () -> {
            content.removeAllViews();
            String query = search.getText().toString().trim().toLowerCase(Locale.ROOT);
            if (query.isEmpty()) {
                List<String> favorites = favoriteModes();
                boolean favTab = settingsPrefs().getInt(PREF_HOME_TAB, 0) == 1;
                String sort = settingsPrefs().getString(PREF_HOME_SORT, "default");
                content.addView(browserBar(favTab, sort, favorites.size(), render[0]));
                List<Integer> shown = new ArrayList<>();
                for (int i = 0; i < MODE_IDS.length; i++) {
                    if (!favTab || favorites.contains(MODE_IDS[i])) {
                        shown.add(i);
                    }
                }
                if (favTab && "default".equals(sort)) {
                    // 즐겨찾기 in their own order (앞으로 / 뒤로).
                    shown.clear();
                    for (String mode : favorites) {
                        shown.add(modeIndex(mode));
                    }
                }
                if ("name".equals(sort)) {
                    final java.text.Collator collator = java.text.Collator.getInstance(Locale.KOREAN);
                    java.util.Collections.sort(shown, (a, b) -> {
                        boolean ha = isHangul(MODE_NAMES[a]);
                        boolean hb = isHangul(MODE_NAMES[b]);
                        return ha != hb ? (ha ? -1 : 1) : collator.compare(MODE_NAMES[a], MODE_NAMES[b]);
                    });
                } else if ("recent".equals(sort)) {
                    final List<Integer> base = new ArrayList<>(shown);
                    java.util.Collections.sort(shown, (a, b) -> {
                        long x = played.get(MODE_IDS[a]);
                        long y = played.get(MODE_IDS[b]);
                        return x != y ? Long.compare(y, x) : Integer.compare(base.indexOf(a), base.indexOf(b));
                    });
                }
                if (shown.isEmpty()) {
                    TextView tip = new TextView(this);
                    tip.setText("아직 즐겨찾기한 게임기가 없어요.\n게임기 큐브를 길게 누르면 여기에 모여요.");
                    tip.setTextColor(Theme.text(STATUS_TEXT_COLOR));
                    tip.setTextSize(13.0f);
                    tip.setGravity(17);
                    tip.setLineSpacing(0, 1.2f);
                    tip.setPadding(0, dp(30), 0, dp(30));
                    content.addView(tip, new LinearLayout.LayoutParams(-1, -2));
                    return;
                }
                addTileGrid(content, shown, counts, current, onPick, render[0], "recent".equals(sort) ? played : null);
                if (favorites.isEmpty() && !favTab) {
                    TextView tip = new TextView(this);
                    tip.setText("게임기를 길게 누르면 즐겨찾기에 넣을 수 있어요.");
                    tip.setTextColor(Theme.text(STATUS_TEXT_COLOR));
                    tip.setTextSize(11.5f);
                    tip.setPadding(dp(2), dp(10), 0, 0);
                    content.addView(tip);
                }
                return;
            }
            // Consoles whose name, engine or file types match.
            List<Integer> modes = new ArrayList<>();
            for (int i = 0; i < MODE_IDS.length; i++) {
                String hay = (MODE_NAMES[i] + " " + MODE_ENGINES[i] + " " + MODE_FILES[i] + " " + MODE_IDS[i]).toLowerCase(Locale.ROOT);
                if (hay.contains(query)) {
                    modes.add(i);
                }
            }
            if (!modes.isEmpty()) {
                content.addView(browserSectionTitle("게임기", modes.size() + "개"));
                addTileGrid(content, modes, counts, current, onPick, render[0]);
            }
            if (this.gameIndex == null) {
                content.addView(browserSectionTitle("게임", "찾는 중…"));
                return;
            }
            List<String[]> games = new ArrayList<>();
            for (String[] game : this.gameIndex) {
                if (game[0].contains(query)) {
                    games.add(game);
                }
            }
            content.addView(browserSectionTitle("게임", games.size() + "개"));
            if (games.isEmpty() && modes.isEmpty()) {
                TextView none = new TextView(this);
                none.setText("\"" + search.getText().toString().trim() + "\"에 맞는 게임기나 게임이 없어요.");
                none.setTextColor(Theme.text(STATUS_TEXT_COLOR));
                none.setTextSize(12.5f);
                none.setPadding(dp(2), 0, 0, 0);
                content.addView(none);
            }
            for (int k = 0; k < games.size() && k < 60; k++) {
                String[] game = games.get(k);
                int index = modeIndex(game[2]);
                LinearLayout row = new LinearLayout(this);
                row.setOrientation(0);
                row.setGravity(16);
                row.setPadding(dp(10), dp(8), dp(12), dp(8));
                row.setBackground(rounded(Color.WHITE, dp(13)));
                ImageView icon = new ImageView(this);
                icon.setImageResource(MODE_DRAWABLES[index]);
                icon.setScaleType(ImageView.ScaleType.FIT_CENTER);
                icon.setPadding(dp(4), dp(4), dp(4), dp(4));
                icon.setBackground(rounded(MODE_COLORS[index], dp(10)));
                row.addView(icon, new LinearLayout.LayoutParams(dp(36), dp(36)));
                LinearLayout texts = new LinearLayout(this);
                texts.setOrientation(1);
                texts.setPadding(dp(10), 0, dp(8), 0);
                TextView title = new TextView(this);
                title.setText(game[1]);
                title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
                title.setTextSize(13.5f);
                title.setTypeface(Typeface.DEFAULT_BOLD);
                title.setSingleLine(true);
                title.setEllipsize(android.text.TextUtils.TruncateAt.END);
                texts.addView(title);
                TextView sub = new TextView(this);
                sub.setText(MODE_NAMES[index]);
                sub.setTextColor(Theme.text(STATUS_TEXT_COLOR));
                sub.setTextSize(11.0f);
                texts.addView(sub);
                row.addView(texts, new LinearLayout.LayoutParams(0, -2, 1.0f));
                TextView play = new TextView(this);
                play.setText("▶");
                play.setTextColor(Theme.text(Color.rgb(22, 185, 207)));
                play.setTextSize(14.0f);
                row.addView(play);
                final File file = new File(game[3]);
                row.setClickable(true);
                row.setOnClickListener(view -> onGame.accept(file));
                LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, -2);
                params.setMargins(0, 0, 0, dp(6));
                content.addView(row, params);
            }
            if (games.size() > 60) {
                TextView more = new TextView(this);
                more.setText("앞의 60개만 보여요. 더 자세히 입력해 주세요.");
                more.setTextColor(Theme.text(STATUS_TEXT_COLOR));
                more.setTextSize(11.5f);
                content.addView(more);
            }
        };
        search.addTextChangedListener(new android.text.TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
            }

            @Override
            public void afterTextChanged(android.text.Editable s) {
                if (MainActivity.this.gameIndex == null && s.toString().trim().length() > 0 && !MainActivity.this.gameIndexLoading) {
                    MainActivity.this.gameIndexLoading = true;
                    new Thread(() -> {
                        List<String[]> built = buildGameIndex();
                        runOnUiThread(() -> {
                            MainActivity.this.gameIndex = built;
                            MainActivity.this.gameIndexLoading = false;
                            if (browser.isAttachedToWindow()) {
                                render[0].run();
                            }
                        });
                    }, "game-index").start();
                }
                render[0].run();
            }
        });
        render[0].run();
        return browser;
    }

    private boolean gameIndexLoading;

    // ---- "Wii 시스템 업데이트": the Wii system from Nintendo's servers through the Dolphin
    // core, and the SSL certificates out of its IOS13, which the Wii's online games need ----
    private static final String[] WII_REGION_CODES = {"KOR", "JPN", "USA", "EUR"};
    private static final String[] WII_REGION_NAMES = {"한국", "일본", "미국", "유럽"};

    private File dolphinUserDir() {
        return new File(new File(new File(getFilesDir(), "saves"), "dolphin"), "User");
    }

    private boolean wiiCertificatesReady() {
        File wii = new File(dolphinUserDir(), "Wii");
        for (String name : new String[]{"clientca.pem", "clientcakey.pem", "rootca.pem"}) {
            if (!new File(wii, name).isFile()) {
                return false;
            }
        }
        return true;
    }

    private String wiiOnlineStatusText() {
        return wiiCertificatesReady() ? "온라인 준비됨 · 인증서 3개" : "인증서 없음 · Wiimmfi에 필요";
    }

    private void showWiiUpdateSheet() {
        if (android.os.Build.VERSION.SDK_INT < 26) {
            showError("게임큐브·Wii는 안드로이드 8 이상에서만 쓸 수 있어요.");
            return;
        }
        if (!new File(getApplicationInfo().nativeLibraryDir, "libdolphin_libretro_android.so").isFile()) {
            showError("이 버전에는 게임큐브·Wii 엔진이 들어 있지 않아요.");
            return;
        }
        int region = Arrays.asList(WII_REGION_CODES).indexOf(settingsPrefs().getString("wii_update_region", "KOR"));
        final int[] chosen = {region < 0 ? 0 : region};
        String[] notes = {"한국판 게임 (마리오 카트 Wii 한국판 등)", "일본판 게임", "북미판 게임", "유럽판 게임"};
        String[] items = new String[WII_REGION_NAMES.length];
        for (int k = 0; k < items.length; k++) {
            items[k] = WII_REGION_NAMES[k] + " · " + notes[k];
        }
        new AppDialog.Builder(this).setTitle("Wii 시스템 업데이트")
                .setMessage((wiiCertificatesReady() ? "이미 인증서가 있어요. 다시 받으려면 지역을 고르세요.\n\n" : "")
                        + "닌텐도 서버에서 Wii 시스템을 직접 받아 온라인에 필요한 인증서 3개를 꺼내 둬요.\n"
                        + "와이파이에서 하세요 · 약 100~200MB · 몇 분 걸려요. 받은 시스템은 이 앱 안에만 저장되고, 게임 세이브는 그대로예요.\n\n"
                        + "게임 지역을 고르세요 (인증서는 어느 지역이든 같아요).")
                .setItems(items, (dialog, which) -> {
                    settingsPrefs().edit().putString("wii_update_region", WII_REGION_CODES[which]).apply();
                    runWiiUpdate(WII_REGION_CODES[which], WII_REGION_NAMES[which]);
                })
                .setNegativeButton("취소", null).show();
    }

    private void runWiiUpdate(String region, String regionName) {
        final Dialog dialog = new Dialog(this);
        dialog.requestWindowFeature(1);
        dialog.setCancelable(false);
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        panel.setPadding(dp(18), dp(20), dp(18), dp(16));
        panel.setBackground(rounded(-1, dp(22)));
        TextView title = new TextView(this);
        title.setText("Wii 시스템 업데이트 중");
        title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        title.setTextSize(17.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        panel.addView(title);
        TextView sub = new TextView(this);
        sub.setText(regionName + " · 닌텐도 서버에 연결하는 중…");
        sub.setTextColor(Theme.text(STATUS_TEXT_COLOR));
        sub.setTextSize(12.5f);
        sub.setPadding(0, dp(4), 0, dp(14));
        panel.addView(sub);
        android.widget.ProgressBar bar = new android.widget.ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);
        bar.setIndeterminate(true);
        bar.setMax(1000);
        panel.addView(bar, new LinearLayout.LayoutParams(-1, dp(14)));
        TextView note = new TextView(this);
        note.setText("끝날 때까지 이 창을 열어 두세요. 끊기면 처음부터 다시 받아요.");
        note.setTextColor(Theme.text(Color.rgb(75, 85, 99)));
        note.setTextSize(11.5f);
        note.setPadding(dp(12), dp(10), dp(12), dp(10));
        note.setBackground(rounded(Color.rgb(246, 247, 249), dp(12)));
        LinearLayout.LayoutParams noteParams = new LinearLayout.LayoutParams(-1, -2);
        noteParams.setMargins(0, dp(12), 0, 0);
        panel.addView(note, noteParams);
        final boolean[] stop = {false};
        TextView cancel = new TextView(this);
        cancel.setText("그만두기");
        cancel.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        cancel.setTextSize(14.0f);
        cancel.setTypeface(Typeface.DEFAULT_BOLD);
        cancel.setGravity(17);
        cancel.setBackground(rounded(Color.rgb(241, 243, 245), dp(12)));
        cancel.setOnClickListener(view -> {
            stop[0] = true;
            cancel.setText("그만두는 중…");
            cancel.setEnabled(false);
        });
        LinearLayout.LayoutParams cancelParams = new LinearLayout.LayoutParams(-1, dp(46));
        cancelParams.setMargins(0, dp(14), 0, 0);
        panel.addView(cancel, cancelParams);
        dialog.setContentView(panel);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(0));
            window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels - dp(32), dp(420)), -2);
            window.addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        }
        dialog.show();
        final File user = dolphinUserDir();
        final File sys = new File(new File(systemDir(), "dolphin-emu"), "Sys");
        new Thread(() -> {
            int result;
            if (!user.isDirectory() && !user.mkdirs()) {
                result = -2;
            } else if (!unpackSystemAsset("dolphin_sys.zip", sys)) {
                result = -3;
            } else {
                try {
                    result = NativeGba.wiiSystemUpdate(user.getAbsolutePath(), sys.getAbsolutePath(), region, (done, total, titleId) -> {
                        runOnUiThread(() -> {
                            if (total > 0) {
                                bar.setIndeterminate(false);
                                bar.setProgress((int) (1000L * done / total));
                                sub.setText(String.format(Locale.US, "%s · %d / %d · %s", regionName, done, total, wiiTitleName(titleId)));
                            }
                        });
                        return !stop[0];
                    });
                } catch (UnsatisfiedLinkError e) {
                    result = -1;
                }
            }
            final int code = result;
            runOnUiThread(() -> {
                dialog.dismiss();
                onWiiUpdateDone(code);
            });
        }, "wii-update").start();
    }

    private static String wiiTitleName(long titleId) {
        if (titleId == 0x0000000100000002L) return "Wii 메뉴";
        if ((titleId >>> 32) == 1 && (titleId & 0xFFFFFFFFL) < 0x100) return "IOS" + (titleId & 0xFFFFFFFFL);
        return String.format(Locale.US, "%016X", titleId);
    }

    private void onWiiUpdateDone(int code) {
        updateHomeStatusCards();
        String message;
        boolean ok = false;
        switch (code) {
            case 0:
            case 1:
                ok = wiiCertificatesReady();
                message = ok ? "인증서 3개를 꺼냈어요. 게임 안 Wi-Fi 메뉴에서 접속해 보세요 (Wiimmfi를 켠 게임)."
                        : "업데이트는 됐는데 인증서 파일이 보이지 않아요.";
                break;
            case 100:
            case 101:
                message = "Wii 시스템은 받았지만 IOS13에서 인증서를 꺼내지 못했어요.";
                break;
            case 5:
                message = "닌텐도 서버(업데이트 목록)에 연결하지 못했어요. 인터넷 연결을 확인하고 다시 해 주세요.";
                break;
            case 6:
                message = "받는 도중에 실패했어요. 와이파이에서 다시 해 주세요.";
                break;
            case 7:
                message = "받은 시스템을 설치하지 못했어요. 저장 공간을 확인해 주세요.";
                break;
            case 8:
                message = "그만뒀어요. 다음에 처음부터 다시 받아요.";
                break;
            case -1:
                message = "엔진에 업데이트 기능이 없어요. 앱을 최신 버전으로 업데이트해 주세요.";
                break;
            default:
                message = "업데이트하지 못했어요 (코드 " + code + ").";
                break;
        }
        new AppDialog.Builder(this).setTitle(ok ? "Wii 온라인 준비 완료" : "Wii 시스템 업데이트").setMessage(message).setPositiveButton("확인", null).show();
    }

    // ---- 앱 업데이트 (AppUpdate): the newest GitHub release, downloaded and installed from here ----
    private AppUpdate.Release pendingRelease;
    private boolean updateDialogShown;
    private boolean updateChecking;
    private boolean installAfterPermission;
    private android.content.BroadcastReceiver downloadReceiver;

    @Override
    protected void onDestroy() {
        if (this.downloadReceiver != null) {
            try {
                unregisterReceiver(this.downloadReceiver);
            } catch (IllegalArgumentException ignored) {
                // Not registered.
            }
            this.downloadReceiver = null;
        }
        super.onDestroy();
    }

    private void registerDownloadReceiver() {
        this.downloadReceiver = new android.content.BroadcastReceiver() {
            @Override
            public void onReceive(android.content.Context context, Intent intent) {
                long id = intent.getLongExtra(android.app.DownloadManager.EXTRA_DOWNLOAD_ID, -1);
                if (id != -1 && id == AppUpdate.downloadId(settingsPrefs())) {
                    onUpdateDownloaded();
                }
            }
        };
        android.content.IntentFilter filter = new android.content.IntentFilter(android.app.DownloadManager.ACTION_DOWNLOAD_COMPLETE);
        if (android.os.Build.VERSION.SDK_INT >= 33) {
            registerReceiver(this.downloadReceiver, filter, 2 /* RECEIVER_EXPORTED: sent by the download manager */);
        } else {
            registerReceiver(this.downloadReceiver, filter);
        }
    }

    // On resume: a daily check, and an install that waited for the "이 출처 허용" setting or
    // for the app to come back after the download finished.
    private void resumeAppUpdate() {
        if (this.installAfterPermission && canInstallPackages()) {
            this.installAfterPermission = false;
            installUpdate();
            return;
        }
        long id = AppUpdate.downloadId(settingsPrefs());
        if (id != -1) {
            long[] state = AppUpdate.progress(this, id);
            if (state[0] == android.app.DownloadManager.STATUS_SUCCESSFUL
                    && AppUpdate.compare(AppUpdate.downloadVersion(settingsPrefs()), AppUpdate.currentVersion(this)) > 0) {
                onUpdateDownloaded();
                return;
            }
            if (state[0] == android.app.DownloadManager.STATUS_FAILED
                    && AppUpdate.compare(AppUpdate.downloadVersion(settingsPrefs()), AppUpdate.currentVersion(this)) > 0) {
                // Failed while the app was away: say why (0.0.353).
                String why = AppUpdate.failureText(state[0], state[3]);
                AppUpdate.cancel(this, id);
                AppUpdate.clearDownload(settingsPrefs());
                showUpdateFailure(null, why, false);
            } else if (state[0] == 0 || state[0] == android.app.DownloadManager.STATUS_FAILED
                    || AppUpdate.compare(AppUpdate.downloadVersion(settingsPrefs()), AppUpdate.currentVersion(this)) <= 0) {
                // Gone, failed, or already installed.
                AppUpdate.clearDownload(settingsPrefs());
            }
        }
        if (AppUpdate.dueForCheck(settingsPrefs())) {
            checkForUpdate(false);
        }
    }

    private void checkForUpdate(boolean manual) {
        if (this.updateChecking) {
            return;
        }
        this.updateChecking = true;
        refreshUpdateIcon();
        if (manual) {
            Toast.makeText(this, "새 버전을 확인하는 중…", Toast.LENGTH_SHORT).show();
        }
        new Thread(() -> {
            AppUpdate.Release release;
            String error = null;
            try {
                release = AppUpdate.fetchLatest();
            } catch (IOException | RuntimeException e) {
                release = null;
                error = e.getMessage();
            }
            final AppUpdate.Release found = release;
            final String failure = error;
            runOnUiThread(() -> {
                this.updateChecking = false;
                if (isFinishing()) {
                    return;
                }
                refreshUpdateIcon();
                if (failure != null) {
                    if (manual) {
                        Toast.makeText(this, "확인하지 못했어요. 인터넷 연결을 확인해 주세요.", Toast.LENGTH_LONG).show();
                    }
                    return;
                }
                AppUpdate.markChecked(settingsPrefs());
                String current = AppUpdate.currentVersion(this);
                if (found == null || AppUpdate.compare(found.version, current) <= 0) {
                    this.pendingRelease = null;
                    refreshUpdateIcon();
                    if (manual) {
                        Toast.makeText(this, "최신 버전이에요 (" + current + ")", Toast.LENGTH_SHORT).show();
                    }
                    return;
                }
                this.pendingRelease = found;
                refreshUpdateIcon();
                if (manual || (!this.updateDialogShown && !AppUpdate.skipped(settingsPrefs(), found.version))) {
                    this.updateDialogShown = true;
                    showUpdateDialog(found);
                }
            });
        }, "update-check").start();
    }

    // ---- The update icon at the top right of the start screen ----
    /** A round button: ↻ (up to date), ↓ with a red dot (newer version), a ring while downloading. */
    private static final class UpdateRing extends View {
        static final int OK = 0, NEW = 1, DOWNLOADING = 2, CHECKING = 3;
        private final android.graphics.Paint paint = new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);
        private final float density;
        int state;
        float progress;

        UpdateRing(android.content.Context context) {
            super(context);
            this.density = context.getResources().getDisplayMetrics().density;
        }

        @Override
        protected void onDraw(android.graphics.Canvas canvas) {
            float w = getWidth();
            float h = getHeight();
            float cx = w / 2f;
            float cy = h / 2f;
            float r = Math.min(w, h) / 2f - 2 * density;
            int accent = Color.rgb(22, 185, 207);
            paint.setStyle(android.graphics.Paint.Style.FILL);
            paint.setColor(Theme.bg(state == NEW ? Color.rgb(236, 254, 255) : Color.WHITE));
            canvas.drawCircle(cx, cy, r, paint);
            paint.setStyle(android.graphics.Paint.Style.STROKE);
            if (state == DOWNLOADING || state == CHECKING) {
                paint.setStrokeWidth(4 * density);
                paint.setColor(Theme.bg(Color.rgb(226, 232, 240)));
                canvas.drawCircle(cx, cy, r - 2 * density, paint);
                paint.setColor(Theme.bg(accent));
                android.graphics.RectF arc = new android.graphics.RectF(cx - r + 2 * density, cy - r + 2 * density, cx + r - 2 * density, cy + r - 2 * density);
                float sweep = state == CHECKING ? 90 : Math.max(4, 360 * progress);
                float start = state == CHECKING ? (System.currentTimeMillis() / 3 % 360) : -90;
                canvas.drawArc(arc, start, sweep, false, paint);
                if (state == DOWNLOADING) {
                    paint.setStyle(android.graphics.Paint.Style.FILL);
                    paint.setColor(Theme.bg(Color.rgb(14, 116, 144)));
                    paint.setTextSize(10 * density);
                    paint.setTypeface(Typeface.DEFAULT_BOLD);
                    paint.setTextAlign(android.graphics.Paint.Align.CENTER);
                    canvas.drawText(Math.round(progress * 100) + "%", cx, cy + 3.5f * density, paint);
                } else {
                    postInvalidateOnAnimation();
                }
                return;
            }
            paint.setStrokeWidth(1.5f * density);
            paint.setColor(Theme.bg(state == NEW ? Color.rgb(103, 232, 249) : Color.rgb(229, 231, 235)));
            canvas.drawCircle(cx, cy, r, paint);
            paint.setStyle(android.graphics.Paint.Style.FILL);
            paint.setColor(Theme.bg(state == NEW ? Color.rgb(14, 116, 144) : accent));
            paint.setTextSize(19 * density);
            paint.setTypeface(Typeface.DEFAULT_BOLD);
            paint.setTextAlign(android.graphics.Paint.Align.CENTER);
            canvas.drawText(state == NEW ? "↓" : "↻", cx, cy + 6.5f * density, paint);
            if (state == NEW) {
                paint.setColor(Theme.bg(Color.rgb(238, 242, 247)));
                canvas.drawCircle(cx + r * 0.72f, cy - r * 0.72f, 7 * density, paint);
                paint.setColor(Theme.bg(Color.rgb(239, 68, 68)));
                canvas.drawCircle(cx + r * 0.72f, cy - r * 0.72f, 5 * density, paint);
            }
        }
    }

    private UpdateRing updateRing;
    private TextView updateLabel;
    private final Runnable updateRingPoll = this::refreshUpdateIcon;

    private View createUpdateIcon() {
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(1);
        box.setGravity(1);
        UpdateRing ring = new UpdateRing(this);
        box.addView(ring, new LinearLayout.LayoutParams(dp(44), dp(44)));
        TextView label = new TextView(this);
        label.setTextSize(9.5f);
        label.setTypeface(Typeface.DEFAULT_BOLD);
        label.setGravity(1);
        label.setPadding(0, dp(2), 0, 0);
        box.addView(label, new LinearLayout.LayoutParams(-2, -2));
        box.setContentDescription("앱 업데이트");
        box.setOnClickListener(this::showUpdatePopup);
        this.updateRing = ring;
        this.updateLabel = label;
        refreshUpdateIcon();
        return box;
    }

    private boolean updateDownloading() {
        long id = AppUpdate.downloadId(settingsPrefs());
        if (id == -1) {
            return false;
        }
        long[] state = AppUpdate.progress(this, id);
        return state[0] == android.app.DownloadManager.STATUS_RUNNING || state[0] == android.app.DownloadManager.STATUS_PENDING
                || state[0] == android.app.DownloadManager.STATUS_PAUSED;
    }

    // Follows the check, the newest version known and the download (polled while it runs).
    private void refreshUpdateIcon() {
        UpdateRing ring = this.updateRing;
        TextView label = this.updateLabel;
        if (ring == null || label == null || !ring.isAttachedToWindow() && ring.getWidth() > 0) {
            return;
        }
        ring.removeCallbacks(this.updateRingPoll);
        long id = AppUpdate.downloadId(settingsPrefs());
        if (id != -1 && updateDownloading()) {
            long[] state = AppUpdate.progress(this, id);
            ring.state = UpdateRing.DOWNLOADING;
            ring.progress = state[2] > 0 ? (float) state[1] / state[2] : 0;
            label.setText("받는 중");
            label.setTextColor(Theme.text(Color.rgb(14, 116, 144)));
            ring.postDelayed(this.updateRingPoll, 700);
        } else if (this.updateChecking) {
            ring.state = UpdateRing.CHECKING;
            label.setText("확인 중");
            label.setTextColor(Theme.text(Color.rgb(107, 114, 128)));
        } else if (this.pendingRelease != null && !AppUpdate.skipped(settingsPrefs(), this.pendingRelease.version)) {
            ring.state = UpdateRing.NEW;
            label.setText("새 버전");
            label.setTextColor(Theme.text(Color.rgb(220, 38, 38)));
        } else {
            ring.state = UpdateRing.OK;
            label.setText("v" + AppUpdate.currentVersion(this));
            label.setTextColor(Theme.text(Color.rgb(156, 163, 175)));
        }
        ring.invalidate();
    }

    private TextView popupRow(LinearLayout parent, String name, String value, View.OnClickListener onClick) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(0);
        row.setGravity(16);
        row.setPadding(dp(11), dp(9), dp(11), dp(9));
        row.setBackground(rounded(Color.rgb(246, 247, 249), dp(11)));
        TextView label = new TextView(this);
        label.setText(name);
        label.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        label.setTextSize(12.5f);
        label.setTypeface(Typeface.DEFAULT_BOLD);
        row.addView(label, new LinearLayout.LayoutParams(0, -2, 1.0f));
        TextView shown = new TextView(this);
        shown.setText(value);
        shown.setTextColor(Theme.text(Color.rgb(75, 85, 99)));
        shown.setTextSize(11.5f);
        row.addView(shown);
        row.setOnClickListener(onClick);
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, -2);
        params.setMargins(0, dp(6), 0, 0);
        parent.addView(row, params);
        return shown;
    }

    // The small window under the icon: up to date (check now, daily check), a newer version
    // (what changed, get it), or the download in progress.
    private void showUpdatePopup(View anchor) {
        long id = AppUpdate.downloadId(settingsPrefs());
        if (id != -1 && updateDownloading()) {
            String version = AppUpdate.downloadVersion(settingsPrefs());
            showUpdateProgress(id, new AppUpdate.Release(version, "", "", 0), UPDATE_RETRIES);
            return;
        }
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        panel.setPadding(dp(14), dp(14), dp(14), dp(12));
        panel.setBackground(rounded(Color.WHITE, dp(18)));
        panel.setElevation(dp(10));
        final android.widget.PopupWindow popup = new android.widget.PopupWindow(panel, dp(260), -2, true);
        popup.setBackgroundDrawable(new ColorDrawable(0));
        popup.setElevation(dp(10));
        TextView title = new TextView(this);
        title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        title.setTextSize(15.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        panel.addView(title);
        TextView sub = new TextView(this);
        sub.setTextSize(11.5f);
        sub.setPadding(0, dp(2), 0, 0);
        panel.addView(sub);
        AppUpdate.Release release = this.pendingRelease;
        String current = AppUpdate.currentVersion(this);
        if (release != null && AppUpdate.compare(release.version, current) > 0) {
            title.setText("새 버전 " + release.version);
            sub.setText("지금 " + current + (release.size > 0 ? " · " + AppUpdate.sizeText(release.size) : ""));
            sub.setTextColor(Theme.text(Color.rgb(107, 114, 128)));
            if (!release.notes.isEmpty()) {
                TextView notes = new TextView(this);
                notes.setText("바뀐 점\n" + (release.notes.length() > 320 ? release.notes.substring(0, 320) + "…" : release.notes));
                notes.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
                notes.setTextSize(11.0f);
                notes.setLineSpacing(0, 1.15f);
                notes.setPadding(dp(11), dp(9), dp(11), dp(9));
                notes.setBackground(rounded(Color.rgb(246, 247, 249), dp(11)));
                LinearLayout.LayoutParams notesParams = new LinearLayout.LayoutParams(-1, -2);
                notesParams.setMargins(0, dp(8), 0, 0);
                panel.addView(notes, notesParams);
            }
            LinearLayout buttons = new LinearLayout(this);
            TextView later = new TextView(this);
            later.setText("나중에");
            later.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
            later.setTextSize(13.0f);
            later.setTypeface(Typeface.DEFAULT_BOLD);
            later.setGravity(17);
            later.setBackground(rounded(Color.rgb(241, 243, 245), dp(11)));
            later.setOnClickListener(view -> popup.dismiss());
            TextView get = new TextView(this);
            get.setText("받기");
            get.setTextColor(Color.WHITE);
            get.setTextSize(13.0f);
            get.setTypeface(Typeface.DEFAULT_BOLD);
            get.setGravity(17);
            get.setBackground(rounded(Color.rgb(22, 185, 207), dp(11)));
            get.setOnClickListener(view -> {
                popup.dismiss();
                startUpdateDownload(release);
            });
            buttons.addView(later, new LinearLayout.LayoutParams(0, dp(38), 1.0f));
            LinearLayout.LayoutParams getParams = new LinearLayout.LayoutParams(0, dp(38), 1.4f);
            getParams.setMargins(dp(6), 0, 0, 0);
            buttons.addView(get, getParams);
            LinearLayout.LayoutParams buttonsParams = new LinearLayout.LayoutParams(-1, -2);
            buttonsParams.setMargins(0, dp(10), 0, 0);
            panel.addView(buttons, buttonsParams);
            TextView skip = new TextView(this);
            skip.setText("이 버전 건너뛰기");
            skip.setTextColor(Theme.text(Color.rgb(156, 163, 175)));
            skip.setTextSize(11.0f);
            skip.setGravity(17);
            skip.setPadding(0, dp(8), 0, 0);
            skip.setOnClickListener(view -> {
                AppUpdate.skip(settingsPrefs(), release.version);
                popup.dismiss();
                refreshUpdateIcon();
            });
            panel.addView(skip, new LinearLayout.LayoutParams(-1, -2));
        } else {
            title.setText("앱 업데이트");
            long last = AppUpdate.lastCheck(settingsPrefs());
            sub.setText(last > 0 ? "✓ 최신 버전이에요 · " + current : "지금 " + current + " · 아직 확인하지 않았어요");
            sub.setTextColor(Theme.text(last > 0 ? Color.rgb(22, 163, 74) : Color.rgb(107, 114, 128)));
            popupRow(panel, "지금 확인", "↻", view -> {
                popup.dismiss();
                checkForUpdate(true);
            });
            final TextView[] auto = new TextView[1];
            auto[0] = popupRow(panel, "자동 확인", AppUpdate.autoCheck(settingsPrefs()) ? "켜짐 · 하루 한 번" : "꺼짐", view -> {
                boolean on = !AppUpdate.autoCheck(settingsPrefs());
                AppUpdate.setAutoCheck(settingsPrefs(), on);
                auto[0].setText(on ? "켜짐 · 하루 한 번" : "꺼짐");
            });
            if (last > 0) {
                TextView when = new TextView(this);
                when.setText("마지막 확인: " + new SimpleDateFormat("M월 d일 HH:mm", Locale.KOREA).format(new Date(last)));
                when.setTextColor(Theme.text(Color.rgb(156, 163, 175)));
                when.setTextSize(10.5f);
                when.setPadding(0, dp(8), 0, 0);
                panel.addView(when);
            }
        }
        popup.showAsDropDown(anchor, -dp(260) + anchor.getWidth(), dp(4));
    }

    private void showUpdateDialog(AppUpdate.Release release) {
        StringBuilder message = new StringBuilder();
        message.append(AppUpdate.currentVersion(this)).append(" → ").append(release.version);
        if (release.size > 0) {
            message.append(" · ").append(AppUpdate.sizeText(release.size));
        }
        if (!release.notes.isEmpty()) {
            message.append("\n\n바뀐 점\n").append(release.notes.length() > 900 ? release.notes.substring(0, 900) + "…" : release.notes);
        }
        message.append("\n\n게임 · 세이브 · 설정은 그대로예요. 와이파이에서 받기를 권해요.");
        new AppDialog.Builder(this).setTitle("새 버전이 있어요")
                .setMessage(message.toString())
                .setNeutralButton("이 버전 건너뛰기", (d, w) -> {
                    AppUpdate.skip(settingsPrefs(), release.version);
                    refreshUpdateIcon();
                })
                .setNegativeButton("나중에", null)
                .setPositiveButton("받기", (d, w) -> startUpdateDownload(release)).show();
    }

    private void startUpdateDownload(AppUpdate.Release release) {
        startUpdateDownload(release, 0);
    }

    // attempt: 0 the first, 1-2 the automatic retries with a fresh link (0.0.353).
    private void startUpdateDownload(AppUpdate.Release release, int attempt) {
        long free = AppUpdate.freeSpace(this);
        if (attempt == 0 && free >= 0 && release.size > 0 && free < release.size + (40L << 20)) {
            showUpdateFailure(release, "휴대폰 저장 공간이 모자라요. 받으려면 " + AppUpdate.sizeText(release.size + (40L << 20))
                    + "가 필요한데 " + AppUpdate.sizeText(free) + "만 남았어요. 설치할 자리까지 500MB쯤 비워 주세요.", false);
            return;
        }
        long id;
        try {
            id = AppUpdate.startDownload(this, settingsPrefs(), release);
        } catch (RuntimeException e) {
            showError("다운로드를 시작하지 못했어요: " + e.getMessage());
            return;
        }
        showUpdateProgress(id, release, attempt);
        refreshUpdateIcon();
    }

    private static final int UPDATE_RETRIES = 2;

    // Why it failed, with 다시 받기 and 브라우저로 받기 (the release page on GitHub).
    private void showUpdateFailure(AppUpdate.Release release, String why, boolean retry) {
        if (isFinishing() || isDestroyed()) {
            return;
        }
        String version = release != null ? release.version : AppUpdate.downloadVersion(settingsPrefs());
        AppDialog.Builder builder = new AppDialog.Builder(this).setTitle("업데이트를 받지 못했어요")
                .setMessage(why + "\n\n안 되면 브라우저로 GitHub 릴리스 페이지에서 Mini-Emulator-" + version
                        + ".apk를 받아 설치해도 돼요. 같은 서명이라 게임 · 세이브 · 설정은 그대로예요.")
                .setNegativeButton("닫기", null)
                .setNeutralButton("브라우저로 받기", (d, w) -> {
                    try {
                        startActivity(new Intent(Intent.ACTION_VIEW, android.net.Uri.parse(AppUpdate.releasePage(version))));
                    } catch (RuntimeException e) {
                        showError("브라우저를 열 수 없어요: " + AppUpdate.releasePage(version));
                    }
                });
        if (retry && release != null && release.url != null && !release.url.isEmpty()) {
            builder.setPositiveButton("다시 받기", (d, w) -> startUpdateDownload(release, 0));
        }
        builder.show();
    }

    private void showUpdateProgress(long id, AppUpdate.Release release, int attempt) {
        final Dialog dialog = new Dialog(this);
        dialog.requestWindowFeature(1);
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        panel.setPadding(dp(18), dp(20), dp(18), dp(16));
        panel.setBackground(rounded(-1, dp(22)));
        TextView title = new TextView(this);
        title.setText("받는 중");
        title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        title.setTextSize(17.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        panel.addView(title);
        TextView sub = new TextView(this);
        sub.setText("Mini-Emulator-" + release.version + ".apk · GitHub");
        sub.setTextColor(Theme.text(STATUS_TEXT_COLOR));
        sub.setTextSize(12.5f);
        sub.setPadding(0, dp(3), 0, dp(14));
        panel.addView(sub);
        android.widget.ProgressBar bar = new android.widget.ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);
        bar.setMax(1000);
        bar.setIndeterminate(true);
        panel.addView(bar, new LinearLayout.LayoutParams(-1, dp(14)));
        TextView amount = new TextView(this);
        amount.setTextColor(Theme.text(Color.rgb(75, 85, 99)));
        amount.setTextSize(12.0f);
        amount.setPadding(0, dp(8), 0, 0);
        panel.addView(amount);
        TextView note = new TextView(this);
        note.setText("숨겨도 계속 받아요 (알림에 진행이 보여요). 다 받으면 설치 화면이 떠요.");
        note.setTextColor(Theme.text(Color.rgb(75, 85, 99)));
        note.setTextSize(11.5f);
        note.setPadding(dp(12), dp(10), dp(12), dp(10));
        note.setBackground(rounded(Color.rgb(246, 247, 249), dp(12)));
        LinearLayout.LayoutParams noteParams = new LinearLayout.LayoutParams(-1, -2);
        noteParams.setMargins(0, dp(12), 0, 0);
        panel.addView(note, noteParams);
        LinearLayout buttons = new LinearLayout(this);
        TextView stop = new TextView(this);
        stop.setText("그만두기");
        stop.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        stop.setTextSize(14.0f);
        stop.setTypeface(Typeface.DEFAULT_BOLD);
        stop.setGravity(17);
        stop.setBackground(rounded(Color.rgb(241, 243, 245), dp(12)));
        TextView hide = new TextView(this);
        hide.setText("숨기기");
        hide.setTextColor(-1);
        hide.setTextSize(14.0f);
        hide.setTypeface(Typeface.DEFAULT_BOLD);
        hide.setGravity(17);
        hide.setBackground(rounded(Color.rgb(22, 185, 207), dp(12)));
        buttons.addView(stop, new LinearLayout.LayoutParams(0, dp(46), 1.0f));
        LinearLayout.LayoutParams hideParams = new LinearLayout.LayoutParams(0, dp(46), 1.4f);
        hideParams.setMargins(dp(8), 0, 0, 0);
        buttons.addView(hide, hideParams);
        LinearLayout.LayoutParams buttonsParams = new LinearLayout.LayoutParams(-1, -2);
        buttonsParams.setMargins(0, dp(14), 0, 0);
        panel.addView(buttons, buttonsParams);
        dialog.setContentView(panel);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(0));
            window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels - dp(32), dp(420)), -2);
        }
        if (attempt > 0) {
            sub.setText("Mini-Emulator-" + release.version + ".apk · GitHub · 다시 받는 중 (" + (attempt + 1) + "/" + (UPDATE_RETRIES + 1) + ")");
        }
        final android.os.Handler handler = new android.os.Handler(android.os.Looper.getMainLooper());
        final Runnable[] poll = new Runnable[1];
        final boolean[] stopped = {false};
        // Kept polling while hidden too, so a failure is retried and told (0.0.353).
        poll[0] = () -> {
            if (stopped[0] || isFinishing() || isDestroyed()) {
                return;
            }
            long[] state = AppUpdate.progress(this, id);
            if (state[2] > 0) {
                bar.setIndeterminate(false);
                bar.setProgress((int) (1000L * state[1] / state[2]));
            }
            String waiting = AppUpdate.pausedText(state[0], state[3]);
            String sizes = state[2] > 0 ? String.format(Locale.US, "%d / %dMB · %d%%", state[1] >> 20, state[2] >> 20, 100L * state[1] / state[2]) : "";
            amount.setText(waiting == null ? sizes : (sizes.isEmpty() ? "" : sizes + " · ") + waiting);
            if (state[0] == android.app.DownloadManager.STATUS_SUCCESSFUL) {
                dialog.dismiss();
                return;
            }
            if (state[0] == android.app.DownloadManager.STATUS_FAILED || state[0] == 0) {
                dialog.dismiss();
                AppUpdate.cancel(this, id);
                AppUpdate.clearDownload(settingsPrefs());
                String why = AppUpdate.failureText(state[0], state[3]);
                boolean again = AppUpdate.retryable(state[0], state[3]);
                if (again && attempt < UPDATE_RETRIES) {
                    // a fresh link (GitHub's expire) after a short wait
                    handler.postDelayed(() -> {
                        if (!isFinishing() && !isDestroyed()) {
                            startUpdateDownload(release, attempt + 1);
                        }
                    }, 3000);
                    Toast.makeText(this, "받지 못해 다시 받아요 · " + why, Toast.LENGTH_LONG).show();
                    return;
                }
                showUpdateFailure(release, why + (attempt > 0 ? " (" + (attempt + 1) + "번 시도함)" : ""), again);
                return;
            }
            handler.postDelayed(poll[0], 500);
        };
        stop.setOnClickListener(view -> {
            stopped[0] = true;
            AppUpdate.cancel(this, id);
            AppUpdate.clearDownload(settingsPrefs());
            dialog.dismiss();
        });
        hide.setOnClickListener(view -> dialog.dismiss());
        dialog.show();
        poll[0].run();
    }

    private void onUpdateDownloaded() {
        if (isFinishing() || isDestroyed()) {
            return;
        }
        installUpdate();
    }

    private boolean canInstallPackages() {
        return android.os.Build.VERSION.SDK_INT < 26 || getPackageManager().canRequestPackageInstalls();
    }

    // Android's installer for the downloaded APK; first the one-time "이 출처 허용" when needed.
    private void installUpdate() {
        long id = AppUpdate.downloadId(settingsPrefs());
        android.net.Uri uri = id == -1 ? null : AppUpdate.downloadedUri(this, id);
        if (uri == null) {
            AppUpdate.clearDownload(settingsPrefs());
            showError("받은 파일을 찾지 못했어요. 다시 받아 주세요.");
            return;
        }
        if (!canInstallPackages()) {
            new AppDialog.Builder(this).setTitle("설치 허용이 한 번 필요해요")
                    .setMessage("안드로이드는 앱이 업데이트를 설치하려면 한 번 허용을 받아요.\n다음 화면에서 \"이 출처 허용\"을 켜고 돌아오면 바로 설치 화면이 떠요.")
                    .setNegativeButton("취소", null)
                    .setPositiveButton("설정 열기", (d, w) -> {
                        this.installAfterPermission = true;
                        try {
                            startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,
                                    android.net.Uri.parse("package:" + getPackageName())));
                        } catch (RuntimeException e) {
                            this.installAfterPermission = false;
                            showError("설정 화면을 열지 못했어요. 휴대폰 설정 › 앱 › Mini Emulator에서 '출처를 알 수 없는 앱 설치'를 허용해 주세요.");
                        }
                    }).show();
            return;
        }
        Intent intent = new Intent(Intent.ACTION_VIEW);
        intent.setDataAndType(uri, "application/vnd.android.package-archive");
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_ACTIVITY_NEW_TASK);
        try {
            startActivity(intent);
        } catch (RuntimeException e) {
            showError("설치 화면을 열지 못했어요: " + e.getMessage());
        }
    }

    private String updateRowShown() {
        String current = AppUpdate.currentVersion(this);
        AppUpdate.Release release = this.pendingRelease;
        return release != null ? current + " · 새 버전 " + release.version : current + " · 확인하기";
    }

    private String modeStatusText(String mode) {
        if (!isModeAvailable(mode)) {
            return "준비 중";
        }
        if ("neogeo".equals(mode) && !neoGeoBiosFile().exists()) {
            return "BIOS 필요";
        }
        if (MODE_X360.equals(mode) && X360Activity.unsupportedReason(this) != null) {
            return "지원 안 됨";
        }
        if (MODE_PS3.equals(mode)) {
            if (Ps3Activity.unsupportedReason(this) != null) {
                return "지원 안 됨";
            }
            if (!Ps3Activity.firmwareInstalled(this)) {
                return "펌웨어 필요";
            }
        }
        return "엔진 준비됨";
    }

    private void onModePicked(String mode) {
        settingsPrefs().edit().putString(PREF_MODE, mode).apply();
        showHome(mode);
    }

