    private void showMameBiosManager() {
        final android.app.Dialog[] alertDialogArr = new android.app.Dialog[1];
        LinearLayout linearLayout = new LinearLayout(this);
        linearLayout.setOrientation(1);
        linearLayout.setPadding(dp(20), dp(4), dp(20), dp(8));
        TextView textView = new TextView(this);
        textView.setText("등록 상태: " + mameBiosStatus());
        textView.setTextColor(Theme.text(Color.rgb(205, 211, 218)));
        textView.setTextSize(13.0f);
        int i = 10;
        textView.setPadding(0, dp(8), 0, dp(10));
        linearLayout.addView(textView);
        File[] listFiles = mameBiosDir().listFiles(MainActivity::isZipFile);
        if (listFiles == null || listFiles.length == 0) {
            TextView textView2 = new TextView(this);
            textView2.setText("아직 등록된 MAME BIOS가 없습니다.");
            textView2.setTextColor(Theme.text(Color.rgb(190, 197, 204)));
            textView2.setTextSize(14.0f);
            textView2.setGravity(17);
            textView2.setPadding(0, dp(24), 0, dp(24));
            linearLayout.addView(textView2);
        } else {
            Arrays.sort(listFiles, Comparator.comparing((File f) -> f.getName().toLowerCase(Locale.US)));
            int length = listFiles.length;
            int i2 = 0;
            while (i2 < length) {
                final File file = listFiles[i2];
                LinearLayout linearLayout2 = new LinearLayout(this);
                linearLayout2.setOrientation(1);
                linearLayout2.setPadding(0, dp(i), 0, dp(i));
                TextView textView3 = new TextView(this);
                textView3.setText(file.getName());
                textView3.setTextColor(Theme.text(Color.rgb(242, 244, 247)));
                textView3.setTextSize(15.0f);
                textView3.setTypeface(Typeface.DEFAULT_BOLD);
                linearLayout2.addView(textView3);
                TextView textView4 = new TextView(this);
                textView4.setText(mameBiosDetail(file));
                textView4.setTextColor(Theme.text(Color.rgb(195, 202, 210)));
                textView4.setTextSize(12.0f);
                textView4.setPadding(0, dp(2), 0, 0);
                linearLayout2.addView(textView4);
                linearLayout2.setOnLongClickListener(view -> onMameBiosLongClick(file, alertDialogArr, view));
                linearLayout.addView(linearLayout2);
                View view = new View(this);
                view.setBackgroundColor(Theme.bg(Color.rgb(105, 110, 116)));
                linearLayout.addView(view, new LinearLayout.LayoutParams(-1, dp(1)));
                i2++;
                i = 10;
            }
        }
        TextView textView5 = new TextView(this);
        textView5.setText("기판별 BIOS ZIP을 원본 파일명 그대로 등록하세요.");
        textView5.setTextColor(Theme.text(Color.rgb(185, 192, 200)));
        textView5.setTextSize(12.0f);
        textView5.setPadding(0, dp(12), 0, dp(4));
        linearLayout.addView(textView5);
        ScrollView scrollView = new ScrollView(this);
        scrollView.addView(linearLayout, new FrameLayout.LayoutParams(-1, -2));
        android.app.Dialog create = new AppDialog.Builder(this).setTitle("MAME BIOS 관리").setView(scrollView).setNegativeButton("닫기", (DialogInterface.OnClickListener) null).setPositiveButton("BIOS 가져오기", (dialogInterface, i3) -> openMameBiosPicker()).create();
        alertDialogArr[0] = create;
        create.show();
    }

    private static boolean isZipFile(File file) {
        return file.isFile() && file.getName().toLowerCase(Locale.US).endsWith(".zip");
    }

    private boolean onMameBiosLongClick(File file, android.app.Dialog[] alertDialogArr, View view) {
        confirmDeleteMameBios(file, alertDialogArr[0]);
        return true;
    }

    private void confirmDeleteMameBios(final File file, final android.app.Dialog alertDialog) {
        new AppDialog.Builder(this).setTitle("MAME BIOS 삭제").setMessage(file.getName() + "을(를) 삭제할까요?").setNegativeButton("취소", (DialogInterface.OnClickListener) null).setPositiveButton("삭제", (dialogInterface, i) -> deleteMameBiosConfirmed(file, alertDialog, dialogInterface, i)).show();
    }

    private void deleteMameBiosConfirmed(File file, android.app.Dialog alertDialog, DialogInterface dialogInterface, int i) {
        if (deleteMameBios(file)) {
            showMessage("MAME BIOS를 삭제했습니다.");
            updateHomeStatusCards();
            updateNote();
            if (alertDialog != null) {
                alertDialog.dismiss();
            }
            showMameBiosManager();
            return;
        }
        showError("MAME BIOS를 삭제할 수 없습니다.");
    }

    private boolean deleteMameBios(File file) {
        if (file.getName().equalsIgnoreCase("stvbios.zip")) {
            removeMergedBiosEntries(new File(arcadeRomDir(), "twcup98.zip"), file);
            File file2 = new File(arcadeRomDir(), "stvbios.zip");
            if (file2.exists() && !file2.delete()) {
                return false;
            }
        }
        return !file.exists() || file.delete();
    }

    @Override
    protected void onActivityResult(int i, int i2, Intent intent) {
        super.onActivityResult(i, i2, intent);
        if (i == REQUEST_PS2_RECIPE) {
            onPs2RecipePicked(i2 == -1 ? intent : null);  // back to the confirm screen either way
            return;
        }
        if (i2 != -1 || intent == null) {
            return;
        }
        Uri data = intent.getData();
        if (i == REQUEST_ARCHIVE_PARTS) {
            List<Uri> merged = this.pendingArchiveUris == null ? new ArrayList<>() : this.pendingArchiveUris;
            java.util.function.Consumer<List<Uri>> resume = this.pendingArchiveResume;
            this.pendingArchiveUris = null;
            this.pendingArchiveResume = null;
            android.content.ClipData clip = intent.getClipData();
            for (int k = 0; clip != null && k < clip.getItemCount(); k++) {
                Uri u = clip.getItemAt(k).getUri();
                if (u != null && !merged.contains(u)) {
                    merged.add(u);
                }
            }
            if (clip == null && intent.getData() != null && !merged.contains(intent.getData())) {
                merged.add(intent.getData());
            }
            if (resume != null) {
                // Only the parts of the same set.
                List<Uri> same = new ArrayList<>();
                String key = merged.isEmpty() ? null : displayNameFor(merged.get(0));
                for (Uri u : merged) {
                    if (key == null || RarReader.sameSet(displayNameFor(u), key)) {
                        same.add(u);
                    }
                }
                resume.accept(same.isEmpty() ? merged : same);
            }
            return;
        }
        if (i == REQUEST_OVERLAY_FILE || i == REQUEST_OVERLAY_FOLDER) {
            File game = this.overlayGame;
            this.overlayGame = null;
            onOverlayPicked(game, intent.getData(), i == REQUEST_OVERLAY_FOLDER);
            return;
        }
        if (i == REQUEST_PICK_NAND) {
            if (intent.getData() != null) {
                onNandPicked(intent.getData());
            }
            return;
        }
        if (i == REQUEST_PICK_NAND_KEYS) {
            if (intent.getData() != null) {
                onNandKeysPicked(intent.getData());
            }
            return;
        }
        if (i == REQUEST_CLOUD_FOLDER) {
            onCloudFolderPicked(intent);
            return;
        }
        if (i == REQUEST_PS3_INSTALL) {
            List<Uri> uris = new ArrayList<>();
            android.content.ClipData clip = intent.getClipData();
            if (clip != null) {
                for (int k = 0; k < clip.getItemCount(); k++) {
                    if (clip.getItemAt(k).getUri() != null) uris.add(clip.getItemAt(k).getUri());
                }
            } else if (intent.getData() != null) {
                uris.add(intent.getData());
            }
            if (!uris.isEmpty()) startPs3Install(uris, this.ps3PendingGame);
            return;
        }
        if (i == REQUEST_PS3_HANPATCH) {
            if (intent.getData() != null) onPs3HanPatchPicked(intent.getData());
            return;
        }
        if (i == REQUEST_PS3_SAVE_IMPORT) {
            if (intent.getData() != null) onPs3SaveImportPicked(intent.getData());
            return;
        }
        if (i == REQUEST_IMPORT_PS3_FIRMWARE) {
            // The install runs in the PS3 engine's own process; Ps3Activity shows its progress.
            Intent install = new Intent(this, Ps3Activity.class);
            install.putExtra(Ps3Activity.EXTRA_ACTION, Ps3Activity.ACTION_FIRMWARE);
            install.setData(intent.getData());
            install.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
            startActivity(install);
            return;
        }
        if (i == REQUEST_PICK_PATCH_PREP) {
            onPrepPatchesPicked(intent);
            return;
        }

        if (i == REQUEST_PICK_PATCH) {
            if (this.patchRom != null && isDiscSheet(this.patchRom)) {
                List<Uri> uris = new ArrayList<>();
                android.content.ClipData clip = intent.getClipData();
                for (int k = 0; clip != null && k < clip.getItemCount(); k++) {
                    if (clip.getItemAt(k).getUri() != null) {
                        uris.add(clip.getItemAt(k).getUri());
                    }
                }
                if (uris.isEmpty() && data != null) {
                    uris.add(data);
                }
                onDiscPatchesPicked(uris);
                return;
            }
            onPatchPicked(data);
            return;
        }
        if (i == REQUEST_PICK_DLC_ZIP || i == REQUEST_PICK_DLC_FOLDER) {
            onDlcPicked(intent, i == REQUEST_PICK_DLC_ZIP);
            return;
        }
        if (i == REQUEST_OPEN_ROM_FOLDER) {
            String mode = this.pendingFolderMode;
            this.pendingFolderMode = null;
            if (data != null && mode != null) {
                scanRomFolder(data, mode);
            }
            return;
        }
        if (i == REQUEST_OPEN_BIOS_FOLDER) {
            String source = this.pendingBiosSource;
            this.pendingBiosSource = null;
            if (data != null) {
                importBiosFolder(data, source);
            }
            return;
        }
        if (i == 1001) {
            importRoms(intent, MODE_GBA);
            return;
        }
        for (String[] console : CONSOLES) {
            if (i == Integer.parseInt(console[5])) {
                importRoms(intent, console[0]);
                return;
            }
        }
        if (i == 1005) {
            importArcadeRoms(intent);
            return;
        }
        if (i == 1002) {
            if (data == null) {
                return;
            }
            exportSave(data);
            return;
        }
        if (i == 1003) {
            if (data == null) {
                return;
            }
            importSave(data);
        } else if (i == 1004) {
            if (data == null) {
                return;
            }
            importBios(data);
        } else if (i == 1006) {
            if (data != null) {
                importNeoGeoBios(data);
            }
        } else if (i == REQUEST_IMPORT_PCE_BIOS) {
            if (data != null) {
                importPceBios(data);
            }
        } else if (i == REQUEST_IMPORT_SATURN_BIOS) {
            if (data != null) {
                importSaturnBios(data);
            }
        } else if (i == REQUEST_IMPORT_MCD_BIOS) {
            importMcdBios(intent);
        } else if (i == REQUEST_IMPORT_DC_BIOS) {
            if (data != null) {
                importDcBios(data);
            }
        } else if (i == REQUEST_IMPORT_NAOMI_BIOS) {
            importNaomiBios(intent);
        } else if (i == REQUEST_NAOMI_BIOS_TREE) {
            if (data != null) {
                importNaomiBiosFromTree(data);
            }
        } else if (i == REQUEST_DOS_SF2 || i == REQUEST_DOS_MT32 || i == REQUEST_DOS_SC55) {
            onDosMidiPicked(i, intent);
        } else if (i == REQUEST_DOS_CONF) {
            onDosConfPicked(intent);
        } else if (i == REQUEST_DOS_PATCH) {
            onDosPatchPicked(intent);
        } else if (i == REQUEST_PC98_FILE_PATCH) {
            onPc98FilePatchPicked(intent);
        } else if (i == REQUEST_PC98_FONT) {
            onPc98FontPicked(intent);
        } else if (i == REQUEST_VITA_FIRMWARE) {
            onVitaFirmwarePicked(intent);
        } else if (i == REQUEST_ARC_PATCH) {
            onArcadePatchPicked(intent);
        } else if (i == REQUEST_VITA_LICENSE) {
            onVitaLicensePicked(intent);
        } else if (i == REQUEST_X360_PATCH) {
            onX360PatchPicked(intent);
        } else if (i == REQUEST_VITA_KOPATCH) {
            onVitaKoPatchPicked(intent);
        } else if (i == REQUEST_VITA_ADDON) {
            onVitaAddonPicked(intent);
        } else if (i == REQUEST_IMPORT_WIIU_KEYS) {
            if (data != null) {
                importWiiuKeys(data);
            }
        } else if (i == REQUEST_IMPORT_N3DS_KEYS) {
            if (data != null) {
                importN3dsKeys(data);
            }
        } else if (i == REQUEST_PICK_CIA) {
            onCiaPicked(intent);
        } else if (i == REQUEST_IMPORT_PS1_BIOS) {
            if (data != null) {
                importPs1Bios(data);
            }
        } else if (i == REQUEST_IMPORT_PC98_BIOS) {
            importPc98Bios(intent);
        } else if (i == REQUEST_PICK_COVER) {
            File rom = this.pendingCoverRom;
            this.pendingCoverRom = null;
            if (data != null && rom != null) {
                Covers.setCustom(this, rom, data, () -> {
                    onCoverFound(rom, null);
                    showMessage("표지를 바꿨어요.");
                }, () -> showError("이 사진을 열 수 없습니다."));
            }
        } else if (i == REQUEST_IMPORT_PS2_BIOS) {
            if (data != null) {
                importPs2Bios(data);
            }
        } else if (i == 1007) {
            importMameBios(intent);
        }
    }

    private void importRoms(Intent intent, String mode) {
        if (MODE_PS2.equals(mode) && ps2PickedBins(intent)) {
            startPs2BinImport(intent);
            return;
        }
        if (MODE_PSP.equals(mode) || MODE_PS1.equals(mode) || MODE_PS2.equals(mode) || MODE_PS3.equals(mode) || MODE_X360.equals(mode) || MODE_PCE.equals(mode) || MODE_WIIU.equals(mode) || MODE_DOS.equals(mode)) {
            // Disc images run to gigabytes; copy them off the UI thread.
            final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
            progress.setTitle(MODE_NAMES[modeIndex(mode)] + " 게임 가져오기");
            progress.setMessage("복사 중… 용량이 커서 시간이 걸릴 수 있어요");
            progress.setCancelable(false);
            progress.show();
            new Thread(() -> {
                final ImportOutcome outcome = copyRoms(intent, mode);
                runOnUiThread(() -> {
                    if (isFinishing() || isDestroyed()) {
                        return;
                    }
                    progress.dismiss();
                    finishRomImport(outcome);
                });
            }, "import").start();
            return;
        }
        finishRomImport(copyRoms(intent, mode));
    }

    // ---- PS2, .cue / .bin 바꿔 넣기 (0.0.380): PS2 engines take .iso / .chd / .cso, so a
    // picked .cue + .bin (or a lone .bin) is turned into a plain .iso of the 2048-byte sectors
    // (Ps2BinImport), after a look at what it is and the room it needs. The other picked files
    // go on through the usual import. ----
    private static List<Uri> pickedUris(Intent intent) {
        List<Uri> out = new ArrayList<>();
        ClipData clip = intent.getClipData();
        if (clip != null) {
            for (int k = 0; k < clip.getItemCount(); k++) {
                Uri uri = clip.getItemAt(k).getUri();
                if (uri != null) out.add(uri);
            }
        } else if (intent.getData() != null) {
            out.add(intent.getData());
        }
        return out;
    }

    private boolean ps2PickedBins(Intent intent) {
        for (Uri uri : pickedUris(intent)) {
            String name = displayNameFor(uri).toLowerCase(Locale.ROOT);
            if (name.endsWith(".cue") || name.endsWith(".bin")) return true;
        }
        return false;
    }

    private static final class Ps2BinJob {
        Uri bin;
        Uri cue;
        String title;
        long size;
        Ps2BinImport.Layout layout;
        int tracks;
        File made;
        Ps2Recipe recipe;   // a 레시피형 patch for this .bin (0.0.383)
        boolean patch;
        String note;
    }

    private void startPs2BinImport(Intent intent) {
        startPs2BinImport(pickedUris(intent), new java.util.HashMap<>());
    }

    // picked: what the player chose; companions: other .bin files of the same folder (by
    // lower-case name), where a picked .cue's data file may be.
    private void startPs2BinImport(final List<Uri> all, final java.util.Map<String, Uri> companions) {
        final android.app.ProgressDialog looking = new android.app.ProgressDialog(this);
        looking.setTitle("PS2 게임 가져오기");
        looking.setMessage(".cue / .bin 살펴보는 중…");
        looking.setCancelable(false);
        looking.show();
        new Thread(() -> {
            final List<Ps2BinJob> jobs = new ArrayList<>();
            final List<Uri> rest = new ArrayList<>();
            final StringBuilder errors = new StringBuilder();
            java.util.Map<String, Uri> bins = new java.util.LinkedHashMap<>();
            java.util.Set<Uri> used = new java.util.HashSet<>();
            List<Ps2Recipe> recipes = new ArrayList<>();
            List<Uri> jsons = new ArrayList<>();
            for (Uri uri : all) {
                String name = displayNameFor(uri);
                String lower = name.toLowerCase(Locale.ROOT);
                if (lower.endsWith(".json")) jsons.add(uri);
            }
            for (Uri uri : all) {
                String name = displayNameFor(uri);
                String lower = name.toLowerCase(Locale.ROOT);
                if (lower.endsWith(".bin") && !lower.equals("patch.bin")) bins.put(lower, uri);
            }
            for (Uri json : jsons) {
                Uri payload = null;
                for (Uri uri : all) {
                    if (displayNameFor(uri).equalsIgnoreCase("patch.bin")) payload = uri;
                }
                Ps2Recipe recipe = loadRecipeJson(json, payload);
                if (recipe != null) recipes.add(recipe);
            }
            for (Uri uri : all) {
                String name = displayNameFor(uri);
                String lower = name.toLowerCase(Locale.ROOT);
                if (lower.endsWith(".bin") || lower.endsWith(".json")) {
                    continue;
                }
                if (lower.endsWith(".zip") && sizeForUri(uri) < (600L << 20)) {
                    Ps2Recipe recipe = loadRecipeZip(uri);
                    if (recipe != null) {
                        recipes.add(recipe);
                        continue;
                    }
                }
                if (!lower.endsWith(".cue")) {
                    rest.add(uri);
                    continue;
                }
                Ps2BinImport.Cue cue = null;
                try (InputStream in = getContentResolver().openInputStream(uri)) {
                    if (in != null) {
                        java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
                        byte[] buffer = new byte[8192];
                        int n;
                        while ((n = in.read(buffer)) > 0 && bytes.size() < (1 << 20)) bytes.write(buffer, 0, n);
                        cue = Ps2BinImport.parseCue(bytes.toByteArray());
                    }
                } catch (IOException | RuntimeException ignored) {
                }
                if (cue == null) {
                    errors.append(name).append(": .cue를 읽지 못했어요\n");
                    continue;
                }
                Uri bin = bins.get(cue.file.toLowerCase(Locale.ROOT));
                if (bin == null) {
                    bin = companions.get(cue.file.toLowerCase(Locale.ROOT));
                }
                if (bin == null) {
                    // Beside the .cue on the phone (with 모든 파일 접근).
                    File real = realFileFor(uri);
                    File[] side = real != null && real.getParentFile() != null ? real.getParentFile().listFiles() : null;
                    for (int k = 0; side != null && k < side.length; k++) {
                        if (side[k].isFile() && side[k].getName().equalsIgnoreCase(cue.file)) bin = Uri.fromFile(side[k]);
                    }
                }
                if (bin == null) {
                    errors.append(name).append(": 짝 파일 ").append(cue.file).append("을(를) 같이 골라 주세요\n");
                    continue;
                }
                if (!cue.dataFirst) {
                    errors.append(name).append(": 첫 트랙이 데이터가 아니에요 (PS2 게임 디스크가 아닌 것 같아요)\n");
                    continue;
                }
                used.add(bin);
                Ps2BinJob job = new Ps2BinJob();
                job.bin = bin;
                job.cue = uri;
                job.title = baseNameWithoutExtension(name);
                job.tracks = cue.tracks;
                jobs.add(job);
            }
            for (Uri bin : bins.values()) {
                if (used.contains(bin)) continue;
                Ps2BinJob job = new Ps2BinJob();
                job.bin = bin;
                job.title = baseNameWithoutExtension(displayNameFor(bin));
                jobs.add(job);
            }
            for (java.util.Iterator<Ps2BinJob> it = jobs.iterator(); it.hasNext(); ) {
                Ps2BinJob job = it.next();
                job.size = sizeForUri(job.bin);
                byte[] head = new byte[Ps2BinImport.RAW_SUB * 2];
                int got = 0;
                try (InputStream in = getContentResolver().openInputStream(job.bin)) {
                    while (in != null && got < head.length) {
                        int n = in.read(head, got, head.length - got);
                        if (n < 0) break;
                        got += n;
                    }
                } catch (IOException | RuntimeException ignored) {
                }
                job.layout = job.size > 0 ? Ps2BinImport.detect(head, got, job.size) : null;
                if (job.layout == null) {
                    errors.append(job.title).append(".bin: PS2 디스크 이미지로 읽지 못했어요\n");
                    it.remove();
                    continue;
                }
                // A 레시피형 patch picked with it, or beside it on the phone (0.0.383).
                job.recipe = recipeFor(job, recipes);
                if (job.recipe == null) {
                    File real = "file".equals(job.bin.getScheme()) && job.bin.getPath() != null ? new File(job.bin.getPath()) : realFileFor(job.bin);
                    if (real != null && real.getParentFile() != null) {
                        job.recipe = recipeFor(job, findRecipesBeside(real.getParentFile()));
                    }
                }
                job.patch = job.recipe != null;
            }
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                looking.dismiss();
                if (jobs.isEmpty()) {
                    if (errors.length() > 0) showError(errors.toString().trim());
                    continuePs2Import(rest, new ArrayList<>(), errors, 0);
                    return;
                }
                showPs2BinConfirm(jobs, rest, errors);
            });
        }, "ps2-bin-look").start();
    }

    // The PS2 .cue files of a folder, and the .bin files no .cue there stands for (0.0.382).
    private static List<File> ps2CueBins(File dir) {
        List<File> out = new ArrayList<>();
        File[] files = dir.listFiles();
        if (files == null) return out;
        java.util.Set<String> covered = new java.util.HashSet<>();
        for (File f : files) {
            if (f.isFile() && f.getName().toLowerCase(Locale.ROOT).endsWith(".cue")) {
                out.add(f);
                for (String track : cueTracks(f)) covered.add(track.toLowerCase(Locale.ROOT));
            }
        }
        for (File f : files) {
            String lower = f.getName().toLowerCase(Locale.ROOT);
            if (f.isFile() && lower.endsWith(".bin") && !covered.contains(lower)) out.add(f);
        }
        java.util.Collections.sort(out, (a, b) -> a.getName().compareToIgnoreCase(b.getName()));
        return out;
    }

    private static void collectPs2CueBins(File dir, int depth, List<File> out) {
        out.addAll(ps2CueBins(dir));
        File[] files = depth <= 0 ? null : dir.listFiles();
        for (File f : files == null ? new File[0] : files) {
            if (f.isDirectory() && !f.getName().startsWith(".")) collectPs2CueBins(f, depth - 1, out);
        }
    }

    private static long ps2DiscBytes(File disc) {
        if (!disc.getName().toLowerCase(Locale.ROOT).endsWith(".cue")) return disc.length();
        long sum = 0;
        for (String track : cueTracks(disc)) sum += new File(disc.getParentFile(), track).length();
        return sum > 0 ? sum : disc.length();
    }

    // Files on the phone (모든 파일 접근) through the same .iso conversion as picked ones.
    private void startPs2DiscFiles(List<File> discs) {
        List<Uri> uris = new ArrayList<>();
        java.util.Map<String, Uri> companions = new java.util.HashMap<>();
        for (File disc : discs) {
            uris.add(Uri.fromFile(disc));
            File[] side = disc.getParentFile() == null ? null : disc.getParentFile().listFiles();
            for (File f : side == null ? new File[0] : side) {
                if (f.isFile() && f.getName().toLowerCase(Locale.ROOT).endsWith(".bin")) {
                    companions.putIfAbsent(f.getName().toLowerCase(Locale.ROOT), Uri.fromFile(f));
                }
            }
        }
        startPs2BinImport(uris, companions);
    }

    // ---- 레시피형 패치 (0.0.383): patch.json (format …-bin-to-iso-v1) + patch.bin, loose or
    // in a zip; see Ps2Recipe. ----
    private Ps2Recipe recipeFor(Ps2BinJob job, List<Ps2Recipe> recipes) {
        for (Ps2Recipe recipe : recipes) {
            if (recipe.sourceSize == job.size && job.layout != null && job.layout.isoSize(job.size) == recipe.targetSize) return recipe;
        }
        return null;
    }

    private static String readSmallText(InputStream in) throws IOException {
        java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
        byte[] buffer = new byte[16384];
        int n;
        while ((n = in.read(buffer)) > 0) {
            bytes.write(buffer, 0, n);
            if (bytes.size() > (8 << 20)) throw new IOException("too big");
        }
        return new String(bytes.toByteArray(), StandardCharsets.UTF_8);
    }

    // patch.json from a Uri; patch.bin picked with it, else beside it on the phone.
    private Ps2Recipe loadRecipeJson(Uri json, Uri payload) {
        if (sizeForUri(json) > (8 << 20)) return null;
        Ps2Recipe recipe;
        try (InputStream in = getContentResolver().openInputStream(json)) {
            recipe = in == null ? null : Ps2Recipe.parse(readSmallText(in));
        } catch (IOException | RuntimeException e) {
            return null;
        }
        if (recipe == null) return null;
        Uri bin = payload;
        File real = "file".equals(json.getScheme()) && json.getPath() != null ? new File(json.getPath()) : realFileFor(json);
        if (bin == null && real != null && real.getParentFile() != null) {
            File side = new File(real.getParentFile(), "patch.bin");
            if (side.isFile()) bin = Uri.fromFile(side);
        }
        if (bin == null) return null;
        final Uri source = bin;
        recipe.payload = () -> getContentResolver().openInputStream(source);
        recipe.sourceName = (real != null && real.getParentFile() != null ? real.getParentFile().getName() + "/" : "") + displayNameFor(json);
        return recipe;
    }

    private static boolean isEntry(String name, String file) {
        String lower = name.replace('\\', '/').toLowerCase(Locale.ROOT);
        return lower.equals(file) || lower.endsWith("/" + file);
    }

    // A zip holding patch.json and patch.bin.
    private Ps2Recipe loadRecipeZip(Uri zip) {
        final String zipName = displayNameFor(zip);
        File real = "file".equals(zip.getScheme()) && zip.getPath() != null ? new File(zip.getPath()) : realFileFor(zip);
        if (real != null && real.isFile()) {
            return loadRecipeZipFile(real);
        }
        String json = null;
        try (java.util.zip.ZipInputStream in = new java.util.zip.ZipInputStream(getContentResolver().openInputStream(zip), StandardCharsets.ISO_8859_1)) {
            java.util.zip.ZipEntry entry;
            while ((entry = in.getNextEntry()) != null) {
                if (isEntry(entry.getName(), "patch.json")) {
                    json = readSmallText(in);
                    break;
                }
            }
        } catch (IOException | RuntimeException e) {
            return null;
        }
        Ps2Recipe recipe = json == null ? null : Ps2Recipe.parse(json);
        if (recipe == null) return null;
        recipe.payload = () -> {
            java.util.zip.ZipInputStream in = new java.util.zip.ZipInputStream(getContentResolver().openInputStream(zip), StandardCharsets.ISO_8859_1);
            java.util.zip.ZipEntry entry;
            while ((entry = in.getNextEntry()) != null) {
                if (isEntry(entry.getName(), "patch.bin")) return in;
            }
            in.close();
            throw new IOException(zipName + " 안에 patch.bin이 없어요");
        };
        recipe.sourceName = zipName;
        return recipe;
    }

    private static Ps2Recipe loadRecipeZipFile(final File file) {
        try (java.util.zip.ZipFile zip = new java.util.zip.ZipFile(file, StandardCharsets.ISO_8859_1)) {
            java.util.zip.ZipEntry json = null;
            java.util.zip.ZipEntry bin = null;
            java.util.Enumeration<? extends java.util.zip.ZipEntry> entries = zip.entries();
            while (entries.hasMoreElements()) {
                java.util.zip.ZipEntry entry = entries.nextElement();
                if (isEntry(entry.getName(), "patch.json")) json = entry;
                if (isEntry(entry.getName(), "patch.bin")) bin = entry;
            }
            if (json == null || bin == null) return null;
            Ps2Recipe recipe;
            try (InputStream in = zip.getInputStream(json)) {
                recipe = Ps2Recipe.parse(readSmallText(in));
            }
            if (recipe == null) return null;
            final String binName = bin.getName();
            recipe.payload = () -> {
                final java.util.zip.ZipFile open = new java.util.zip.ZipFile(file, StandardCharsets.ISO_8859_1);
                java.util.zip.ZipEntry entry = open.getEntry(binName);
                if (entry == null) {
                    open.close();
                    throw new IOException("patch.bin을 찾지 못했어요");
                }
                return new java.io.FilterInputStream(open.getInputStream(entry)) {
                    @Override
                    public void close() throws IOException {
                        super.close();
                        open.close();
                    }
                };
            };
            recipe.sourceName = file.getName();
            return recipe;
        } catch (IOException | RuntimeException e) {
            return null;
        }
    }

    // patch.json + patch.bin in a folder (and its sub folders, a level down), or zips there.
    private static List<Ps2Recipe> findRecipesBeside(File dir) {
        List<Ps2Recipe> out = new ArrayList<>();
        List<File> places = new ArrayList<>();
        places.add(dir);
        File[] subs = dir.listFiles(File::isDirectory);
        for (int k = 0; subs != null && k < subs.length && k < 20; k++) places.add(subs[k]);
        for (File place : places) {
            File json = new File(place, "patch.json");
            File bin = new File(place, "patch.bin");
            if (json.isFile() && bin.isFile() && json.length() < (8 << 20)) {
                try (InputStream in = new java.io.FileInputStream(json)) {
                    Ps2Recipe recipe = Ps2Recipe.parse(readSmallText(in));
                    if (recipe != null) {
                        recipe.payload = () -> new java.io.FileInputStream(bin);
                        recipe.sourceName = place.getName() + "/patch.json";
                        out.add(recipe);
                    }
                } catch (IOException | RuntimeException ignored) {
                }
            }
            File[] zips = place.listFiles((d, n) -> n.toLowerCase(Locale.ROOT).endsWith(".zip"));
            for (File zip : zips == null ? new File[0] : zips) {
                if (zip.length() < (600L << 20)) {
                    Ps2Recipe recipe = loadRecipeZipFile(zip);
                    if (recipe != null) out.add(recipe);
                }
            }
        }
        return out;
    }

    // The picked files hold a 레시피형 patch (zip, or patch.json + patch.bin): it goes on a
    // copy of the .iso, kept only when that copy hashes to the patch's finished value. The
    // .iso must be the plain conversion of the patch's original .bin (same size; the final
    // check proves the rest).
    private boolean offerPs2RecipeOnIso(final File iso, List<Uri> picked) {
        boolean candidate = false;
        for (Uri uri : picked) {
            String lower = displayNameFor(uri).toLowerCase(Locale.ROOT);
            candidate |= lower.endsWith(".json") || (lower.endsWith(".zip") && sizeForUri(uri) < (600L << 20));
        }
        if (!candidate) return false;
        Ps2Recipe recipe = null;
        Uri payload = null;
        for (Uri uri : picked) if (displayNameFor(uri).equalsIgnoreCase("patch.bin")) payload = uri;
        for (Uri uri : picked) {
            String lower = displayNameFor(uri).toLowerCase(Locale.ROOT);
            if (recipe == null && lower.endsWith(".json")) recipe = loadRecipeJson(uri, payload);
            if (recipe == null && lower.endsWith(".zip")) recipe = loadRecipeZip(uri);
        }
        if (recipe == null) {
            boolean json = false;
            for (Uri uri : picked) json |= displayNameFor(uri).toLowerCase(Locale.ROOT).endsWith(".json");
            if (!json) return false;  // a zip of ordinary patches: the usual way
            this.prepError = payload == null ? "patch.json과 patch.bin을 같이 골라 주세요 (또는 둘이 든 ZIP)." : "읽을 수 있는 패치(patch.json …-bin-to-iso-v1)가 아니에요.";
            renderPatchPrep();
            return true;
        }
        if (this.prepDialog != null && this.prepDialog.isShowing()) {
            this.prepDialog.dismiss();
        }
        if (iso.length() != recipe.targetSize) {
            showError("이 패치는 이 .iso에 맞지 않아요.\n\n패치가 바라는 .iso 크기: " + String.format(Locale.ROOT, "%,d", recipe.targetSize)
                    + "바이트\n이 .iso: " + String.format(Locale.ROOT, "%,d", iso.length()) + "바이트\n\n원본 .bin(" + String.format(Locale.ROOT, "%,d", recipe.sourceSize)
                    + "바이트)을 PS2 › ROM 추가로 다시 넣으면서 패치를 함께 적용할 수도 있어요.");
            return true;
        }
        long free = iso.getParentFile() == null ? 0 : iso.getParentFile().getUsableSpace();
        final Ps2Recipe chosen = recipe;
        String title = displayGameNameFor(iso);
        new AppDialog.Builder(this).setTitle("레시피형 패치 적용")
                .setMessage(title + "\n\n패치: " + recipe.sourceName + " · 조각 " + recipe.pieces() + "개 · " + megabytes(recipe.payloadBytes())
                        + "\n이 .iso는 그대로 두고, 복사본에 패치해서 \"" + title + " " + recipe.suffix() + "\"로 넣어요."
                        + "\n완성본 검사값(SHA-256)이 패치와 맞을 때만 넣어요.\n\n필요한 빈 공간: 약 " + megabytes(iso.length())
                        + " · 남은 공간 " + String.format(Locale.ROOT, "%.1f GB", free / 1073741824.0))
                .setNegativeButton("취소", null)
                .setPositiveButton("패치해서 넣기", (d, w) -> {
                    if (free > 0 && free < iso.length() + (64L << 20)) {
                        showError("빈 공간이 모자라요.");
                        return;
                    }
                    runPs2RecipeOnIso(iso, chosen, title);
                })
                .show();
        return true;
    }

    private void runPs2RecipeOnIso(final File iso, final Ps2Recipe recipe, final String title) {
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setTitle("패치한 .iso 만드는 중…");
        progress.setProgressStyle(android.app.ProgressDialog.STYLE_HORIZONTAL);
        progress.setMax(1000);
        progress.setProgressNumberFormat(null);
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            String error = null;
            File made = null;
            String outTitle = title + " " + recipe.suffix();
            File out = uniqueFile(iso.getParentFile(), sanitizeFileName(outTitle + ".iso"));
            Ps2Recipe.Progress show = (done, all) -> {
                int permille = all > 0 ? (int) (done * 1000 / all) : 0;
                runOnUiThread(() -> progress.setProgress(permille));
            };
            try {
                runOnUiThread(() -> progress.setMessage("1/3 복사본 만드는 중…"));
                try (InputStream in = new java.io.FileInputStream(iso); java.io.OutputStream os = new FileOutputStream(out)) {
                    byte[] buffer = new byte[1 << 20];
                    long done = 0;
                    int n;
                    while ((n = in.read(buffer)) > 0) {
                        os.write(buffer, 0, n);
                        done += n;
                        show.at(done, iso.length());
                    }
                }
                runOnUiThread(() -> progress.setMessage("2/3 패치 조각 덮어쓰는 중…"));
                try (java.io.RandomAccessFile raf = new java.io.RandomAccessFile(out, "rw")) {
                    recipe.apply(raf, show);
                    raf.getFD().sync();
                }
                runOnUiThread(() -> progress.setMessage("3/3 완성본 확인하는 중…"));
                String finished = Ps2Recipe.sha256Of(out, show);
                if (!recipe.targetSha.equals(finished)) {
                    throw new IOException("완성본 검사값이 패치와 달라요. 이 .iso가 패치의 원본에서 만든 것이 아니거나(다른 판본 · 이미 고친 파일), 패치 파일이 손상됐어요");
                }
                made = finalizeImportedRom(out, outTitle);
                if (made == null) {
                    error = "같은 게임(패치한 .iso)이 이미 목록에 있어요";
                }
            } catch (IOException | RuntimeException e) {
                out.delete();
                error = e.getMessage();
            }
            final String failure = error;
            final File result = made;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                progress.dismiss();
                refreshLibrary();
                if (failure != null) {
                    showError("패치하지 못했어요.\n\n" + failure + "\n\n원래 .iso는 그대로예요.");
                } else {
                    showMessage("패치를 적용해서 넣었어요 · 완성본 검사값 맞음\n\n" + result.getName() + "\n원래 .iso는 그대로 남아 있어요 (필요 없으면 지워도 돼요).");
                }
            });
        }, "ps2-recipe-iso").start();
    }

    private static String megabytes(long bytes) {
        return String.format(Locale.ROOT, "%.1f MB", bytes / 1048576.0);
    }

    private void showPs2BinConfirm(List<Ps2BinJob> jobs, List<Uri> rest, StringBuilder errors) {
        long need = 0;
        StringBuilder text = new StringBuilder();
        for (Ps2BinJob job : jobs) {
            long iso = job.layout.isoSize(job.size);
            need += iso;
            text.append("■ ").append(job.title).append('\n')
                    .append("원본: .bin ").append(String.format(Locale.ROOT, "%,d", job.size)).append("바이트 (").append(megabytes(job.size)).append(")\n")
                    .append("디스크 형식: ").append(job.layout.describe()).append('\n')
                    .append("결과: .iso ").append(String.format(Locale.ROOT, "%,d", iso)).append("바이트 (").append(megabytes(iso)).append(")\n");
            if (job.tracks > 1) {
                text.append("트랙 ").append(job.tracks).append("개 중 첫 데이터 트랙만 써요 (오디오 트랙은 빠져요)\n");
            }
            if (job.recipe != null) {
                text.append("패치: ").append(job.recipe.sourceName).append(" · 조각 ").append(job.recipe.pieces()).append("개 · ")
                        .append(megabytes(job.recipe.payloadBytes())).append(" · 이 원본용 (크기 맞음)\n");
            }
            text.append('\n');
        }
        boolean anyRecipe = false;
        for (Ps2BinJob job : jobs) anyRecipe |= job.recipe != null;
        long free = romDirFor(MODE_PS2).getUsableSpace();
        text.append("필요한 빈 공간: 약 ").append(megabytes(need)).append(" · 지금 남은 공간 ").append(String.format(Locale.ROOT, "%.1f GB", free / 1073741824.0));
        if (errors.length() > 0) {
            text.append("\n\n못 넣는 파일:\n").append(errors.toString().trim());
        }
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        int pad = (int) (8 * getResources().getDisplayMetrics().density);
        box.setPadding(pad * 2, pad, pad * 2, 0);
        TextView info = new TextView(this);
        info.setText(text);
        info.setTextSize(13f);
        info.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        box.addView(info);
        TextView label = new TextView(this);
        label.setText("\n바꾼 뒤 원본 .cue / .bin");
        label.setTextSize(13f);
        label.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
        label.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        box.addView(label);
        android.widget.RadioGroup group = new android.widget.RadioGroup(this);
        android.widget.RadioButton keep = new android.widget.RadioButton(this);
        keep.setText("그대로 두기 (기본)");
        keep.setId(View.generateViewId());
        android.widget.RadioButton drop = new android.widget.RadioButton(this);
        drop.setText("지우기 (바꾸기가 끝나고 검사가 맞을 때만)");
        drop.setId(View.generateViewId());
        group.addView(keep);
        group.addView(drop);
        group.check(keep.getId());
        box.addView(group);
        final android.widget.RadioButton[] patchOn = {null};
        if (anyRecipe) {
            TextView patchLabel = new TextView(this);
            patchLabel.setText("\n패치 함께 적용");
            patchLabel.setTextSize(13f);
            patchLabel.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            patchLabel.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
            box.addView(patchLabel);
            android.widget.RadioGroup patchGroup = new android.widget.RadioGroup(this);
            android.widget.RadioButton apply = new android.widget.RadioButton(this);
            apply.setText("패치 적용 (원본 · 완성본 검사값을 확인해요)");
            apply.setId(View.generateViewId());
            android.widget.RadioButton plain = new android.widget.RadioButton(this);
            plain.setText("원본 그대로");
            plain.setId(View.generateViewId());
            patchGroup.addView(apply);
            patchGroup.addView(plain);
            patchGroup.check(apply.getId());
            box.addView(patchGroup);
            patchOn[0] = apply;
        }
        TextView pickPatch = new TextView(this);
        pickPatch.setText(anyRecipe ? "다른 패치 고르기 ›" : "패치 고르기 (patch.json + patch.bin 또는 그 ZIP) ›");
        pickPatch.setTextSize(13f);
        pickPatch.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
        pickPatch.setTextColor(Theme.text(Color.rgb(37, 99, 235)));
        pickPatch.setPadding(0, pad * 2, 0, pad);
        box.addView(pickPatch);
        android.widget.ScrollView scroll = new android.widget.ScrollView(this);
        scroll.addView(box);
        boolean enough = free <= 0 || free > need + (64L << 20);
        AppDialog.Builder builder = new AppDialog.Builder(this).setTitle(".iso로 바꿔 넣기").setView(scroll)
                .setNegativeButton("취소", (d, w) -> continuePs2Import(rest, new ArrayList<>(), new StringBuilder(), 0));
        if (enough) {
            builder.setPositiveButton(anyRecipe ? "바꿔 넣기 · 패치" : "바꿔 넣기", (d, w) -> {
                boolean patch = patchOn[0] != null && patchOn[0].isChecked();
                for (Ps2BinJob job : jobs) job.patch = patch && job.recipe != null;
                runPs2BinJobs(jobs, rest, drop.isChecked());
            });
        } else {
            info.append("\n\n빈 공간이 모자라요. 공간을 비우고 다시 골라 주세요.");
        }
        final Dialog shown = builder.show();
        pickPatch.setOnClickListener(v -> {
            if (shown != null) shown.dismiss();
            this.pendingPs2Jobs = jobs;
            this.pendingPs2Rest = rest;
            this.pendingPs2Errors = errors;
            Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
            intent.addCategory(Intent.CATEGORY_OPENABLE);
            intent.setType("*/*");
            intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
            startActivityForResult(intent, REQUEST_PS2_RECIPE);
        });
    }

    private static final int REQUEST_PS2_RECIPE = 1095;
    private List<Ps2BinJob> pendingPs2Jobs;
    private List<Uri> pendingPs2Rest;
    private StringBuilder pendingPs2Errors;

    // The patch picked from the confirm screen: a zip, or patch.json (+ patch.bin).
    private void onPs2RecipePicked(Intent intent) {
        final List<Ps2BinJob> jobs = this.pendingPs2Jobs;
        final List<Uri> rest = this.pendingPs2Rest;
        final StringBuilder errors = this.pendingPs2Errors;
        this.pendingPs2Jobs = null;
        if (jobs == null) return;
        final List<Uri> picked = intent == null ? new ArrayList<>() : pickedUris(intent);
        new Thread(() -> {
            List<Ps2Recipe> recipes = new ArrayList<>();
            Uri payload = null;
            for (Uri uri : picked) if (displayNameFor(uri).equalsIgnoreCase("patch.bin")) payload = uri;
            boolean jsonOnly = false;
            for (Uri uri : picked) {
                String lower = displayNameFor(uri).toLowerCase(Locale.ROOT);
                Ps2Recipe recipe = null;
                if (lower.endsWith(".zip")) recipe = loadRecipeZip(uri);
                if (lower.endsWith(".json")) {
                    recipe = loadRecipeJson(uri, payload);
                    jsonOnly |= recipe == null && payload == null;
                }
                if (recipe != null) recipes.add(recipe);
            }
            final boolean needBin = jsonOnly;
            int matched = 0;
            for (Ps2BinJob job : jobs) {
                Ps2Recipe recipe = recipeFor(job, recipes);
                if (recipe != null) {
                    job.recipe = recipe;
                    matched++;
                }
            }
            final int found = matched;
            final int read = recipes.size();
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                if (found == 0) {
                    Toast.makeText(this, needBin ? "patch.json과 patch.bin을 같이 골라 주세요"
                            : read > 0 ? "고른 패치가 이 원본과 크기가 맞지 않아요" : "읽을 수 있는 패치(patch.json …-bin-to-iso-v1)가 아니에요", Toast.LENGTH_LONG).show();
                }
                showPs2BinConfirm(jobs, rest, errors);
            });
        }, "ps2-recipe").start();
    }

    private void runPs2BinJobs(List<Ps2BinJob> jobs, List<Uri> rest, boolean dropOriginals) {
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setTitle(".iso로 바꾸는 중…");
        progress.setProgressStyle(android.app.ProgressDialog.STYLE_HORIZONTAL);
        progress.setMax(1000);
        progress.setProgressNumberFormat(null);
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            StringBuilder errors = new StringBuilder();
            List<File> made = new ArrayList<>();
            int duplicates = 0;
            File romDir = romDirFor(MODE_PS2);
            romDir.mkdirs();
            for (int index = 0; index < jobs.size(); index++) {
                Ps2BinJob job = jobs.get(index);
                final long total = job.layout.isoSize(job.size);
                final String head = (jobs.size() > 1 ? "(" + (index + 1) + "/" + jobs.size() + ") " : "") + job.title;
                final long started = System.currentTimeMillis();
                final long[] shown = {0};
                String outTitle = job.patch ? job.title + " " + job.recipe.suffix() : job.title;
                File out = uniqueFile(romDir, sanitizeFileName(outTitle + ".iso"));
                java.security.MessageDigest sourceDigest = job.patch ? Ps2Recipe.sha256() : null;
                try (InputStream raw = getContentResolver().openInputStream(job.bin);
                     InputStream in = raw == null || sourceDigest == null ? raw : new java.security.DigestInputStream(raw, sourceDigest);
                     java.io.OutputStream os = new java.io.BufferedOutputStream(new FileOutputStream(out), 1 << 20)) {
                    if (in == null) throw new IOException("파일을 열 수 없어요");
                    Ps2BinImport.convert(new java.io.BufferedInputStream(in, 1 << 20), os, job.layout, job.size, written -> {
                        long now = System.currentTimeMillis();
                        if (now - shown[0] > 250 || written >= total) {
                            shown[0] = now;
                            long elapsed = Math.max(1, now - started);
                            long left = written > 0 ? (total - written) * elapsed / written / 1000 : 0;
                            int permille = total > 0 ? (int) (written * 1000 / total) : 0;
                            String message = head + "\n" + (written >> 20) + " / " + (total >> 20) + " MB · 남은 시간 약 " + left + "초";
                            runOnUiThread(() -> {
                                progress.setProgress(permille);
                                progress.setMessage(message);
                            });
                        }
                        return true;
                    });
                } catch (IOException | RuntimeException e) {
                    out.delete();
                    errors.append(job.title).append(": ").append(e.getMessage()).append('\n');
                    continue;
                }
                if (out.length() != total) {
                    out.delete();
                    errors.append(job.title).append(": 만든 .iso 크기가 맞지 않아요\n");
                    continue;
                }
                if (job.patch) {
                    // 레시피형 패치: only on the original it was made for, and kept only when the
                    // finished .iso hashes to the patch's value.
                    if (!job.recipe.sourceSha.equals(Ps2Recipe.hex(sourceDigest.digest()))) {
                        job.note = "원본 .bin의 검사값이 패치가 바라는 값과 달라서(다른 판본 · 다른 덤프 · 이미 고친 파일) 패치 없이 넣었어요";
                        File plain = uniqueFile(romDir, sanitizeFileName(job.title + ".iso"));
                        if (out.renameTo(plain)) out = plain;
                        outTitle = job.title;
                    } else {
                        try (java.io.RandomAccessFile iso = new java.io.RandomAccessFile(out, "rw")) {
                            job.recipe.apply(iso, (done, all) -> {
                                int permille = all > 0 ? (int) (done * 1000 / all) : 0;
                                runOnUiThread(() -> {
                                    progress.setProgress(permille);
                                    progress.setMessage(head + "\n패치 조각 덮어쓰는 중… " + (done >> 20) + " / " + (all >> 20) + " MB");
                                });
                            });
                            iso.getFD().sync();
                        } catch (IOException | RuntimeException e) {
                            out.delete();
                            errors.append(job.title).append(": 패치하지 못했어요 · ").append(e.getMessage()).append('\n');
                            continue;
                        }
                        String finished;
                        try {
                            finished = Ps2Recipe.sha256Of(out, (done, all) -> {
                                int permille = all > 0 ? (int) (done * 1000 / all) : 0;
                                runOnUiThread(() -> {
                                    progress.setProgress(permille);
                                    progress.setMessage(head + "\n완성본 확인하는 중… " + (done >> 20) + " / " + (all >> 20) + " MB");
                                });
                            });
                        } catch (IOException e) {
                            finished = "";
                        }
                        if (!job.recipe.targetSha.equals(finished)) {
                            out.delete();
                            errors.append(job.title).append(": 패치한 .iso의 검사값이 맞지 않아 넣지 않았어요 (패치 파일 손상 · 다른 버전)\n");
                            continue;
                        }
                        job.note = "패치를 적용했어요 · 완성본 검사값 맞음";
                    }
                }
                runOnUiThread(() -> progress.setMessage(head + "\n확인하는 중…"));
                try {
                    File kept = finalizeImportedRom(out, outTitle);
                    if (kept == null) {
                        duplicates++;
                    } else {
                        job.made = kept;
                        made.add(kept);
                    }
                } catch (IOException e) {
                    errors.append(job.title).append(": ").append(e.getMessage()).append('\n');
                    continue;
                }
                if (dropOriginals) {
                    for (Uri original : new Uri[]{job.bin, job.cue}) {
                        if (original != null && !deletePickedFile(original)) {
                            errors.append(displayNameFor(original)).append(": 원본을 지우지 못했어요 (직접 지워 주세요)\n");
                        }
                    }
                }
            }
            final int dup = duplicates;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                progress.dismiss();
                boolean gun = false;
                for (Ps2BinJob job : jobs) {
                    String lower = job.title.toLowerCase(Locale.ROOT);
                    if (job.made != null && (lower.contains("guncon") || lower.contains("time crisis") || lower.contains("vampire night"))) gun = true;
                }
                for (Ps2BinJob job : jobs) {
                    if (job.note != null && job.made != null) errors.append(job.title).append(": ").append(job.note).append('\n');
                }
                if (gun) {
                    errors.append("건콘2 게임: 건콘은 PCSX2 엔진에서만 돼요 (게임 설정에서 엔진 바꾸기)\n");
                }
                continuePs2Import(rest, made, errors, dup);
            });
        }, "ps2-bin-convert").start();
    }

    private boolean deletePickedFile(Uri uri) {
        try {
            File real = "file".equals(uri.getScheme()) && uri.getPath() != null ? new File(uri.getPath()) : realFileFor(uri);
            if (real != null && real.isFile()) {
                return real.delete();
            }
            return android.provider.DocumentsContract.deleteDocument(getContentResolver(), uri);
        } catch (Exception e) {
            return false;
        }
    }

    // The rest of the picked files through the usual import, then one summary for all.
    private void continuePs2Import(List<Uri> rest, List<File> made, StringBuilder errors, int duplicates) {
        Intent restIntent = new Intent();
        if (!rest.isEmpty()) {
            ClipData clip = ClipData.newRawUri("", rest.get(0));
            for (int k = 1; k < rest.size(); k++) clip.addItem(new ClipData.Item(rest.get(k)));
            restIntent.setClipData(clip);
        }
        Runnable work = () -> {
            ImportOutcome outcome = rest.isEmpty() ? new ImportOutcome() : copyRoms(restIntent, MODE_PS2);
            outcome.mode = MODE_PS2;
            outcome.picked += made.size() + (made.isEmpty() && duplicates == 0 && errors.length() > 0 ? 1 : 0) + duplicates;
            outcome.imported += made.size();
            outcome.duplicates += duplicates;
            if (outcome.first == null && !made.isEmpty()) outcome.first = made.get(0);
            if (errors.length() > 0) outcome.errors.insert(0, errors);
            runOnUiThread(() -> {
                if (!isFinishing() && !isDestroyed()) finishRomImport(outcome);
            });
        };
        new Thread(work, "import").start();
    }

    private static final class ImportOutcome {
        String mode;
        final List<Uri> archives = new ArrayList<>();
        int imported;
        int duplicates;
        int picked;
        File first;
        final StringBuilder errors = new StringBuilder();
        // DOS: {game zip, conf text, conf name} to offer after the import.
        final List<Object[]> dosConfs = new ArrayList<>();
        // PS3: .pkg / .rap / .edat picked with the games, installed by the engine (0.0.392).
        final List<Uri> ps3Installs = new ArrayList<>();
    }

    // DOS: a picked or neighbouring .conf; read as bytes (ISO-8859-1 keeps them for the batch file).
    private String readDosConf(Uri uri) {
        try (java.io.InputStream in = getContentResolver().openInputStream(uri)) {
            if (in == null) return null;
            java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int n;
            while ((n = in.read(buffer)) > 0) {
                bytes.write(buffer, 0, n);
                if (bytes.size() > (1 << 20)) return null;
            }
            return new String(bytes.toByteArray(), StandardCharsets.ISO_8859_1);
        } catch (IOException | RuntimeException e) {
            return null;
        }
    }

    private void offerDosConfs(final List<Object[]> confs, final int index, final Runnable done) {
        if (index >= confs.size()) {
            if (done != null) done.run();
            return;
        }
        Object[] c = confs.get(index);
        showDosConfApply((File) c[0], (String) c[1], (String) c[2], () -> offerDosConfs(confs, index + 1, done));
    }

    private void finishRomImport(ImportOutcome outcome) {
        if (outcome.picked == 0) {
            return;
        }
        if (!outcome.ps3Installs.isEmpty()) {
            List<Uri> installs = new ArrayList<>(outcome.ps3Installs);
            outcome.ps3Installs.clear();
            outcome.picked -= installs.size();
            startPs3Install(installs, null);
            if (outcome.picked <= 0) {
                return;
            }
        }
        if (!outcome.dosConfs.isEmpty()) {
            List<Object[]> confs = new ArrayList<>(outcome.dosConfs);
            outcome.dosConfs.clear();
            refreshLibrary();
            offerDosConfs(confs, 0, () -> finishRomImport(outcome));
            return;
        }
        if (!outcome.archives.isEmpty()) {
            refreshLibrary();
            if (outcome.errors.length() > 0) {
                showError(outcome.errors.toString());
            }
            if (outcome.imported > 0) {
                Toast.makeText(this, "가져오기 완료: " + outcome.imported + "개", Toast.LENGTH_SHORT).show();
            }
            openRomArchives(outcome.mode, new java.util.ArrayDeque<>(groupArchives(outcome.archives)));
            return;
        }
        refreshLibrary();
        String str = "가져오기 완료: " + outcome.imported + "개";
        if (outcome.duplicates > 0) {
            str = str + "  |  중복 건너뜀: " + outcome.duplicates + "개";
        }
        if (outcome.errors.length() > 0) {
            showError(str + "\n" + outcome.errors);
        } else {
            showMessage(str);
        }
        if (outcome.picked == 1 && outcome.imported == 1 && outcome.first != null) {
            launchGame(outcome.first);
        }
    }

    private ImportOutcome copyRoms(Intent intent, String mode) {
        ImportOutcome outcome = new ImportOutcome();
        outcome.mode = mode;
        List<File> singletonOrEmpty;
        ArrayList<Uri> arrayList = new ArrayList();
        ClipData clipData = intent.getClipData();
        int i = 0;
        if (clipData != null) {
            for (int i2 = 0; i2 < clipData.getItemCount(); i2++) {
                Uri uri = clipData.getItemAt(i2).getUri();
                if (uri != null) {
                    arrayList.add(uri);
                }
            }
        } else if (intent.getData() != null) {
            arrayList.add(intent.getData());
        }
        outcome.picked = arrayList.size();
        if (arrayList.isEmpty()) {
            return outcome;
        }
        StringBuilder sb = outcome.errors;
        File file = null;
        int i3 = 0;
        List<String[]> dosConfs = new ArrayList<>();   // {name, text}
        List<File> dosGames = new ArrayList<>();
        for (Uri uri2 : arrayList) {
            String displayNameFor = displayNameFor(uri2);
            String lowerCase = displayNameFor.toLowerCase(Locale.US);
            if (MODE_DOS.equals(mode) && lowerCase.endsWith(".conf")) {
                String text = readDosConf(uri2);
                if (text == null) {
                    sb.append(displayNameFor).append(": 설정 파일을 읽지 못했어요\n");
                } else {
                    dosConfs.add(new String[]{displayNameFor, text});
                }
                outcome.picked--;
                continue;
            }
            if (MODE_DOS.equals(mode) && (lowerCase.endsWith(".zip") || lowerCase.endsWith(".dosz"))) {
                // A conf beside the zip on the phone (same name, or dosbox.conf), with 모든 파일 접근.
                File real = realFileFor(uri2);
                if (real != null && real.getParentFile() != null) {
                    String base = real.getName().replaceAll("(?i)\\.(zip|dosz)$", "");
                    for (String n : new String[]{base + ".conf", "dosbox.conf"}) {
                        File side = new File(real.getParentFile(), n);
                        if (side.isFile() && side.length() < (1 << 20)) {
                            String text = readDosConf(Uri.fromFile(side));
                            if (text != null) {
                                dosConfs.add(new String[]{base + ".conf", text, base});
                                break;
                            }
                        }
                    }
                }
            }
            if ((lowerCase.endsWith(".rar") || lowerCase.endsWith(".7z") || RarReader.isSplitName(lowerCase)) && !MODE_NAOMI.equals(mode)
                    && !"arcade".equals(mode) && !"neogeo".equals(mode)) {
                outcome.archives.add(uri2);  // after this: 압축 파일 안의 게임 (split parts grouped)
                continue;
            }
            if (MODE_PS3.equals(mode) && (lowerCase.endsWith(".pkg") || lowerCase.endsWith(".rap") || lowerCase.endsWith(".edat"))) {
                outcome.ps3Installs.add(uri2);
                continue;
            }
            if (MODE_PS3.equals(mode) && lowerCase.endsWith(".ps3game")) {
                sb.append(displayNameFor).append(": 지원하지 않는 파일\n");
                continue;
            }
            if (!isRomNameFor(mode, lowerCase) && !lowerCase.endsWith(".zip")) {
                sb.append(displayNameFor).append(": 지원하지 않는 파일\n");
            } else {
                try {
                    if (lowerCase.endsWith(".zip") && !MODE_NAOMI.equals(mode) && !MODE_DOS.equals(mode)) {
                        singletonOrEmpty = copyZippedRomsToAppStorage(uri2, displayNameFor, mode);
                    } else {
                        // Naomi sets stay ZIPs (the engine reads the archive itself).
                        singletonOrEmpty = singletonOrEmpty(copyRomToAppStorage(uri2, displayNameFor, mode));
                        if (MODE_NAOMI.equals(mode)) {
                            List<File> renamed = new ArrayList<>();
                            for (File imported : singletonOrEmpty) {
                                File named = nameNaomiSet(imported);
                                if (named == null) {
                                    sb.append(displayNameFor).append(": Flycast가 모르는 세트예요. MAME 세트명(.zip)인지 확인해 주세요\n");
                                }
                                renamed.add(named != null ? named : imported);
                            }
                            singletonOrEmpty = renamed;
                        }
                    }
                    if (singletonOrEmpty.isEmpty()) {
                        i3++;
                    }
                    for (File file2 : singletonOrEmpty) {
                        i++;
                        if (file == null) {
                            file = file2;
                        }
                        dosGames.add(file2);
                    }
                } catch (IOException e) {
                    sb.append(displayNameFor).append(": ").append(e.getMessage()).append('\n');
                }
            }
        }
        outcome.imported = i;
        outcome.duplicates = i3;
        outcome.first = file;
        // Each conf to its game: same name, else the one game imported with it, else a game of
        // that name already in the list.
        for (String[] conf : dosConfs) {
            String base = (conf.length > 2 ? conf[2] : conf[0].replaceAll("(?i)\\.conf$", "")).toLowerCase(Locale.ROOT);
            File game = null;
            for (File g : dosGames) {
                if (g.getName().toLowerCase(Locale.ROOT).replaceAll("\\.(zip|dosz)$", "").equals(base)) game = g;
            }
            if (game == null && dosGames.size() == 1) game = dosGames.get(0);
            if (game == null) {
                File[] existing = romDirFor(MODE_DOS).listFiles();
                for (File g : existing == null ? new File[0] : existing) {
                    if (g.getName().toLowerCase(Locale.ROOT).replaceAll("\\.(zip|dosz)$", "").equals(base)) game = g;
                }
            }
            if (game == null) {
                sb.append(conf[0]).append(": 짝이 되는 게임 zip을 못 찾았어요. 게임 메뉴의 DOS 설정 → 설정 파일 넣기로 넣어 주세요\n");
            } else {
                outcome.dosConfs.add(new Object[]{game, conf[1], conf[0]});
            }
        }
        if (outcome.picked == 0 && !outcome.dosConfs.isEmpty()) {
            outcome.picked = 1;
        }
        return outcome;
    }

    private void importArcadeRoms(Intent intent) {
        ArrayList<Uri> arrayList = new ArrayList();
        ClipData clipData = intent.getClipData();
        int i = 0;
        if (clipData != null) {
            for (int i2 = 0; i2 < clipData.getItemCount(); i2++) {
                Uri uri = clipData.getItemAt(i2).getUri();
                if (uri != null) {
                    arrayList.add(uri);
                }
            }
        } else if (intent.getData() != null) {
            arrayList.add(intent.getData());
        }
        StringBuilder sb = new StringBuilder();
        int i3 = 0;
        for (Uri uri2 : arrayList) {
            String displayNameFor = displayNameFor(uri2);
            if (displayNameFor.equalsIgnoreCase("neogeo.zip")) {
                importNeoGeoBios(uri2);
            } else if (displayNameFor.toLowerCase(Locale.US).endsWith(".zip") && RomsetIndex.isBiosName(this, baseNameWithoutExtension(displayNameFor.toLowerCase(Locale.US)))) {
                // Board BIOS archives picked as ROMs go to the MAME BIOS folder.
                try {
                    copyUriToFile(uri2, new File(mameBiosDir(), sanitizeFileName(displayNameFor).toLowerCase(Locale.US)));
                    sb.append(displayNameFor).append(": 기판 BIOS라서 MAME BIOS로 등록했습니다\n");
                } catch (IOException e) {
                    sb.append(displayNameFor).append(": ").append(e.getMessage()).append('\n');
                }
            } else if (!displayNameFor.toLowerCase(Locale.US).endsWith(".zip")) {
                sb.append(displayNameFor).append(": 아케이드 ROM은 ZIP 파일이어야 합니다.\n");
            } else {
                try {
                    File imported = copyArcadeRomToAppStorage(uri2, displayNameFor);
                    if (imported == null) {
                        i3++;
                    } else {
                        i++;
                        RomsetResult romset = RomsetIndex.isAvailable(this) ? resolveRomset(imported) : null;
                        if (romset == null) {
                            continue;
                        }
                        if (romset.match == null) {
                            sb.append(displayNameFor).append(": 엔진이 알아볼 수 없는 ROM입니다 (지원하지 않는 게임이거나 일부 파일만 있음)\n");
                        } else if (romset.renameConflict != null) {
                            sb.append(displayNameFor).append(": 같은 게임(").append(romset.renameConflict).append(")이 이미 있습니다\n");
                        }
                    }
                } catch (IOException e) {
                    sb.append(displayNameFor).append(": ").append(e.getMessage()).append('\n');
                }
            }
        }
        refreshLibrary();
        String str = "아케이드 ROM 가져오기 완료: " + i + "개";
        if (i3 > 0) {
            str = str + "  |  중복 건너뜀: " + i3 + "개";
        }
        if (sb.length() > 0) {
            showError(str + "\n" + ((Object) sb));
        } else {
            showMessage(str);
        }
    }

    private void importBios(Uri uri) {
        try {
            File systemDir = systemDir();
            if (!systemDir.exists() && !systemDir.mkdirs()) {
                throw new IOException("BIOS 폴더를 만들 수 없습니다");
            }
            File file = new File(systemDir, "gba_bios.bin");
            try (InputStream openInputStream = getContentResolver().openInputStream(uri);
                 FileOutputStream fileOutputStream = new FileOutputStream(file)) {
                if (openInputStream == null) {
                    throw new IOException("선택한 BIOS 파일을 열 수 없습니다");
                }
                copy(openInputStream, fileOutputStream);
            }
            if (file.length() != 16384) {
                if (!file.delete()) {
                    file.deleteOnExit();
                }
                throw new IOException("GBA BIOS는 16KB 파일이어야 합니다.");
            }
            showMessage("GBA BIOS를 가져왔습니다.");
            updateHomeStatusCards();
            updateNote();
        } catch (IOException e) {
            showError("BIOS 가져오기 실패: " + e.getMessage());
        }
    }

    private void importNeoGeoBios(Uri uri) {
        try {
            File systemDir = systemDir();
            if (!systemDir.exists() && !systemDir.mkdirs()) {
                throw new IOException("BIOS 폴더를 만들 수 없습니다");
            }
            File neoGeoBiosFile = neoGeoBiosFile();
            try (InputStream openInputStream = getContentResolver().openInputStream(uri);
                 FileOutputStream fileOutputStream = new FileOutputStream(neoGeoBiosFile)) {
                if (openInputStream == null) {
                    throw new IOException("선택한 BIOS 파일을 열 수 없습니다");
                }
                copy(openInputStream, fileOutputStream);
            }
            if (neoGeoBiosFile.length() == 0) {
                if (!neoGeoBiosFile.delete()) {
                    neoGeoBiosFile.deleteOnExit();
                }
                throw new IOException("비어 있는 BIOS 파일입니다");
            }
            File romDir = arcadeRomDir();
            if (!romDir.exists() && !romDir.mkdirs()) {
                throw new IOException("ROM 폴더를 만들 수 없습니다");
            }
            prepareNeoGeoBiosForArcade(neoGeoBiosFile, new File(romDir, "neogeo.zip"));
            showMessage("Neo Geo BIOS를 가져왔습니다.");
            updateHomeStatusCards();
            updateNote();
        } catch (IOException e) {
            showError("Neo Geo BIOS 가져오기 실패: " + e.getMessage());
        }
    }

    private void importMameBios(Intent intent) {
        ArrayList<Uri> arrayList = new ArrayList();
        ClipData clipData = intent.getClipData();
        int i = 0;
        if (clipData != null) {
            for (int i2 = 0; i2 < clipData.getItemCount(); i2++) {
                Uri uri = clipData.getItemAt(i2).getUri();
                if (uri != null) {
                    arrayList.add(uri);
                }
            }
        } else if (intent.getData() != null) {
            arrayList.add(intent.getData());
        }
        StringBuilder sb = new StringBuilder();
        File mameBiosDir = mameBiosDir();
        if (!mameBiosDir.exists() && !mameBiosDir.mkdirs()) {
            showError("MAME BIOS 폴더를 만들 수 없습니다.");
            return;
        }
        for (Uri uri2 : arrayList) {
            String sanitizeFileName = sanitizeFileName(displayNameFor(uri2));
            if (!sanitizeFileName.toLowerCase(Locale.US).endsWith(".zip")) {
                sb.append(sanitizeFileName).append(": BIOS는 ZIP 파일이어야 합니다.\n");
            } else {
                File file = new File(mameBiosDir, sanitizeFileName + ".import");
                File file2 = new File(mameBiosDir, sanitizeFileName);
                try {
                    try (InputStream openInputStream = getContentResolver().openInputStream(uri2);
                         FileOutputStream fileOutputStream = new FileOutputStream(file)) {
                        if (openInputStream == null) {
                            throw new IOException("선택한 파일을 열 수 없습니다");
                        }
                        copy(openInputStream, fileOutputStream);
                    }
                    if (!isReadableZip(file)) {
                        throw new IOException("올바른 ZIP 파일이 아닙니다");
                    }
                    if (sanitizeFileName.equalsIgnoreCase("stvbios.zip") && file2.exists()) {
                        removeMergedBiosEntries(new File(arcadeRomDir(), "twcup98.zip"), file2);
                    }
                    if (!copyFile(file, file2)) {
                        throw new IOException("BIOS를 저장할 수 없습니다");
                    }
                    if (sanitizeFileName.equalsIgnoreCase("stvbios.zip")) {
                        File romDir = arcadeRomDir();
                        if (!romDir.exists() && !romDir.mkdirs()) {
                            throw new IOException("ROM 폴더를 만들 수 없습니다");
                        }
                        if (!copyFile(file2, new File(romDir, "stvbios.zip"))) {
                            throw new IOException("ST-V BIOS를 코어 폴더에 준비할 수 없습니다");
                        }
                    }
                    i++;
                } catch (IOException e) {
                    sb.append(sanitizeFileName).append(": ").append(e.getMessage()).append('\n');
                } finally {
                    if (file.exists() && !file.delete()) {
                        file.deleteOnExit();
                    }
                }
            }
        }
        migrateKnownArcadeRoms();
        updateHomeStatusCards();
        updateNote();
        String str = "MAME BIOS 등록 완료: " + i + "개";
        if (sb.length() > 0) {
            showError(str + "\n" + ((Object) sb));
        } else {
            showMessage(str);
        }
    }

    // ---- Folder imports ----

    private static final String BIOS_SOURCE_MAME = "mame";

    private void openFolderPicker(int requestCode) {
        Intent intent = new Intent("android.intent.action.OPEN_DOCUMENT_TREE");
        try {
            startActivityForResult(intent, requestCode);
        } catch (android.content.ActivityNotFoundException e) {
            showError("폴더를 고를 수 있는 앱이 없습니다.");
        }
    }

    // BIOS tiles offer a single file or a whole folder; a folder is sorted by file type.
    // The card opens with what is registered so far.
    private void showBiosChooser(String source) {
        final Dialog dialog = new Dialog(this);
        dialog.requestWindowFeature(1);
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        panel.setPadding(dp(16), dp(18), dp(16), dp(16));
        panel.setBackground(rounded(-1, dp(24)));
        boolean mame = BIOS_SOURCE_MAME.equals(source);
        boolean neoGeo = "neogeo".equals(source);
        TextView title = new TextView(this);
        title.setText(mame ? "MAME BIOS" : neoGeo ? "Neo Geo BIOS" : "GBA BIOS");
        title.setTextSize(17.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        title.setPadding(dp(4), 0, dp(4), 0);
        panel.addView(title);

        // Status: green when ready, amber when something is missing, red when nothing is there.
        int state;
        String headline;
        String note = null;
        int count = 0;
        if (mame) {
            File[] files = mameBiosDir().listFiles(MainActivity::isZipFile);
            count = files == null ? 0 : files.length;
            String status = mameBiosStatus();
            if (count == 0) {
                state = 2;
                headline = "등록된 BIOS가 없어요";
                note = "BIOS가 필요한 기판 게임은 실행되지 않아요";
            } else {
                headline = "BIOS " + count + "개 등록됨";
                state = status.startsWith("ST-V 불완전") ? 1 : 0;
                if (state == 1) {
                    note = "ST-V (stvbios.zip) 파일 일부 부족";
                }
            }
        } else if (neoGeo) {
            boolean ok = neoGeoBiosFile().exists();
            state = ok ? 0 : 2;
            headline = ok ? "Neo Geo BIOS 등록됨" : "Neo Geo BIOS가 없어요";
            note = ok ? "neogeo.zip" : "Neo Geo 게임을 실행하려면 neogeo.zip이 필요해요";
        } else {
            boolean ok = biosFile().exists();
            state = ok ? 0 : 1;
            headline = ok ? "GBA BIOS 등록됨" : "GBA BIOS가 없어요";
            note = ok ? "gba_bios.bin" : "없어도 대부분의 게임은 실행돼요";
        }
        int[] fills = {Color.rgb(240, 253, 244), Color.rgb(255, 247, 237), Color.rgb(254, 242, 242)};
        int[] icons = {Color.rgb(34, 179, 90), Color.rgb(245, 158, 11), Color.rgb(229, 72, 77)};
        int[] heads = {Color.rgb(20, 83, 45), Color.rgb(124, 45, 18), Color.rgb(127, 29, 29)};
        LinearLayout statusCard = new LinearLayout(this);
        statusCard.setOrientation(0);
        statusCard.setGravity(16);
        statusCard.setPadding(dp(12), dp(11), dp(12), dp(11));
        statusCard.setBackground(rounded(fills[state], dp(14)));
        TextView mark = new TextView(this);
        mark.setText(state == 0 ? "✓" : "!");
        mark.setTextColor(-1);
        mark.setTextSize(15.0f);
        mark.setTypeface(Typeface.DEFAULT_BOLD);
        mark.setGravity(17);
        mark.setBackground(rounded(icons[state], dp(15)));
        statusCard.addView(mark, new LinearLayout.LayoutParams(dp(30), dp(30)));
        LinearLayout statusTexts = new LinearLayout(this);
        statusTexts.setOrientation(1);
        TextView head = new TextView(this);
        head.setText(headline);
        head.setTextSize(13.5f);
        head.setTypeface(Typeface.DEFAULT_BOLD);
        head.setTextColor(Theme.text(heads[state]));
        statusTexts.addView(head);
        if (note != null) {
            TextView noteView = new TextView(this);
            noteView.setText(note);
            noteView.setTextSize(11.5f);
            noteView.setTextColor(Theme.text(state == 0 ? Color.rgb(77, 124, 96) : Color.rgb(180, 83, 9)));
            statusTexts.addView(noteView);
        }
        LinearLayout.LayoutParams statusTextsParams = new LinearLayout.LayoutParams(0, -2, 1.0f);
        statusTextsParams.setMargins(dp(10), 0, 0, 0);
        statusCard.addView(statusTexts, statusTextsParams);
        LinearLayout.LayoutParams statusParams = new LinearLayout.LayoutParams(-1, -2);
        statusParams.setMargins(0, dp(12), 0, dp(10));
        panel.addView(statusCard, statusParams);

        LinearLayout tiles = new LinearLayout(this);
        int column = 0;
        int last = mame ? 2 : 1;
        if (mame) {
            tiles.addView(createActionTile(dialog, RoundIconView.MULTI, Color.rgb(239, 84, 103), "관리", count + "개", false, this::showMameBiosManager), gridParams(column++, last));
        }
        tiles.addView(createActionTile(dialog, RoundIconView.CARD, RoundIconView.COLOR_LOAD, "파일", null, false, () -> openSingleBiosPicker(source)), gridParams(column++, last));
        tiles.addView(createActionTile(dialog, RoundIconView.FOLDER, RoundIconView.COLOR_SAVE, "폴더째", null, false, () -> {
            this.pendingBiosSource = source;
            openFolderPicker(REQUEST_OPEN_BIOS_FOLDER);
        }), gridParams(column, last));
        panel.addView(tiles, new LinearLayout.LayoutParams(-1, -2));
        panel.addView(createCancelButton(dialog, "취소"));
        showCardDialog(dialog, panel, -2);
    }

    private LinearLayout.LayoutParams gridParams(int column, int last) {
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, -1, 1.0f);
        params.setMargins(column == 0 ? 0 : dp(4), 0, column == last ? 0 : dp(4), 0);
        return params;
    }

    private TextView createCancelButton(Dialog dialog, String label) {
        TextView cancel = new TextView(this);
        cancel.setText(label);
        cancel.setTextSize(14.0f);
        cancel.setTypeface(Typeface.DEFAULT_BOLD);
        cancel.setTextColor(Theme.text(Color.rgb(75, 85, 99)));
        cancel.setGravity(17);
        cancel.setBackground(rounded(Color.rgb(238, 240, 243), dp(13)));
        cancel.setOnClickListener(view -> dialog.dismiss());
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, dp(44));
        params.setMargins(0, dp(12), 0, 0);
        cancel.setLayoutParams(params);
        return cancel;
    }

    private void openSingleBiosPicker(String source) {
        if ("neogeo".equals(source)) {
            openNeoGeoBiosPicker();
        } else if (BIOS_SOURCE_MAME.equals(source)) {
            openMameBiosPicker();
        } else {
            openBiosPicker();
        }
    }

