    private boolean patchRunning;

    private void runPatch(File file, String originalName, String newName, RomPatcher.Big patch, PatchSource source, RomPatcher.Check check) {
        File dir = outputDirFor(file);
        String base = sanitizeSaveBaseName(newName);
        boolean cue = source.cue != null;
        boolean multi = cue && source.tracks.size() > 1;
        // A name none of the new files (the game, and a CUE's tracks) already has.
        String chosen = base;
        for (int k = 2; patchTargetsExist(dir, chosen, source, cue, multi); k++) {
            chosen = base + " " + k;
        }
        final String name = chosen;
        final File out = new File(dir, name + (cue ? ".cue" : source.extension));
        final File dataOut = cue ? new File(dir, trackName(name, 0, source, multi)) : out;
        final File temp = new File(dir, "." + dataOut.getName() + ".patching");
        long needed = source.rom.length();
        if (cue) {
            for (int k = 1; k < source.tracks.size(); k++) {
                needed += source.tracks.get(k).length();
            }
        }
        long free = new android.os.StatFs(dir.getAbsolutePath()).getAvailableBytes();
        if (free < needed + 64L * 1024 * 1024) {
            new File(getCacheDir(), "patch_input").delete();
            if (source.temporary) {
                source.rom.delete();
            }
            showError("저장 공간이 부족해요. 패치한 복사본을 만들려면 " + formatSize(needed) + " 정도가 필요한데, 남은 공간은 " + formatSize(free) + "예요.");
            return;
        }
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setMessage(needed > 512L * 1024 * 1024 ? "패치를 적용하는 중… 디스크가 커서 몇 분 걸릴 수 있어요" : "패치를 적용하는 중…");
        progress.setCancelable(false);
        progress.show();
        this.patchRunning = true;
        new Thread(() -> {
            String error = null;
            java.util.List<File> written = new ArrayList<>();
            try {
                RomPatcher.apply(patch, source.rom, check, temp);
                if (!temp.renameTo(dataOut)) {
                    throw new IOException("패치한 롬을 저장하지 못했어요.");
                }
                written.add(dataOut);
                if (cue) {
                    // The other tracks (music) are copied too, so deleting the original game later
                    // doesn't take them from this one; the CUE names the new files.
                    List<String> lines = new ArrayList<>(source.cueLines);
                    java.util.Set<Integer> renamed = new java.util.HashSet<>();
                    for (int k = 0; k < source.tracks.size(); k++) {
                        String track = trackName(name, k, source, multi);
                        if (k > 0) {
                            File copy = new File(dir, track);
                            if (!copyFile(source.tracks.get(k), copy)) {
                                throw new IOException("트랙 파일을 복사하지 못했어요.");
                            }
                            written.add(copy);
                        }
                        int index = source.cueFileLines.get(k);
                        java.util.regex.Matcher match = CUE_FILE.matcher(lines.get(index));
                        if (match.matches()) {
                            lines.set(index, match.group(1) + "\"" + track + "\"" + match.group(5));
                            renamed.add(index);
                        }
                    }
                    // Lines as they were (bytes kept), the new FILE lines in UTF-8 like the file names.
                    try (OutputStream writer = new FileOutputStream(out)) {
                        for (int k = 0; k < lines.size(); k++) {
                            writer.write(lines.get(k).getBytes(renamed.contains(k) ? "UTF-8" : "ISO-8859-1"));
                            writer.write(new byte[]{'\r', '\n'});
                        }
                    }
                    written.add(out);
                }
            } catch (IOException e) {
                error = e.getMessage();
            } catch (OutOfMemoryError e) {
                error = "메모리가 부족해서 패치하지 못했어요.";
            } finally {
                temp.delete();
                new File(getCacheDir(), "patch_input").delete();
                if (source.temporary) {
                    source.rom.delete();
                }
            }
            if (error != null) {
                for (File f : written) {
                    f.delete();
                }
            }
            final String why = error;
            runOnUiThread(() -> {
                this.patchRunning = false;
                if (isFinishing() || isDestroyed()) {
                    return;
                }
                progress.dismiss();
                if (why != null) {
                    showError(why);
                    return;
                }
                romPrefs().edit().putString("title:" + out.getName(), newName).putString("patched:" + out.getName(), originalName).apply();
                finishNewGame(file, out, this.carrySaveFrom != null);
                this.carrySaveFrom = null;
                recordPatch(out, RomPatcher.formatName(check.format), java.util.Collections.singletonList((this.lastPatchName == null ? "패치" : this.lastPatchName)
                        + (check.sourceMatches > 0 ? " · 원본 CRC 일치" : "")));
                Toast.makeText(this, "패치를 적용했어요 · 목록에 추가됨", Toast.LENGTH_LONG).show();
                refreshLibrary();
            });
        }, "patch").start();
    }

    // The file name of track k of a patched CUE game ("이름.bin", or "이름 (Track 01).bin").
    private static String trackName(String name, int k, PatchSource source, boolean multi) {
        String track = source.tracks.get(k).getName();
        int dot = track.lastIndexOf('.');
        String extension = dot >= 0 ? track.substring(dot) : ".bin";
        return multi ? String.format(Locale.ROOT, "%s (Track %02d)%s", name, k + 1, extension) : name + extension;
    }

    private static boolean patchTargetsExist(File dir, String name, PatchSource source, boolean cue, boolean multi) {
        if (!cue) {
            return new File(dir, name + source.extension).exists();
        }
        if (new File(dir, name + ".cue").exists()) {
            return true;
        }
        for (int k = 0; k < source.tracks.size(); k++) {
            if (new File(dir, trackName(name, k, source, multi)).exists()) {
                return true;
            }
        }
        return false;
    }

    // ---- Patches for disc games with several tracks (CUE: PS1 · PC엔진 CD · 메가CD · 새턴;
    // GDI: 드림캐스트): each patch goes to its own track ("track5.bin에 적용"), found from the
    // patch (BPS / UPS original CRC, how far an xdelta reads), its file name, or picked. ----
    private static final java.util.regex.Pattern GDI_LINE = java.util.regex.Pattern.compile("^(\\s*\\d+\\s+\\d+\\s+(\\d+)\\s+\\d+\\s+)(\"([^\"]+)\"|(\\S+))(\\s+.*)?$");
    private static final java.util.regex.Pattern TRACK_HINT = java.util.regex.Pattern.compile("(?i)track\\s*[_\\-]?\\s*0*(\\d{1,2})(?!\\d)");

    private static final class DiscPatch {
        String name;
        File file;
        RomPatcher.Big patch;
        int format;
        int track = -1;          // index into the source's tracks; -1 not decided
        int span = 1;            // tracks the patch covers, joined end to end (from track on)
        // The track's stored pregap ("<track>.pregap", from a CHD unpacked by 0.0.304+): the
        // patch was made on a Redump track, which is that pregap followed by the GDI track.
        File pregap;
        String reason = "";
        boolean noMatch;         // the patch says none of the tracks is its original
    }

    // What a refused track is, to compare with the patch's notes (원본 md5 · 크기): the track's
    // MD5 and size, and the same with its stored pregap in front (the Redump track).
    private static String trackDiagnosis(File track, File pregap, DiscPatch item) {
        StringBuilder sb = new StringBuilder("확인용 (패치 안내문의 원본 md5와 비교해 보세요)\n");
        long expected = RomPatcher.xdeltaSourceEnd(item.patch);
        if (expected > 0) {
            sb.append("· 패치가 읽는 원본 크기: ").append(String.format(Locale.ROOT, "%,d", expected)).append(" 바이트 이상\n");
        }
        sb.append("· 지금 트랙: ").append(String.format(Locale.ROOT, "%,d", track.length())).append(" 바이트 · md5 ").append(md5Of(new File[]{track})).append('\n');
        if (pregap != null && pregap.isFile()) {
            sb.append("· 프리갭(").append(pregap.length() / 2352).append("섹터) + 트랙: ")
                    .append(String.format(Locale.ROOT, "%,d", pregap.length() + track.length())).append(" 바이트 · md5 ").append(md5Of(new File[]{pregap, track}));
        } else {
            sb.append("· 프리갭: 없음 (CHD에 저장되지 않았거나, 0.0.304 전에 푼 GDI)");
        }
        return sb.toString();
    }

    private static String md5Of(File[] parts) {
        try {
            java.security.MessageDigest digest = java.security.MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[1 << 20];
            for (File part : parts) {
                try (InputStream in = new FileInputStream(part)) {
                    int n;
                    while ((n = in.read(buffer)) > 0) {
                        digest.update(buffer, 0, n);
                    }
                }
            }
            StringBuilder hex = new StringBuilder();
            for (byte b : digest.digest()) {
                hex.append(String.format(Locale.ROOT, "%02X", b & 0xFF));
            }
            return hex.toString();
        } catch (Exception e) {
            return "(읽지 못함)";
        }
    }

    // A GDI track's start (LBA) from its line in the sheet ("number lba type size file offset").
    private static int gdiTrackLba(PatchSource source, int k) {
        try {
            String line = source.cueLines.get(source.cueFileLines.get(k)).trim();
            String[] parts = line.split("\\s+");
            return parts.length >= 2 ? Integer.parseInt(parts[1]) : -1;
        } catch (RuntimeException e) {
            return -1;
        }
    }

    // The gap before a data track that a Redump track holds and a CHD may not keep: tried in
    // turn — empty Mode 1 sectors (minutes past 99 written two ways), silence first then such
    // sectors, all silence. The patch checks every window, so only the true gap gets through.
    // Returns what the gap was, or null when none fits.
    private static String applyWithBuiltPregap(DiscPatch item, File track, File out, File dir, int lba, int frames) throws IOException {
        String[] names = {"빈 데이터 섹터", "무음 75 + 빈 데이터 섹터", "무음 150 + 빈 데이터 섹터", "빈 데이터 섹터 (분 표기 2)",
                "무음 75 + 빈 데이터 섹터 (분 표기 2)", "무음"};
        int[][] plans = {{0, 0}, {75, 0}, {150, 0}, {0, 1}, {75, 1}, {frames, 0}};   // {silent frames first, minute style}
        File joined = new File(dir, "." + out.getName() + ".built");
        File patched = new File(dir, "." + out.getName() + ".built-out");
        long gapBytes = (long) frames * CdSector.SIZE;
        try {
            try (OutputStream joinOut = new java.io.BufferedOutputStream(new FileOutputStream(joined), 1 << 20)) {
                joinOut.write(new byte[(int) gapBytes]);
                byte[] buffer = new byte[1 << 20];
                try (InputStream in = new FileInputStream(track)) {
                    int n;
                    while ((n = in.read(buffer)) > 0) {
                        joinOut.write(buffer, 0, n);
                    }
                }
            }
            for (int p = 0; p < plans.length; p++) {
                if (plans[p][0] > frames || (p == 2 && frames <= 150)) {
                    continue;
                }
                try (java.io.RandomAccessFile raf = new java.io.RandomAccessFile(joined, "rw")) {
                    byte[] silent = new byte[CdSector.SIZE];
                    for (int i = 0; i < frames; i++) {
                        raf.write(i < plans[p][0] ? silent : CdSector.emptyMode1(lba - frames + i, plans[p][1]));
                    }
                }
                try {
                    RomPatcher.Check check = RomPatcher.check(item.patch, joined);
                    RomPatcher.apply(item.patch, joined, check, patched);
                } catch (IOException wrongGap) {
                    patched.delete();
                    continue;
                }
                try (java.io.RandomAccessFile in = new java.io.RandomAccessFile(patched, "r");
                     OutputStream trackOut = new java.io.BufferedOutputStream(new FileOutputStream(out), 1 << 20)) {
                    in.seek(gapBytes);
                    byte[] buffer = new byte[1 << 20];
                    int n;
                    while ((n = in.read(buffer)) > 0) {
                        trackOut.write(buffer, 0, n);
                    }
                }
                return names[p] + " " + frames + "섹터";
            }
            return null;
        } finally {
            joined.delete();
            patched.delete();
        }
    }

    // A patch made on a Redump track: pregap + track joined, patched, and the pregap's length
    // cut off again, so the result is the GDI track (the GDI keeps its layout).
    private static void applyWithPregap(DiscPatch item, File track, File out, File dir) throws IOException {
        // The whole stored pregap first; then only its end, so pregap + track is exactly the
        // size the patch reads (a Redump track can keep fewer pregap frames than the CHD).
        long whole = item.pregap.length();
        long end = RomPatcher.xdeltaSourceEnd(item.patch);
        long part = end - track.length();
        IOException first;
        try {
            applyWithPregap(item, track, out, dir, whole);
            return;
        } catch (IOException e) {
            first = e;
        }
        if (part > 0 && part < whole && part % 2352 == 0) {
            try {
                applyWithPregap(item, track, out, dir, part);
                return;
            } catch (IOException ignored) {
                // The first reason is the one to show.
            }
        }
        throw first;
    }

    private static void applyWithPregap(DiscPatch item, File track, File out, File dir, long prefix) throws IOException {
        File joined = new File(dir, "." + out.getName() + ".joined");
        File patched = new File(dir, "." + out.getName() + ".joined-out");
        try {
            try (OutputStream joinOut = new java.io.BufferedOutputStream(new FileOutputStream(joined), 1 << 20)) {
                byte[] buffer = new byte[1 << 20];
                try (java.io.RandomAccessFile in = new java.io.RandomAccessFile(item.pregap, "r")) {
                    in.seek(item.pregap.length() - prefix);
                    int n;
                    while ((n = in.read(buffer)) > 0) {
                        joinOut.write(buffer, 0, n);
                    }
                }
                try (InputStream in = new FileInputStream(track)) {
                    int n;
                    while ((n = in.read(buffer)) > 0) {
                        joinOut.write(buffer, 0, n);
                    }
                }
            }
            RomPatcher.Check check = RomPatcher.check(item.patch, joined);
            RomPatcher.apply(item.patch, joined, check, patched);
            joined.delete();
            long cut = prefix;
            if (patched.length() < cut) {
                throw new IOException("패치한 결과의 크기가 맞지 않아요.");
            }
            try (java.io.RandomAccessFile in = new java.io.RandomAccessFile(patched, "r");
                 OutputStream trackOut = new java.io.BufferedOutputStream(new FileOutputStream(out), 1 << 20)) {
                in.seek(cut);
                byte[] buffer = new byte[1 << 20];
                int n;
                while ((n = in.read(buffer)) > 0) {
                    trackOut.write(buffer, 0, n);
                }
            }
        } catch (IOException e) {
            out.delete();
            throw e;
        } finally {
            joined.delete();
            patched.delete();
        }
    }

    private static boolean isDiscSheet(File file) {
        String lower = file.getName().toLowerCase(Locale.ROOT);
        return lower.endsWith(".cue") || lower.endsWith(".gdi");
    }

    // A GDI sheet: "count" then per track "number lba type sector-size file offset"; type 4 is data.
    private PatchSource gdiSourceFor(File file) throws IOException {
        PatchSource source = new PatchSource();
        source.cue = file;
        source.gdi = true;
        source.extension = ".gdi";
        source.cueLines = new ArrayList<>();
        try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(new FileInputStream(file), "ISO-8859-1"))) {
            String line;
            while ((line = reader.readLine()) != null) {
                java.util.regex.Matcher match = GDI_LINE.matcher(line);
                if (!source.cueLines.isEmpty() && match.matches()) {
                    String raw = match.group(4) != null ? match.group(4) : match.group(5);
                    File track = new File(file.getParentFile(), new File(new String(raw.getBytes("ISO-8859-1"), "UTF-8")).getName());
                    if (!track.isFile()) {
                        throw new IOException("GDI에 적힌 트랙 파일(" + track.getName() + ")이 없어요. 트랙 파일도 함께 가져와 주세요.");
                    }
                    source.cueFileLines.add(source.cueLines.size());
                    source.tracks.add(track);
                    source.dataTracks.add("4".equals(match.group(2)));
                }
                source.cueLines.add(line);
            }
        }
        if (source.tracks.isEmpty()) {
            throw new IOException("GDI 파일에 트랙이 없어요.");
        }
        source.rom = source.tracks.get(0);
        return source;
    }

    // Which tracks of a CUE sheet hold data (the TRACK line after each FILE line is not AUDIO).
    private static void markCueDataTracks(PatchSource source) {
        source.dataTracks.clear();
        for (int k = 0; k < source.cueFileLines.size(); k++) {
            int from = source.cueFileLines.get(k) + 1;
            int to = k + 1 < source.cueFileLines.size() ? source.cueFileLines.get(k + 1) : source.cueLines.size();
            boolean data = true;
            for (int line = from; line < to; line++) {
                String text = source.cueLines.get(line).trim().toUpperCase(Locale.ROOT);
                if (text.startsWith("TRACK")) {
                    data = !text.contains("AUDIO");
                    break;
                }
            }
            source.dataTracks.add(data);
        }
    }

    private String spanLabel(PatchSource source, DiscPatch item) {
        if (item.span <= 1) {
            return trackLabel(source, item.track);
        }
        long size = 0;
        StringBuilder names = new StringBuilder();
        for (int k = item.track; k < item.track + item.span; k++) {
            size += source.tracks.get(k).length();
            names.append(names.length() == 0 ? "Track " : " + ").append(String.format(Locale.ROOT, "%02d", k + 1));
        }
        return names + " (이어서) · " + formatSize(size);
    }

    private String trackLabel(PatchSource source, int k) {
        boolean data = k < source.dataTracks.size() && source.dataTracks.get(k);
        return String.format(Locale.ROOT, "Track %02d", k + 1) + " · " + source.tracks.get(k).getName() + " · " + formatSize(source.tracks.get(k).length())
                + " · " + (data ? "데이터" : "음악");
    }

    // The track a patch belongs to, from what the patch says, then its name.
    private void placeDiscPatch(DiscPatch item, PatchSource source) throws IOException {
        boolean anyRejects = false;
        int rejects = 0;
        if (item.format == RomPatcher.BPS || item.format == RomPatcher.UPS || item.format == RomPatcher.PPF) {
            for (int k = 0; k < source.tracks.size(); k++) {
                RomPatcher.Check check = RomPatcher.check(item.patch, source.tracks.get(k));
                if (check.sourceMatches > 0) {
                    item.track = k;
                    item.reason = "원본 CRC 일치";
                    return;
                }
                if (check.sourceMatches < 0) {
                    anyRejects = true;
                    rejects++;
                }
            }
            if (anyRejects && rejects == source.tracks.size()) {
                item.noMatch = true;
                item.reason = "이 디스크의 트랙과 맞지 않아요";
                return;
            }
        }
        if (item.format == RomPatcher.XDELTA) {
            long end = RomPatcher.xdeltaSourceEnd(item.patch);
            if (end > 0) {
                // Made on a Redump track: pregap + this track, exactly.
                for (int k = 0; k < source.tracks.size(); k++) {
                    File pregap = new File(source.tracks.get(k).getPath() + ".pregap");
                    long size = source.tracks.get(k).length();
                    if (pregap.isFile() && pregap.length() > 0 && end > size && end <= size + pregap.length()) {
                        item.track = k;
                        item.pregap = pregap;
                        item.reason = "원본 크기 = 프리갭 + 트랙 (Redump 방식)";
                        return;
                    }
                }
                // Exactly one track's size, or the track the patch's name gives.
                for (int k = 0; k < source.tracks.size(); k++) {
                    if (source.tracks.get(k).length() == end) {
                        item.track = k;
                        item.reason = "원본 크기와 같음";
                        return;
                    }
                }
                java.util.regex.Matcher named = TRACK_HINT.matcher(item.name);
                if (named.find()) {
                    int k = Integer.parseInt(named.group(1)) - 1;
                    if (k >= 0 && k < source.tracks.size()) {
                        item.track = k;
                        item.reason = "파일 이름";
                        return;
                    }
                }
                int only = -1;
                int count = 0;
                for (int k = 0; k < source.tracks.size(); k++) {
                    if (source.dataTracks.get(k) && source.tracks.get(k).length() >= end) {
                        only = k;
                        count++;
                    }
                }
                if (count == 1) {
                    item.track = only;
                    item.reason = "원본 크기와 맞음";
                    return;
                }
                // A patch made for several tracks joined into one file (some patches for
                // discs dumped as one .bin): consecutive tracks whose sizes add up to exactly
                // what the patch reads and makes, so the result splits back at the same places.
                if (count == 0 && RomPatcher.xdeltaTargetSize(item.patch) == end) {
                    for (int k = 0; k < source.tracks.size(); k++) {
                        long sum = 0;
                        for (int n = k; n < source.tracks.size() && sum < end; n++) {
                            sum += source.tracks.get(n).length();
                            if (sum == end && n > k) {
                                item.track = k;
                                item.span = n - k + 1;
                                item.reason = "원본 크기 = 트랙 " + (n - k + 1) + "개를 이어 붙인 크기";
                                return;
                            }
                        }
                    }
                }
            }
        }
        java.util.regex.Matcher hint = TRACK_HINT.matcher(item.name);
        if (hint.find()) {
            int k = Integer.parseInt(hint.group(1)) - 1;
            if (k >= 0 && k < source.tracks.size()) {
                item.track = k;
                item.reason = "파일 이름";
                return;
            }
        }
        if (source.tracks.size() == 1) {
            item.track = 0;
            item.reason = "트랙이 하나뿐";
        }
    }

    private void pickDiscPatches(File file) {
        this.patchRom = file;
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("*/*");
        intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
        try {
            startActivityForResult(intent, REQUEST_PICK_PATCH);
        } catch (Exception e) {
            showError("파일을 고르는 화면을 열 수 없어요.");
        }
    }

    private void onDiscPatchesPicked(final List<Uri> uris) {
        final File file = this.patchRom;
        if (file == null || uris.isEmpty()) {
            return;
        }
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setMessage("패치 파일과 트랙을 확인하는 중…");
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            List<DiscPatch> items = new ArrayList<>();
            PatchSource source = null;
            String error = null;
            try {
                source = file.getName().toLowerCase(Locale.ROOT).endsWith(".gdi") ? gdiSourceFor(file) : patchSourceFor(file);
                if (!source.gdi) {
                    markCueDataTracks(source);
                }
                int dcps = 0;
                for (Uri uri : uris) {
                    String shown = displayNameFor(uri);
                    if (shown != null && shown.toLowerCase(Locale.ROOT).endsWith(".dcp")) {
                        dcps++;
                    }
                }
                if (dcps > 0) {
                    boolean dcCue = MODE_DC.equals(modeForFile(file)) && file.getName().toLowerCase(Locale.ROOT).endsWith(".cue");
                    if (!source.gdi && !dcCue) {
                        throw new IOException(".dcp 패치는 드림캐스트 GDI · CUE 게임에만 적용할 수 있어요.");
                    }
                    if (uris.size() > 1) {
                        throw new IOException(".dcp 패치는 한 번에 하나만 골라 주세요 (다른 패치와 함께 고를 수 없어요).");
                    }
                    DiscPatch item = new DiscPatch();
                    item.name = displayNameFor(uris.get(0));
                    item.file = new File(getCacheDir(), "patch_input.dcp");
                    try (InputStream in = getContentResolver().openInputStream(uris.get(0)); OutputStream out = new FileOutputStream(item.file)) {
                        if (in == null) {
                            throw new IOException(item.name + "을(를) 열 수 없어요.");
                        }
                        byte[] buffer = new byte[1 << 16];
                        int n;
                        while ((n = in.read(buffer)) > 0) {
                            out.write(buffer, 0, n);
                        }
                    }
                    final DcpPatcher.Plan plan;
                    try {
                        plan = DcpPatcher.inspect(file, item.file);
                    } catch (IOException e) {
                        item.file.delete();
                        throw e;
                    }
                    runOnUiThread(() -> {
                        if (isFinishing() || isDestroyed()) {
                            item.file.delete();
                            return;
                        }
                        progress.dismiss();
                        showDcpDialog(file, item, plan);
                    });
                    return;
                }
                for (int k = 0; k < uris.size(); k++) {
                    DiscPatch item = new DiscPatch();
                    String shown = displayNameFor(uris.get(k));
                    item.name = shown == null ? "패치 " + (k + 1) : shown;
                    item.file = new File(getCacheDir(), "patch_input_" + k);
                    try (InputStream in = getContentResolver().openInputStream(uris.get(k)); OutputStream out = new FileOutputStream(item.file)) {
                        if (in == null) {
                            throw new IOException(item.name + "을(를) 열 수 없어요.");
                        }
                        byte[] buffer = new byte[1 << 16];
                        int n;
                        while ((n = in.read(buffer)) > 0) {
                            out.write(buffer, 0, n);
                        }
                    }
                    item.patch = RomPatcher.Big.map(item.file, 0, item.file.length(), false);
                    item.format = RomPatcher.detect(item.patch);
                    placeDiscPatch(item, source);
                    items.add(item);
                }
            } catch (IOException e) {
                error = e.getMessage();
            } catch (OutOfMemoryError e) {
                error = "패치 파일이 너무 커서 열 수 없어요.";
            }
            if (error != null) {
                deleteDiscPatchFiles(items);
            }
            final PatchSource found = source;
            final String why = error;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) {
                    return;
                }
                progress.dismiss();
                if (why != null) {
                    showError(why);
                    return;
                }
                showDiscPatchDialog(file, items, found);
            });
        }, "disc-patch-check").start();
    }

    private static void deleteDiscPatchFiles(List<DiscPatch> items) {
        for (DiscPatch item : items) {
            if (item.patch != null) {
                item.patch.close();
            }
            if (item.file != null) {
                item.file.delete();
            }
        }
    }

    private void showDiscPatchDialog(final File file, final List<DiscPatch> items, final PatchSource source) {
        final Dialog dialog = new Dialog(this);
        dialog.requestWindowFeature(1);
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        panel.setPadding(dp(16), dp(18), dp(16), dp(16));
        panel.setBackground(rounded(-1, dp(24)));
        LinearLayout header = new LinearLayout(this);
        header.setGravity(16);
        header.addView(new RoundIconView(this, RoundIconView.PATCH, RoundIconView.COLOR_PATCH), new LinearLayout.LayoutParams(dp(36), dp(36)));
        LinearLayout titles = new LinearLayout(this);
        titles.setOrientation(1);
        TextView title = new TextView(this);
        title.setText("패치 적용");
        title.setTextSize(17.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        titles.addView(title);
        final String gameName = displayGameNameFor(file);
        TextView sub = new TextView(this);
        sub.setText(gameName + " · " + (source.gdi ? "GDI" : "CUE") + " 트랙 " + source.tracks.size() + "개");
        sub.setTextSize(12.0f);
        sub.setTextColor(Theme.text(Color.rgb(122, 130, 140)));
        titles.addView(sub);
        LinearLayout.LayoutParams titlesParams = new LinearLayout.LayoutParams(0, -2, 1.0f);
        titlesParams.setMargins(dp(10), 0, 0, 0);
        header.addView(titles, titlesParams);
        panel.addView(header);
        panel.addView(patchStepBar(2));
        TextView count = new TextView(this);
        count.setText("패치 파일 " + items.size() + "개 · 줄을 누르면 트랙을 바꿔요");
        count.setTextSize(12.0f);
        count.setTypeface(Typeface.DEFAULT_BOLD);
        count.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        count.setPadding(0, dp(12), 0, 0);
        panel.addView(count);
        final LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(1);
        panel.addView(rows, new LinearLayout.LayoutParams(-1, -2));
        final Runnable[] render = new Runnable[1];
        render[0] = () -> {
            rows.removeAllViews();
            for (DiscPatch item : items) {
                boolean open = item.track < 0;
                LinearLayout row = new LinearLayout(this);
                row.setOrientation(1);
                row.setPadding(dp(11), dp(9), dp(11), dp(9));
                GradientDrawable background = rounded(open ? Color.rgb(255, 251, 235) : Color.rgb(246, 247, 249), dp(12));
                if (open) {
                    background.setStroke(dp(2), Theme.line(Color.rgb(245, 158, 11)));
                }
                row.setBackground(background);
                TextView name = new TextView(this);
                name.setText(item.name + " · " + RomPatcher.formatName(item.format));
                name.setTextSize(12.5f);
                name.setTypeface(Typeface.DEFAULT_BOLD);
                name.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
                row.addView(name);
                TextView target = new TextView(this);
                if (open) {
                    target.setText("→ 트랙 고르기 ▾ · " + (item.noMatch ? item.reason : "정해지지 않았어요"));
                    target.setTextColor(Theme.text(Color.rgb(180, 83, 9)));
                } else {
                    target.setText("→ " + spanLabel(source, item) + " · ✓ " + item.reason);
                    target.setTextColor(Theme.text(Color.rgb(22, 101, 52)));
                }
                target.setTextSize(11.0f);
                row.addView(target);
                row.setOnClickListener(view -> chooseTrack(item, source, render[0]));
                LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(-1, -2);
                rowParams.setMargins(0, dp(7), 0, 0);
                rows.addView(row, rowParams);
            }
        };
        render[0].run();
        TextView nameLabel = new TextView(this);
        nameLabel.setText("새 게임 이름");
        nameLabel.setTextSize(12.0f);
        nameLabel.setTypeface(Typeface.DEFAULT_BOLD);
        nameLabel.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        nameLabel.setPadding(0, dp(12), 0, 0);
        panel.addView(nameLabel);
        final EditText nameField = new EditText(this);
        nameField.setSingleLine(true);
        nameField.setText(gameName + " (한글)");
        nameField.setTextSize(14.0f);
        nameField.setTypeface(Typeface.DEFAULT_BOLD);
        GradientDrawable fieldBackground = rounded(-1, dp(10));
        fieldBackground.setStroke(Math.max(1, Math.round(1.5f * getResources().getDisplayMetrics().density)), Theme.line(Color.rgb(212, 215, 220)));
        nameField.setBackground(fieldBackground);
        nameField.setPadding(dp(10), dp(8), dp(10), dp(8));
        LinearLayout.LayoutParams fieldParams = new LinearLayout.LayoutParams(-1, -2);
        fieldParams.setMargins(0, dp(6), 0, 0);
        panel.addView(nameField, fieldParams);
        long total = 0;
        for (File track : source.tracks) {
            total += track.length();
        }
        long free = new android.os.StatFs(file.getParentFile().getAbsolutePath()).getAvailableBytes();
        TextView note = new TextView(this);
        note.setText("원본은 그대로 두고 새 게임으로 추가해요. 패치하지 않는 트랙은 그대로 복사돼요 (약 " + formatSize(total) + " 필요 · 남은 공간 " + formatSize(free) + "). 같은 트랙에 패치가 둘이면 고른 순서대로 이어서 적용해요.");
        note.setTextSize(11.5f);
        note.setTextColor(Theme.text(Color.rgb(14, 95, 107)));
        note.setLineSpacing(0, 1.15f);
        note.setPadding(dp(12), dp(9), dp(12), dp(9));
        note.setBackground(rounded(Color.rgb(236, 254, 255), dp(12)));
        LinearLayout.LayoutParams noteParams = new LinearLayout.LayoutParams(-1, -2);
        noteParams.setMargins(0, dp(12), 0, 0);
        panel.addView(note, noteParams);
        addSaveWhereSection(panel, file);
        final CheckBox carry = addSaveCarryBox(panel, file, false, "원본 세이브 같이 쓰기");
        LinearLayout buttons = new LinearLayout(this);
        TextView cancel = new TextView(this);
        cancel.setText("← 이전");
        cancel.setTextSize(15.0f);
        cancel.setTypeface(Typeface.DEFAULT_BOLD);
        cancel.setTextColor(Theme.text(Color.rgb(75, 85, 99)));
        cancel.setGravity(17);
        cancel.setBackground(rounded(Color.rgb(241, 242, 244), dp(14)));
        cancel.setOnClickListener(view -> {
            dialog.dismiss();
            showPatchPrep(file);
        });
        buttons.addView(cancel, new LinearLayout.LayoutParams(0, dp(48), 1.0f));
        TextView apply = new TextView(this);
        apply.setText("패치 적용");
        apply.setTextSize(15.0f);
        apply.setTypeface(Typeface.DEFAULT_BOLD);
        apply.setTextColor(-1);
        apply.setGravity(17);
        apply.setBackground(rounded(RoundIconView.COLOR_PATCH, dp(14)));
        apply.setOnClickListener(view -> {
            for (DiscPatch item : items) {
                if (item.track < 0) {
                    showError(item.name + "을(를) 어느 트랙에 적용할지 골라 주세요.");
                    return;
                }
            }
            String newName = nameField.getText().toString().trim();
            if (newName.isEmpty()) {
                showError("이름을 비워둘 수 없습니다.");
                return;
            }
            this.carrySaveFrom = carry != null && carry.isChecked() ? file : null;
            this.patchRunning = true;
            dialog.dismiss();
            runDiscPatch(file, gameName, newName, items, source);
        });
        LinearLayout.LayoutParams applyParams = new LinearLayout.LayoutParams(0, dp(48), 1.4f);
        applyParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(apply, applyParams);
        LinearLayout.LayoutParams buttonsParams = new LinearLayout.LayoutParams(-1, -2);
        buttonsParams.setMargins(0, dp(14), 0, 0);
        panel.addView(buttons, buttonsParams);
        ScrollView scroll = new ScrollView(this);
        scroll.addView(panel);
        dialog.setContentView(scroll);
        dialog.setOnDismissListener(d -> {
            if (!this.patchRunning) {
                deleteDiscPatchFiles(items);
            }
        });
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(0));
            window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels - dp(36), dp(420)), -2);
        }
        dialog.show();
    }

    // "어느 트랙에 적용할까요?": every track, the likely one first marked, music tracks last.
    private void chooseTrack(DiscPatch item, PatchSource source, Runnable done) {
        int suggested = item.track;
        if (suggested < 0) {
            // The biggest data track: where a translation usually goes.
            long best = -1;
            for (int k = 0; k < source.tracks.size(); k++) {
                if (source.dataTracks.get(k) && source.tracks.get(k).length() > best) {
                    best = source.tracks.get(k).length();
                    suggested = k;
                }
            }
        }
        String[] names = new String[source.tracks.size()];
        for (int k = 0; k < names.length; k++) {
            names[k] = trackLabel(source, k) + (k == suggested ? "  · 추천" : "");
        }
        new AppDialog.Builder(this).setTitle("어느 트랙에 적용할까요?")
                .setMessage(item.name + "\n안내문에 적힌 트랙을 고르세요 (예: track5.bin → Track 05).")
                .setItems(names, (d, which) -> {
                    item.track = which;
                    item.span = 1;
                    item.noMatch = false;
                    item.reason = "직접 고름";
                    done.run();
                })
                .setNegativeButton("취소", null).show();
    }

    private void runDiscPatch(File file, String originalName, String newName, List<DiscPatch> items, PatchSource source) {
        File dir = outputDirFor(file);
        String base = sanitizeSaveBaseName(newName);
        boolean multi = source.tracks.size() > 1;
        String chosen = base;
        for (int k = 2; patchTargetsExist(dir, chosen, source, true, multi); k++) {
            chosen = base + " " + k;
        }
        final String name = chosen;
        final File out = new File(dir, name + (source.gdi ? ".gdi" : ".cue"));
        long needed = 0;
        for (File track : source.tracks) {
            needed += track.length();
        }
        for (DiscPatch item : items) {
            for (int k = item.track; item.span > 1 && k < item.track + item.span; k++) {
                needed += 2 * source.tracks.get(k).length();  // the joined copy and its patched copy, for a while
            }
            if (item.pregap != null && item.track >= 0) {
                needed += 2 * (source.tracks.get(item.track).length() + item.pregap.length());
            }
        }
        long free = new android.os.StatFs(dir.getAbsolutePath()).getAvailableBytes();
        if (free < needed + 64L * 1024 * 1024) {
            deleteDiscPatchFiles(items);
            this.patchRunning = false;
            showError("저장 공간이 부족해요. 패치한 복사본을 만들려면 " + formatSize(needed) + " 정도가 필요한데, 남은 공간은 " + formatSize(free) + "예요.");
            return;
        }
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setMessage(needed > 512L * 1024 * 1024 ? "패치를 적용하는 중… 디스크가 커서 몇 분 걸릴 수 있어요" : "패치를 적용하는 중…");
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            String error = null;
            List<File> written = new ArrayList<>();
            java.util.TreeSet<Integer> patchedTracks = new java.util.TreeSet<>();
            List<String> builtGaps = new ArrayList<>();
            File[] joinedResult = new File[source.tracks.size()];
            try {
                // Patches for joined tracks: join them, patch, and split the result back.
                for (DiscPatch item : items) {
                    if (item.span <= 1) {
                        continue;
                    }
                    for (int k = item.track; k < item.track + item.span; k++) {
                        if (joinedResult[k] != null) {
                            throw new IOException(item.name + "과(와) 다른 패치가 같은 트랙(Track " + String.format(Locale.ROOT, "%02d", k + 1) + ")을 이어 붙여 바꿔요. 하나씩 적용해 주세요.");
                        }
                    }
                    File joined = new File(dir, "." + name + ".joined.patching");
                    File patched = new File(dir, "." + name + ".joined-out.patching");
                    try {
                        try (OutputStream joinOut = new java.io.BufferedOutputStream(new FileOutputStream(joined), 1 << 20)) {
                            byte[] buffer = new byte[1 << 20];
                            for (int k = item.track; k < item.track + item.span; k++) {
                                try (InputStream in = new FileInputStream(source.tracks.get(k))) {
                                    int n;
                                    while ((n = in.read(buffer)) > 0) {
                                        joinOut.write(buffer, 0, n);
                                    }
                                }
                            }
                        }
                        RomPatcher.Check check = RomPatcher.check(item.patch, joined);
                        RomPatcher.apply(item.patch, joined, check, patched);
                        joined.delete();
                        if (patched.length() != RomPatcher.xdeltaTargetSize(item.patch)) {
                            throw new IOException("패치한 결과의 크기가 맞지 않아요.");
                        }
                        try (InputStream in = new java.io.BufferedInputStream(new FileInputStream(patched), 1 << 20)) {
                            byte[] buffer = new byte[1 << 20];
                            for (int k = item.track; k < item.track + item.span; k++) {
                                File part = new File(dir, "." + trackName(name, k, source, multi) + ".patching");
                                long left = source.tracks.get(k).length();
                                try (OutputStream partOut = new FileOutputStream(part)) {
                                    while (left > 0) {
                                        int n = in.read(buffer, 0, (int) Math.min(buffer.length, left));
                                        if (n <= 0) {
                                            throw new IOException("패치한 결과를 트랙으로 나누지 못했어요.");
                                        }
                                        partOut.write(buffer, 0, n);
                                        left -= n;
                                    }
                                }
                                joinedResult[k] = part;
                            }
                        }
                    } finally {
                        joined.delete();
                        patched.delete();
                    }
                }
                for (int k = 0; k < source.tracks.size(); k++) {
                    File target = new File(dir, trackName(name, k, source, multi));
                    File current = source.tracks.get(k);
                    boolean first = true;
                    if (joinedResult[k] != null) {
                        current = joinedResult[k];
                        joinedResult[k] = null;
                        first = false;
                        patchedTracks.add(k + 1);
                    }
                    for (DiscPatch item : items) {
                        if (item.track != k || item.span > 1) {
                            continue;
                        }
                        File temp = new File(dir, "." + target.getName() + ".patching");
                        if (item.pregap != null) {
                            try {
                                applyWithPregap(item, current, temp, dir);
                            } catch (IOException e) {
                                throw new IOException(item.name + " → Track " + String.format(Locale.ROOT, "%02d", k + 1) + ": " + e.getMessage()
                                        + "\n\n" + trackDiagnosis(current, item.pregap, item));
                            }
                            if (!first) {
                                current.delete();
                            }
                            current = temp;
                            first = false;
                            patchedTracks.add(k + 1);
                            continue;
                        }
                        RomPatcher.Check check = RomPatcher.check(item.patch, current);
                        if (check.sourceMatches < 0) {
                            throw new IOException(item.name + "이(가) Track " + String.format(Locale.ROOT, "%02d", k + 1) + "과(와) 맞지 않아요. 안내문의 트랙과 원본 버전을 확인해 주세요.");
                        }
                        try {
                            RomPatcher.apply(item.patch, current, check, temp);
                        } catch (IOException e) {
                            temp.delete();
                            // It may have been made on the Redump track (pregap + track) though its
                            // size couldn't tell: try that before giving up.
                            File stored = new File(source.tracks.get(k).getPath() + ".pregap");
                            if (stored.isFile() && stored.length() > 0) {
                                item.pregap = stored;
                                try {
                                    applyWithPregap(item, current, temp, dir);
                                    if (!first) {
                                        current.delete();
                                    }
                                    current = temp;
                                    first = false;
                                    patchedTracks.add(k + 1);
                                    continue;
                                } catch (IOException again) {
                                    item.pregap = null;
                                }
                            }
                            // No pregap kept (the CHD didn't store it): rebuild the gap the patch reads
                            // in front of the track from what such a gap holds, and let the patch's
                            // own check values say which one is right.
                            long gap = RomPatcher.xdeltaSourceEnd(item.patch) - current.length();
                            int lba = gdiTrackLba(source, k);
                            if (source.gdi && gap > 0 && gap <= 300L * CdSector.SIZE && lba > 0
                                    && k < source.dataTracks.size() && source.dataTracks.get(k)) {
                                // What the patch reads ends at or before the original's end, so the
                                // gap is at least that many frames: the usual 225 (3 s) first.
                                int least = (int) ((gap + CdSector.SIZE - 1) / CdSector.SIZE);
                                String used = null;
                                java.util.LinkedHashSet<Integer> sizes = new java.util.LinkedHashSet<>(Arrays.asList(225, least, 150, 75, 300));
                                for (int frames : sizes) {
                                    if (used == null && frames >= least) {
                                        used = applyWithBuiltPregap(item, current, temp, dir, lba, frames);
                                    }
                                }
                                if (used != null) {
                                    if (!first) {
                                        current.delete();
                                    }
                                    current = temp;
                                    first = false;
                                    patchedTracks.add(k + 1);
                                    builtGaps.add("Track " + String.format(Locale.ROOT, "%02d", k + 1) + ": " + used);
                                    continue;
                                }
                            }
                            if (!stored.isFile() && source.gdi
                                    && RomPatcher.xdeltaSourceEnd(item.patch) > current.length()) {
                                throw new IOException(item.name + " → Track " + String.format(Locale.ROOT, "%02d", k + 1) + ": " + e.getMessage()
                                        + "\n\n이 패치는 원본 트랙이 지금보다 커요 — Redump 덤프(트랙 앞 공백 포함)용 패치예요. CHD에 저장된 공백도, 앱이 다시 만들어 본 공백(75 · 150 · 225 · 300섹터)도 맞지 않았어요. 패치 안내문의 원본과 다른 덤프일 수 있어요.\n\n"
                                        + trackDiagnosis(current, null, item));
                            }
                            throw new IOException(item.name + " → Track " + String.format(Locale.ROOT, "%02d", k + 1) + ": " + e.getMessage()
                                    + "\n\n" + trackDiagnosis(current, stored.isFile() ? stored : null, item));
                        }
                        if (!first) {
                            current.delete();
                        }
                        current = temp;
                        first = false;
                        patchedTracks.add(k + 1);
                    }
                    if (first) {
                        if (!copyFile(current, target)) {
                            throw new IOException("트랙 파일을 복사하지 못했어요.");
                        }
                    } else if (!current.renameTo(target)) {
                        current.delete();
                        throw new IOException("패치한 트랙을 저장하지 못했어요.");
                    }
                    written.add(target);
                    // The track's stored pregap goes along, for patches on top of this one.
                    File pregap = new File(source.tracks.get(k).getPath() + ".pregap");
                    if (pregap.isFile()) {
                        File pregapCopy = new File(target.getPath() + ".pregap");
                        if (copyFile(pregap, pregapCopy)) {
                            written.add(pregapCopy);
                        }
                    }
                }
                // The sheet with the new track names; other lines as they were (bytes kept).
                List<String> lines = new ArrayList<>(source.cueLines);
                java.util.Set<Integer> renamed = new java.util.HashSet<>();
                for (int k = 0; k < source.tracks.size(); k++) {
                    int index = source.cueFileLines.get(k);
                    String track = trackName(name, k, source, multi);
                    if (source.gdi) {
                        java.util.regex.Matcher match = GDI_LINE.matcher(lines.get(index));
                        if (match.matches()) {
                            lines.set(index, match.group(1) + "\"" + track + "\"" + (match.group(6) == null ? "" : match.group(6)));
                            renamed.add(index);
                        }
                    } else {
                        java.util.regex.Matcher match = CUE_FILE.matcher(lines.get(index));
                        if (match.matches()) {
                            lines.set(index, match.group(1) + "\"" + track + "\"" + match.group(5));
                            renamed.add(index);
                        }
                    }
                }
                try (OutputStream writer = new FileOutputStream(out)) {
                    for (int k = 0; k < lines.size(); k++) {
                        writer.write(lines.get(k).getBytes(renamed.contains(k) ? "UTF-8" : "ISO-8859-1"));
                        writer.write(new byte[]{'\r', '\n'});
                    }
                }
                written.add(out);
            } catch (IOException e) {
                error = e.getMessage();
            } catch (OutOfMemoryError e) {
                error = "메모리가 부족해서 패치하지 못했어요.";
            } finally {
                deleteDiscPatchFiles(items);
                for (File part : joinedResult) {
                    if (part != null) {
                        part.delete();
                    }
                }
            }
            if (error != null) {
                for (File f : written) {
                    f.delete();
                }
            }
            final String why = error;
            final String tracksText = android.text.TextUtils.join(" · ", patchedTracks);
            runOnUiThread(() -> {
                this.patchRunning = false;
                if (isFinishing() || isDestroyed()) {
                    return;
                }
                progress.dismiss();
                if (why != null) {
                    showError(why);
                    return;
                }
                romPrefs().edit().putString("title:" + out.getName(), newName).putString("patched:" + out.getName(), originalName)
                        .putString("patched_tracks:" + out.getName(), tracksText).putString("patched_from:" + out.getName(), file.getName()).apply();
                finishNewGame(file, out, this.carrySaveFrom != null);
                this.carrySaveFrom = null;
                List<String> logLines = new ArrayList<>();
                for (DiscPatch item : items) {
                    logLines.add(item.name + " → " + (item.span > 1 ? spanLabel(source, item) : String.format(Locale.ROOT, "Track %02d", item.track + 1))
                            + (item.reason.isEmpty() ? "" : " (" + item.reason + ")"));
                }
                recordPatch(out, "트랙 패치", logLines);
                Toast.makeText(this, "패치 " + items.size() + "개를 적용했어요 (Track " + tracksText + ") · 목록에 추가됨", Toast.LENGTH_LONG).show();
                refreshLibrary();
            });
        }, "disc-patch").start();
    }

    // ---- 드림캐스트 CHD 풀기 · .dcp 패치 ----

    // CHD games that can be unpacked: Dreamcast (GDI), CD consoles (CUE + BIN), PS2 (ISO).
    private static boolean isDcChd(File file, String mode) {
        return file.getName().toLowerCase(Locale.ROOT).endsWith(".chd") && (MODE_DC.equals(mode) || MODE_PS1.equals(mode) || MODE_SS.equals(mode)
                || MODE_MCD.equals(mode) || MODE_PCE.equals(mode) || MODE_PS2.equals(mode));
    }

    // "GDI" / "CUE" / "ISO": what a console's CHD unpacks to.
    private static String unpackFormat(String mode) {
        return MODE_DC.equals(mode) ? "GDI" : MODE_PS2.equals(mode) ? "ISO" : "CUE";
    }

    private static String unpackFiles(String mode) {
        return MODE_DC.equals(mode) ? ".gdi + 트랙" : MODE_PS2.equals(mode) ? ".iso 한 파일" : ".cue + 트랙";
    }

    private LinearLayout createUnpackRow(Dialog dialog, File file) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(0);
        row.setGravity(16);
        row.setPadding(dp(14), 0, dp(14), 0);
        row.setBackground(rounded(Color.rgb(246, 247, 249), dp(14)));
        String mode = modeForFile(file);
        row.addView(new RoundIconView(this, RoundIconView.FOLDER, MODE_COLORS[modeIndex(mode)]), new LinearLayout.LayoutParams(dp(32), dp(32)));
        TextView label = new TextView(this);
        label.setText(unpackFormat(mode) + "로 풀기");
        label.setTextSize(14.0f);
        label.setTypeface(Typeface.DEFAULT_BOLD);
        label.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        LinearLayout.LayoutParams labelParams = new LinearLayout.LayoutParams(-2, -2);
        labelParams.setMargins(dp(12), 0, 0, 0);
        row.addView(label, labelParams);
        row.addView(new View(this), new LinearLayout.LayoutParams(0, 1, 1.0f));
        TextView value = new TextView(this);
        value.setText(unpackFiles(mode) + "  ›");
        value.setTextSize(12.5f);
        value.setTypeface(Typeface.DEFAULT_BOLD);
        value.setTextColor(Theme.text(Color.rgb(122, 130, 140)));
        row.addView(value);
        row.setClickable(true);
        row.setOnClickListener(view -> {
            dialog.dismiss();
            showChdUnpack(file, false);
        });
        return row;
    }

    // ---- (0.0.406) "ISO로 풀기": a compressed GameCube / Wii disc as a plain .iso (Dolphin) ----

    private boolean isGcCompressed(File file) {
        if (file == null || file.isDirectory() || !MODE_GC.equals(modeForFile(file))) {
            return false;
        }
        String name = file.getName().toLowerCase(Locale.ROOT);
        return name.endsWith(".rvz") || name.endsWith(".wia") || name.endsWith(".gcz") || name.endsWith(".ciso") || name.endsWith(".wbfs");
    }

    private static String extensionUpper(File file) {
        String name = file.getName();
        int dot = name.lastIndexOf('.');
        return dot < 0 ? "" : name.substring(dot + 1).toUpperCase(Locale.ROOT);
    }

    private LinearLayout createGcUnpackRow(Dialog dialog, File file) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(0);
        row.setGravity(16);
        row.setPadding(dp(14), 0, dp(14), 0);
        row.setBackground(rounded(Color.rgb(246, 247, 249), dp(14)));
        row.addView(new RoundIconView(this, RoundIconView.FOLDER, MODE_COLORS[modeIndex(MODE_GC)]), new LinearLayout.LayoutParams(dp(32), dp(32)));
        TextView label = new TextView(this);
        label.setText("ISO로 풀기");
        label.setTextSize(14.0f);
        label.setTypeface(Typeface.DEFAULT_BOLD);
        label.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        LinearLayout.LayoutParams labelParams = new LinearLayout.LayoutParams(-2, -2);
        labelParams.setMargins(dp(12), 0, 0, 0);
        row.addView(label, labelParams);
        row.addView(new View(this), new LinearLayout.LayoutParams(0, 1, 1.0f));
        TextView value = new TextView(this);
        value.setText(extensionUpper(file) + " → .iso  ›");
        value.setTextSize(12.5f);
        value.setTypeface(Typeface.DEFAULT_BOLD);
        value.setTextColor(Theme.text(Color.rgb(122, 130, 140)));
        row.addView(value);
        row.setClickable(true);
        row.setOnClickListener(view -> {
            dialog.dismiss();
            showGcUnpack(file, false);
        });
        return row;
    }

    private void showGcUnpack(final File disc, final boolean thenPatch) {
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setMessage("디스크를 확인하는 중…");
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            long size;
            try {
                size = NativeGba.dolphinPlainSize(disc.getAbsolutePath());
            } catch (Throwable error) {
                size = -1;
            }
            final long bytes = size;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) {
                    return;
                }
                progress.dismiss();
                if (bytes <= 0) {
                    showError("이 " + extensionUpper(disc) + " 파일을 게임큐브 · Wii 디스크로 읽지 못했어요. 파일이 깨졌거나, 이 APK에 게임큐브 · Wii 엔진이 없을 수 있어요.");
                    return;
                }
                showGcUnpackDialog(disc, thenPatch, bytes);
            });
        }, "gc-size").start();
    }

