    // ---- 한글 패치 적용 1단계: 원본 파일 (the game, fixed) and the patch files, then 다음 → the
    // checking window (2단계), which has ← 이전 back to here with the same files. ----

    private static final int REQUEST_PICK_PATCH_PREP = 1060;
    private File prepRom;
    private final List<Uri> prepUris = new ArrayList<>();
    private String prepError;
    private Dialog prepDialog;

    private long sizeForUri(Uri uri) {
        if ("file".equals(uri.getScheme()) && uri.getPath() != null) {
            return new File(uri.getPath()).length();
        }
        try (Cursor cursor = getContentResolver().query(uri, new String[]{android.provider.OpenableColumns.SIZE}, null, null, null)) {
            if (cursor != null && cursor.moveToFirst() && !cursor.isNull(0)) {
                return cursor.getLong(0);
            }
        } catch (RuntimeException e) {
            // Unknown.
        }
        return -1;
    }

    // The patch format from the file's first bytes ("IPS" …), ".dcp" by name, or null.
    private String patchKindOf(Uri uri) {
        String name = displayNameFor(uri);
        if (name != null && name.toLowerCase(Locale.ROOT).endsWith(".dcp")) {
            return ".dcp";
        }
        byte[] head = new byte[8];
        int got = 0;
        try (InputStream in = getContentResolver().openInputStream(uri)) {
            if (in == null) {
                return null;
            }
            int n;
            while (got < head.length && (n = in.read(head, got, head.length - got)) > 0) {
                got += n;
            }
        } catch (IOException | RuntimeException e) {
            return null;
        }
        String text = new String(head, 0, got, StandardCharsets.ISO_8859_1);
        if (text.startsWith("PATCH")) {
            return "IPS";
        }
        if (text.startsWith("UPS1")) {
            return "UPS";
        }
        if (text.startsWith("BPS1")) {
            return "BPS";
        }
        if (text.startsWith("PPF10") || text.startsWith("PPF20") || text.startsWith("PPF30")) {
            return "PPF";
        }
        if (got >= 3 && (head[0] & 0xFF) == 0xD6 && (head[1] & 0xFF) == 0xC3 && (head[2] & 0xFF) == 0xC4) {
            return "xdelta";
        }
        if (text.startsWith("APS1")) {
            return "APS";
        }
        if (text.startsWith("NINJA2")) {
            return "RUP";
        }
        if (text.startsWith("BSDIFF40")) {
            return "BDF";
        }
        return null;
    }

    // Opens 1단계 for a game; keeps the files already picked when it is the same game.
    private void showPatchPrep(File file) {
        if (!file.equals(this.prepRom)) {
            this.prepRom = file;
            this.prepUris.clear();
        }
        this.prepError = null;
        renderPatchPrep();
    }

    private void renderPatchPrep() {
        final File file = this.prepRom;
        if (file == null) {
            return;
        }
        if (this.prepDialog != null && this.prepDialog.isShowing()) {
            this.prepDialog.dismiss();
        }
        final boolean sheet = isDiscSheet(file);
        final int teal = RoundIconView.COLOR_PATCH;
        final Dialog dialog = new Dialog(this);
        this.prepDialog = dialog;
        dialog.requestWindowFeature(1);
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        panel.setPadding(dp(16), dp(18), dp(16), dp(16));
        panel.setBackground(rounded(-1, dp(24)));
        cardHeader(panel, RoundIconView.PATCH, teal, "한글 패치 적용", "1단계 · 원본과 패치 파일 고르기");
        panel.addView(patchStepBar(1));
        // 원본 파일
        panel.addView(prepLabel("원본 파일"));
        String type = file.getName().contains(".") ? file.getName().substring(file.getName().lastIndexOf('.') + 1).toUpperCase(Locale.ROOT) : "파일";
        String detail = type + (sheet ? " · 트랙 " + cueTracks(file).size() + "개" : "") + " · " + formatSize(romBytes(file)) + " · 원본은 바뀌지 않아요";
        LinearLayout source = prepCard(RoundIconView.FOLDER, MODE_COLORS[modeIndex(modeForFile(file))], file.getName(), detail, Color.rgb(246, 247, 249), 0);
        TextView lock = new TextView(this);
        lock.setText("🔒 원본");
        lock.setTextSize(10.5f);
        lock.setTypeface(Typeface.DEFAULT_BOLD);
        lock.setTextColor(Theme.text(Color.rgb(148, 163, 184)));
        source.addView(lock);
        panel.addView(source, prepCardParams());
        // 패치 파일
        panel.addView(prepLabel(sheet ? "패치 파일 (여러 개 가능)" : "패치 파일"));
        for (final Uri uri : new ArrayList<>(this.prepUris)) {
            String name = displayNameFor(uri);
            long size = sizeForUri(uri);
            String kind = patchKindOf(uri);
            LinearLayout card = prepCard(RoundIconView.PATCH, teal, name == null ? "패치 파일" : name,
                    (kind == null ? "?" : kind) + (size >= 0 ? " · " + formatSize(size) : "")
                            + (this.prepArchiveOf.containsKey(uri) ? " · 🗜 " + this.prepArchiveOf.get(uri) + " 안" : "") + " · 패치 파일 맞음 ✓", Color.rgb(236, 254, 255), teal);
            TextView remove = new TextView(this);
            remove.setText("✕");
            remove.setTextSize(15.0f);
            remove.setTextColor(Theme.text(Color.rgb(148, 163, 184)));
            remove.setPadding(dp(8), dp(4), dp(4), dp(4));
            remove.setOnClickListener(view -> {
                this.prepUris.remove(uri);
                renderPatchPrep();
            });
            card.addView(remove);
            panel.addView(card, prepCardParams());
        }
        if (this.prepError != null) {
            TextView error = new TextView(this);
            error.setText(this.prepError);
            error.setTextSize(12.0f);
            error.setTextColor(Theme.text(Color.rgb(185, 28, 28)));
            error.setLineSpacing(0, 1.15f);
            error.setPadding(dp(12), dp(10), dp(12), dp(10));
            GradientDrawable box = rounded(Color.rgb(254, 242, 242), dp(12));
            box.setStroke(dp(2), Theme.line(Color.rgb(252, 165, 165)));
            error.setBackground(box);
            panel.addView(error, prepCardParams());
        }
        if (sheet || this.prepUris.isEmpty()) {
            boolean first = this.prepUris.isEmpty();
            TextView pick = new TextView(this);
            pick.setText(this.prepError != null ? "📄 다시 고르기" : first ? "📄 패치 파일 고르기" : "📄 + 패치 더 고르기");
            pick.setTextSize(13.5f);
            pick.setTypeface(Typeface.DEFAULT_BOLD);
            pick.setGravity(17);
            boolean hl = this.prepError != null;
            pick.setTextColor(Theme.text(hl ? teal : Color.rgb(100, 116, 139)));
            GradientDrawable dashed = rounded(hl ? Color.rgb(236, 254, 255) : Color.WHITE, dp(12));
            dashed.setStroke(dp(2), Theme.line(hl ? teal : Color.rgb(203, 213, 225)), dp(6), dp(4));
            pick.setBackground(dashed);
            pick.setOnClickListener(view -> pickPrepPatch(sheet));
            LinearLayout.LayoutParams pickParams = new LinearLayout.LayoutParams(-1, dp(52));
            pickParams.setMargins(0, dp(6), 0, 0);
            panel.addView(pick, pickParams);
        } else {
            TextView change = new TextView(this);
            change.setText("다른 파일로 바꾸기");
            change.setTextSize(12.0f);
            change.setTypeface(Typeface.DEFAULT_BOLD);
            change.setTextColor(Theme.text(teal));
            change.setPadding(dp(2), dp(8), 0, 0);
            change.setOnClickListener(view -> pickPrepPatch(false));
            panel.addView(change);
        }
        TextView kinds = new TextView(this);
        kinds.setText(MODE_DC.equals(modeForFile(file)) && file.getName().toLowerCase(Locale.ROOT).endsWith(".gdi")
                ? "IPS · UPS · BPS · PPF · xdelta · APS · RUP · BDF · .dcp" : "IPS · UPS · BPS · PPF · xdelta · APS · RUP · BDF");
        kinds.setTextSize(11.0f);
        kinds.setTextColor(Theme.text(Color.rgb(107, 114, 128)));
        kinds.setPadding(dp(2), dp(6), 0, 0);
        panel.addView(kinds);
        LinearLayout buttons = new LinearLayout(this);
        TextView cancel = multiDeleteButton("취소", Color.rgb(241, 242, 244), Color.rgb(55, 65, 81));
        cancel.setOnClickListener(view -> {
            this.prepUris.clear();
            this.prepRom = null;
            dialog.dismiss();
        });
        buttons.addView(cancel, new LinearLayout.LayoutParams(0, dp(48), 1.0f));
        final boolean ready = !this.prepUris.isEmpty();
        TextView next = multiDeleteButton("다음 →", ready ? teal : Color.rgb(203, 213, 225), -1);
        next.setOnClickListener(view -> {
            if (!ready) {
                showMessage("패치 파일을 먼저 골라 주세요.");
                return;
            }
            dialog.dismiss();
            this.patchRom = file;
            if (sheet) {
                onDiscPatchesPicked(new ArrayList<>(this.prepUris));
            } else {
                onPatchPicked(this.prepUris.get(0));
            }
        });
        LinearLayout.LayoutParams nextParams = new LinearLayout.LayoutParams(0, dp(48), 1.6f);
        nextParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(next, nextParams);
        LinearLayout.LayoutParams buttonsParams = new LinearLayout.LayoutParams(-1, -2);
        buttonsParams.setMargins(0, dp(16), 0, 0);
        panel.addView(buttons, buttonsParams);
        ScrollView scroll = new ScrollView(this);
        scroll.addView(panel);
        dialog.setContentView(scroll);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(0));
            window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels - dp(36), dp(420)), -2);
        }
        dialog.show();
    }

    // "1 파일 고르기 — 2 확인 · 적용" under a patch window's title.
    private LinearLayout patchStepBar(int step) {
        int teal = RoundIconView.COLOR_PATCH;
        LinearLayout bar = new LinearLayout(this);
        bar.setOrientation(1);
        bar.setPadding(0, dp(10), 0, 0);
        LinearLayout lines = new LinearLayout(this);
        for (int k = 1; k <= 2; k++) {
            View line = new View(this);
            line.setBackground(rounded(k <= step ? teal : Color.rgb(226, 232, 240), dp(2)));
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, dp(4), 1.0f);
            params.setMargins(k == 1 ? 0 : dp(6), 0, 0, 0);
            lines.addView(line, params);
        }
        bar.addView(lines);
        LinearLayout labels = new LinearLayout(this);
        String[] names = {"1 파일 고르기", "2 확인 · 적용"};
        for (int k = 1; k <= 2; k++) {
            TextView label = new TextView(this);
            label.setText(names[k - 1]);
            label.setTextSize(10.5f);
            label.setTypeface(Typeface.DEFAULT_BOLD);
            label.setTextColor(Theme.text(k <= step ? teal : Color.rgb(148, 163, 184)));
            label.setGravity(k == 1 ? android.view.Gravity.START : android.view.Gravity.END);
            labels.addView(label, new LinearLayout.LayoutParams(0, -2, 1.0f));
        }
        bar.addView(labels);
        return bar;
    }

    private TextView prepLabel(String text) {
        TextView label = new TextView(this);
        android.text.SpannableStringBuilder value = new android.text.SpannableStringBuilder(text + " *");
        value.setSpan(new android.text.style.ForegroundColorSpan(Color.rgb(229, 72, 77)), text.length() + 1, value.length(), 0);
        label.setText(value);
        label.setTextSize(13.0f);
        label.setTypeface(Typeface.DEFAULT_BOLD);
        label.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        label.setPadding(0, dp(14), 0, 0);
        return label;
    }

    private LinearLayout prepCard(int icon, int color, String name, String detail, int background, int stroke) {
        LinearLayout card = new LinearLayout(this);
        card.setGravity(16);
        card.setPadding(dp(10), dp(9), dp(10), dp(9));
        GradientDrawable shape = rounded(background, dp(12));
        if (stroke != 0) {
            shape.setStroke(dp(2), Theme.line(stroke));
        }
        card.setBackground(shape);
        card.addView(new RoundIconView(this, icon, color), new LinearLayout.LayoutParams(dp(32), dp(32)));
        LinearLayout texts = new LinearLayout(this);
        texts.setOrientation(1);
        TextView title = new TextView(this);
        title.setText(name);
        title.setTextSize(13.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        title.setSingleLine(true);
        title.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);
        texts.addView(title);
        TextView sub = new TextView(this);
        sub.setText(detail);
        sub.setTextSize(11.0f);
        sub.setTextColor(Theme.text(stroke != 0 ? Color.rgb(15, 118, 110) : Color.rgb(107, 114, 128)));
        texts.addView(sub);
        LinearLayout.LayoutParams textsParams = new LinearLayout.LayoutParams(0, -2, 1.0f);
        textsParams.setMargins(dp(10), 0, 0, 0);
        card.addView(texts, textsParams);
        return card;
    }

    private LinearLayout.LayoutParams prepCardParams() {
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, -2);
        params.setMargins(0, dp(6), 0, 0);
        return params;
    }

    private void pickPrepPatch(boolean multiple) {
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("*/*");
        if (multiple) {
            intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
        }
        try {
            startActivityForResult(intent, REQUEST_PICK_PATCH_PREP);
        } catch (Exception e) {
            showError("파일을 고르는 화면을 열 수 없어요.");
        }
    }

    private void onPrepPatchesPicked(Intent intent) {
        File file = this.prepRom;
        if (file == null) {
            return;
        }
        List<Uri> picked = new ArrayList<>();
        android.content.ClipData clip = intent.getClipData();
        for (int k = 0; clip != null && k < clip.getItemCount(); k++) {
            if (clip.getItemAt(k).getUri() != null) {
                picked.add(clip.getItemAt(k).getUri());
            }
        }
        if (picked.isEmpty() && intent.getData() != null) {
            picked.add(intent.getData());
        }
        if (MODE_PS2.equals(modeForFile(file)) && file.getName().toLowerCase(Locale.ROOT).endsWith(".iso") && offerPs2RecipeOnIso(file, picked)) {
            return;  // 레시피형 패치 on an .iso made from a .bin (0.0.383)
        }
        boolean sheet = isDiscSheet(file);
        boolean gdi = file.getName().toLowerCase(Locale.ROOT).endsWith(".gdi");
        // A zip / 7z: the patches inside it (or, for a game with 덧씌우는 패치, that screen
        // when it holds none).
        List<Uri> archives = new ArrayList<>();
        for (Uri uri : picked) {
            String name = displayNameFor(uri);
            String lower = name == null ? "" : name.toLowerCase(Locale.ROOT);
            if (lower.endsWith(".zip") || lower.endsWith(".7z") || lower.endsWith(".rar") || RarReader.isSplitName(lower)) {
                archives.add(uri);
            }
        }
        if (!archives.isEmpty()) {
            List<Uri> first = groupArchives(archives).get(0);
            openPatchArchive(file, first, displayNameFor(first.get(0)));
            return;
        }
        // (0.0.414) An Xbox 360 .patch.toml is a game patch the engine applies: to that screen.
        if (MODE_X360.equals(modeForFile(file))) {
            for (Uri uri : picked) {
                String name = displayNameFor(uri);
                if (name != null && name.toLowerCase(Locale.ROOT).endsWith(".toml")) {
                    if (this.prepDialog != null && this.prepDialog.isShowing()) {
                        this.prepDialog.dismiss();
                    }
                    this.pendingX360PatchGame = file;
                    onX360PatchPicked(new Intent().setData(uri));
                    return;
                }
            }
        }
        // A PS2 .pnach is a 덧씌우는 패치: over to that screen.
        if (overlayKind(file) != null) {
            for (Uri uri : picked) {
                String name = displayNameFor(uri);
                String lower = name == null ? "" : name.toLowerCase(Locale.ROOT);
                if (lower.endsWith(".pnach")) {
                    if (this.prepDialog != null && this.prepDialog.isShowing()) {
                        this.prepDialog.dismiss();
                    }
                    Toast.makeText(this, "덧씌우는 한글 패치로 넣어요 (원본은 그대로)", Toast.LENGTH_SHORT).show();
                    onOverlayPicked(file, uri, false);
                    return;
                }
            }
        }
        List<String> bad = new ArrayList<>();
        if (!sheet) {
            this.prepUris.clear();
        }
        for (Uri uri : picked) {
            String kind = patchKindOf(uri);
            String name = displayNameFor(uri);
            if (kind == null || (".dcp".equals(kind) && !gdi)) {
                bad.add(name == null ? "고른 파일" : name);
                continue;
            }
            if (".dcp".equals(kind) || this.prepUris.stream().anyMatch(u -> ".dcp".equals(patchKindOf(u)))) {
                this.prepUris.clear();  // a .dcp goes alone
            }
            if (!this.prepUris.contains(uri)) {
                this.prepUris.add(uri);
            }
            if (!sheet) {
                break;
            }
        }
        if (!bad.isEmpty()) {
            String names = android.text.TextUtils.join(", ", bad);
            boolean dcp = names.toLowerCase(Locale.ROOT).endsWith(".dcp");
            this.prepError = dcp ? names + "는 드림캐스트 GDI 게임에만 쓸 수 있어요. 이 게임에는 IPS · UPS · BPS · PPF · xdelta · APS · RUP · BDF 패치를 골라 주세요."
                    : names + "는 패치 파일이 아니에요.\nIPS · UPS · BPS · PPF · xdelta · APS · RUP · BDF 파일이나, 그것이 든 zip · 7z · rar를 골라 주세요.";
        } else {
            this.prepError = null;
        }
        renderPatchPrep();
    }



    // ---- 압축 파일 안의 게임: a RAR or 7z picked in ROM 추가 ----

    private static final class ArchiveGame {
        String label;
        final List<String> entries = new ArrayList<>();   // the main file first (a sheet, then its tracks)
        long size;
        boolean exists;
        boolean sheet;
    }

    // ---- An archive picked (one file, or the parts of a split RAR) and where it is read from ----

    private static final int REQUEST_ARCHIVE_PARTS = 1068;
    private List<Uri> pendingArchiveUris;
    private java.util.function.Consumer<List<Uri>> pendingArchiveResume;

    private static final class ArchiveInput {
        final List<File> parts = new ArrayList<>();
        final List<String> partNames = new ArrayList<>();
        final List<String> missing = new ArrayList<>();
        final List<File> temps = new ArrayList<>();
        final List<Uri> uris = new ArrayList<>();
        String label;
        boolean split;
        boolean direct;
        long size;

        void cleanup() {
            for (File f : temps) {
                f.delete();
            }
            temps.clear();
        }
    }

    // The file a picked document is, when its path can be read directly (모든 파일 접근).
    private File realFileFor(Uri uri) {
        if (!hasAllFilesAccess() || uri == null) {
            return null;
        }
        try {
            if ("file".equals(uri.getScheme()) && uri.getPath() != null) {
                File f = new File(uri.getPath());
                return f.canRead() ? f : null;
            }
            if (!android.provider.DocumentsContract.isDocumentUri(this, uri)) {
                return null;
            }
            String id = android.provider.DocumentsContract.getDocumentId(uri);
            String authority = uri.getAuthority();
            File f = null;
            if ("com.android.externalstorage.documents".equals(authority) && id.contains(":")) {
                String volume = id.substring(0, id.indexOf(':'));
                String path = id.substring(id.indexOf(':') + 1);
                f = "primary".equalsIgnoreCase(volume) ? new File(android.os.Environment.getExternalStorageDirectory(), path) : new File("/storage/" + volume, path);
            } else if ("com.android.providers.downloads.documents".equals(authority) && id.startsWith("raw:")) {
                f = new File(id.substring(4));
            } else if ("com.android.providers.downloads.documents".equals(authority)) {
                String name = displayNameFor(uri);
                File guess = new File(android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_DOWNLOADS), name);
                if (guess.isFile() && guess.length() == sizeForUri(uri)) {
                    f = guess;
                }
            }
            return f != null && f.isFile() && f.canRead() ? f : null;
        } catch (RuntimeException e) {
            return null;
        }
    }

    // Groups picked archives: the parts of one split RAR together, others on their own.
    private List<List<Uri>> groupArchives(List<Uri> uris) {
        List<List<Uri>> groups = new ArrayList<>();
        List<String> keys = new ArrayList<>();
        for (Uri u : uris) {
            String name = displayNameFor(u);
            Object[] part = RarReader.isSplitName(name) || name.toLowerCase(Locale.ROOT).endsWith(".rar") ? RarReader.partOf(name) : null;
            String key = part != null ? (String) part[0] : "\u0002" + u;
            int at = keys.indexOf(key);
            if (at < 0) {
                keys.add(key);
                groups.add(new ArrayList<>());
                at = groups.size() - 1;
            }
            groups.get(at).add(u);
        }
        return groups;
    }

    // Where the archive is read from: its own files when they can be read (and a split set's
    // other parts from the same folder), else copies in the cache. Run off the UI thread.
    private ArchiveInput resolveArchive(List<Uri> uris) throws IOException {
        ArchiveInput in = new ArchiveInput();
        in.uris.addAll(uris);
        List<String> names = new ArrayList<>();
        for (Uri u : uris) {
            names.add(displayNameFor(u));
        }
        in.split = uris.size() > 1 || RarReader.isSplitName(names.get(0));
        File first = realFileFor(uris.get(0));
        if (first != null) {
            in.direct = true;
            if (in.split) {
                in.parts.addAll(RarReader.siblings(first));
            } else {
                in.parts.add(first);
            }
        } else {
            File dir = new File(getCacheDir(), "archive_in_" + System.currentTimeMillis());
            if (!dir.mkdirs()) {
                throw new IOException("임시 폴더를 만들지 못했어요.");
            }
            for (int k = 0; k < uris.size(); k++) {
                File copy = new File(dir, new File(names.get(k)).getName());
                try (InputStream is = getContentResolver().openInputStream(uris.get(k)); OutputStream out = new FileOutputStream(copy)) {
                    if (is == null) {
                        throw new IOException(names.get(k) + "을(를) 열 수 없어요.");
                    }
                    byte[] buffer = new byte[1 << 16];
                    int n;
                    while ((n = is.read(buffer)) > 0) {
                        out.write(buffer, 0, n);
                    }
                }
                in.temps.add(copy);
                in.parts.add(copy);
            }
            in.temps.add(dir);
            if (in.split) {
                in.parts.sort((a, b) -> Integer.compare((Integer) RarReader.partOf(a.getName())[1], (Integer) RarReader.partOf(b.getName())[1]));
            }
        }
        for (File p : in.parts) {
            in.partNames.add(p.getName());
            in.size += p.length();
        }
        if (in.split) {
            in.missing.addAll(RarReader.missingParts(new ArrayList<>(in.partNames)));
            String base = in.partNames.get(0).replaceAll("(?i)(\\.part\\d+)?\\.(rar|r\\d\\d)$", "");
            in.label = base + (in.partNames.get(0).toLowerCase(Locale.ROOT).matches(".*\\.part\\d+\\.rar$") ? ".part1~" + in.partNames.size() + ".rar" : ".rar 외 " + (in.partNames.size() - 1) + "개");
        } else {
            in.label = names.get(0);
        }
        return in;
    }

    // For a split archive: its parts, what is missing, and on to the next step when all are there.
    private void splitGate(final ArchiveInput in, final Runnable cancel, final Runnable go, final java.util.function.Consumer<List<Uri>> repick) {
        if (!in.split) {
            go.run();
            return;
        }
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        cardHeader(panel, RoundIconView.IMPORT, RoundIconView.COLOR_PATCH, "분할 압축 찾기",
                in.direct ? new File(in.uris.isEmpty() ? in.partNames.get(0) : displayNameFor(in.uris.get(0))).getName() + " 을 골랐어요" : "고른 파일 " + in.uris.size() + "개");
        TextView intro = new TextView(this);
        intro.setText(in.direct ? "\"모든 파일 접근\"이 켜져 있어서 같은 폴더에서 나머지 조각을 찾았어요. 복사 없이 원래 자리에서 바로 읽어요."
                : "\"모든 파일 접근\"이 꺼져 있어서 고른 파일만 읽을 수 있어요. 조각을 모두 함께 골라 주세요.");
        intro.setTextSize(11.5f);
        intro.setTextColor(Theme.text(in.direct ? Color.rgb(17, 94, 89) : Color.rgb(146, 64, 14)));
        intro.setPadding(dp(12), dp(9), dp(12), dp(9));
        intro.setBackground(rounded(in.direct ? Color.rgb(240, 253, 250) : Color.rgb(255, 251, 235), dp(12)));
        panel.addView(intro, spaced(10));
        List<String> all = new ArrayList<>(in.partNames);
        all.addAll(in.missing);
        RarReader.sortParts(all);
        panel.addView(sectionLabel("조각 " + all.size() + "개" + (in.missing.isEmpty() ? " · 모두 있음" : " 중 " + in.partNames.size() + "개")));
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(1);
        for (String name : all) {
            boolean have = in.partNames.contains(name);
            File f = have ? in.parts.get(in.partNames.indexOf(name)) : null;
            LinearLayout row = new LinearLayout(this);
            row.setGravity(16);
            row.setPadding(dp(10), dp(7), dp(10), dp(7));
            GradientDrawable bg = rounded(have ? Color.rgb(240, 253, 244) : Color.rgb(254, 242, 242), dp(10));
            bg.setStroke(dp(1), Theme.line(have ? Color.rgb(134, 239, 172) : Color.rgb(252, 165, 165)));
            row.setBackground(bg);
            TextView n = new TextView(this);
            n.setText("📦 " + name);
            n.setTextSize(11.5f);
            n.setTypeface(Typeface.DEFAULT_BOLD);
            n.setSingleLine(true);
            n.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);
            n.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
            row.addView(n, new LinearLayout.LayoutParams(0, -2, 1.0f));
            TextView size = new TextView(this);
            size.setText(f != null ? formatSize(f.length()) + "  " : "—  ");
            size.setTextSize(10.5f);
            size.setTextColor(Theme.text(Color.rgb(107, 114, 128)));
            row.addView(size);
            TextView mark = new TextView(this);
            mark.setText(have ? "✓" : "없음");
            mark.setTextSize(10.0f);
            mark.setTypeface(Typeface.DEFAULT_BOLD);
            mark.setTextColor(Color.WHITE);
            mark.setGravity(17);
            mark.setPadding(dp(6), dp(1), dp(6), dp(1));
            mark.setBackground(rounded(have ? Color.rgb(22, 163, 74) : Color.rgb(220, 38, 38), dp(7)));
            row.addView(mark, new LinearLayout.LayoutParams(dp(38), -2));
            list.addView(row, spaced(5));
        }
        ScrollView scroll = new ScrollView(this);
        scroll.addView(list);
        panel.addView(scroll, new LinearLayout.LayoutParams(-1, Math.min((int) (getResources().getDisplayMetrics().heightPixels * 0.4f), dp(44) * all.size() + dp(10))));
        TextView info = new TextView(this);
        if (in.missing.isEmpty()) {
            info.setText("압축 크기 " + formatSize(in.size) + (in.direct ? " · 캐시에 복사하지 않아요" : "") + "\n다음: 압축 파일 안을 살펴봐요");
            info.setTextColor(Theme.text(Color.rgb(30, 58, 138)));
            info.setBackground(rounded(Color.rgb(239, 246, 255), dp(12)));
        } else {
            info.setText(android.text.TextUtils.join(", ", in.missing) + " 조각이 빠졌어요. 다시 고를 때 조각을 모두 함께 골라 주세요. (여러 개 고르기: 파일을 길게 누른 뒤 나머지를 눌러요)");
            info.setTextColor(Theme.text(Color.rgb(153, 27, 27)));
            info.setBackground(rounded(Color.rgb(254, 242, 242), dp(12)));
        }
        info.setTextSize(11.5f);
        info.setPadding(dp(12), dp(9), dp(12), dp(9));
        panel.addView(info, spaced(8));
        final boolean[] going = {false};
        LinearLayout buttons = new LinearLayout(this);
        TextView no = new TextView(this);
        no.setText("취소");
        no.setTextSize(15.0f);
        no.setTypeface(Typeface.DEFAULT_BOLD);
        no.setGravity(17);
        no.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        no.setBackground(rounded(Color.rgb(241, 243, 245), dp(14)));
        no.setOnClickListener(view -> dialog.dismiss());
        buttons.addView(no, new LinearLayout.LayoutParams(0, dp(48), 1.0f));
        TextView yes = new TextView(this);
        yes.setText(in.missing.isEmpty() ? "다음 →" : "빠진 조각 고르기");
        yes.setTextSize(15.0f);
        yes.setTypeface(Typeface.DEFAULT_BOLD);
        yes.setGravity(17);
        yes.setTextColor(Color.WHITE);
        yes.setBackground(rounded(RoundIconView.COLOR_PATCH, dp(14)));
        yes.setOnClickListener(view -> {
            going[0] = true;
            dialog.dismiss();
            if (in.missing.isEmpty()) {
                go.run();
                return;
            }
            in.cleanup();
            this.pendingArchiveUris = new ArrayList<>(in.uris);
            this.pendingArchiveResume = repick;
            Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
            intent.addCategory(Intent.CATEGORY_OPENABLE);
            intent.setType("*/*");
            intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
            try {
                startActivityForResult(intent, REQUEST_ARCHIVE_PARTS);
            } catch (Exception e) {
                showError("파일을 고르는 화면을 열 수 없어요.");
            }
        });
        LinearLayout.LayoutParams yesParams = new LinearLayout.LayoutParams(0, dp(48), 1.5f);
        yesParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(yes, yesParams);
        panel.addView(buttons, spaced(12));
        if (!in.missing.isEmpty() && !hasAllFilesAccess()) {
            TextView auto = new TextView(this);
            auto.setText("\"모든 파일 접근\" 켜고 자동으로 찾기 ›");
            auto.setTextSize(12.0f);
            auto.setTypeface(Typeface.DEFAULT_BOLD);
            auto.setGravity(17);
            auto.setTextColor(Theme.text(COLOR_OVERLAY));
            auto.setPadding(0, dp(10), 0, dp(2));
            auto.setOnClickListener(view -> {
                going[0] = true;
                dialog.dismiss();
                in.cleanup();
                withAllFilesAccess(() -> repick.accept(new ArrayList<>(in.uris)));
            });
            panel.addView(auto);
        }
        dialog.setOnDismissListener(d -> {
            if (!going[0]) {
                in.cleanup();
                cancel.run();
            }
        });
        dialog.show();
    }

    private void openRomArchives(final String mode, final java.util.ArrayDeque<List<Uri>> queue) {
        final List<Uri> job = queue.poll();
        if (job == null) {
            refreshLibrary();
            return;
        }
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setMessage(displayNameFor(job.get(0)) + " 살펴보는 중…");
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            ArchiveInput resolved = null;
            String error = null;
            try {
                resolved = resolveArchive(job);
            } catch (IOException e) {
                error = e.getMessage();
            }
            final ArchiveInput in = resolved;
            final String why = error;
            runOnUiThread(() -> {
                progress.dismiss();
                if (isFinishing() || isDestroyed()) {
                    if (in != null) {
                        in.cleanup();
                    }
                    return;
                }
                if (why != null) {
                    showError(displayNameFor(job.get(0)) + ": " + why);
                    openRomArchives(mode, queue);
                    return;
                }
                splitGate(in, () -> openRomArchives(mode, queue), () -> listRomArchive(mode, in, queue), uris -> {
                    queue.addFirst(uris);
                    openRomArchives(mode, queue);
                });
            });
        }, "rom-archive").start();
    }

    private void listRomArchive(final String mode, final ArchiveInput in, final java.util.ArrayDeque<List<Uri>> queue) {
        if (MODE_DOS.equals(mode)) {
            repackDosArchive(in, queue);
            return;
        }
        final String archiveName = in.label;
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setMessage(archiveName + " 살펴보는 중…");
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            String error = null;
            List<ArchiveGame> games = new ArrayList<>();
            List<String> others = new ArrayList<>();
            long total = 0;
            try {
                List<PatchArchive.Listed> listed = PatchArchive.list(in.parts);
                boolean encrypted = false;
                for (PatchArchive.Listed l : listed) {
                    encrypted |= l.encrypted;
                    total += Math.max(0, l.size);
                }
                if (encrypted) {
                    throw new IOException("암호 걸린 압축이라 풀 수 없어요. 컴퓨터에서 암호를 넣고 풀어서 가져와 주세요.");
                }
                findArchiveGames(in.parts, mode, listed, games, others);
            } catch (IOException e) {
                error = e.getMessage();
            } catch (RuntimeException e) {
                error = "압축 파일을 읽지 못했어요 (" + e.getClass().getSimpleName() + ").";
            }
            final String why = error;
            final long size = total;
            runOnUiThread(() -> {
                progress.dismiss();
                if (isFinishing() || isDestroyed()) {
                    in.cleanup();
                    return;
                }
                if (why != null) {
                    in.cleanup();
                    showError(archiveName + ": " + why);
                    openRomArchives(mode, queue);
                    return;
                }
                if (games.isEmpty()) {
                    in.cleanup();
                    showError(archiveName + " 안에 " + MODE_NAMES[modeIndex(mode)] + " 게임(" + MODE_FILES[modeIndex(mode)] + ")이 없어요. 다른 게임기 모드에서 가져와 주세요.");
                    openRomArchives(mode, queue);
                    return;
                }
                showRomArchive(mode, archiveName, in, games, others, size, queue);
            });
        }, "rom-archive-list").start();
    }

    // DOS: a 7z / rar holds one game's folder; DOSBox Pure reads only zip, so its files go
    // into a zip of the same name (stored as it is, unpacked into nothing on the phone).
    private void repackDosArchive(final ArchiveInput in, final java.util.ArrayDeque<List<Uri>> queue) {
        final String archiveName = in.label;
        final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
        progress.setMessage(archiveName + " → zip으로 옮기는 중…");
        progress.setCancelable(false);
        progress.show();
        new Thread(() -> {
            String error = null;
            File made = null;
            File work = new File(getCacheDir(), "dos_repack");
            deleteRecursively(work);
            try {
                List<PatchArchive.Listed> listed = PatchArchive.list(in.parts);
                long total = 0;
                List<String> names = new ArrayList<>();
                List<File> outs = new ArrayList<>();
                for (PatchArchive.Listed l : listed) {
                    if (l.encrypted) {
                        throw new IOException("암호 걸린 압축이라 풀 수 없어요. 컴퓨터에서 암호를 넣고 풀어서 가져와 주세요.");
                    }
                    String name = l.name.replace('\\', '/');
                    while (name.startsWith("/")) {
                        name = name.substring(1);
                    }
                    if (name.isEmpty() || name.contains("../")) {
                        continue;
                    }
                    names.add(l.name);
                    outs.add(new File(work, String.valueOf(outs.size())));
                    total += Math.max(0, l.size);
                }
                if (names.isEmpty()) {
                    throw new IOException("압축 안에 파일이 없어요.");
                }
                if (getCacheDir().getUsableSpace() < total * 2 + (64L << 20)) {
                    throw new IOException("저장 공간이 모자라요 (" + formatSize(total * 2) + " 필요).");
                }
                work.mkdirs();
                final long all = total;
                PatchArchive.extract(in.parts, names, outs, done -> runOnUiThread(() ->
                        progress.setMessage(archiveName + " 푸는 중… " + (all > 0 ? Math.min(100, done * 100 / all) : 0) + "%")));
                String base = archiveName;
                String lower = base.toLowerCase(Locale.ROOT);
                for (String ext : new String[]{".7z", ".rar", ".zip"}) {
                    if (lower.endsWith(ext)) {
                        base = base.substring(0, base.length() - ext.length());
                        break;
                    }
                }
                base = base.replaceAll("(?i)\\.part0*1$", "").replaceAll("(?i)\\.(r00|001|z01)$", "");
                File romDir = romDirFor(MODE_DOS);
                romDir.mkdirs();
                File target = new File(romDir, sanitizeFileName(base) + ".zip");
                if (target.exists()) {
                    throw new IOException("같은 이름의 게임이 이미 있어요: " + target.getName());
                }
                File temp = new File(romDir, target.getName() + ".part");
                runOnUiThread(() -> progress.setMessage(archiveName + " → zip으로 묶는 중…"));
                try (java.util.zip.ZipOutputStream zip = new java.util.zip.ZipOutputStream(new java.io.BufferedOutputStream(new FileOutputStream(temp), 1 << 16))) {
                    zip.setLevel(1);
                    byte[] buffer = new byte[1 << 16];
                    for (int k = 0; k < names.size(); k++) {
                        String name = names.get(k).replace('\\', '/');
                        while (name.startsWith("/")) {
                            name = name.substring(1);
                        }
                        zip.putNextEntry(new java.util.zip.ZipEntry(name));
                        try (java.io.InputStream inStream = new java.io.FileInputStream(outs.get(k))) {
                            int n;
                            while ((n = inStream.read(buffer)) > 0) {
                                zip.write(buffer, 0, n);
                            }
                        }
                        zip.closeEntry();
                        outs.get(k).delete();
                    }
                }
                if (!temp.renameTo(target)) {
                    temp.delete();
                    throw new IOException("zip을 저장하지 못했어요.");
                }
                made = target;
            } catch (IOException e) {
                error = e.getMessage();
            } catch (RuntimeException e) {
                error = "압축 파일을 읽지 못했어요 (" + e.getClass().getSimpleName() + ").";
            } finally {
                deleteRecursively(work);
                in.cleanup();
            }
            final String why = error;
            final File game = made;
            runOnUiThread(() -> {
                progress.dismiss();
                if (isFinishing() || isDestroyed()) {
                    return;
                }
                if (why != null) {
                    showError(archiveName + ": " + why);
                } else if (game != null) {
                    Toast.makeText(this, game.getName() + " 으로 넣었어요", Toast.LENGTH_SHORT).show();
                }
                openRomArchives(MODE_DOS, queue);
            });
        }, "dos-repack").start();
    }

    // The games inside: this console's files, a .cue / .gdi with the tracks it names as one game.
    private void findArchiveGames(List<File> archive, String mode, List<PatchArchive.Listed> listed, List<ArchiveGame> games, List<String> others) throws IOException {
        java.util.Map<String, Long> sizes = new java.util.LinkedHashMap<>();
        for (PatchArchive.Listed l : listed) {
            sizes.put(l.name, l.size);
        }
        java.util.Set<String> used = new java.util.HashSet<>();
        File sheets = new File(getCacheDir(), "rom_archive_sheets");
        deleteRecursively(sheets);
        List<String> sheetNames = new ArrayList<>();
        List<File> sheetFiles = new ArrayList<>();
        for (String name : sizes.keySet()) {
            String lower = name.toLowerCase(Locale.ROOT);
            if ((lower.endsWith(".cue") || lower.endsWith(".gdi")) && isRomNameFor(mode, lower) && sizes.get(name) < (1 << 20)) {
                sheetNames.add(name);
                sheetFiles.add(new File(sheets, String.valueOf(sheetFiles.size())));
            }
        }
        if (!sheetNames.isEmpty()) {
            PatchArchive.extract(archive, sheetNames, sheetFiles, null);
        }
        File romDir = romDirFor(mode);
        for (int k = 0; k < sheetNames.size(); k++) {
            String sheet = sheetNames.get(k);
            String dir = sheet.contains("/") ? sheet.substring(0, sheet.lastIndexOf('/') + 1) : "";
            ArchiveGame game = new ArchiveGame();
            game.sheet = true;
            game.entries.add(sheet);
            game.size = sizes.get(sheet);
            String text = PatchArchive.readText(sheetFiles.get(k));
            java.util.regex.Matcher m = java.util.regex.Pattern.compile("(?im)^[ \\t]*FILE[ \\t]+\"([^\"]+)\"|^[ \\t]*FILE[ \\t]+(\\S+)|^[ \\t]*\\d+[ \\t]+\\d+[ \\t]+\\d+[ \\t]+\\d+[ \\t]+\"([^\"]+)\"|^[ \\t]*\\d+[ \\t]+\\d+[ \\t]+\\d+[ \\t]+\\d+[ \\t]+(\\S+)").matcher(text);
            while (m.find()) {
                String ref = m.group(1) != null ? m.group(1) : m.group(2) != null ? m.group(2) : m.group(3) != null ? m.group(3) : m.group(4);
                String full = dir + ref.replace('\\', '/');
                String match = null;
                for (String name : sizes.keySet()) {
                    if (name.equalsIgnoreCase(full)) {
                        match = name;
                    }
                }
                if (match != null && !game.entries.contains(match)) {
                    game.entries.add(match);
                    game.size += sizes.get(match);
                }
            }
            String base = new File(sheet).getName();
            game.label = base + (game.entries.size() > 1 ? " + 트랙 " + (game.entries.size() - 1) + "개" : " (트랙 없음)");
            game.exists = new File(romDir, base).exists();
            used.addAll(game.entries);
            games.add(game);
        }
        for (String name : sizes.keySet()) {
            if (used.contains(name)) {
                continue;
            }
            String base = new File(name).getName();
            String lower = base.toLowerCase(Locale.ROOT);
            if (isRomNameFor(mode, lower) && !lower.endsWith(".cue") && !lower.endsWith(".gdi")) {
                // Tracks of a sheet game that isn't in the archive are not games of their own.
                boolean track = (lower.endsWith(".bin") || lower.endsWith(".raw")) && consoleFor(mode) != null
                        && (consoleFor(mode)[2].contains(".cue") || consoleFor(mode)[2].contains(".gdi")) && !MODE_MD.equals(mode);
                if (!track) {
                    ArchiveGame game = new ArchiveGame();
                    game.entries.add(name);
                    game.size = sizes.get(name);
                    game.label = base;
                    game.exists = new File(romDir, sanitizeFileName(base)).exists();
                    games.add(game);
                    continue;
                }
            }
            String other = null;
            for (String[] console : CONSOLES) {
                if (!console[0].equals(mode) && hasExtension(lower, console[2])) {
                    other = MODE_NAMES[modeIndex(console[0])] + " 게임 · 그 모드에서 가져와요";
                    break;
                }
            }
            others.add(base + " — " + (other != null ? other : "게임이 아닌 파일"));
        }
        deleteRecursively(sheets);
    }

