    private static boolean extractTo(java.util.zip.ZipFile zip, java.util.zip.ZipEntry entry, File to) {
        File parent = to.getParentFile();
        if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
            return false;
        }
        try (InputStream in = zip.getInputStream(entry); OutputStream out = new FileOutputStream(to)) {
            byte[] buffer = new byte[1 << 16];
            int n;
            while ((n = in.read(buffer)) > 0) {
                out.write(buffer, 0, n);
            }
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    private int restoreFromZip(File zipFile, List<RestoreItem> items, boolean keepNewer) {
        int done = 0;
        try (java.util.zip.ZipFile zip = new java.util.zip.ZipFile(zipFile)) {
            for (RestoreItem item : items) {
                if (item.state == 1 || (item.state == 2 && keepNewer)) {
                    continue;
                }
                File sav;
                File state;
                File slots;
                if (item.game != null) {
                    backupSaves(item.game);
                    SaveSet mine = saveSetFor(item.game);
                    sav = mine.sav;
                    state = mine.state;
                    slots = mine.slots;
                } else {
                    // No game here yet: where its saves go once a game file of that name comes.
                    File coreDir = new File(saveDir(), item.core);
                    sav = new File(coreDir, item.base + ".sav");
                    state = new File(coreDir, item.base + ".state");
                    slots = new File(new File(coreDir, "quicksaves"), item.base);
                }
                boolean any = false;
                java.util.zip.ZipEntry entry = zip.getEntry(item.prefix + "game.sav");
                if (entry != null) {
                    any |= extractTo(zip, entry, sav);
                }
                entry = zip.getEntry(item.prefix + "game.state");
                if (entry != null) {
                    any |= extractTo(zip, entry, state);
                }
                java.util.Enumeration<? extends java.util.zip.ZipEntry> all = zip.entries();
                while (all.hasMoreElements()) {
                    java.util.zip.ZipEntry slot = all.nextElement();
                    String name = slot.getName();
                    if (name.startsWith(item.prefix + "slots/") && isQuickSaveFileName(name.substring(name.lastIndexOf('/') + 1))) {
                        any |= extractTo(zip, slot, new File(slots, name.substring(name.lastIndexOf('/') + 1)));
                    }
                }
                if (any) {
                    done++;
                }
            }
            java.util.Enumeration<? extends java.util.zip.ZipEntry> all = zip.entries();
            while (all.hasMoreElements()) {
                java.util.zip.ZipEntry card = all.nextElement();
                if (card.getName().startsWith("ps2/") && card.getName().toLowerCase(Locale.US).endsWith(".ps2")) {
                    File target = new File(pcsx2MemcardDir(), card.getName().substring(4));
                    if (keepNewer && target.isFile() && target.lastModified() > card.getTime()) {
                        continue;
                    }
                    if (target.isFile()) {
                        copyInto(target, new File(target.getPath() + ".bak"));
                    }
                    extractTo(zip, card, target);
                }
            }
        } catch (IOException e) {
            showError("백업 파일을 읽지 못했어요.");
        }
        return done;
    }

    // ---- Wii 온라인: 내 Wii 본체 정보 (a BootMii NAND backup of the player's own Wii, through
    // Dolphin's importer), Wii 시스템 업데이트 and 오류 코드 안내 ----

    private static final int REQUEST_PICK_NAND = 1062;
    private static final int REQUEST_PICK_NAND_KEYS = 1063;
    private static final long NAND_BIN_SIZE = 0x21000000L;
    private Uri pendingNand;

    private File wiiBeforeNand() {
        return new File(dolphinUserDir(), "Wii.before-nand");
    }

    // {device id hex, region} of the Wii here when it is the player's own, else null.
    private String[] ownWiiInfo() {
        File root = WiiHelp.wiiRoot(this);
        File keys = new File(root, "keys.bin");
        if (!keys.isFile()) {
            return null;
        }
        String id = "?";
        byte[] head = readHead(keys, 0x128);
        if (head != null) {
            id = String.format(Locale.ROOT, "0x%02X%02X%02X%02X", head[0x124], head[0x125], head[0x126], head[0x127]);
        }
        String region = "";
        File setting = new File(root, "title/00000001/00000002/data/setting.txt");
        byte[] data = readHead(setting, (int) Math.min(setting.length(), 0x100));
        if (data != null) {
            // setting.txt is XORed with a rolling key.
            long key = 0x73B5DBFAL;
            StringBuilder text = new StringBuilder();
            for (byte b : data) {
                text.append((char) ((b ^ key) & 0xFF));
                key = ((key << 1) | (key >>> 31)) & 0xFFFFFFFFL;
            }
            java.util.regex.Matcher match = java.util.regex.Pattern.compile("AREA=([A-Z]{3})").matcher(text);
            if (match.find()) {
                String area = match.group(1);
                region = "KOR".equals(area) ? "한국 (KOR)" : "JPN".equals(area) ? "일본 (JPN)" : "USA".equals(area) ? "미국 (USA)" : "EUR".equals(area) ? "유럽 (EUR)" : area;
            }
        }
        return new String[]{id, region};
    }

    private String wiiOnlineTileText() {
        return (WiiHelp.ownConsole(this) ? "내 Wii" : "기본 본체") + " · " + (wiiCertificatesReady() ? "인증서 있음" : "인증서 없음");
    }

    private void showWiiOnline() {
        if (android.os.Build.VERSION.SDK_INT < 26) {
            showError("게임큐브·Wii는 안드로이드 8 이상에서만 쓸 수 있어요.");
            return;
        }
        final Dialog dialog = new Dialog(this);
        final int indigo = Color.rgb(99, 102, 241);
        LinearLayout body = pageDialog(dialog, "Wii 온라인", "게임큐브 · Wii 모드", indigo);
        String[] own = ownWiiInfo();
        if (own != null) {
            addPageRow(body, settingsRow("✓ 내 Wii" + (own[1].isEmpty() ? "" : " · " + own[1]), "기기 번호 " + own[0] + " · 공개 서버(WiiLink WFC · Wiimmfi)에 접속할 수 있어요", null));
        } else {
            addPageRow(body, settingsRow("Dolphin 기본 본체 (모두 같은 정보)", "친구끼리 방 · 오프라인은 그대로 돼요 · 공개 서버(WiiLink · Wiimmfi)는 막혀요 (22001 · 23934)", null));
        }
        addPageRow(body, settingsRow(own == null ? "내 Wii NAND 가져오기" : "다른 NAND로 바꾸기",
                "BootMii로 내 Wii에서 만든 nand.bin (약 528MB, 예전 BootMii면 keys.bin도)", () -> {
                    dialog.dismiss();
                    Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
                    intent.addCategory(Intent.CATEGORY_OPENABLE);
                    intent.setType("*/*");
                    try {
                        startActivityForResult(intent, REQUEST_PICK_NAND);
                    } catch (Exception e) {
                        showError("파일을 고르는 화면을 열 수 없어요.");
                    }
                }));
        if (own != null) {
            final boolean hasBefore = wiiBeforeNand().isDirectory();
            addPageRow(body, settingsRow("Dolphin 기본 본체로 되돌리기", hasBefore ? "가져오기 전 상태로 돌아가요" : "앱 안의 Wii 저장 데이터가 지워져요 (가져오기 전 백업이 없어요)", () -> {
                new AppDialog.Builder(this).setTitle("기본 본체로 되돌릴까요?")
                        .setMessage(hasBefore ? "내 Wii NAND를 지우고, 가져오기 전의 Dolphin 상태로 돌아가요." : "내 Wii NAND와 그 안의 Wii 세이브 · 채널을 지워요. 되돌릴 수 없어요.")
                        .setNegativeButton("취소", null).setPositiveButton("되돌리기", (d, which) -> {
                            File root = WiiHelp.wiiRoot(this);
                            deleteTree(root);
                            if (hasBefore && !wiiBeforeNand().renameTo(root)) {
                                showError("되돌리지 못했어요.");
                            }
                            dialog.dismiss();
                            updateHomeStatusCards();
                            showWiiOnline();
                        }).show();
            }));
        }
        addPageRow(body, settingsRow("Wii 시스템 업데이트", wiiCertificatesReady() ? "인증서 3개 있음 · 다시 받기" : "인증서 없음 · 온라인에 필요해요 (20100)", () -> {
            dialog.dismiss();
            showWiiUpdateSheet();
        }));
        addPageRow(body, settingsRow("오류 코드 안내", "게임에 나온 숫자로 원인 · 해결 찾기", () -> WiiHelp.show(this)));
        addPageRow(body, settingsRow("알아두기", "실제 Wii가 없으면 NAND 가져오기는 쓸 수 없어요 (공개 서버 대신 친구끼리 방을 써요). "
                + "다른 사람의 백업을 쓰거나 같은 NAND를 여러 기기에 넣으면 서버가 계정을 막을 수 있어요. 가짜 본체 정보는 만들지 않아요.", null));
        dialog.show();
    }

    private void onNandPicked(Uri uri) {
        long size = sizeForUri(uri);
        if (size != NAND_BIN_SIZE && size != NAND_BIN_SIZE + 0x400) {
            showError("BootMii NAND 백업(nand.bin)이 아니에요. 크기가 " + (size < 0 ? "알 수 없어요" : formatSize(size)) + "인데, BootMii 백업은 528MB예요.");
            return;
        }
        if (size == NAND_BIN_SIZE) {
            this.pendingNand = uri;
            new AppDialog.Builder(this).setTitle("keys.bin도 골라 주세요")
                    .setMessage("이 nand.bin에는 본체 키가 들어 있지 않아요 (예전 BootMii). BootMii가 같은 폴더에 만든 keys.bin을 골라 주세요.")
                    .setNegativeButton("취소", null).setPositiveButton("keys.bin 고르기", (d, which) -> {
                        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
                        intent.addCategory(Intent.CATEGORY_OPENABLE);
                        intent.setType("*/*");
                        try {
                            startActivityForResult(intent, REQUEST_PICK_NAND_KEYS);
                        } catch (Exception e) {
                            showError("파일을 고르는 화면을 열 수 없어요.");
                        }
                    }).show();
            return;
        }
        confirmNandImport(uri, null);
    }

    private void onNandKeysPicked(Uri keys) {
        Uri nand = this.pendingNand;
        this.pendingNand = null;
        if (nand == null) {
            return;
        }
        long size = sizeForUri(keys);
        if (size >= 0 && size < 0x400) {
            showError("keys.bin이 아니에요 (크기가 너무 작아요).");
            return;
        }
        confirmNandImport(nand, keys);
    }

    private void confirmNandImport(final Uri nand, final Uri keys) {
        long free = new android.os.StatFs(getFilesDir().getAbsolutePath()).getAvailableBytes();
        final long needed = NAND_BIN_SIZE + 600L * 1024 * 1024;
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        final CheckBox backup = new CheckBox(this);
        backup.setText("지금 앱 안의 Wii 저장 데이터 백업해 두기\n(미니 Wii 세이브 · 시스템 설정 · 받은 채널, 되돌리기용)");
        backup.setTextSize(12.5f);
        backup.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        backup.setChecked(true);
        panel.addView(backup);
        new AppDialog.Builder(this).setTitle("내 Wii NAND 가져오기")
                .setMessage(displayNameFor(nand) + (keys != null ? " + " + displayNameFor(keys) : " · 키 포함") + "\n\n"
                        + "가져오면 앱 안의 Wii가 내 Wii로 바뀌어요. 내 Wii에 있던 세이브 · Mii · 인증서도 같이 들어와요.\n"
                        + "필요한 공간 약 " + formatSize(needed) + " · 남은 공간 " + formatSize(free) + (free < needed ? " (부족해요)" : "") + "\n몇 분 걸려요.")
                .setView(panel)
                .setNegativeButton("취소", null)
                .setPositiveButton("가져오기", (d, which) -> {
                    if (free < needed) {
                        showError("저장 공간이 부족해요. " + formatSize(needed) + " 정도가 필요해요.");
                        return;
                    }
                    runNandImport(nand, keys, backup.isChecked());
                }).show();
    }

    private void runNandImport(final Uri nand, final Uri keys, final boolean keepBefore) {
        final File user = dolphinUserDir();
        final File sys = new File(new File(systemDir(), "dolphin-emu"), "Sys");
        final File root = WiiHelp.wiiRoot(this);
        final File aside = new File(user, "Wii.import-old");
        final File nandCopy = new File(getFilesDir(), "nand_import.bin");
        final File keysCopy = new File(getFilesDir(), "nand_keys.bin");
        final StepDialog steps = new StepDialog("NAND 가져오는 중", displayNameFor(nand), RoundIconView.IMPORT, Color.rgb(99, 102, 241),
                new String[]{"백업 파일 복사", "NAND 읽기", "파일 꺼내기", "확인"}, new String[]{"528MB", "", "", "본체 정보 · 인증서"});
        new Thread(() -> {
            String error = null;
            try {
                if (!user.isDirectory() && !user.mkdirs()) {
                    throw new IOException("Dolphin 폴더를 만들 수 없어요.");
                }
                if (!unpackSystemAsset("dolphin_sys.zip", sys)) {
                    throw new IOException("Dolphin 시스템 파일을 풀지 못했어요.");
                }
                long total = NAND_BIN_SIZE + 0x400;
                long done = 0;
                long last = 0;
                try (InputStream in = getContentResolver().openInputStream(nand); OutputStream out = new FileOutputStream(nandCopy)) {
                    if (in == null) {
                        throw new IOException("nand.bin을 열 수 없어요.");
                    }
                    byte[] buffer = new byte[1 << 20];
                    int n;
                    while ((n = in.read(buffer)) > 0) {
                        if (steps.cancelled) {
                            throw new IOException("취소했어요.");
                        }
                        out.write(buffer, 0, n);
                        done += n;
                        long now = android.os.SystemClock.uptimeMillis();
                        if (now - last > 200) {
                            last = now;
                            final long d = done;
                            runOnUiThread(() -> steps.set(0, formatSize(d) + " / 528MB", (int) (300 * d / total)));
                        }
                    }
                }
                if (keys != null) {
                    try (InputStream in = getContentResolver().openInputStream(keys); OutputStream out = new FileOutputStream(keysCopy)) {
                        if (in == null) {
                            throw new IOException("keys.bin을 열 수 없어요.");
                        }
                        copy(in, out);
                    }
                }
                // The Wii here is put aside; the import goes into an empty one.
                deleteTree(aside);
                if (root.exists() && !root.renameTo(aside)) {
                    throw new IOException("지금 Wii 데이터를 옮기지 못했어요.");
                }
                int result;
                try {
                    result = NativeGba.wiiImportNand(user.getAbsolutePath(), sys.getAbsolutePath(), nandCopy.getAbsolutePath(),
                            keys != null ? keysCopy.getAbsolutePath() : null, (step, current, max) -> {
                                final int permille = 300 + (step == 0 ? (int) (300L * current / Math.max(1, max)) : 600 + (int) (350L * current / Math.max(1, max)) - 300);
                                runOnUiThread(() -> steps.set(step == 0 ? 1 : 2, current + " / " + max, Math.min(950, permille)));
                                return !steps.cancelled;
                            });
                } catch (UnsatisfiedLinkError e) {
                    result = -1;
                }
                if (result != 0) {
                    deleteTree(root);
                    if (aside.exists()) {
                        aside.renameTo(root);
                    }
                    switch (result) {
                        case 1:
                            throw new IOException("BootMii NAND 백업이 아니에요.");
                        case 2:
                            throw new IOException("본체 키(keys.bin)가 없어요.");
                        case 3:
                            throw new IOException("백업에서 Wii 파일을 꺼내지 못했어요. 백업이 손상됐거나 다른 형식일 수 있어요.");
                        case 4:
                            throw new IOException("취소했어요.");
                        default:
                            throw new IOException("이 버전의 게임큐브·Wii 엔진에는 NAND 가져오기가 없어요. 앱을 업데이트해 주세요.");
                    }
                }
                if (keepBefore && aside.exists()) {
                    deleteTree(wiiBeforeNand());
                    aside.renameTo(wiiBeforeNand());
                } else {
                    deleteTree(aside);
                }
            } catch (IOException e) {
                error = e.getMessage();
            } finally {
                nandCopy.delete();
                keysCopy.delete();
            }
            final String why = error;
            runOnUiThread(() -> {
                steps.dismiss();
                if (isFinishing() || isDestroyed()) {
                    return;
                }
                updateHomeStatusCards();
                if (why != null) {
                    if (!steps.cancelled) {
                        showError(why);
                    }
                    return;
                }
                String[] own = ownWiiInfo();
                new AppDialog.Builder(this).setTitle("내 Wii로 바꿨어요")
                        .setMessage((own == null ? "" : "기기 번호 " + own[0] + (own[1].isEmpty() ? "" : " · " + own[1]) + "\n")
                                + (wiiCertificatesReady() ? "인증서도 들어왔어요. " : "인증서가 없으면 Wii 시스템 업데이트를 해 주세요. ")
                                + "이제 게임의 인터넷 서버에서 WiiLink WFC나 Wiimmfi를 고르면 돼요.")
                        .setPositiveButton("확인", null).show();
            });
        }, "nand-import").start();
    }

    // ---- 복사 없이 연결하기: a game stays where it is on the phone and the app's ROM folder
    // gets a link (a symbolic link) to it, so everything that opens a game by its path works
    // the same and nothing is copied. Needs "모든 파일 접근". A .cue / .gdi is linked with its
    // tracks. Deleting the game deletes the link only; a patched or unpacked game is still made
    // inside the app. Folders can be linked for good: new games there are linked on start. ----

    private static final String PREF_LINK_DIRS = "link_dirs:";
    private static final String PREF_LINK_RECENT = "link_recent";

    private boolean hasAllFilesAccess() {
        if (android.os.Build.VERSION.SDK_INT >= 30) {
            return Environment.isExternalStorageManager();
        }
        return checkSelfPermission(android.Manifest.permission.READ_EXTERNAL_STORAGE) == android.content.pm.PackageManager.PERMISSION_GRANTED;
    }

    private Runnable afterAllFilesAccess;

    private void withAllFilesAccess(Runnable then) {
        if (hasAllFilesAccess()) {
            then.run();
            return;
        }
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(1);
        new AppDialog.Builder(this).setTitle("\"모든 파일 접근\" 허락이 필요해요")
                .setMessage("게임 엔진은 파일 경로로 롬을 열어서, 폰의 다른 폴더에 있는 롬을 그대로 읽으려면 이 허락이 필요해요.\n\n"
                        + "· 앱은 고른 롬 폴더에서 게임 파일만 읽어요\n· 사진 · 문서 같은 다른 파일은 보지 않아요\n· 설정 화면에서 언제든 끌 수 있어요\n\n"
                        + "다음 화면에서 \"Mini Emulator\"를 찾아 켜고, 뒤로 돌아오면 돼요.")
                .setNegativeButton("취소", null)
                .setPositiveButton("허락하러 가기", (d, which) -> {
                    this.afterAllFilesAccess = then;
                    if (android.os.Build.VERSION.SDK_INT >= 30) {
                        try {
                            startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION, Uri.parse("package:" + getPackageName())));
                        } catch (Exception e) {
                            startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_ALL_FILES_ACCESS_PERMISSION));
                        }
                    } else {
                        requestPermissions(new String[]{android.Manifest.permission.READ_EXTERNAL_STORAGE}, 1064);
                    }
                }).show();
    }

    // Back from the settings screen (onResume): carry on when it was allowed.
    private void resumeAfterAllFilesAccess() {
        Runnable then = this.afterAllFilesAccess;
        if (then != null && hasAllFilesAccess()) {
            this.afterAllFilesAccess = null;
            then.run();
        }
    }

    private static boolean isLink(File file) {
        return java.nio.file.Files.isSymbolicLink(file.toPath());
    }

    private static File linkTarget(File file) {
        try {
            return java.nio.file.Files.readSymbolicLink(file.toPath()).toFile();
        } catch (IOException | RuntimeException e) {
            return null;
        }
    }

    // Links whose game is gone (moved or deleted), in a console's folder.
    private List<File> brokenLinks(String mode) {
        List<File> list = new ArrayList<>();
        File[] files = romDirFor(mode).listFiles();
        for (File file : files == null ? new File[0] : files) {
            if (isLink(file) && !file.exists()) {
                list.add(file);
            }
        }
        return list;
    }

    // The files a game is: a sheet with its tracks, or the file itself.
    private static List<File> gameFiles(File game) {
        List<File> files = new ArrayList<>();
        files.add(game);
        if (isDiscSheet(game)) {
            for (String track : cueTracks(game)) {
                files.add(new File(game.getParentFile(), track));
            }
        }
        return files;
    }

    // Links a game into the console's folder; a copy already there with the same name and
    // size is swapped for the link (freeing its space). Returns bytes freed, or -1 when a
    // different file has the name.
    private long linkGame(File game, String mode) throws IOException {
        if (game.isDirectory()) {
            VitaFolder folder = MODE_VITA.equals(mode) ? readVitaFolder(game) : null;
            if (folder == null) {
                throw new IOException(game.getName() + "은(는) 게임 폴더가 아니에요.");
            }
            addVitaFolderGame(folder);
            return 0;
        }
        File dir = romDirFor(mode);
        if (!dir.isDirectory() && !dir.mkdirs()) {
            throw new IOException("ROM 폴더를 만들 수 없어요.");
        }
        long freed = 0;
        for (File part : gameFiles(game)) {
            File link = new File(dir, part.getName());
            if (isLink(link)) {
                File target = linkTarget(link);
                if (target != null && target.getCanonicalPath().equals(part.getCanonicalPath())) {
                    continue;
                }
                link.delete();
            } else if (link.exists()) {
                if (link.length() != part.length()) {
                    return -1;
                }
                freed += link.length();
                if (!link.delete()) {
                    throw new IOException(link.getName() + "의 앱 안 복사본을 지우지 못했어요.");
                }
            }
            try {
                android.system.Os.symlink(part.getAbsolutePath(), link.getAbsolutePath());
            } catch (android.system.ErrnoException e) {
                throw new IOException(part.getName() + "을(를) 연결하지 못했어요.");
            }
        }
        return freed;
    }

    private boolean isTrackOfSheet(File file) {
        File dir = file.getParentFile();
        File[] sheets = dir == null ? null : dir.listFiles((d, name) -> name.toLowerCase(Locale.US).endsWith(".cue") || name.toLowerCase(Locale.US).endsWith(".gdi"));
        for (File sheet : sheets == null ? new File[0] : sheets) {
            for (String track : cueTracks(sheet)) {
                if (track.equalsIgnoreCase(file.getName())) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isLinkableGame(File file, String mode) {
        String lower = file.getName().toLowerCase(Locale.US);
        return file.isFile() && isRomNameFor(mode, lower) && !isTrackOfSheet(file) && !isPs2DiscForPs1(file, mode);
    }

    // (0.0.381) A PS2 game on CD (.cue + .bin like a PS1 one) is not a PS1 game: kept out of
    // the PS1 list; it goes in through PS2 (.iso made from it).
    private static boolean isPs2DiscForPs1(File file, String mode) {
        if (!MODE_PS1.equals(mode)) {
            return false;
        }
        String lower = file.getName().toLowerCase(Locale.US);
        File image = file;
        if (lower.endsWith(".cue")) {
            List<String> tracks = cueTracks(file);
            image = tracks.isEmpty() || file.getParentFile() == null ? null : new File(file.getParentFile(), tracks.get(0));
        } else if (!lower.endsWith(".bin") && !lower.endsWith(".img") && !lower.endsWith(".iso")) {
            return false;
        }
        return Ps2BinImport.isPs2Disc(image);
    }

    // Games under a folder (sub folders too, a few levels down).
    private List<File> findLinkableGames(File dir, String mode, int depth, List<File> out) {
        File[] files = dir.listFiles();
        if (files == null || out.size() > 2000) {
            return out;
        }
        Arrays.sort(files, (a, b) -> a.getName().compareToIgnoreCase(b.getName()));
        for (File file : files) {
            if (file.getName().startsWith(".")) {
                continue;
            }
            if (file.isDirectory()) {
                if (MODE_VITA.equals(mode) && isVitaGameFolder(file)) {
                    out.add(file);  // a dumped game folder (app/<ID>): linked as a .vitadir
                } else if (depth > 0 && !file.getName().equals("Android")) {
                    findLinkableGames(file, mode, depth - 1, out);
                }
            } else if (isLinkableGame(file, mode)) {
                out.add(file);
            }
        }
        return out;
    }

    private File phoneRoot() {
        return Environment.getExternalStorageDirectory();
    }

    // SD cards: the volumes other than the phone's own.
    private List<File> sdRoots() {
        List<File> roots = new ArrayList<>();
        File[] dirs = getExternalFilesDirs(null);
        for (int k = 1; dirs != null && k < dirs.length; k++) {
            if (dirs[k] == null) {
                continue;
            }
            String path = dirs[k].getAbsolutePath();
            int cut = path.indexOf("/Android/");
            if (cut > 0) {
                roots.add(new File(path.substring(0, cut)));
            }
        }
        return roots;
    }

    // The app's own file browser: folders, and the console's game files (checked to link),
    // or folder mode (link everything under the folder shown).
    private void showLinkBrowser(final String mode, final boolean folderMode, File start, final java.util.Set<String> picked) {
        final File dir = start == null ? phoneRoot() : start;
        final Dialog dialog = new Dialog(this, android.R.style.Theme_Material_Light_NoActionBar);
        final int teal = Color.rgb(14, 116, 144);
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(1);
        root.setBackgroundColor(Theme.bg(Color.WHITE));
        LinearLayout top = new LinearLayout(this);
        top.setOrientation(1);
        top.setPadding(dp(14), dp(14), dp(14), dp(8));
        LinearLayout titleRow = new LinearLayout(this);
        titleRow.setGravity(16);
        TextView back = new TextView(this);
        back.setText("←");
        back.setTextSize(18.0f);
        back.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        back.setPadding(0, 0, dp(12), 0);
        titleRow.addView(back);
        TextView title = new TextView(this);
        title.setText(folderMode ? "폴더째로 연결하기" : "파일 골라 연결하기");
        title.setTextSize(16.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        title.setTextColor(Theme.text(Color.rgb(17, 24, 39)));
        titleRow.addView(title);
        top.addView(titleRow);
        String rootPath = phoneRoot().getAbsolutePath();
        String shown = dir.getAbsolutePath().startsWith(rootPath) ? "📱 내 폰" + dir.getAbsolutePath().substring(rootPath.length()).replace("/", " › ") : dir.getAbsolutePath();
        TextView path = new TextView(this);
        path.setText(shown);
        path.setTextSize(11.5f);
        path.setTextColor(Theme.text(teal));
        path.setPadding(0, dp(6), 0, 0);
        top.addView(path);
        android.widget.HorizontalScrollView shortcutScroll = new android.widget.HorizontalScrollView(this);
        shortcutScroll.setHorizontalScrollBarEnabled(false);
        LinearLayout shortcuts = new LinearLayout(this);
        shortcutScroll.addView(shortcuts);
        List<String[]> places = new ArrayList<>();
        places.add(new String[]{"📱 내 폰", rootPath});
        places.add(new String[]{"⬇ Download", new File(phoneRoot(), Environment.DIRECTORY_DOWNLOADS).getAbsolutePath()});
        for (File sd : sdRoots()) {
            places.add(new String[]{"💾 SD 카드", sd.getAbsolutePath()});
        }
        String recent = settingsPrefs().getString(PREF_LINK_RECENT, "");
        if (!recent.isEmpty() && new File(recent).isDirectory()) {
            places.add(new String[]{"🕒 최근 연결", recent});
        }
        for (final String[] place : places) {
            TextView chip = multiDeleteChip(place[0]);
            chip.setOnClickListener(view -> {
                dialog.dismiss();
                showLinkBrowser(mode, folderMode, new File(place[1]), picked);
            });
            LinearLayout.LayoutParams chipParams = new LinearLayout.LayoutParams(-2, -2);
            chipParams.setMargins(0, 0, dp(6), 0);
            shortcuts.addView(chip, chipParams);
        }
        LinearLayout.LayoutParams shortcutParams = new LinearLayout.LayoutParams(-1, -2);
        shortcutParams.setMargins(0, dp(8), 0, 0);
        top.addView(shortcutScroll, shortcutParams);
        root.addView(top);
        LinearLayout rows = new LinearLayout(this);
        rows.setOrientation(1);
        rows.setPadding(dp(10), 0, dp(10), dp(10));
        ScrollView scroll = new ScrollView(this);
        scroll.addView(rows);
        root.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1.0f));
        File[] children = dir.listFiles();
        List<File> folders = new ArrayList<>();
        List<File> games = new ArrayList<>();
        List<File> ps2Discs = ps2CueBins(dir);
        int hidden = 0;
        for (File child : children == null ? new File[0] : children) {
            if (child.getName().startsWith(".")) {
                continue;
            }
            if (child.isDirectory()) {
                folders.add(child);
            } else if (MODE_PS2.equals(mode) && (child.getName().toLowerCase(Locale.ROOT).endsWith(".cue") || child.getName().toLowerCase(Locale.ROOT).endsWith(".bin"))) {
                if (!ps2Discs.contains(child)) hidden++;  // a .bin a .cue stands for
            } else if (isLinkableGame(child, mode)) {
                games.add(child);
            } else {
                hidden++;
            }
        }
        java.util.Comparator<File> byName = (a, b) -> a.getName().compareToIgnoreCase(b.getName());
        java.util.Collections.sort(folders, byName);
        java.util.Collections.sort(games, byName);
        final Runnable[] refreshBar = new Runnable[1];
        for (final File folder : folders) {
            int count = 0;
            File[] inside = folder.listFiles();
            for (File f : inside == null ? new File[0] : inside) {
                if (f.isFile() && isLinkableGame(f, mode)) {
                    count++;
                }
            }
            final boolean vitaGame = MODE_VITA.equals(mode) && isVitaGameFolder(folder);
            LinearLayout row = browserRow(vitaGame ? "🎮" : "📁", folder.getName(), vitaGame ? "PS Vita 게임 폴더 · 눌러서 넣기" : count > 0 ? "게임 " + count + "개" : "폴더", true, null);
            row.setOnClickListener(view -> {
                if (vitaGame) {
                    VitaFolder game = readVitaFolder(folder);
                    if (game != null) {
                        long[] sum = new long[2];
                        measureFolder(game.content, sum, 0);
                        game.size = sum[0];
                        game.files = (int) sum[1];
                        showVitaFolderConfirm(dialog, game);
                        return;
                    }
                }
                dialog.dismiss();
                showLinkBrowser(mode, folderMode, folder, picked);
            });
            rows.addView(row);
        }
        File appDir = romDirFor(mode);
        for (final File game : games) {
            File inApp = new File(appDir, game.getName());
            boolean already = inApp.exists() && !isLink(inApp) && inApp.length() == game.length();
            boolean linked = isLink(inApp) && game.getAbsolutePath().equals(String.valueOf(linkTarget(inApp)));
            String ext = game.getName().contains(".") ? game.getName().substring(game.getName().lastIndexOf('.') + 1).toUpperCase(Locale.ROOT) : "?";
            String detail = formatSize(romBytes(game)) + " · " + formatTimestamp(game.lastModified())
                    + (linked ? " · 이미 연결됨" : already ? " · 앱 안에 복사본 있음 (연결하면 그만큼 비어요)" : "");
            final boolean[] on = {picked.contains(game.getAbsolutePath())};
            LinearLayout row = browserRow(ext, game.getName(), detail, false, folderMode || linked ? null : on);
            if (linked) {
                row.setAlpha(0.5f);
            } else if (!folderMode) {
                row.setOnClickListener(view -> {
                    on[0] = !on[0];
                    if (on[0]) {
                        picked.add(game.getAbsolutePath());
                    } else {
                        picked.remove(game.getAbsolutePath());
                    }
                    dialog.dismiss();
                    showLinkBrowser(mode, false, dir, picked);
                });
            }
            rows.addView(row);
        }
        if (MODE_PS2.equals(mode)) {
            // (0.0.382) .cue / .bin: the PS2 engines need an .iso, so these are made into one
            // (a copy in the app) instead of linked.
            for (final File disc : ps2Discs) {
                LinearLayout row = browserRow(disc.getName().toLowerCase(Locale.ROOT).endsWith(".cue") ? "CUE" : "BIN", disc.getName(),
                        formatSize(ps2DiscBytes(disc)) + " · 눌러서 .iso로 바꿔 넣기 (연결이 아니라 앱 안에 만들어요)", false, null);
                row.setOnClickListener(view -> {
                    dialog.dismiss();
                    startPs2DiscFiles(java.util.Collections.singletonList(disc));
                });
                rows.addView(row);
            }
        }
        TextView note = new TextView(this);
        note.setText(MODE_NAMES[modeIndex(mode)] + " 게임 파일만 보여요" + (hidden > 0 ? " · 다른 파일 " + hidden + "개 숨김" : ""));
        note.setTextSize(11.0f);
        note.setTextColor(Theme.text(Color.rgb(148, 163, 184)));
        note.setPadding(dp(6), dp(10), 0, 0);
        rows.addView(note);
        LinearLayout bottom = new LinearLayout(this);
        bottom.setOrientation(1);
        bottom.setPadding(dp(14), dp(10), dp(14), dp(14));
        bottom.setBackgroundColor(Theme.bg(Color.WHITE));
        bottom.setElevation(dp(6));
        TextView summary = new TextView(this);
        summary.setTextSize(12.5f);
        summary.setTypeface(Typeface.DEFAULT_BOLD);
        summary.setTextColor(Theme.text(Color.rgb(17, 24, 39)));
        bottom.addView(summary);
        LinearLayout buttons = new LinearLayout(this);
        TextView cancel = multiDeleteButton("취소", Color.rgb(241, 242, 244), Color.rgb(55, 65, 81));
        cancel.setOnClickListener(view -> dialog.dismiss());
        buttons.addView(cancel, new LinearLayout.LayoutParams(0, dp(46), 1.0f));
        TextView go = multiDeleteButton(folderMode ? "이 폴더 연결하기" : "연결하기", teal, -1);
        LinearLayout.LayoutParams goParams = new LinearLayout.LayoutParams(0, dp(46), 1.6f);
        goParams.setMargins(dp(8), 0, 0, 0);
        buttons.addView(go, goParams);
        LinearLayout.LayoutParams buttonsParams = new LinearLayout.LayoutParams(-1, -2);
        buttonsParams.setMargins(0, dp(8), 0, 0);
        bottom.addView(buttons, buttonsParams);
        root.addView(bottom);
        if (folderMode) {
            summary.setText("지금 폴더: " + dir.getName() + " · 하위 폴더까지 찾아서 골라요");
            go.setOnClickListener(view -> {
                dialog.dismiss();
                showLinkFolderPick(mode, dir);
            });
        } else {
            long bytes = 0;
            for (String p : picked) {
                bytes += romBytes(new File(p));
            }
            summary.setText(picked.size() + "개 고름" + (picked.isEmpty() ? "" : " · " + formatSize(bytes)) + " · 늘어나는 용량 0MB");
            go.setText(picked.isEmpty() ? "연결하기" : picked.size() + "개 연결하기");
            go.setOnClickListener(view -> {
                if (picked.isEmpty()) {
                    showMessage("연결할 게임을 눌러서 골라 주세요.");
                    return;
                }
                dialog.dismiss();
                List<File> chosen = new ArrayList<>();
                for (String p : picked) {
                    chosen.add(new File(p));
                }
                runLinkGames(mode, chosen, null, false);
            });
        }
        back.setOnClickListener(view -> {
            dialog.dismiss();
            File parent = dir.getParentFile();
            if (parent != null && parent.canRead() && !dir.equals(phoneRoot())) {
                showLinkBrowser(mode, folderMode, parent, picked);
            }
        });
        dialog.setContentView(root);
        dialog.show();
    }

    private LinearLayout browserRow(String icon, String name, String detail, boolean folder, boolean[] checked) {
        LinearLayout row = new LinearLayout(this);
        row.setGravity(16);
        row.setPadding(dp(6), dp(9), dp(6), dp(9));
        if (checked != null) {
            View box = new View(this);
            GradientDrawable shape = rounded(checked[0] ? Color.rgb(14, 116, 144) : Color.WHITE, dp(6));
            if (!checked[0]) {
                shape.setStroke(dp(2), Theme.line(Color.rgb(203, 213, 225)));
            }
            box.setBackground(shape);
            LinearLayout.LayoutParams boxParams = new LinearLayout.LayoutParams(dp(20), dp(20));
            boxParams.setMargins(0, 0, dp(10), 0);
            row.addView(box, boxParams);
        }
        TextView badge = new TextView(this);
        badge.setText(icon);
        badge.setTextSize(folder ? 15.0f : 11.0f);
        badge.setTypeface(Typeface.DEFAULT_BOLD);
        badge.setGravity(17);
        badge.setTextColor(Theme.text(folder ? Color.rgb(3, 105, 161) : Color.rgb(14, 116, 144)));
        badge.setBackground(rounded(folder ? Color.rgb(224, 242, 254) : Color.rgb(236, 254, 255), dp(9)));
        row.addView(badge, new LinearLayout.LayoutParams(dp(38), dp(38)));
        LinearLayout texts = new LinearLayout(this);
        texts.setOrientation(1);
        TextView title = new TextView(this);
        title.setText(name);
        title.setTextSize(13.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        title.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        title.setSingleLine(true);
        title.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);
        texts.addView(title);
        TextView sub = new TextView(this);
        sub.setText(detail);
        sub.setTextSize(11.0f);
        sub.setTextColor(Theme.text(Color.rgb(107, 114, 128)));
        texts.addView(sub);
        LinearLayout.LayoutParams textsParams = new LinearLayout.LayoutParams(0, -2, 1.0f);
        textsParams.setMargins(dp(10), 0, 0, 0);
        row.addView(texts, textsParams);
        if (folder) {
            TextView more = new TextView(this);
            more.setText("›");
            more.setTextSize(15.0f);
            more.setTextColor(Theme.text(Color.rgb(148, 163, 184)));
            row.addView(more);
        }
        return row;
    }

    // 폴더째로 연결: everything under the folder, picked like the folder import.
    private void showLinkFolderPick(final String mode, final File dir) {
        final List<File> games = findLinkableGames(dir, mode, 6, new ArrayList<>());
        if (games.isEmpty() && MODE_PS2.equals(mode)) {
            List<File> discs = new ArrayList<>();
            collectPs2CueBins(dir, 4, discs);
            if (!discs.isEmpty()) {
                startPs2DiscFiles(discs);  // .cue / .bin only: made into .iso (0.0.382)
                return;
            }
        }
        if (games.isEmpty()) {
            showMessage(dir.getName() + " 안에 " + MODE_NAMES[modeIndex(mode)] + " 게임이 없어요.");
            return;
        }
        final Dialog dialog = new Dialog(this);
        final int teal = Color.rgb(14, 116, 144);
        LinearLayout body = pageDialog(dialog, "연결할 게임 고르기", dir.getName() + " · 하위 폴더 포함 · " + games.size() + "개", teal);
        final boolean[] checked = new boolean[games.size()];
        File appDir = romDirFor(mode);
        String base = dir.getAbsolutePath();
        for (int k = 0; k < games.size(); k++) {
            final int index = k;
            File game = games.get(k);
            File inApp = new File(appDir, game.getName());
            boolean folderGame = game.isDirectory();
            boolean linked = folderGame ? vitaPointerFor(game) != null : isLink(inApp) && game.getAbsolutePath().equals(String.valueOf(linkTarget(inApp)));
            boolean copy = !folderGame && inApp.exists() && !isLink(inApp) && inApp.length() == game.length();
            checked[k] = !linked && !copy;
            String rel = game.getAbsolutePath().substring(Math.min(game.getAbsolutePath().length(), base.length() + 1)).replace("/", " / ");
            String detail = (folderGame ? "게임 폴더" : formatSize(romBytes(game))) + (linked ? " · 이미 연결됨" : copy ? " · 이미 앱 안에 복사본 · 연결로 바꾸면 " + formatSize(inApp.length()) + " 확보" : "");
            final boolean[] on = {checked[k]};
            final LinearLayout[] holder = new LinearLayout[1];
            holder[0] = browserRow(folderGame ? "VITA" : game.getName().substring(game.getName().lastIndexOf('.') + 1).toUpperCase(Locale.ROOT), rel, detail, false, on);
            if (linked) {
                holder[0].setAlpha(0.5f);
            } else {
                holder[0].setOnClickListener(view -> {
                    checked[index] = !checked[index];
                    View box = holder[0].getChildAt(0);
                    GradientDrawable shape = rounded(checked[index] ? teal : Color.WHITE, dp(6));
                    if (!checked[index]) {
                        shape.setStroke(dp(2), Theme.line(Color.rgb(203, 213, 225)));
                    }
                    box.setBackground(shape);
                });
            }
            holder[0].setBackground(rounded(Color.WHITE, dp(12)));
            addPageRow(body, holder[0]);
        }
        final CheckBox auto = new CheckBox(this);
        auto.setText("이 폴더에 새 게임이 생기면 다음에 켤 때 자동으로 연결");
        auto.setTextSize(12.5f);
        auto.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        auto.setChecked(true);
        addPageRow(body, auto);
        TextView go = multiDeleteButton("연결하기", teal, -1);
        go.setOnClickListener(view -> {
            List<File> chosen = new ArrayList<>();
            for (int k = 0; k < games.size(); k++) {
                if (checked[k]) {
                    chosen.add(games.get(k));
                }
            }
            if (chosen.isEmpty() && !auto.isChecked()) {
                showMessage("연결할 게임을 골라 주세요.");
                return;
            }
            dialog.dismiss();
            runLinkGames(mode, chosen, dir, auto.isChecked());
        });
        LinearLayout.LayoutParams goParams = new LinearLayout.LayoutParams(-1, dp(46));
        goParams.setMargins(0, dp(10), 0, 0);
        body.addView(go, goParams);
        dialog.show();
    }

    private void runLinkGames(final String mode, final List<File> games, final File folder, final boolean auto) {
        settingsPrefs().edit().putString(PREF_LINK_RECENT, folder != null ? folder.getAbsolutePath()
                : games.isEmpty() ? "" : games.get(0).getParent()).apply();
        if (folder != null && auto) {
            java.util.LinkedHashSet<String> dirs = new java.util.LinkedHashSet<>(Arrays.asList(settingsPrefs().getString(PREF_LINK_DIRS + mode, "").split("\n")));
            dirs.remove("");
            dirs.add(folder.getAbsolutePath());
            settingsPrefs().edit().putString(PREF_LINK_DIRS + mode, android.text.TextUtils.join("\n", dirs)).apply();
        }
        int linked = 0;
        int clash = 0;
        long freed = 0;
        String error = null;
        for (File game : games) {
            try {
                long result = linkGame(game, mode);
                if (result < 0) {
                    clash++;
                } else {
                    linked++;
                    freed += result;
                }
            } catch (IOException e) {
                error = e.getMessage();
            }
        }
        refreshLibrary();
        StringBuilder message = new StringBuilder("🔗 " + linked + "개를 연결했어요 · 늘어난 용량 0MB");
        if (freed > 0) {
            message.append("\n앱 안 복사본을 지워서 ").append(formatSize(freed)).append("가 비었어요.");
        }
        if (clash > 0) {
            message.append("\n이름이 같은 다른 게임이 이미 있어서 ").append(clash).append("개는 건너뛰었어요.");
        }
        if (folder != null && auto) {
            message.append("\n이 폴더에 넣는 새 게임은 다음에 앱을 켤 때 자동으로 연결돼요.");
        }
        if (error != null) {
            message.append("\n").append(error);
        }
        new AppDialog.Builder(this).setTitle("연결했어요").setMessage(message.toString()).setPositiveButton("확인", null).show();
    }

    // On start: new games in the folders linked for good.
    private void autoLinkFolders() {
        if (!hasAllFilesAccess()) {
            return;
        }
        new Thread(() -> {
            int added = 0;
            for (String mode : MODE_IDS) {
                String dirs = settingsPrefs().getString(PREF_LINK_DIRS + mode, "");
                if (dirs.isEmpty()) {
                    continue;
                }
                for (String path : dirs.split("\n")) {
                    File dir = new File(path);
                    if (!dir.isDirectory()) {
                        continue;
                    }
                    for (File game : findLinkableGames(dir, mode, 6, new ArrayList<>())) {
                        File inApp = new File(romDirFor(mode), game.getName());
                        if (game.isDirectory() ? vitaPointerFor(game) != null : inApp.exists() || isLink(inApp)) {
                            continue;
                        }
                        try {
                            if (linkGame(game, mode) >= 0) {
                                added++;
                            }
                        } catch (IOException ignored) {
                            // Next time.
                        }
                    }
                }
            }
            final int count = added;
            if (count > 0) {
                runOnUiThread(() -> {
                    refreshLibrary();
                    Toast.makeText(this, "🔗 연결한 폴더의 새 게임 " + count + "개를 목록에 넣었어요", Toast.LENGTH_LONG).show();
                });
            }
        }, "auto-link").start();
    }

    // Links whose game was moved or deleted: find it again (same name keeps the saves) or drop.
    private void showBrokenLinks(final String mode) {
        final List<File> broken = brokenLinks(mode);
        if (broken.isEmpty()) {
            showMessage("원본을 찾을 수 없는 연결이 없어요.");
            return;
        }
        final Dialog dialog = new Dialog(this);
        LinearLayout body = pageDialog(dialog, "원본을 찾을 수 없는 연결", broken.size() + "개 · 옮기거나 지운 게임", Color.rgb(217, 119, 6));
        for (final File link : broken) {
            File target = linkTarget(link);
            LinearLayout row = settingsRow(link.getName(), "원래 위치: " + (target == null ? "?" : target.getParent()), null);
            TextView find = multiDeleteChip("다시 찾기");
            find.setOnClickListener(view -> {
                dialog.dismiss();
                showRelinkBrowser(mode, link, phoneRoot());
            });
            TextView drop = multiDeleteChip("빼기");
            drop.setOnClickListener(view -> {
                link.delete();
                dialog.dismiss();
                refreshLibrary();
                if (!brokenLinks(mode).isEmpty()) {
                    showBrokenLinks(mode);
                }
            });
            LinearLayout.LayoutParams chipParams = new LinearLayout.LayoutParams(-2, -2);
            chipParams.setMargins(dp(6), 0, 0, 0);
            row.addView(find, chipParams);
            row.addView(drop, chipParams);
            addPageRow(body, row);
        }
        addPageRow(body, settingsRow("알아두기", "세이브는 앱 안에 그대로 있어요. 같은 이름의 파일로 다시 찾으면 세이브가 이어져요.", null));
        dialog.show();
    }

    // A small browser to point a broken link at the game's new place.
    private void showRelinkBrowser(final String mode, final File link, final File dir) {
        File[] children = dir.listFiles();
        List<File> entries = new ArrayList<>();
        for (File child : children == null ? new File[0] : children) {
            if (!child.getName().startsWith(".") && (child.isDirectory() || isLinkableGame(child, mode))) {
                entries.add(child);
            }
        }
        java.util.Collections.sort(entries, (a, b) -> a.isDirectory() != b.isDirectory() ? (a.isDirectory() ? -1 : 1) : a.getName().compareToIgnoreCase(b.getName()));
        String[] names = new String[entries.size() + (dir.equals(phoneRoot()) ? 0 : 1)];
        int at = 0;
        if (!dir.equals(phoneRoot())) {
            names[at++] = "📁 ..  (위 폴더)";
        }
        for (File entry : entries) {
            names[at++] = (entry.isDirectory() ? "📁 " : (entry.getName().equalsIgnoreCase(link.getName()) ? "✓ " : "   ")) + entry.getName();
        }
        final int offset = dir.equals(phoneRoot()) ? 0 : 1;
        new AppDialog.Builder(this).setTitle(link.getName() + " 다시 찾기").setItems(names, (d, which) -> {
            if (which < offset) {
                showRelinkBrowser(mode, link, dir.getParentFile());
                return;
            }
            File chosen = entries.get(which - offset);
            if (chosen.isDirectory()) {
                showRelinkBrowser(mode, link, chosen);
                return;
            }
            link.delete();
            try {
                android.system.Os.symlink(chosen.getAbsolutePath(), link.getAbsolutePath());
                if (isDiscSheet(chosen)) {
                    linkGame(chosen, mode);
                }
                Toast.makeText(this, "다시 연결했어요", Toast.LENGTH_SHORT).show();
            } catch (android.system.ErrnoException | IOException e) {
                showError("다시 연결하지 못했어요.");
            }
            refreshLibrary();
        }).setNegativeButton("취소", null).show();
    }

    // ---- 저장할 곳 (patched / unpacked games): inside the app, next to a linked original
    // (made there and linked), or inside the app and copied to a phone folder too ----

    private static final int SAVE_IN_APP = 0;
    private static final int SAVE_IN_FOLDER = 1;      // made in the folder, linked into the app
    private static final int SAVE_ALSO_FOLDER = 2;    // made in the app, copied to the folder
    private static final String PREF_SAVE_FOLDER = "save_folder";
    private int saveWhere = SAVE_IN_APP;
    private File saveFolder;

    private File defaultPhoneFolder() {
        String last = settingsPrefs().getString(PREF_SAVE_FOLDER, null);
        if (last != null && new File(last).isDirectory()) {
            return new File(last);
        }
        return new File(new File(phoneRoot(), Environment.DIRECTORY_DOWNLOADS), "Mini Emulator");
    }

    private String phonePathText(File dir) {
        String root = phoneRoot().getAbsolutePath();
        String path = dir.getAbsolutePath();
        return path.startsWith(root) ? (path.length() == root.length() ? "내 폰" : path.substring(root.length())) : path;
    }

    // "저장할 곳" under a patch / unpack window; sets saveWhere / saveFolder as it is changed.
    private void addSaveWhereSection(LinearLayout panel, File source) {
        final boolean linked = isLink(source);
        final File origin = linked && linkTarget(source) != null ? linkTarget(source).getParentFile() : null;
        this.saveWhere = linked && origin != null ? SAVE_IN_FOLDER : SAVE_IN_APP;
        this.saveFolder = linked && origin != null ? origin : defaultPhoneFolder();
        TextView label = new TextView(this);
        label.setText("저장할 곳");
        label.setTextSize(12.0f);
        label.setTypeface(Typeface.DEFAULT_BOLD);
        label.setTextColor(Theme.text(Color.rgb(55, 65, 81)));
        label.setPadding(0, dp(12), 0, 0);
        panel.addView(label);
        final android.widget.RadioGroup group = new android.widget.RadioGroup(this);
        panel.addView(group);
        final List<int[]> kinds = new ArrayList<>();
        final List<android.widget.RadioButton> buttons = new ArrayList<>();
        final Runnable[] render = new Runnable[1];
        render[0] = () -> {
            group.removeAllViews();
            kinds.clear();
            buttons.clear();
            if (linked && origin != null) {
                addWhere(group, kinds, buttons, SAVE_IN_FOLDER, 0, "원본과 같은 폴더", phonePathText(origin) + " · 목록에는 🔗 연결로");
                addWhere(group, kinds, buttons, SAVE_IN_APP, 0, "앱 안", "원본 폴더는 그대로");
                addWhere(group, kinds, buttons, SAVE_IN_FOLDER, 1, "다른 폴더 고르기",
                        this.saveFolder.equals(origin) ? "앱 안 탐색기로 고르기" : phonePathText(this.saveFolder) + " · 바꾸려면 다시 누르기");
            } else {
                addWhere(group, kinds, buttons, SAVE_IN_APP, 0, "앱 안", "원본도 앱 안에 있어요");
                addWhere(group, kinds, buttons, SAVE_ALSO_FOLDER, 1, "폰 폴더에도 저장", phonePathText(this.saveFolder) + " · 누르면 폴더를 바꿀 수 있어요");
            }
            for (int k = 0; k < kinds.size(); k++) {
                boolean on = kinds.get(k)[0] == this.saveWhere && (kinds.get(k)[0] == SAVE_IN_APP
                        || (linked && origin != null ? (kinds.get(k)[1] == 1) == !this.saveFolder.equals(origin) : true));
                buttons.get(k).setChecked(on);
            }
        };
        render[0].run();
        group.setOnCheckedChangeListener((g, id) -> {
            for (int k = 0; k < buttons.size(); k++) {
                if (buttons.get(k).getId() != id || !buttons.get(k).isPressed()) {
                    continue;
                }
                final int[] kind = kinds.get(k);
                if (kind[0] == SAVE_IN_APP) {
                    this.saveWhere = SAVE_IN_APP;
                } else if (kind[1] == 0 && origin != null) {
                    this.saveWhere = SAVE_IN_FOLDER;
                    this.saveFolder = origin;
                } else {
                    withAllFilesAccess(() -> showFolderPicker(this.saveFolder.isDirectory() ? this.saveFolder : phoneRoot(), "저장할 폴더 고르기", picked -> {
                        this.saveWhere = kind[0];
                        this.saveFolder = picked;
                        settingsPrefs().edit().putString(PREF_SAVE_FOLDER, picked.getAbsolutePath()).apply();
                        render[0].run();
                    }));
                }
            }
        });
    }

    private void addWhere(android.widget.RadioGroup group, List<int[]> kinds, List<android.widget.RadioButton> buttons, int where, int variant, String title, String detail) {
        android.widget.RadioButton button = new android.widget.RadioButton(this);
        button.setId(View.generateViewId());
        android.text.SpannableStringBuilder text = new android.text.SpannableStringBuilder(title + "\n" + detail);
        text.setSpan(new android.text.style.StyleSpan(Typeface.BOLD), 0, title.length(), 0);
        text.setSpan(new android.text.style.RelativeSizeSpan(0.85f), title.length() + 1, text.length(), 0);
        text.setSpan(new android.text.style.ForegroundColorSpan(Color.rgb(107, 114, 128)), title.length() + 1, text.length(), 0);
        button.setText(text);
        button.setTextSize(13.0f);
        button.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        button.setPadding(dp(4), dp(4), 0, dp(4));
        group.addView(button);
        kinds.add(new int[]{where, variant});
        buttons.add(button);
    }

    // Where a new game from source is made (and checked for space).
    private File outputDirFor(File source) {
        if (this.saveWhere == SAVE_IN_FOLDER && this.saveFolder != null && (this.saveFolder.isDirectory() || this.saveFolder.mkdirs())) {
            return this.saveFolder;
        }
        return source.getParentFile() != null && !isLink(source) ? source.getParentFile() : romDirFor(modeForFile(source));
    }

    // A folder chooser: the folder shown is picked with "이 폴더 선택"; "+ 새 폴더" makes one.
    private void showFolderPicker(final File dir, final String title, final java.util.function.Consumer<File> onPick) {
        File[] children = dir.listFiles(f -> f.isDirectory() && !f.getName().startsWith("."));
        final List<File> folders = new ArrayList<>(Arrays.asList(children == null ? new File[0] : children));
        java.util.Collections.sort(folders, (a, b) -> a.getName().compareToIgnoreCase(b.getName()));
        final boolean top = dir.equals(phoneRoot());
        List<String> names = new ArrayList<>();
        names.add("✓ 이 폴더 선택 · " + phonePathText(dir));
        names.add("+ 새 폴더 만들기");
        if (!top) {
            names.add("📁 ..  (위 폴더)");
        } else {
            names.add("⬇ Download");
        }
        for (File folder : folders) {
            names.add("📁 " + folder.getName());
        }
        new AppDialog.Builder(this).setTitle(title).setItems(names.toArray(new String[0]), (d, which) -> {
            if (which == 0) {
                onPick.accept(dir);
            } else if (which == 1) {
                final EditText name = new EditText(this);
                name.setSingleLine(true);
                name.setText("Mini Emulator");
                new AppDialog.Builder(this).setTitle("새 폴더").setView(name).setNegativeButton("취소", null).setPositiveButton("만들기", (d2, w2) -> {
                    File made = new File(dir, sanitizeFileName(name.getText().toString().trim().isEmpty() ? "Mini Emulator" : name.getText().toString().trim()));
                    if (!made.isDirectory() && !made.mkdirs()) {
                        showError("폴더를 만들 수 없어요.");
                        showFolderPicker(dir, title, onPick);
                        return;
                    }
                    showFolderPicker(made, title, onPick);
                }).show();
            } else if (which == 2) {
                showFolderPicker(top ? new File(phoneRoot(), Environment.DIRECTORY_DOWNLOADS) : dir.getParentFile(), title, onPick);
            } else {
                showFolderPicker(folders.get(which - 3), title, onPick);
            }
        }).setNegativeButton("취소", null).show();
    }

    // Why the last copyPlain failed (shown to the player).
    private static volatile String lastCopyError;

    private static boolean copyPlain(File from, File to) {
        if (from.isDirectory()) {
            // A game folder (PS3, 0.0.394): the whole tree.
            if (!to.isDirectory() && !to.mkdirs()) {
                lastCopyError = "폴더를 만들 수 없어요: " + to.getName();
                return false;
            }
            File[] files = from.listFiles();
            if (files == null) {
                lastCopyError = "폴더를 읽을 수 없어요: " + from.getName();
                return false;
            }
            for (File f : files) {
                File target = new File(to, f.getName());
                if (f.isFile() && target.isFile() && target.length() == f.length()) {
                    continue;
                }
                if (!copyPlain(f, target)) {
                    return false;
                }
            }
            return true;
        }
        File temp = new File(to.getPath() + ".copying");
        try (InputStream in = new FileInputStream(from); OutputStream out = new FileOutputStream(temp)) {
            byte[] buffer = new byte[1 << 20];
            int n;
            while ((n = in.read(buffer)) > 0) {
                out.write(buffer, 0, n);
            }
        } catch (IOException e) {
            temp.delete();
            String why = e.getMessage() == null ? e.toString() : e.getMessage();
            lastCopyError = from.getName() + ": " + (why.contains("EFBIG") || why.contains("File too large")
                    ? "고른 곳이 4GB보다 큰 파일을 담을 수 없는 저장소예요 (FAT32 SD카드 등). 휴대폰 내장 저장소의 폴더를 골라 주세요."
                    : why.contains("ENOSPC") ? "저장 공간이 모자라요." : why);
            return false;
        }
        if (temp.renameTo(to) || (to.delete() && temp.renameTo(to))) {
            return true;
        }
        lastCopyError = to.getName() + "(으)로 이름을 바꾸지 못했어요";
        return false;
    }

    // After a new game was made: in a phone folder it is linked into the app; "폰 폴더에도
    // 저장" copies it there in the background. Returns the game as the app lists it.
    private File placeNewGame(File source, File made) {
        String mode = modeForFile(source);
        File inApp = made;
        if (!romDirFor(mode).equals(made.getParentFile())) {
            try {
                if (linkGame(made, mode) < 0) {
                    showError("앱 안에 이름이 같은 다른 게임이 있어서 목록에 넣지 못했어요. 파일은 " + phonePathText(made) + "에 있어요.");
                } else {
                    inApp = new File(romDirFor(mode), made.getName());
                }
            } catch (IOException e) {
                showError(e.getMessage());
            }
        } else if (this.saveWhere == SAVE_ALSO_FOLDER && this.saveFolder != null) {
            final File folder = this.saveFolder;
            final List<File> files = gameFiles(made);
            new Thread(() -> {
                boolean ok = folder.isDirectory() || folder.mkdirs();
                for (File part : files) {
                    ok &= ok && copyPlain(part, new File(folder, part.getName()));
                }
                final boolean done = ok;
                runOnUiThread(() -> Toast.makeText(this, done ? "폰 폴더에도 저장했어요 · " + phonePathText(folder) : "폰 폴더에 저장하지 못했어요", Toast.LENGTH_LONG).show());
            }, "save-also").start();
        }
        this.saveWhere = SAVE_IN_APP;
        return inApp;
    }

    // ---- 게임 파일 내보내기: a copy of games in the app into a phone folder ----

    private static final String PREF_EXPORT_FOLDER = "export_folder";

    private void exportGame(final File game) {
        if (game.getName().toLowerCase(Locale.ROOT).endsWith(".ps3game")) {
            showMessage("PSN 게임(PKG로 설치한 게임)은 PS3 엔진 안에 설치돼 있어서 파일로 내보낼 수 없어요. 설치했던 PKG 파일을 보관해 두면 다시 설치할 수 있어요.");
            return;
        }
        withAllFilesAccess(() -> {
            String last = settingsPrefs().getString(PREF_EXPORT_FOLDER, null);
            File start = last != null && new File(last).isDirectory() ? new File(last) : new File(phoneRoot(), Environment.DIRECTORY_DOWNLOADS);
            showFolderPicker(start, "내보낼 폴더 고르기", folder -> {
                settingsPrefs().edit().putString(PREF_EXPORT_FOLDER, folder.getAbsolutePath()).apply();
                final List<File> parts = gameFiles(game);
                long bytes = 0;
                for (File part : parts) {
                    bytes += romBytes(part);
                }
                long free = new android.os.StatFs(folder.getAbsolutePath()).getAvailableBytes();
                if (free < bytes + 16L * 1024 * 1024) {
                    showError("공간이 부족해요. " + formatSize(bytes) + "가 필요한데 " + formatSize(free) + " 남았어요.");
                    return;
                }
                final android.app.ProgressDialog progress = new android.app.ProgressDialog(this);
                progress.setMessage(displayGameNameFor(game) + " 내보내는 중… " + formatSize(bytes));
                progress.setCancelable(false);
                progress.show();
                new Thread(() -> {
                    boolean ok = true;
                    lastCopyError = null;
                    for (File part : parts) {
                        File to = new File(folder, part.getName());
                        if (to.isFile() && to.length() == part.length()) {
                            continue;
                        }
                        ok = ok && copyPlain(part, to);
                    }
                    final boolean done = ok;
                    final String why = lastCopyError;
                    runOnUiThread(() -> {
                        progress.dismiss();
                        if (!done) {
                            showError("내보내지 못했어요." + (why != null ? "\n" + why : " 폴더와 공간을 확인해 주세요."));
                            return;
                        }
                        final File exported = new File(folder, game.getName());
                        if (game.isDirectory()) {
                            // A PS3 game folder: copied whole; it stays in the app (no 연결 for folders).
                            showMessage(phonePathText(exported) + " 폴더로 내보냈어요 (게임 폴더째, 한글패치 원본 백업 .mini_original 포함).\n\n앱 안의 게임은 그대로 있어요.");
                            return;
                        }
                        new AppDialog.Builder(this).setTitle("내보냈어요")
                                .setMessage(phonePathText(exported) + "\n\n이제 앱을 지우거나 롬을 실수로 지워도 이 파일로 다시 가져올 수 있어요.\n\n"
                                        + "앱 안 복사본을 지우고 내보낸 파일을 🔗 연결로 쓰면 " + formatSize(romBytes(game)) + "가 비어요. 세이브는 그대로 이어져요.")
                                .setNegativeButton("두 군데 다 두기", null)
                                .setPositiveButton("연결로 바꾸기", (d, which) -> {
                                    try {
                                        long freed = linkGame(exported, modeForFile(game));
                                        refreshLibrary();
                                        Toast.makeText(this, "🔗 연결로 바꿨어요 · " + formatSize(Math.max(0, freed)) + " 비었어요", Toast.LENGTH_LONG).show();
                                    } catch (IOException e) {
                                        showError(e.getMessage());
                                    }
                                }).show();
                    });
                }, "export-game").start();
            });
        });
    }

    // 설정 → 게임 파일 내보내기: every game kept inside the app, a folder per console.
    private void showBulkExport() {
        withAllFilesAccess(() -> {
            final java.util.LinkedHashMap<String, List<File>> byMode = new java.util.LinkedHashMap<>();
            long total = 0;
            int count = 0;
            for (String mode : MODE_IDS) {
                File[] files = romDirFor(mode).listFiles(this::isRomFile);
                List<File> list = new ArrayList<>();
                for (File file : files == null ? new File[0] : files) {
                    if (!isLink(file)) {
                        list.add(file);
                        total += romBytes(file);
                    }
                }
                if (!list.isEmpty()) {
                    byMode.put(mode, list);
                    count += list.size();
                }
            }
            if (count == 0) {
                showMessage("앱 안에 복사해 둔 게임이 없어요 (연결한 게임은 이미 폰에 있어요).");
                return;
            }
            final long bytes = total;
            final int games = count;
            final File[] target = {new File(new File(phoneRoot(), Environment.DIRECTORY_DOWNLOADS), "Mini Emulator 백업")};
            final Dialog dialog = new Dialog(this);
            final int teal = Color.rgb(14, 116, 144);
            LinearLayout body = pageDialog(dialog, "모든 게임 파일 내보내기", "앱 안 게임 " + games + "개 · " + formatSize(bytes), teal);
            StringBuilder list = new StringBuilder();
            for (java.util.Map.Entry<String, List<File>> entry : byMode.entrySet()) {
                long size = 0;
                for (File file : entry.getValue()) {
                    size += romBytes(file);
                }
                list.append(MODE_NAMES[modeIndex(entry.getKey())]).append(" · ").append(entry.getValue().size()).append("개 · ").append(formatSize(size)).append('\n');
            }
            addPageRow(body, settingsRow("내보낼 게임", list.toString().trim(), null));
            final LinearLayout[] whereRow = new LinearLayout[1];
            final LinearLayout holder = new LinearLayout(this);
            holder.setOrientation(1);
            addPageRow(body, holder);
            final Runnable[] showWhere = new Runnable[1];
            showWhere[0] = () -> {
                holder.removeAllViews();
                whereRow[0] = settingsRow("내보낼 곳 · 바꾸려면 누르기", phonePathText(target[0]) + "\n게임기마다 폴더를 나눠요 · 이미 같은 파일이 있으면 건너뛰어요", () ->
                        showFolderPicker(target[0].isDirectory() ? target[0] : target[0].getParentFile(), "내보낼 곳 고르기", picked -> {
                            target[0] = picked;
                            showWhere[0].run();
                        }));
                holder.addView(whereRow[0]);
            };
            showWhere[0].run();
            final CheckBox toLinks = new CheckBox(this);
            toLinks.setText("끝나면 전부 연결로 바꾸기 (앱 안 복사본을 지워 " + formatSize(bytes) + "를 비워요)");
            toLinks.setTextSize(12.5f);
        toLinks.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
            addPageRow(body, toLinks);
            TextView go = multiDeleteButton(games + "개 내보내기 · " + formatSize(bytes), teal, -1);
            go.setOnClickListener(view -> {
                long free = new android.os.StatFs((target[0].isDirectory() ? target[0] : phoneRoot()).getAbsolutePath()).getAvailableBytes();
                if (free < bytes + 64L * 1024 * 1024) {
                    showError("공간이 부족해요. " + formatSize(bytes) + "가 필요한데 " + formatSize(free) + " 남았어요.");
                    return;
                }
                dialog.dismiss();
                runBulkExport(byMode, target[0], toLinks.isChecked(), bytes);
            });
            LinearLayout.LayoutParams goParams = new LinearLayout.LayoutParams(-1, dp(48));
            goParams.setMargins(0, dp(10), 0, 0);
            body.addView(go, goParams);
            dialog.show();
        });
    }

    private void runBulkExport(final java.util.Map<String, List<File>> byMode, final File target, final boolean toLinks, final long bytes) {
        final StepDialog steps = new StepDialog("게임 파일 내보내는 중", phonePathText(target), RoundIconView.EXPORT, Color.rgb(14, 116, 144),
                new String[]{"복사", toLinks ? "연결로 바꾸기" : "확인"}, new String[]{"", ""});
        new Thread(() -> {
            long done = 0;
            int copied = 0;
            int skipped = 0;
            long freed = 0;
            String error = null;
            outer:
            for (java.util.Map.Entry<String, List<File>> entry : byMode.entrySet()) {
                File folder = new File(target, sanitizeFileName(MODE_NAMES[modeIndex(entry.getKey())]));
                if (!folder.isDirectory() && !folder.mkdirs()) {
                    error = "폴더를 만들 수 없어요: " + folder.getName();
                    break;
                }
                for (File game : entry.getValue()) {
                    if (steps.cancelled) {
                        break outer;
                    }
                    for (File part : gameFiles(game)) {
                        File to = new File(folder, part.getName());
                        final String detail = part.getName();
                        final int permille = (int) (900 * done / Math.max(1, bytes));
                        runOnUiThread(() -> steps.set(0, detail, permille));
                        if (to.isFile() && to.length() == part.length()) {
                            skipped++;
                        } else if (!copyPlain(part, to)) {
                            error = part.getName() + "을(를) 복사하지 못했어요." + (lastCopyError != null ? "\n" + lastCopyError : "");
                            break outer;
                        } else {
                            copied++;
                        }
                        done += part.isDirectory() ? romBytes(part) : part.length();
                    }
                    if (toLinks) {
                        try {
                            freed += Math.max(0, linkGame(new File(folder, game.getName()), entry.getKey()));
                        } catch (IOException e) {
                            error = e.getMessage();
                        }
                    }
                }
            }
            final String why = error;
            final int c = copied;
            final int s = skipped;
            final long f = freed;
            runOnUiThread(() -> {
                steps.dismiss();
                refreshLibrary();
                if (why != null) {
                    showError(why);
                    return;
                }
                new AppDialog.Builder(this).setTitle(steps.cancelled ? "그만뒀어요" : "내보냈어요")
                        .setMessage(phonePathText(target) + "\n파일 " + c + "개 복사" + (s > 0 ? " · 이미 있어서 " + s + "개 건너뜀" : "")
                                + (toLinks ? "\n🔗 연결로 바꿔서 " + formatSize(f) + "가 비었어요." : ""))
                        .setPositiveButton("확인", null).show();
            });
        }, "bulk-export").start();
    }

    // ---- 도움말: the overview document of this version (assets/help) ----

    @android.annotation.SuppressLint("SetJavaScriptEnabled")
    private void showHelp() {
        final Dialog dialog = new Dialog(this, Theme.isDark() ? android.R.style.Theme_Material_NoActionBar : android.R.style.Theme_Material_Light_NoActionBar);
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(1);
        root.setBackgroundColor(Theme.bg(Color.WHITE));
        LinearLayout bar = new LinearLayout(this);
        bar.setGravity(16);
        bar.setPadding(dp(14), dp(12), dp(14), dp(12));
        bar.setBackgroundColor(Theme.bg(Color.rgb(22, 163, 74)));
        TextView close = new TextView(this);
        close.setText("✕");
        close.setTextSize(18.0f);
        close.setTextColor(Color.WHITE);
        close.setPadding(0, 0, dp(14), 0);
        close.setOnClickListener(view -> dialog.dismiss());
        bar.addView(close);
        TextView title = new TextView(this);
        title.setText("도움말 · Mini Emulator " + AppUpdate.currentVersion(this));
        title.setTextSize(16.0f);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        title.setTextColor(Color.WHITE);
        bar.addView(title);
        root.addView(bar);
        final android.webkit.WebView web = new android.webkit.WebView(this);
        web.getSettings().setJavaScriptEnabled(false);
        web.getSettings().setBuiltInZoomControls(true);
        web.getSettings().setDisplayZoomControls(false);
        web.getSettings().setAllowFileAccess(true);
        web.setWebViewClient(new android.webkit.WebViewClient() {
            @Override
            public boolean shouldOverrideUrlLoading(android.webkit.WebView view, android.webkit.WebResourceRequest request) {
                Uri url = request.getUrl();
                if ("file".equals(url.getScheme())) {
                    return false;
                }
                try {
                    startActivity(new Intent(Intent.ACTION_VIEW, url));
                } catch (Exception ignored) {
                    // No browser.
                }
                return true;
            }
        });
        root.addView(web, new LinearLayout.LayoutParams(-1, 0, 1.0f));
        dialog.setContentView(root);
        dialog.setOnKeyListener((d, keyCode, event) -> {
            if (keyCode == android.view.KeyEvent.KEYCODE_BACK && event.getAction() == android.view.KeyEvent.ACTION_UP && web.canGoBack()) {
                web.goBack();
                return true;
            }
            return false;
        });
        dialog.setOnDismissListener(d -> web.destroy());
        web.setBackgroundColor(Theme.isDark() ? Color.rgb(18, 20, 24) : Color.rgb(244, 245, 248));
        web.loadUrl("file:///android_asset/help/overview-" + (Theme.isDark() ? "dark" : "light") + ".html");
        dialog.show();
    }

    private String patchedFrom(File file) {
        return romPrefs().getString("patched:" + file.getName(), null);
    }

    private LinearLayout.LayoutParams actionGridParams(int column) {
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, -1, 1.0f);
        params.setMargins(column == 0 ? 0 : dp(4), 0, column == 2 ? 0 : dp(4), 0);
        return params;
    }

    private LinearLayout createActionTile(Dialog dialog, int icon, int color, String label, String sub, boolean danger, Runnable action) {
        LinearLayout tile = new LinearLayout(this);
        tile.setOrientation(1);
        tile.setGravity(1);
        tile.setPadding(dp(6), dp(13), dp(6), dp(11));
        final int normal = danger ? Color.rgb(255, 241, 241) : Color.rgb(246, 247, 249);
        final int pressed = danger ? Color.rgb(252, 222, 222) : Color.rgb(228, 231, 236);
        tile.setBackground(rounded(normal, dp(16)));
        tile.addView(new RoundIconView(this, icon, color), new LinearLayout.LayoutParams(dp(42), dp(42)));
        TextView text = new TextView(this);
        text.setText(label);
        text.setTextSize(12.5f);
        text.setTypeface(Typeface.DEFAULT_BOLD);
        text.setTextColor(Theme.text(danger ? Color.rgb(217, 61, 66) : Color.rgb(31, 41, 51)));
        text.setGravity(1);
        LinearLayout.LayoutParams textParams = new LinearLayout.LayoutParams(-2, -2);
        textParams.setMargins(0, dp(7), 0, 0);
        tile.addView(text, textParams);
        if (sub != null) {
            TextView subText = new TextView(this);
            subText.setText(sub);
            subText.setTextSize(10.5f);
            subText.setTextColor(Theme.text(Color.rgb(138, 146, 156)));
            subText.setGravity(1);
            tile.addView(subText, new LinearLayout.LayoutParams(-2, -2));
        }
        pressable(tile, normal, pressed, dp(16));
        tile.setOnClickListener(view -> {
            dialog.dismiss();
            action.run();
        });
        return tile;
    }

    private LinearLayout createOutlineButton(Dialog dialog, int icon, String label, Runnable action) {
        LinearLayout button = new LinearLayout(this);
        button.setOrientation(0);
        button.setGravity(17);
        GradientDrawable outline = new GradientDrawable();
        outline.setColor(Theme.bg(-1));
        outline.setStroke(Math.round(1.5f * getResources().getDisplayMetrics().density), Theme.line(Color.rgb(243, 199, 200)));
        outline.setCornerRadius(dp(13));
        button.setBackground(outline);
        RoundIconView iconView = new RoundIconView(this, icon, Color.rgb(229, 72, 77));
        button.addView(iconView, new LinearLayout.LayoutParams(dp(24), dp(24)));
        TextView text = new TextView(this);
        text.setText(label);
        text.setTextSize(13.5f);
        text.setTypeface(Typeface.DEFAULT_BOLD);
        text.setTextColor(Theme.text(Color.rgb(229, 72, 77)));
        LinearLayout.LayoutParams textParams = new LinearLayout.LayoutParams(-2, -2);
        textParams.setMargins(dp(6), 0, 0, 0);
        button.addView(text, textParams);
        button.setClickable(true);
        button.setOnClickListener(view -> {
            dialog.dismiss();
            action.run();
        });
        return button;
    }

    // Darkens a rounded tile while it is held down.
    private void pressable(View view, int normal, int pressed, int radius) {
        view.setClickable(true);
        view.setOnTouchListener((v, event) -> {
            int action = event.getActionMasked();
            if (action == MotionEvent.ACTION_DOWN) {
                v.setBackground(rounded(pressed, radius));
            } else if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                v.setBackground(rounded(normal, radius));
            }
            return false;
        });
    }

