    private void addEngineBar(LinearLayout row, String label, int value, int on, int text) {
        TextView name = new TextView(this);
        name.setText(label);
        name.setTextSize(11.0f);
        name.setTypeface(Typeface.DEFAULT_BOLD);
        name.setTextColor(Theme.text(text));
        row.addView(name);
        for (int i = 0; i < 5; i++) {
            View step = new View(this);
            step.setBackground(rounded(i < value ? on : (on == -1 ? Color.argb(70, 255, 255, 255) : Color.rgb(229, 231, 235)), dp(3)));
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(dp(14), dp(6));
            params.setMargins(i == 0 ? dp(6) : dp(3), 0, 0, 0);
            row.addView(step, params);
        }
        View gap = new View(this);
        row.addView(gap, new LinearLayout.LayoutParams(dp(16), 1));
    }

    private void onCoreSelected(File file, String[] strArr, DialogInterface dialogInterface, int i) {
        romPrefs().edit().putString("core:" + file.getName(), strArr[i]).apply();
        dialogInterface.dismiss();
        refreshLibrary();
        showMessage("실행 코어: " + coreDisplayName(strArr[i]));
    }

    private void launchPs3Game(File file) {
        String unsupported = Ps3Activity.unsupportedReason(this);
        if (unsupported != null) {
            showError(unsupported);
            return;
        }
        if (!Ps3Activity.firmwareInstalled(this)) {
            showError("PS3 게임은 PS3 펌웨어가 있어야 해요. 먼저 펌웨어를 설치해 주세요.");
            showPs3FirmwareSheet();
            return;
        }
        String path = file.getAbsolutePath();
        if (file.getName().toLowerCase(Locale.ROOT).endsWith(".ps3game")) {
            path = ps3GameLink(file);
            if (path == null || !new File(path).isDirectory()) {
                showError("이 PSN 게임의 설치 폴더가 없어요. PKG를 다시 설치해 주세요.");
                return;
            }
        }
        Intent intent = new Intent(this, Ps3Activity.class);
        intent.putExtra(Ps3Activity.EXTRA_ACTION, Ps3Activity.ACTION_BOOT);
        intent.putExtra(Ps3Activity.EXTRA_PATH, path);
        intent.putExtra(Ps3Activity.EXTRA_TITLE, displayGameNameFor(file));
        markRecentlyPlayed(file);
        startActivity(intent);
    }

    // ---- Xbox 360 (0.0.412) ----
    // X360Activity's 재시작: the engine boots once per process, so the game is opened again
    // from here, in a new one.
    static final String EXTRA_RELAUNCH_X360 = "com.example.minigba.RELAUNCH_X360";
    static final String EXTRA_RELAUNCH_X360_TITLE = "com.example.minigba.RELAUNCH_X360_TITLE";

    private void launchX360Game(String path, String title) {
        X360Patches.sync(this);  // (0.0.414) the game patches as chosen
        String unsupported = X360Activity.unsupportedReason(this);
        if (unsupported != null) {
            showError(unsupported);
            return;
        }
        if (X360Activity.isOriginalXboxDisc(new File(path))) {
            new AppDialog.Builder(this).setTitle("초대 Xbox 게임이에요")
                    .setMessage("이 디스크는 Xbox 360이 아니라 초대 Xbox(2001~2005년) 게임이에요 (안에 default.xbe가 있어요).\n\n"
                            + "Xbox 360 엔진(XenDroid)으로는 켜지지 않아서 검은 화면만 나와요. 초대 Xbox 모드는 준비 중이에요.")
                    .setPositiveButton("확인", null).show();
            return;
        }
        Intent intent = new Intent(this, X360Activity.class);
        intent.putExtra(X360Activity.EXTRA_PATH, path);
        intent.putExtra(X360Activity.EXTRA_TITLE, title);
        startActivity(intent);
    }

    private void relaunchX360IfAsked(Intent intent) {
        String path = intent == null ? null : intent.getStringExtra(EXTRA_RELAUNCH_X360);
        if (path == null) {
            return;
        }
        String title = intent.getStringExtra(EXTRA_RELAUNCH_X360_TITLE);
        intent.removeExtra(EXTRA_RELAUNCH_X360);
        // A moment for the old engine process to end.
        new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(() -> {
            if (!isFinishing() && !isDestroyed()) launchX360Game(path, title);
        }, 700);
    }

