    private String ps3FirmwareStatusText() {
        if (Ps3Activity.unsupportedReason(this) != null) {
            return "지원 안 됨";
        }
        return Ps3Activity.firmwareInstalled(this) ? "설치됨" : "설치 안 됨";
    }

    private void launchGame(File file) {
        if (MODE_PS3.equals(modeForFile(file))) {
            launchPs3Game(file);
            return;
        }
        if (MODE_X360.equals(modeForFile(file))) {
            launchX360Game(file.getAbsolutePath(), displayGameNameFor(file));
            markRecentlyPlayed(file);
            return;
        }
        if (MODE_PC98.equals(modeForFile(file)) && Pc98Flux.isFluxImage(file.getName().toLowerCase(Locale.ROOT))) {
            showPc98FluxPrompt(file);   // .hfe / .scp: converted first (0.0.320)
            return;
        }
        this.cloudAfterGame = true;
        if (!file.exists()) {
            showError("ROM 실행 실패: 가져온 ROM 파일이 없습니다");
            refreshLibrary();
            return;
        }
        String mode = modeForFile(file);
        if (isPs2DiscForPs1(file, mode)) {
            showError("이 디스크는 PS2 게임이에요 (CD로 나온 PS2 게임은 파일 모양이 PS1과 같아요).\n\nPS2 › 게임 추가에서 .cue / .bin을 고르면 .iso로 바꿔 넣어요. PS1 목록의 이 항목은 지워도 돼요.");
            return;
        }
        if ("neogeo".equals(mode) && !neoGeoBiosFile().exists()) {
            new AppDialog.Builder(this).setTitle("Neo Geo BIOS가 필요합니다").setMessage("neogeo.zip을 등록해야 Neo Geo 게임을 실행할 수 있어요.").setNegativeButton("취소", null).setPositiveButton("BIOS 등록", (dialog, which) -> openNeoGeoBiosPicker()).show();
            return;
        }
        if ("arcade".equals(mode) || "neogeo".equals(mode)) {
            launchArcadeGame(file);
            return;
        }
        startGameActivity(file);
    }

    private void startGameActivity(File file) {
        String mode = modeForFile(file);
        if (MODE_SS.equals(mode) && CORE_BEETLE_SS.equals(coreFor(file))) {
            syncSaturnRegionBios();
            if (!new File(systemDir(), SS_BIOS_JP).isFile() && !new File(systemDir(), SS_BIOS_US).isFile()) {
                showError("Beetle Saturn은 진짜 새턴 BIOS가 있어야 해요. 새턴 화면의 BIOS 칸에서 가져와 주세요.");
                showSaturnBiosSheet();
                return;
            }
        } else if (MODE_SS.equals(mode) && !saturnBiosFile().isFile() && settingsPrefs().getInt("ss_bios:" + saveBaseNameFor(file), 0) != 1) {
            showError("세가 새턴 게임은 새턴 BIOS가 필요해요. 새턴 화면의 BIOS 칸에서 가져와 주세요.");
            showSaturnBiosSheet();
            return;
        }
        if (MODE_MCD.equals(mode) && !file.getName().toLowerCase(Locale.US).endsWith(".32x") && mcdBiosRegions().isEmpty()) {
            showError("메가CD 게임은 CD BIOS가 필요해요. 메가CD 화면의 CD BIOS 칸에서 가져와 주세요.");
            showMcdBiosSheet();
            return;
        }
        if (MODE_PCE.equals(mode) && isPceCd(file) && !pceBiosFile().isFile()) {
            showError("CD-ROM² 게임은 System Card BIOS가 필요해요. PC엔진 화면의 CD BIOS 칸에서 가져와 주세요.");
            showPceBiosSheet();
            return;
        }
        if (MODE_GC.equals(mode)) {
            if (android.os.Build.VERSION.SDK_INT < 26) {
                showError("게임큐브·Wii는 안드로이드 8 이상에서만 실행할 수 있어요.");
                return;
            }
            if (!new File(getApplicationInfo().nativeLibraryDir, "libdolphin_libretro_android.so").isFile()) {
                showError("이 버전에는 게임큐브·Wii 엔진이 아직 들어 있지 않아요. 다음 업데이트를 기다려 주세요.");
                return;
            }
            // Dolphin's data (game settings, fonts, shaders) in <system>/dolphin-emu/Sys.
            if (!unpackSystemAsset("dolphin_sys.zip", new File(new File(systemDir(), "dolphin-emu"), "Sys"))) {
                showError("게임큐브·Wii 엔진 파일을 준비하지 못했어요. 저장 공간을 확인해 주세요.");
                return;
            }
        }
        if (MODE_VITA.equals(mode)) {
            if (!new File(getApplicationInfo().nativeLibraryDir, "libvita3k_libretro_android.so").isFile()) {
                showError("이 버전에는 PS Vita 엔진이 아직 들어 있지 않아요. 다음 업데이트를 기다려 주세요.");
                return;
            }
            if (!vitaFirmwareReady()) {
                showError("PS Vita 펌웨어(시스템 소프트웨어)가 필요해요. PS Vita 화면의 펌웨어 칸에서 PSP2UPDAT.PUP를 넣어 주세요.");
                showVitaFirmwareSheet();
                return;
            }
            if (VitaPatch.isFolderGame(file) && VitaPatch.folderContent(VitaPatch.folderOf(file)) == null) {
                showError("게임 폴더를 찾을 수 없어요: " + phonePath(VitaPatch.folderOf(file)) + "\n옮겼으면 ROM 추가 › 게임 폴더로 넣기로 새 자리를 다시 넣어 주세요.");
                return;
            }
            if (isVitaPkg(file) && !vitaLicensePresent(file)) {
                showVitaLicenseSheet(file);
                return;
            }
            if (isVitaPkg(file) && !vitaPkgInstalled(file)) {
                Toast.makeText(this, "PKG를 처음 설치하는 중이에요 (암호 풀기 · 몇 분). 화면이 잠시 멈춰 있어도 기다려 주세요.", Toast.LENGTH_LONG).show();
            } else if (VitaPatch.isFolderGame(file) && !vitaGameInstalled(vitaTitleId(file))) {
                Toast.makeText(this, "게임 폴더에서 처음 설치하는 중이에요 (몇 분). 화면이 잠시 멈춰 있어도 기다려 주세요.", Toast.LENGTH_LONG).show();
            } else {
                String vitaId = vitaTitleId(file);
                if (vitaId != null) {
                    int ready = 0;
                    for (File queued : vitaQueued(vitaId)) {
                        if (vitaLicensePresent(queued)) {
                            ready++;
                        }
                    }
                    if (ready > 0) {
                        Toast.makeText(this, "업데이트 · DLC PKG " + ready + "개를 설치하는 중이에요 (몇 분). 화면이 잠시 멈춰 있어도 기다려 주세요.", Toast.LENGTH_LONG).show();
                    }
                }
            }
        }
        if (MODE_WIIU.equals(mode)) {
            if (!cemuShipped()) {
                showError("이 버전에는 Wii U 엔진이 아직 들어 있지 않아요. 다음 업데이트를 기다려 주세요.");
                return;
            }
            String lower = file.getName().toLowerCase(Locale.US);
            if ((lower.endsWith(".wud") || lower.endsWith(".wux")) && !wiiuKeysFile().isFile() && !wiiuDiscKeyFile(file).isFile()) {
                showError("암호화된 디스크 이미지(.wud · .wux)는 키 파일이 필요해요. Wii U 화면의 키 파일 칸에서 keys.txt를 넣어 주세요.");
                showWiiuKeysSheet();
                return;
            }
            // Cemu's shared fonts (games draw their text with them) and per-game profiles.
            if (!unpackSystemAsset("cemu_resources.zip", new File(systemDir(), "Cemu"))) {
                showError("Wii U 시스템 파일을 준비하지 못했습니다. 저장 공간을 확인해 주세요.");
                return;
            }
        }
        if (MODE_DOS.equals(mode)) {
            if (!dosShipped()) {
                showError("이 버전에는 DOS 엔진이 아직 들어 있지 않아요. 다음 업데이트를 기다려 주세요.");
                return;
            }
            // First run of a game folder: which program starts it.
            if (DosSetup.isZip(file) && DosSetup.start(settingsPrefs(), saveBaseNameFor(file)) == null) {
                showDosExePicker(file, () -> startGameActivity(file));
                return;
            }
        }
        if ("arcade".equals(mode)) {
            syncArcadeBiosFiles();
        } else if ("neogeo".equals(mode)) {
            syncNeoGeoBiosInto(file.getParentFile());
        } else if (MODE_PSP.equals(mode) && !preparePspSystemFiles()) {
            showError("PSP 시스템 파일을 준비하지 못했습니다. 저장 공간을 확인해 주세요.");
            return;
        } else if (MODE_MSX.equals(mode) && !prepareMsxSystemFiles()) {
            showError("MSX 시스템 파일을 준비하지 못했습니다. 저장 공간을 확인해 주세요.");
            return;
        } else if (MODE_PC98.equals(mode) && !preparePc98SystemFiles(file)) {
            showError("PC-98 글꼴 파일을 준비하지 못했습니다. 저장 공간을 확인해 주세요.");
            return;
        } else if (CORE_PCSX2.equals(coreFor(file)) && !unpackSystemAsset("pcsx2_resources.zip", new File(new File(systemDir(), "pcsx2"), "resources"))) {
            showError("PCSX2 게임 데이터베이스를 준비하지 못했습니다. 저장 공간을 확인해 주세요.");
            return;
        }
        // 0.0.107 ran PCSX2 on the bridge's Vulkan device and left its shader and pipeline
        // caches built there; since then quick saves resumed to a black picture. Start them
        // over once (PCSX2 rebuilds them as it goes).
        if (CORE_PCSX2.equals(coreFor(file)) && !settingsPrefs().getBoolean("pcsx2_cache_reset_110", false)) {
            deleteRecursively(new File(new File(systemDir(), "pcsx2"), "cache"));
            settingsPrefs().edit().putBoolean("pcsx2_cache_reset_110", true).apply();
        }
        migrateSaveFileIfNeeded(file);
        markRecentlyPlayed(file);
        syncOverlays(file);
        Intent intent = new Intent(this, (Class<?>) GameActivity.class);
        intent.putExtra("com.example.minigba.ROM_PATH", file.getAbsolutePath());
        intent.putExtra("com.example.minigba.SAVE_BASE_NAME", saveBaseNameFor(file));
        intent.putExtra("com.example.minigba.CORE_ID", coreFor(file));
        intent.putExtra(GameActivity.EXTRA_MODE, mode);
        intent.putExtra(GameActivity.EXTRA_TITLE, displayGameNameFor(file));
        afterGameProcessEnds(() -> startActivity(intent));
    }

    // ---- DOS (DOSBox Pure) ----

    private boolean dosShipped() {
        return new File(getApplicationInfo().nativeLibraryDir, "libdosbox_pure_libretro_android.so").isFile();
    }

    private TextView dosButton(String text, int background, int color) {
        TextView button = new TextView(this);
        button.setText(text);
        button.setTextSize(15.0f);
        button.setTypeface(Typeface.DEFAULT_BOLD);
        button.setGravity(17);
        button.setTextColor(color);
        button.setBackground(rounded(background, dp(14)));
        return button;
    }

    // The program a DOS game starts with, picked once (then again from the game's sheet).
    private void showDosExePicker(final File file, final Runnable then) {
        final String save = saveBaseNameFor(file);
        final SharedPreferences prefs = settingsPrefs();
        final List<DosSetup.Exe> exes;
        try {
            exes = DosSetup.executables(file);
        } catch (IOException e) {
            showError(displayGameNameFor(file) + ": zip을 읽지 못했어요. 손상됐거나 zip이 아니에요.");
            return;
        }
        if (exes.isEmpty()) {
            // A CD or disk image inside, or nothing to run: DOSBox Pure's own start menu.
            prefs.edit().putString(DosSetup.key("exe", save), DosSetup.MENU).apply();
            then.run();
            return;
        }
        final int teal = Color.rgb(15, 118, 110);
        final String[] picked = {DosSetup.start(prefs, save)};
        final String[] helper = {DosSetup.helper(prefs, save)};
        if (picked[0] == null || DosSetup.MENU.equals(picked[0])) {
            picked[0] = exes.get(0).path;
        }
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        cardHeader(panel, RoundIconView.PLAY, Color.rgb(51, 65, 85), "실행할 파일 고르기", displayGameNameFor(file) + " · 실행 파일 " + exes.size() + "개");
        panel.addView(noteBox("DOS 게임은 실행 파일이 여러 개예요. 게임을 시작하는 파일을 한 번 고르면 다음부터 바로 시작해요. (게임 메뉴에서 바꿀 수 있어요)",
                Color.rgb(248, 250, 252), Color.rgb(51, 65, 85)), spaced(10));
        final LinearLayout list = new LinearLayout(this);
        list.setOrientation(1);
        final TextView warn = noteBox("", Color.rgb(254, 242, 242), Color.rgb(153, 27, 27));
        final Runnable[] render = new Runnable[1];
        render[0] = () -> {
            list.removeAllViews();
            for (final DosSetup.Exe exe : exes) {
                boolean on = exe.path.equals(picked[0]);
                boolean with = exe.path.equals(helper[0]);
                LinearLayout row = new LinearLayout(this);
                row.setGravity(16);
                row.setPadding(dp(11), dp(8), dp(11), dp(8));
                GradientDrawable bg = rounded(on ? Color.rgb(236, 254, 255) : Color.rgb(246, 247, 249), dp(12));
                bg.setStroke(dp(on ? 2 : 1), Theme.line(on ? teal : Color.rgb(229, 231, 235)));
                row.setBackground(bg);
                TextView kind = new TextView(this);
                String lower = exe.path.toLowerCase(Locale.ROOT);
                kind.setText(lower.substring(lower.lastIndexOf('.') + 1));
                kind.setTypeface(Typeface.MONOSPACE, Typeface.BOLD);
                kind.setTextSize(11.0f);
                kind.setTextColor(Theme.text(Color.rgb(51, 65, 85)));
                row.addView(kind, new LinearLayout.LayoutParams(dp(30), -2));
                LinearLayout texts = new LinearLayout(this);
                texts.setOrientation(1);
                TextView name = new TextView(this);
                name.setText(exe.path + (exe.recommended ? "  · 추천" : "") + (with ? "  · 함께 실행" : ""));
                name.setTypeface(Typeface.MONOSPACE, Typeface.BOLD);
                name.setTextSize(12.5f);
                name.setSingleLine(true);
                name.setEllipsize(android.text.TextUtils.TruncateAt.START);
                name.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
                texts.addView(name);
                TextView detail = new TextView(this);
                boolean renamed = exe.dos != null && !exe.dos.replace('\\', '/').equalsIgnoreCase(exe.path);
                detail.setText((exe.note.isEmpty() ? "" : exe.note + " · ") + formatSize(exe.size)
                        + (renamed ? "\nDOS 이름: C:\\" + DosSetup.shown(exe.dos) : ""));
                detail.setTextSize(10.5f);
                detail.setTextColor(Theme.text(Color.rgb(107, 114, 128)));
                texts.addView(detail);
                row.addView(texts, new LinearLayout.LayoutParams(0, -2, 1.0f));
                if (exe.helper) {
                    TextView chip = new TextView(this);
                    chip.setText(with ? "함께 실행 ✓" : "함께 실행");
                    chip.setTextSize(11.0f);
                    chip.setTypeface(Typeface.DEFAULT_BOLD);
                    chip.setTextColor(with ? Color.WHITE : Color.rgb(124, 58, 237));
                    chip.setPadding(dp(8), dp(5), dp(8), dp(5));
                    GradientDrawable chipBg = rounded(with ? Color.rgb(124, 58, 237) : Color.WHITE, dp(9));
                    chipBg.setStroke(dp(1), Color.rgb(124, 58, 237));
                    chip.setBackground(chipBg);
                    chip.setOnClickListener(view -> {
                        helper[0] = with ? "" : exe.path;
                        render[0].run();
                    });
                    row.addView(chip);
                }
                row.setOnClickListener(view -> {
                    picked[0] = exe.path;
                    if (exe.path.equals(helper[0])) {
                        helper[0] = "";
                    }
                    render[0].run();
                });
                list.addView(row, spaced(6));
            }
            boolean startable = true;
            for (DosSetup.Exe exe : exes) {
                if ((exe.path.equals(picked[0]) || exe.path.equals(helper[0])) && exe.dos == null) {
                    startable = false;
                }
            }
            warn.setText("이 파일의 DOS 이름을 정하지 못해 바로 시작할 수 없어요. 'DOS 화면으로'를 누르면 DOSBox의 시작 메뉴에서 고를 수 있어요.");
            warn.setVisibility(startable ? View.GONE : View.VISIBLE);
        };
        ScrollView scroll = new ScrollView(this);
        scroll.addView(list);
        int max = (int) (getResources().getDisplayMetrics().heightPixels * 0.45f);
        panel.addView(scroll, new LinearLayout.LayoutParams(-1, Math.min(max, exes.size() * dp(58) + dp(8))));
        panel.addView(warn, spaced(8));
        panel.addView(noteBox("💡 처음 하는 게임은 SETUP(설정)에서 사운드를 \"Sound Blaster\"로 맞춰 두면 소리가 나요.",
                Color.rgb(255, 251, 235), Color.rgb(146, 64, 14)), spaced(8));
        LinearLayout buttons = new LinearLayout(this);
        TextView menu = dosButton("DOS 화면으로", Color.rgb(241, 243, 245), Theme.text(Color.rgb(55, 65, 81)));
        menu.setOnClickListener(view -> {
            prefs.edit().putString(DosSetup.key("exe", save), DosSetup.MENU).apply();
            dialog.dismiss();
            then.run();
        });
        buttons.addView(menu, new LinearLayout.LayoutParams(0, dp(48), 1.0f));
        TextView go = dosButton("이 파일로 시작", teal, Color.WHITE);
        go.setOnClickListener(view -> {
            prefs.edit().putString(DosSetup.key("exe", save), picked[0]).putString(DosSetup.key("helper", save), helper[0]).apply();
            dialog.dismiss();
            then.run();
        });
        LinearLayout.LayoutParams goParams = new LinearLayout.LayoutParams(0, dp(48), 1.5f);
        goParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(go, goParams);
        panel.addView(buttons, spaced(12));
        render[0].run();
        dialog.show();
    }

    // Per game: CPU speed, sound card, memory, controls, mouse, the key row.
    private void showDosSettings(final File file) {
        final String save = saveBaseNameFor(file);
        final SharedPreferences prefs = settingsPrefs();
        final int slate = Color.rgb(51, 65, 85);
        final int[] cpu = {DosSetup.clamp(DosSetup.choice(prefs, "cpu", save), DosSetup.CPU_NAMES.length)};
        final int[] sound = {DosSetup.clamp(DosSetup.choice(prefs, "sound", save), DosSetup.SOUND_NAMES.length)};
        final int[] memory = {DosSetup.clamp(DosSetup.choice(prefs, "memory", save), DosSetup.MEMORY_NAMES.length)};
        final int[] control = {DosSetup.clamp(DosSetup.choice(prefs, "control", save), DosSetup.CONTROL_NAMES.length)};
        final int[] mouse = {DosSetup.clamp(DosSetup.choice(prefs, "mouse", save), DosSetup.MOUSE_NAMES.length)};
        final int[] midi = {DosSetup.midiChoice(prefs, save)};
        final int[] voodoo = {DosSetup.clamp(DosSetup.choice(prefs, "voodoo", save), DosSetup.VOODOO_NAMES.length)};
        String exe = DosSetup.start(prefs, save);
        final String confName = prefs.getString(DosSetup.key("conf", save), null);
        final boolean hasAutoexec = prefs.getString(DosSetup.key("autoexec", save), null) != null;
        final String[] startNames = hasAutoexec ? new String[]{"고른 실행 파일", "설정 파일의 실행 순서", "DOS 화면 (시작 메뉴)"} : new String[]{"고른 실행 파일", "DOS 화면 (시작 메뉴)"};
        final int menuIndex = startNames.length - 1;
        final int[] start = {DosSetup.MENU.equals(exe) ? menuIndex : hasAutoexec && DosSetup.CONF.equals(exe) ? 1 : 0};
        final int cpuBefore = cpu[0];
        final int soundBefore = sound[0];
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        cardHeader(panel, RoundIconView.GEAR, slate, "DOS 설정", displayGameNameFor(file) + " · 이 게임만");
        if (confName != null) {
            TextView badge = new TextView(this);
            badge.setText("⚙ 설정 파일에서 가져옴 · " + confName);
            badge.setTextSize(11.0f);
            badge.setTypeface(Typeface.DEFAULT_BOLD);
            badge.setTextColor(Color.rgb(15, 118, 110));
            badge.setPadding(dp(9), dp(4), dp(9), dp(4));
            GradientDrawable badgeBg = rounded(Color.rgb(236, 254, 255), dp(9));
            badgeBg.setStroke(dp(1), Color.rgb(15, 118, 110));
            badge.setBackground(badgeBg);
            LinearLayout.LayoutParams badgeParams = new LinearLayout.LayoutParams(-2, -2);
            badgeParams.setMargins(0, dp(8), 0, 0);
            panel.addView(badge, badgeParams);
        }
        addDosChoice(panel, "CPU 속도", DosSetup.CPU_NAMES, cpu);
        addDosChoice(panel, "사운드", DosSetup.SOUND_NAMES, sound);
        addDosChoice(panel, "MIDI 음악", DosSetup.MIDI_NAMES, midi);
        LinearLayout midiState = new LinearLayout(this);
        File sys = systemDir();
        midiState.addView(dosStateChip("General MIDI · " + (DosSetup.userSoundfont(sys).isFile() ? "내 사운드폰트" : "앱에 들어 있음 (TimGM6mb)"), true));
        midiState.addView(dosStateChip(DosSetup.hasMt32(sys) ? "MT-32 · 있음" : "MT-32 · ROM 없음", DosSetup.hasMt32(sys)));
        midiState.addView(dosStateChip(DosSetup.hasSc55(sys) ? "SC-55 · 있음" : "SC-55 · ROM 없음", DosSetup.hasSc55(sys)));
        android.widget.HorizontalScrollView midiScroll = new android.widget.HorizontalScrollView(this);
        midiScroll.setHorizontalScrollBarEnabled(false);
        midiScroll.addView(midiState);
        panel.addView(midiScroll, spaced(6));
        TextView midiSheet = dosButton("🎵 MIDI 음원 관리", Color.rgb(241, 245, 249), Theme.text(slate));
        midiSheet.setTextSize(12.5f);
        midiSheet.setOnClickListener(view -> {
            dialog.dismiss();
            showDosMidiSheet(() -> showDosSettings(file));
        });
        panel.addView(midiSheet, spaced(8));
        midiSheet.getLayoutParams().height = dp(40);
        addDosChoice(panel, "3D 가속 (3dfx Voodoo) · 실험적", DosSetup.VOODOO_NAMES, voodoo);
        panel.addView(noteBox("3dfx(Glide) 판이 있는 게임만 해당돼요 (툼레이더 · 카마게돈 · 디센트 II 등). 게임의 SETUP에서 그래픽을 3Dfx / Glide로 골라야 써요. "
                + "하드웨어는 폰 GPU로 그려서 빨라요(실험적 · 화면 전체가 GPU로 그려져요). GPU를 못 쓰면 엔진이 소프트웨어로 돌아가요. 다음 실행부터.",
                Color.rgb(245, 243, 255), Color.rgb(91, 33, 182)), spaced(6));
        addDosChoice(panel, "메모리", DosSetup.MEMORY_NAMES, memory);
        addDosChoice(panel, "조작 (처음 보이는 화면)", DosSetup.CONTROL_NAMES, control);
        addDosChoice(panel, "마우스", DosSetup.MOUSE_NAMES, mouse);
        addDosChoice(panel, "시작", startNames, start);
        panel.addView(sectionLabel("설정 파일 (dosbox.conf)"));
        LinearLayout confRow = new LinearLayout(this);
        if (hasAutoexec) {
            confRow.addView(dosChip("실행 순서 보기", Color.rgb(241, 245, 249), slate, () -> new AppDialog.Builder(this).setTitle("실행 순서 ([autoexec])")
                    .setMessage(DosSetup.shown(prefs.getString(DosSetup.key("autoexec", save), ""))).setPositiveButton("확인", null).show()));
        }
        confRow.addView(dosChip(confName == null ? "설정 파일 넣기" : "다른 conf 넣기", Color.rgb(241, 245, 249), slate, () -> {
            dialog.dismiss();
            pickDosConf(file);
        }));
        if (confName != null) {
            confRow.addView(dosChip("지우기", Color.rgb(254, 242, 242), Color.rgb(185, 28, 28), () -> {
                DosSetup.clearConf(prefs, save);
                dialog.dismiss();
                showDosSettings(file);
            }));
        }
        panel.addView(confRow, new LinearLayout.LayoutParams(-1, -2));
        panel.addView(sectionLabel("키 줄 (쉼표로 · \"키=이름\"으로 이름 붙이기)"));
        final android.widget.EditText keys = new android.widget.EditText(this);
        keys.setText(DosSetup.keyRow(prefs, save));
        keys.setTextSize(13.0f);
        keys.setSingleLine(true);
        panel.addView(keys, new LinearLayout.LayoutParams(-1, -2));
        panel.addView(sectionLabel("큰 버튼 (예: Ctrl=공격, Space=대화 넘기기)"));
        final android.widget.EditText big = new android.widget.EditText(this);
        big.setText(DosSetup.buttonRow(prefs, save));
        big.setTextSize(13.0f);
        big.setSingleLine(true);
        panel.addView(big, new LinearLayout.LayoutParams(-1, -2));
        TextView change = dosButton("실행 파일 바꾸기 · 지금: " + (exe == null || DosSetup.MENU.equals(exe) ? "시작 메뉴" : DosSetup.CONF.equals(exe) ? "설정 파일의 실행 순서" : exe), Color.rgb(241, 245, 249), Theme.text(slate));
        change.setTextSize(13.0f);
        change.setOnClickListener(view -> {
            dialog.dismiss();
            showDosExePicker(file, () -> showDosSettings(file));
        });
        panel.addView(change, spaced(10));
        change.getLayoutParams().height = dp(44);
        panel.addView(noteBox("세이브: 게임이 저장한 파일은 원본 zip을 건드리지 않고 따로 보관해요 (빠른 저장 · 세이브 내보내기 · 클라우드 백업도 돼요).\n"
                + "한글: 한글판 게임은 대부분 안에 한글 출력기가 들어 있어요. 따로 필요하면 실행 파일 고르기에서 \"함께 실행\"으로 넣어요.\n"
                + "게임패드를 연결하면 방향키 · 버튼이 DOSBox의 자동 연결로 키에 이어져요.\n"
                + "MIDI: 게임의 SETUP에서 음악 장치를 General MIDI(또는 MT-32 · \"Roland\")로 골라야 MIDI 소리가 나요. 효과음은 Sound Blaster 그대로.", Color.rgb(248, 250, 252), slate), spaced(10));
        LinearLayout buttons = new LinearLayout(this);
        TextView close = dosButton("닫기", Color.rgb(241, 243, 245), Theme.text(Color.rgb(55, 65, 81)));
        close.setOnClickListener(view -> dialog.dismiss());
        buttons.addView(close, new LinearLayout.LayoutParams(0, dp(48), 1.0f));
        TextView apply = dosButton("적용", Color.rgb(15, 118, 110), Color.WHITE);
        apply.setOnClickListener(view -> {
            SharedPreferences.Editor edit = prefs.edit()
                    .putInt(DosSetup.key("cpu", save), cpu[0])
                    .putInt(DosSetup.key("sound", save), sound[0])
                    .putInt(DosSetup.key("memory", save), memory[0])
                    .putInt(DosSetup.key("control", save), control[0])
                    .putInt(DosSetup.key("mouse", save), mouse[0])
                    .putInt(DosSetup.key("midi", save), midi[0])
                    .putInt(DosSetup.key("voodoo", save), voodoo[0])
                    .putString(DosSetup.key("keys", save), keys.getText().toString().trim().isEmpty() ? DosSetup.DEFAULT_KEYS : keys.getText().toString().trim())
                    .putString(DosSetup.key("buttons", save), big.getText().toString().trim().isEmpty() ? DosSetup.DEFAULT_BUTTONS : big.getText().toString().trim());
            if (cpu[0] != cpuBefore) {
                edit.remove(DosSetup.key("cycles", save));  // the chip, not the conf's exact speed
            }
            if (sound[0] != soundBefore) {
                edit.remove(DosSetup.key("sbtype", save));
            }
            String current = DosSetup.start(prefs, save);
            if (start[0] == menuIndex) {
                edit.putString(DosSetup.key("exe", save), DosSetup.MENU);
            } else if (hasAutoexec && start[0] == 1) {
                edit.putString(DosSetup.key("exe", save), DosSetup.CONF);
            } else if (DosSetup.MENU.equals(current) || DosSetup.CONF.equals(current)) {
                // Back to a start file: pick it on the next run.
                edit.remove(DosSetup.key("exe", save));
            }
            edit.apply();
            dialog.dismiss();
            Toast.makeText(this, "DOS 설정을 저장했어요 · 다음 실행부터 적용돼요", Toast.LENGTH_SHORT).show();
        });
        LinearLayout.LayoutParams applyParams = new LinearLayout.LayoutParams(0, dp(48), 1.5f);
        applyParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(apply, applyParams);
        panel.addView(buttons, spaced(12));
        dialog.show();
    }

