    private void buildDosPatched(File game, DosPatch.Plan plan, String newTitle, boolean useStart) {
        Toast.makeText(this, "한글판을 만드는 중…", Toast.LENGTH_SHORT).show();
        final String oldBase = saveBaseNameFor(game);
        final String oldExe = DosSetup.start(settingsPrefs(), oldBase);
        new Thread(() -> {
            File out = uniqueFile(romDirFor(MODE_DOS), sanitizeFileName(newTitle) + ".zip");
            String error = null;
            try {
                DosPatch.build(plan, out);
            } catch (IOException e) {
                error = "한글판을 만들지 못했어요: " + e.getMessage();
                out.delete();
            }
            // The start file in the new zip, as the exe picker names it.
            String start = null;
            if (error == null) {
                try {
                    String wanted = useStart && plan.startName != null ? plan.startName : oldExe == null ? null : oldExe.substring(oldExe.lastIndexOf('/') + 1);
                    String oldDir = oldExe == null ? null : oldExe.substring(0, oldExe.lastIndexOf('/') + 1);
                    if (wanted != null) {
                        for (DosSetup.Exe exe : DosSetup.executables(out)) {
                            String name = exe.path.substring(exe.path.lastIndexOf('/') + 1);
                            if (!name.equalsIgnoreCase(DosPatch.shown(wanted)) && !name.equalsIgnoreCase(wanted)) continue;
                            if (start == null || (oldDir != null && exe.path.startsWith(oldDir))) start = exe.path;
                        }
                    }
                } catch (IOException ignored) {
                }
            }
            final String why = error;
            final String startPath = start;
            runOnUiThread(() -> {
                if (why != null) {
                    showError(why);
                    return;
                }
                romPrefs().edit().putString("title:" + out.getName(), newTitle).putString("patched:" + out.getName(), game.getName()).apply();
                String newBase = saveBaseNameFor(out);
                // The DOS settings come along (CPU, sound, keys ...); the start file is the patch's.
                SharedPreferences prefs = settingsPrefs();
                SharedPreferences.Editor edit = prefs.edit();
                String suffix = ":" + oldBase;
                for (Map.Entry<String, ?> entry : prefs.getAll().entrySet()) {
                    String key = entry.getKey();
                    if (!key.startsWith("dos:") || !key.endsWith(suffix)) continue;
                    String copy = key.substring(0, key.length() - suffix.length()) + ":" + newBase;
                    Object value = entry.getValue();
                    if (value instanceof String) edit.putString(copy, (String) value);
                    else if (value instanceof Integer) edit.putInt(copy, (Integer) value);
                    else if (value instanceof Boolean) edit.putBoolean(copy, (Boolean) value);
                    else if (value instanceof Long) edit.putLong(copy, (Long) value);
                    else if (value instanceof Float) edit.putFloat(copy, (Float) value);
                }
                if (startPath != null) edit.putString(DosSetup.key("exe", newBase), startPath);
                edit.apply();
                romPrefs().edit().putString("source:" + out.getName(), game.getName()).apply();
                recordPatch(out, "한글패치 덮어쓰기", java.util.Arrays.asList("바뀐 파일 " + plan.replaced.size() + "개 · 새 파일 " + plan.added.size() + "개",
                        startPath == null ? "시작 파일: 처음 실행 때 고름" : "시작 파일: " + startPath));
                Toast.makeText(this, "\"" + newTitle + "\"을(를) 추가했어요 · 파일 " + plan.replaced.size() + "개를 바꾸고 " + plan.added.size() + "개를 더했어요", Toast.LENGTH_LONG).show();
                refreshLibrary();
            });
        }, "dos-patch-build").start();
    }

    // ---- dosbox.conf ----
    private static final int REQUEST_DOS_CONF = 1070;
    private static final String PREF_PENDING_DOS_CONF = "pending_dos_conf";

    private void pickDosConf(File game) {
        settingsPrefs().edit().putString(PREF_PENDING_DOS_CONF, game.getAbsolutePath()).apply();
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("*/*");
        try {
            startActivityForResult(intent, REQUEST_DOS_CONF);
        } catch (Exception e) {
            showError("파일을 고르는 화면을 열 수 없어요.");
        }
    }

    private void onDosConfPicked(Intent data) {
        String path = settingsPrefs().getString(PREF_PENDING_DOS_CONF, null);
        settingsPrefs().edit().remove(PREF_PENDING_DOS_CONF).apply();
        if (data == null || data.getData() == null || path == null || !new File(path).isFile()) {
            return;
        }
        Uri uri = data.getData();
        String name = displayNameFor(uri);
        String text;
        try (java.io.InputStream in = getContentResolver().openInputStream(uri)) {
            if (in == null) throw new IOException();
            java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int n;
            while ((n = in.read(buffer)) > 0 && bytes.size() < (1 << 20)) {
                bytes.write(buffer, 0, n);
            }
            text = new String(bytes.toByteArray(), StandardCharsets.ISO_8859_1);
        } catch (IOException e) {
            showError(name + ": 읽지 못했어요.");
            return;
        }
        showDosConfApply(new File(path), text, name, null);
    }

    // What the conf sets, to apply or leave.
    private void showDosConfApply(final File game, String text, final String confName, final Runnable after) {
        final DosSetup.Conf conf = DosSetup.parseConf(text, game, systemDir());
        if (conf.rows.isEmpty()) {
            showError(confName + ": DOSBox 설정 파일에서 쓸 값을 찾지 못했어요 (cycles · sbtype · memsize · [autoexec]).");
            if (after != null) after.run();
            return;
        }
        final int teal = Color.rgb(15, 118, 110);
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        cardHeader(panel, RoundIconView.GEAR, Color.rgb(51, 65, 85), "설정 파일을 찾았어요", displayGameNameFor(game) + " + " + confName);
        panel.addView(noteBox("함께 고른 " + confName + "(eXoDOS식 · 직접 만든 것)에서 이 게임에 맞춘 값을 읽었어요. 적용하면 DOS 설정과 실행 순서가 자동으로 채워져요.",
                Color.rgb(240, 253, 250), Color.rgb(17, 94, 89)), spaced(10));
        LinearLayout table = new LinearLayout(this);
        table.setOrientation(1);
        table.setPadding(dp(10), dp(4), dp(10), dp(4));
        table.setBackground(rounded(Color.rgb(248, 250, 252), dp(12)));
        for (String[] row : conf.rows) {
            LinearLayout line = new LinearLayout(this);
            line.setGravity(16);
            line.setPadding(0, dp(6), 0, dp(6));
            TextView key = new TextView(this);
            key.setText(row[0]);
            key.setTypeface(Typeface.MONOSPACE, Typeface.BOLD);
            key.setTextSize(10.5f);
            key.setTextColor(Theme.text(Color.rgb(100, 116, 139)));
            line.addView(key, new LinearLayout.LayoutParams(dp(120), -2));
            TextView value = new TextView(this);
            value.setText("→ " + row[1]);
            value.setTextSize(11.5f);
            value.setTypeface(Typeface.DEFAULT_BOLD);
            value.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
            line.addView(value, new LinearLayout.LayoutParams(0, -2, 1.0f));
            TextView state = new TextView(this);
            state.setText(row[2]);
            state.setTextSize(10.0f);
            state.setTextColor("적용".equals(row[2]) ? Color.rgb(22, 163, 74) : Color.rgb(180, 83, 9));
            line.addView(state);
            table.addView(line);
        }
        panel.addView(table, spaced(8));
        if (!conf.autoexec.isEmpty()) {
            panel.addView(sectionLabel("[autoexec] 실행 순서"));
            TextView code = new TextView(this);
            code.setText(DosSetup.shown(android.text.TextUtils.join("\n", conf.autoexec)));
            code.setTypeface(Typeface.MONOSPACE, Typeface.BOLD);
            code.setTextSize(11.0f);
            code.setTextColor(Color.rgb(167, 243, 208));
            code.setPadding(dp(11), dp(9), dp(11), dp(9));
            code.setBackground(rounded(Color.rgb(15, 23, 42), dp(12)));
            panel.addView(code, new LinearLayout.LayoutParams(-1, -2));
            TextView hint = new TextView(this);
            hint.setText("mount · imgmount 줄은 엔진이 zip을 C:로 이미 붙여서 뺐어요 (시디 이미지는 zip 안에 있어야 붙어요). 긴 폴더 이름의 cd는 DOS 이름으로 바꿨어요.");
            hint.setTextSize(10.5f);
            hint.setTextColor(Theme.text(Color.rgb(107, 114, 128)));
            panel.addView(hint, spaced(6));
        }
        LinearLayout buttons = new LinearLayout(this);
        TextView skip = dosButton("적용 안 함", Color.rgb(241, 243, 245), Theme.text(Color.rgb(55, 65, 81)));
        skip.setOnClickListener(view -> dialog.dismiss());
        buttons.addView(skip, new LinearLayout.LayoutParams(0, dp(48), 1.0f));
        TextView ok = dosButton("이대로 적용", teal, Color.WHITE);
        ok.setOnClickListener(view -> {
            DosSetup.applyConf(settingsPrefs(), saveBaseNameFor(game), conf, confName);
            dialog.dismiss();
            Toast.makeText(this, "설정 파일을 적용했어요 · 다음 실행부터", Toast.LENGTH_SHORT).show();
        });
        LinearLayout.LayoutParams okParams = new LinearLayout.LayoutParams(0, dp(48), 1.5f);
        okParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(ok, okParams);
        panel.addView(buttons, spaced(12));
        dialog.setOnDismissListener(d -> {
            if (after != null) after.run();
        });
        dialog.show();
    }

    private void addDosChoice(LinearLayout panel, String title, final String[] names, final int[] chosen) {
        panel.addView(sectionLabel(title));
        final android.widget.HorizontalScrollView scroll = new android.widget.HorizontalScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        final LinearLayout row = new LinearLayout(this);
        scroll.addView(row);
        final Runnable[] render = new Runnable[1];
        render[0] = () -> {
            row.removeAllViews();
            for (int k = 0; k < names.length; k++) {
                final int index = k;
                boolean on = chosen[0] == k;
                TextView chip = new TextView(this);
                chip.setText(names[k]);
                chip.setTextSize(12.0f);
                chip.setTypeface(Typeface.DEFAULT_BOLD);
                chip.setTextColor(on ? Color.WHITE : Theme.text(Color.rgb(100, 116, 139)));
                chip.setPadding(dp(11), dp(7), dp(11), dp(7));
                chip.setBackground(rounded(on ? Color.rgb(51, 65, 85) : Color.rgb(241, 245, 249), dp(10)));
                chip.setOnClickListener(view -> {
                    chosen[0] = index;
                    render[0].run();
                });
                LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-2, -2);
                params.setMargins(0, 0, dp(6), 0);
                row.addView(chip, params);
            }
        };
        render[0].run();
        panel.addView(scroll, new LinearLayout.LayoutParams(-1, -2));
    }

    // PPSSPP reads its fonts, VFPU tables and compat.ini from <system>/PPSSPP; they ship in
    // assets/ppsspp_system.zip and are unpacked again whenever the app version changes.
    private boolean preparePspSystemFiles() {
        return unpackSystemAsset("ppsspp_system.zip", new File(systemDir(), "PPSSPP"));
    }

    // blueMSX reads <system>/Machines (machine descriptions, C-BIOS) and <system>/Databases;
    // they ship in assets/msx_system.zip. BIOS ROMs the player added stay where they are.
    private boolean prepareMsxSystemFiles() {
        File system = systemDir();
        new File(new File(system, "Machines"), "Shared Roms").mkdirs();
        return unpackSystemAsset("msx_system.zip", system, new File(new File(system, "Machines"), ".mini_emulator_version"))
                // XBIOS (CC BY-NC-ND, unchanged): its blueMSX machines, licence and example disk.
                && unpackSystemAsset("msx_xbios.zip", system, new File(new File(system, "XBIOS"), ".mini_emulator_version"));
    }

    // ---- PC-98 (NP2kai, 0.0.317) ----
    // NP2kai reads <system>/np2kai: bios.rom, font.rom, sound.rom, itf.rom and the YM2608
    // rhythm samples (2608_*.wav) the player adds from their own machine; without them it
    // runs on its built-in BIOS. Its libretro build has no TrueType support, so the app ships
    // font.bmp made from the public-domain Shinonome fonts (assets/pc98_system.zip). NP2kai
    // reads font.bmp before font.rom, so ours goes away once the player adds a font.rom.
    private static final String[] PC98_SYSTEM_FILES = {"bios.rom", "font.rom", "sound.rom", "itf.rom", "ide.rom", "sasi.rom", "scsi.rom", "d8000.rom",
            "bios9821.rom", "2608_bd.wav", "2608_sd.wav", "2608_top.wav", "2608_hh.wav", "2608_tom.wav", "2608_rim.wav", "font.bmp"};
    private static final int REQUEST_IMPORT_PC98_BIOS = 1082;

    private File pc98SystemDir() {
        return new File(systemDir(), "np2kai");
    }

    private boolean pc98Has(String name) {
        File dir = pc98SystemDir();
        return new File(dir, name).isFile() || new File(dir, name.toUpperCase(Locale.ROOT)).isFile();
    }

    // ---- PC-98 fonts (0.0.323) ----
    // NP2kai reads <system>/np2kai/font.bmp before font.rom. The app keeps the fonts apart in
    // np2kai/fonts and puts the one for the game in font.bmp before each start:
    //   the game's own (picked for it, or a .bmp of the same name as the game next to it —
    //   Korean patches often come with one), else the player's font.bmp, else font.rom (no
    //   font.bmp), else the Shinonome font the app ships.
    private File pc98FontDir() {
        return new File(pc98SystemDir(), "fonts");
    }

    private File pc98UserFont() {
        return new File(pc98FontDir(), "_user.bmp");
    }

    private File pc98ShinonomeFont() {
        return new File(pc98FontDir(), "_shinonome.bmp");
    }

    // NP2kai takes a 2048x2048 1-bit BMP whose header gives the image size as 524288; tools
    // often leave that 0, so it is filled in. Null when the file is not such a font.
    static byte[] pc98FontBytes(byte[] bmp) {
        if (bmp.length < 62 || bmp[0] != 'B' || bmp[1] != 'M') return null;
        java.nio.ByteBuffer b = java.nio.ByteBuffer.wrap(bmp).order(java.nio.ByteOrder.LITTLE_ENDIAN);
        int offBits = b.getInt(10);
        int width = b.getInt(18);
        int height = Math.abs(b.getInt(22));
        int bpp = b.getShort(28) & 0xFFFF;
        if (width != 2048 || height != 2048 || bpp != 1 || offBits <= 0 || (long) offBits + 524288 > bmp.length) return null;
        byte[] out = bmp.clone();
        java.nio.ByteBuffer.wrap(out).order(java.nio.ByteOrder.LITTLE_ENDIAN).putInt(34, 524288);
        return out;
    }

    private static String pc98FontProblem(byte[] bmp) {
        if (bmp.length < 62 || bmp[0] != 'B' || bmp[1] != 'M') return "BMP 파일이 아니에요";
        java.nio.ByteBuffer b = java.nio.ByteBuffer.wrap(bmp).order(java.nio.ByteOrder.LITTLE_ENDIAN);
        return "PC-98 글꼴 BMP는 2048×2048 · 흑백(1비트)이어야 해요 (이 파일: " + b.getInt(18) + "×" + Math.abs(b.getInt(22)) + " · " + (b.getShort(28) & 0xFFFF) + "비트)";
    }

    // The game's own font: picked for it, or a .bmp named like the game (or one of its disks).
    private File pc98GameFont(File game) {
        String picked = settingsPrefs().getString("pc98_font:" + saveBaseNameFor(game), null);
        if (picked != null && new File(picked).isFile()) return new File(picked);
        List<File> names = new ArrayList<>();
        names.add(game);
        names.addAll(msxPlaylistDisks(game));
        for (File f : names) {
            String base = f.getName().replaceAll("\\.[^.]+$", "");
            for (String ext : new String[]{".bmp", ".BMP"}) {
                File bmp = new File(f.getParentFile(), base + ext);
                if (bmp.isFile()) return bmp;
            }
        }
        return null;
    }

    private boolean preparePc98SystemFiles(File game) {
        File dir = pc98SystemDir();
        File fonts = pc98FontDir();
        if (!fonts.isDirectory() && !fonts.mkdirs()) {
            return false;
        }
        File font = new File(dir, "font.bmp");
        File marker = new File(dir, ".mini_emulator_font");
        // Before 0.0.323 a player's own font.bmp sat there unmarked; it becomes their default.
        if (font.isFile() && !marker.isFile() && !pc98UserFont().isFile()) {
            font.renameTo(pc98UserFont());
        }
        File shinonome = pc98ShinonomeFont();
        if (!shinonome.isFile()) {
            try (ZipInputStream zip = new ZipInputStream(getAssets().open("pc98_system.zip"))) {
                ZipEntry entry;
                while ((entry = zip.getNextEntry()) != null) {
                    if (!"np2kai/font.bmp".equals(entry.getName())) continue;
                    File part = new File(fonts, "_shinonome.part");
                    try (FileOutputStream out = new FileOutputStream(part)) {
                        copy(zip, out);
                    }
                    if (!part.renameTo(shinonome)) return false;
                }
            } catch (IOException e) {
                return false;
            }
        }
        File own = game == null ? null : pc98GameFont(game);
        File chosen = own != null ? own : pc98UserFont().isFile() ? pc98UserFont() : pc98Has("font.rom") ? null : shinonome;
        if (chosen == null) {
            font.delete();
            marker.delete();
            return true;
        }
        String tag = chosen.getAbsolutePath() + "\n" + chosen.length() + "\n" + chosen.lastModified();
        if (font.isFile() && tag.equals(readSmallTextFull(marker))) {
            return true;
        }
        try {
            byte[] bytes = pc98FontBytes(java.nio.file.Files.readAllBytes(chosen.toPath()));
            if (bytes == null) {
                if (own == null) return false;
                showMessage("게임 글꼴 " + chosen.getName() + "을(를) 쓸 수 없어서 기본 글꼴로 켜요 (2048×2048 흑백 BMP가 아님)");
                bytes = java.nio.file.Files.readAllBytes(shinonome.toPath());
                tag = shinonome.getAbsolutePath();
            }
            File part = new File(dir, "font.bmp.part");
            try (FileOutputStream out = new FileOutputStream(part)) {
                out.write(bytes);
            }
            if (!part.renameTo(font)) return false;
            try (FileOutputStream out = new FileOutputStream(marker)) {
                out.write(tag.getBytes(StandardCharsets.UTF_8));
            }
        } catch (IOException | OutOfMemoryError e) {
            return false;
        }
        return true;
    }

    private static final int REQUEST_PC98_FONT = 1084;
    private static final String PREF_PENDING_PC98_FONT = "pending_pc98_font";

    private String pc98FontSummary(File game) {
        String picked = settingsPrefs().getString("pc98_font:" + saveBaseNameFor(game), null);
        File own = pc98GameFont(game);
        if (own == null) return "기본";
        return picked != null && own.getAbsolutePath().equals(picked) ? "이 게임 전용" : "같은 이름 " + own.getName();
    }

    private void showPc98FontDialog(File game) {
        File own = pc98GameFont(game);
        String key = "pc98_font:" + saveBaseNameFor(game);
        String picked = settingsPrefs().getString(key, null);
        String now = own == null ? "기본 글꼴 (" + (pc98UserFont().isFile() ? "내 font.bmp" : pc98Has("font.rom") ? "font.rom" : "동운 글꼴") + ")"
                : own.getName() + (picked != null && own.getAbsolutePath().equals(picked) ? " (이 게임 전용으로 넣은 것)" : " (게임 옆 같은 이름)");
        String message = "지금: " + now + "\n\n한글패치 중에는 한글 글자를 담은 글꼴 BMP(font.bmp)를 같이 쓰는 것이 있어요. 이 게임에만 그 글꼴을 쓰게 할 수 있어요.\n"
                + "· 게임 파일과 같은 이름의 .bmp(예: 게임.hdm 옆에 게임.bmp)를 PC-98 목록에 같이 넣어도 자동으로 써요.\n"
                + "· 글꼴은 2048×2048 흑백(1비트) BMP여야 해요 (NP2 · Neko Project 형식).";
        AppDialog.Builder builder = new AppDialog.Builder(this).setTitle("글꼴 · " + displayGameNameFor(game)).setMessage(message)
                .setPositiveButton("BMP 고르기", (d, w) -> {
                    settingsPrefs().edit().putString(PREF_PENDING_PC98_FONT, game.getAbsolutePath()).apply();
                    Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
                    intent.addCategory(Intent.CATEGORY_OPENABLE);
                    intent.setType("*/*");
                    try {
                        startActivityForResult(intent, REQUEST_PC98_FONT);
                    } catch (Exception e) {
                        showError("파일을 고르는 화면을 열 수 없어요.");
                    }
                });
        if (picked != null) {
            builder.setNegativeButton("기본 글꼴로", (d, w) -> {
                new File(picked).delete();
                settingsPrefs().edit().remove(key).apply();
                showMessage("이 게임은 기본 글꼴로 켜요" + (pc98GameFont(game) != null ? " (단, 게임 옆에 같은 이름 .bmp가 있으면 그것)" : ""));
            });
        } else {
            builder.setNegativeButton("닫기", null);
        }
        builder.show();
    }

    private void onPc98FontPicked(Intent data) {
        String path = settingsPrefs().getString(PREF_PENDING_PC98_FONT, null);
        settingsPrefs().edit().remove(PREF_PENDING_PC98_FONT).apply();
        if (data == null || data.getData() == null || path == null) return;
        File game = new File(path);
        try (InputStream in = getContentResolver().openInputStream(data.getData())) {
            if (in == null) throw new IOException("파일을 열 수 없어요");
            byte[] bmp = readLimited(in, 4 * 1024 * 1024);
            String error = setPc98GameFont(game, bmp);
            if (error != null) {
                showError(error);
                return;
            }
            showMessage("이 게임은 " + displayNameFor(data.getData()) + " 글꼴로 켜요. 게임을 다시 켜면 적용돼요.");
        } catch (IOException e) {
            showError("글꼴을 넣지 못했어요: " + e.getMessage());
        }
    }

    // Keeps bmp as this game's font; null, or why it can't be used.
    private String setPc98GameFont(File game, byte[] bmp) throws IOException {
        byte[] font = pc98FontBytes(bmp);
        if (font == null) return pc98FontProblem(bmp);
        File fonts = pc98FontDir();
        if (!fonts.isDirectory() && !fonts.mkdirs()) throw new IOException("글꼴 폴더를 만들 수 없어요");
        String name = "game_" + Integer.toHexString(saveBaseNameFor(game).hashCode()) + ".bmp";
        File target = new File(fonts, name);
        try (FileOutputStream out = new FileOutputStream(target)) {
            out.write(font);
        }
        settingsPrefs().edit().putString("pc98_font:" + saveBaseNameFor(game), target.getAbsolutePath()).apply();
        return null;
    }

    private String pc98BiosStatusText() {
        boolean bios = pc98Has("bios.rom");
        boolean font = pc98Has("font.rom") || pc98UserFont().isFile();
        if (bios && font) return "BIOS · 글꼴 있음";
        if (bios) return "BIOS 있음 · 동운 글꼴";
        return font ? "내장 BIOS · 내 글꼴" : "내장 BIOS · 동운 글꼴";
    }

    private void showPc98BiosSheet() {
        StringBuilder have = new StringBuilder();
        for (String name : PC98_SYSTEM_FILES) {
            if ("font.bmp".equals(name) ? pc98UserFont().isFile() : pc98Has(name)) {
                have.append(have.length() == 0 ? "" : " · ").append(name);
            }
        }
        String message = "PC-98은 바이오스 없이 NP2kai의 내장 호환 BIOS로 켜져요. 일본어 글자는 앱에 든 동운(東雲) 글꼴(퍼블릭 도메인)로 나와요.\n\n"
                + "직접 가진 PC-98에서 뽑은 파일이 있으면 넣을 수 있어요 (여러 개 한꺼번에, .zip도 돼요):\n"
                + "· bios.rom · itf.rom · sound.rom — 원래 BIOS (호환성 ↑)\n"
                + "· font.rom — 원래 글꼴 (넣으면 동운 글꼴 대신 이것)\n"
                + "· font.bmp — 모든 게임의 기본 글꼴로 (한 게임에만 쓸 글꼴은 그 게임을 길게 눌러 \"글꼴\")\n"
                + "· 2608_bd · sd · top · hh · tom · rim.wav — 86 보드의 드럼 소리\n\n"
                + "지금 있는 파일: " + (have.length() == 0 ? "없음" : have) + "\n"
                + "넣은 파일은 게임을 다시 켜면 적용돼요.";
        new AppDialog.Builder(this).setTitle("PC-98 BIOS · 글꼴").setMessage(message).setNegativeButton("닫기", null)
                .setPositiveButton("파일 넣기", (d, w) -> {
                    Intent intent = new Intent("android.intent.action.OPEN_DOCUMENT");
                    intent.addCategory("android.intent.category.OPENABLE");
                    intent.setType("*/*");
                    intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
                    startActivityForResult(intent, REQUEST_IMPORT_PC98_BIOS);
                }).show();
    }

    private static String pc98SystemName(String fileName) {
        String base = new File(fileName.replace('\\', '/')).getName().toLowerCase(Locale.ROOT);
        for (String name : PC98_SYSTEM_FILES) {
            if (name.equals(base)) return name;
        }
        return null;
    }

    private void importPc98Bios(Intent intent) {
        List<Uri> uris = new ArrayList<>();
        android.content.ClipData clip = intent.getClipData();
        for (int k = 0; clip != null && k < clip.getItemCount(); k++) {
            if (clip.getItemAt(k).getUri() != null) uris.add(clip.getItemAt(k).getUri());
        }
        if (clip == null && intent.getData() != null) uris.add(intent.getData());
        File dir = pc98SystemDir();
        if (!dir.isDirectory() && !dir.mkdirs()) {
            showError("시스템 폴더를 만들 수 없습니다");
            return;
        }
        List<String> added = new ArrayList<>();
        try {
            for (Uri uri : uris) {
                String name = displayNameFor(uri);
                try (InputStream in = getContentResolver().openInputStream(uri)) {
                    if (in == null) continue;
                    if (name.toLowerCase(Locale.ROOT).endsWith(".zip")) {
                        try (ZipInputStream zip = new ZipInputStream(in)) {
                            ZipEntry entry;
                            while ((entry = zip.getNextEntry()) != null) {
                                String known = entry.isDirectory() ? null : pc98SystemName(entry.getName());
                                if (known != null) {
                                    writePc98SystemFile(known, readLimited(zip, 8 * 1024 * 1024));
                                    added.add(known);
                                }
                            }
                        }
                    } else {
                        String known = pc98SystemName(name);
                        if (known != null) {
                            writePc98SystemFile(known, readLimited(in, 8 * 1024 * 1024));
                            added.add(known);
                        }
                    }
                }
            }
        } catch (IOException e) {
            showError("PC-98 파일 넣기 실패: " + e.getMessage());
            return;
        }
        if (added.isEmpty()) {
            showError("PC-98 바이오스 파일이 아니에요. bios.rom · font.rom · sound.rom · itf.rom · 2608_*.wav 이름의 파일을 골라 주세요.");
            return;
        }
        if (added.contains("font.bmp")) {
            // The player's default font (np2kai/fonts/_user.bmp), checked and its header filled in.
            File put = new File(dir, "font.bmp");
            try {
                byte[] bytes = java.nio.file.Files.readAllBytes(put.toPath());
                byte[] fixed = pc98FontBytes(bytes);
                put.delete();
                if (fixed == null) {
                    showError("font.bmp: " + pc98FontProblem(bytes));
                    added.remove("font.bmp");
                } else {
                    pc98FontDir().mkdirs();
                    try (FileOutputStream out = new FileOutputStream(pc98UserFont())) {
                        out.write(fixed);
                    }
                }
            } catch (IOException e) {
                added.remove("font.bmp");
            }
            new File(dir, ".mini_emulator_font").delete();
        }
        if (added.contains("font.rom")) {
            new File(dir, ".mini_emulator_font").delete();   // font.bmp is put again at the next start
        }
        showMessage("PC-98 파일 " + added.size() + "개를 넣었어요: " + android.text.TextUtils.join(", ", added) + "\n게임을 다시 켜면 적용돼요.");
        updateHomeStatusCards();
    }

    private void writePc98SystemFile(String name, byte[] data) throws IOException {
        if (data.length == 0) throw new IOException(name + " 파일이 비어 있어요");
        File target = new File(pc98SystemDir(), name);
        File part = new File(pc98SystemDir(), name + ".part");
        try (FileOutputStream out = new FileOutputStream(part)) {
            out.write(data);
        }
        if (!part.renameTo(target)) {
            part.delete();
            throw new IOException(name + "을(를) 저장하지 못했어요");
        }
    }

    // ---- PC-98 games on several floppies: "Name (Disk A).hdm", "Name (Disk 2).fdi" … ----
    // NP2kai takes no .m3u; it reads a .cmd whose first line is a command line naming the
    // images ("np2kai "A" "B" …"): the first two go into FDD1 and FDD2, and all of them are
    // its disk-control list. The app writes one per game; the lines after the first list the
    // disks for the app. A group the app made for a blank save disk ("(added)") is kept as it is.
    private static final java.util.regex.Pattern PC98_SPLIT_DISK = java.util.regex.Pattern.compile(
            "^(.*?)\\s*[(\\[]\\s*(?:disk|disc|디스크)\\s*([0-9]{1,2}|[a-z])(?:\\s*(?:of|/)\\s*\\w{1,2})?\\s*[)\\]](.*)\\.(?:hdm|fdi|d88|88d|d98|98d|xdf|dup|2hd|tfd|nfd|fdd)$",
            java.util.regex.Pattern.CASE_INSENSITIVE);
    static final String PC98_CMD_MARK = "# Mini Emulator: PC-98 disks";
    static final String PC98_CMD_ADDED = "# Mini Emulator: PC-98 disks (added)";
    private static final int PC98_CMD_MAX = 1000;   // NP2kai reads the first 1024 bytes of the line
    private java.util.Set<String> pc98Grouped;

    static int pc98DiskNumber(String label) {
        if (label == null || label.isEmpty()) return 0;
        char c = Character.toLowerCase(label.charAt(0));
        if (c >= 'a' && c <= 'z' && label.length() == 1) return c - 'a' + 1;
        try {
            return Integer.parseInt(label);
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    // The disks listed in a .cmd the app wrote (empty for anything else).
    static List<File> pc98CmdDisks(File cmd) {
        List<File> disks = new ArrayList<>();
        if (!cmd.isFile() || cmd.length() > 16384) return disks;
        try (java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(new FileInputStream(cmd), StandardCharsets.UTF_8))) {
            String first = in.readLine();
            String mark = in.readLine();
            if (first == null || mark == null || !mark.startsWith(PC98_CMD_MARK)) return disks;
            String line;
            while ((line = in.readLine()) != null) {
                line = line.trim();
                if (!line.isEmpty() && !line.startsWith("#")) disks.add(new File(cmd.getParentFile(), line));
            }
        } catch (IOException e) {
            disks.clear();
        }
        return disks;
    }

    private static boolean pc98CmdAdded(File cmd) {
        String text = readSmallTextFull(cmd);
        return text != null && text.contains(PC98_CMD_ADDED);
    }

    // The .cmd's text for these disks, or null when the command line would be too long.
    private static String pc98CmdText(List<File> disks, boolean added) {
        StringBuilder line = new StringBuilder("np2kai");
        for (File disk : disks) {
            if (disk.getAbsolutePath().indexOf('"') >= 0) return null;
            line.append(" \"").append(disk.getAbsolutePath()).append('"');
        }
        if (line.length() > PC98_CMD_MAX) return null;
        StringBuilder text = new StringBuilder(line).append('\n').append(added ? PC98_CMD_ADDED : PC98_CMD_MARK).append(" (").append(disks.size()).append(")\n");
        for (File disk : disks) text.append(disk.getName()).append('\n');
        return text.toString();
    }

    // Names of the files the app's .cmd groups in this folder hold (hidden from the list).
    private java.util.Set<String> pc98GroupedNames(File dir) {
        if (this.pc98Grouped == null) {
            java.util.Set<String> names = new java.util.HashSet<>();
            java.util.Set<String> games = new java.util.HashSet<>();
            File[] files = dir.listFiles();
            for (File file : files == null ? new File[0] : files) {
                if (file.getName().toLowerCase(Locale.ROOT).endsWith(".cmd")) {
                    for (File disk : pc98CmdDisks(file)) {
                        names.add(disk.getName());
                        // The disk a patched one stands in for stays out of the list too.
                        String from = romPrefs().getString("patched_from:" + disk.getName(), null);
                        for (int k = 0; from != null && k < 16 && names.add(from); k++) {
                            from = romPrefs().getString("patched_from:" + from, null);
                        }
                    }
                    if (!pc98CmdDisks(file).isEmpty() && !pc98CmdAdded(file)) {
                        games.add(file.getName().substring(0, file.getName().length() - 4));
                    }
                }
            }
            // Every disk of a game the app grouped (its other versions: originals of patched ones).
            for (File file : files == null ? new File[0] : files) {
                java.util.regex.Matcher m = PC98_SPLIT_DISK.matcher(splitSourceName(file));
                if (m.matches() && games.contains(pc98GameKey(splitSourceName(file), files))) {
                    names.add(file.getName());
                }
            }
            this.pc98Grouped = names;
        }
        return this.pc98Grouped;
    }

    private void groupPc98Disks() {
        File dir = romDirFor(MODE_PC98);
        File[] files = dir.listFiles();
        this.pc98Grouped = null;
        if (files == null) return;
        Map<String, Map<Integer, File>> games = new java.util.TreeMap<>();
        for (File file : files) {
            String source = splitSourceName(file);
            java.util.regex.Matcher m = PC98_SPLIT_DISK.matcher(source);
            if (!file.isFile() || !m.matches()) continue;
            String game = pc98GameKey(source, files);
            int number = pc98DiskNumber(m.group(2));
            if (game.isEmpty() || number <= 0) continue;
            Map<Integer, File> byNumber = games.get(game);
            if (byNumber == null) games.put(game, byNumber = new java.util.TreeMap<>());
            File had = byNumber.get(number);
            // A disk patched in the app takes its original's place; the newest of a kind.
            int rank = source.equals(file.getName()) ? 0 : 1;
            int hadRank = had == null ? -1 : splitSourceName(had).equals(had.getName()) ? 0 : 1;
            if (had == null || rank > hadRank || (rank == hadRank && file.lastModified() > had.lastModified())) {
                byNumber.put(number, file);
            }
        }
        java.util.Set<String> made = new java.util.HashSet<>();
        for (Map.Entry<String, Map<Integer, File>> entry : games.entrySet()) {
            List<File> disks = new ArrayList<>(entry.getValue().values());
            File cmd = new File(dir, entry.getKey() + ".cmd");
            if (disks.size() < 2 || disks.size() > 16 || (cmd.exists() && (pc98CmdDisks(cmd).isEmpty() || pc98CmdAdded(cmd)))) {
                continue;   // one disk, too many, the player's own .cmd, or a group with a save disk
            }
            String text = pc98CmdText(disks, false);
            if (text == null) continue;
            made.add(cmd.getName());
            String old = cmd.isFile() ? readSmallTextFull(cmd) : null;
            if (text.equals(old)) continue;
            if (old != null && !pc98Prefix(pc98CmdDisks(cmd), disks)) {
                // Other disks now (a patched one): the scene saved with the old ones would come
                // back with their contents, so the game starts afresh once.
                settingsPrefs().edit().putBoolean("fresh_start:" + saveBaseNameFor(cmd), true).apply();
            }
            try (FileOutputStream out = new FileOutputStream(cmd)) {
                out.write(text.getBytes(StandardCharsets.UTF_8));
            } catch (IOException ignored) {
            }
        }
        for (File file : files) {
            String name = file.getName();
            if (name.toLowerCase(Locale.ROOT).endsWith(".cmd") && !made.contains(name) && !pc98CmdAdded(file) && !pc98CmdDisks(file).isEmpty()) {
                file.delete();   // its disks belong elsewhere now (or are gone)
            }
        }
        this.pc98Grouped = null;
    }

    // The game a split disk belongs to: its name around the number ("Name (Disk 1) [v2]" →
    // "Name [v2]"); or, when the disks of that name carry different tags after the number (a
    // translated Disk 1 next to an untouched Disk 2), the name before it, as long as no disk
    // number comes twice under it.
    private String pc98GameKey(String source, File[] files) {
        java.util.regex.Matcher m = PC98_SPLIT_DISK.matcher(source);
        if (!m.matches()) return "";
        String base = m.group(1).trim().replaceAll("\\s+", " ");
        String full = (base + " " + m.group(3).trim()).trim().replaceAll("\\s+", " ");
        java.util.Set<Integer> numbers = new java.util.HashSet<>();
        java.util.Set<String> fulls = new java.util.HashSet<>();
        for (File other : files) {
            String name = splitSourceName(other);
            java.util.regex.Matcher o = PC98_SPLIT_DISK.matcher(name);
            if (!other.isFile() || !o.matches() || !o.group(1).trim().replaceAll("\\s+", " ").equalsIgnoreCase(base)) continue;
            if (!splitSourceName(other).equals(other.getName())) continue;   // a patched copy stands in for its original
            if (!numbers.add(pc98DiskNumber(o.group(2)))) return full;    // two disks with one number: versions apart
            fulls.add((base + " " + o.group(3).trim()).trim().replaceAll("\\s+", " "));
        }
        return fulls.size() > 1 ? base : full;
    }

    // Whether before's disks are the first ones of after (a disk added at the end).
    private static boolean pc98Prefix(List<File> before, List<File> after) {
        if (before.size() > after.size()) return false;
        for (int k = 0; k < before.size(); k++) {
            if (!before.get(k).getName().equals(after.get(k).getName())) return false;
        }
        return true;
    }

    // 빈 세이브 디스크: a 2HD floppy (1.2MB) for the games that ask for a user disk.
    // Formatted: an .hdm full of empty sectors (77 cylinders, 2 sides, 8 sectors of 1024 bytes),
    // ready for games that write their own data. Unformatted: a .d88 with no tracks yet, for
    // games that format the disk themselves.
    // The same choices as the game menu's (GameActivity.PC98_SOUND_VALUES), kept per game.
    private static final String[] PC98_SOUND_SHORT = {"86 (추천)", "26K", "86 + 스피크", "86 + 118", "118", "없음"};

    private void showPc98SoundPicker(File file) {
        String key = "pc98_sound:" + saveBaseNameFor(file);
        int now = settingsPrefs().getInt(key, 0);
        CharSequence[] names = {"PC-9801-86 (추천) — 90년대 게임 대부분", "PC-9801-26K — 80년대 게임", "86 + 스피크 보드", "86 + 118", "PC-9801-118", "없음"};
        new AppDialog.Builder(this).setTitle("사운드 보드").setSingleChoiceItems(names, now < 0 || now >= names.length ? 0 : now, (d, which) -> {
            settingsPrefs().edit().putInt(key, which).apply();
            d.dismiss();
            showMessage("사운드 보드: " + PC98_SOUND_SHORT[which] + " · 다음에 켤 때부터 적용돼요.");
        }).setNegativeButton("닫기", null).show();
    }

    // ---- PC-98 phase 2 (0.0.318): blank hard disk, file overwrite patches ----
    private static final int REQUEST_PC98_FILE_PATCH = 1083;
    private static final String PREF_PENDING_PC98_PATCH = "pending_pc98_patch";
    private static final int[] PC98_HDD_SIZES = {20, 40, 80, 120};

    private static boolean pc98IsHdd(File file) {
        String name = file.getName().toLowerCase(Locale.ROOT);
        return name.endsWith(".hdi") || name.endsWith(".thd") || name.endsWith(".nhd") || name.endsWith(".vhd") || name.endsWith(".hdn");
    }

    private static File pc98Hdd(List<File> disks) {
        for (File disk : disks) {
            if (pc98IsHdd(disk)) return disk;
        }
        return null;
    }

    // 빈 하드디스크: an .hdi of NP2kai's own IDE geometry (8 heads, 17 sectors of 512 bytes,
    // 15 cylinders a megabyte), all zero; the game's installer (or MS-DOS FORMAT) prepares it.
    // It goes into a group with the game's floppies.
    private void showPc98BlankHddDialog(File file) {
        List<File> disks = file.getName().toLowerCase(Locale.ROOT).endsWith(".cmd") ? pc98CmdDisks(file) : new ArrayList<>(java.util.Collections.singletonList(file));
        if (pc98Hdd(disks) != null || pc98IsHdd(file)) {
            showError("이 게임에는 이미 하드디스크가 있어요.");
            return;
        }
        CharSequence[] sizes = {"20MB", "40MB (추천)", "80MB", "120MB"};
        new AppDialog.Builder(this).setTitle("빈 하드디스크 만들기")
                .setMessage("하드디스크에 설치해서 하는 게임용이에요. 만든 하드디스크와 이 게임의 플로피를 한 묶음으로 켜면 설치 프로그램이 하드디스크에 깔아요. "
                        + "설치가 끝나면 길게 누르기 → \"하드디스크로만 켜기\".\n하드디스크는 포맷 전 상태예요 (설치 프로그램이나 MS-DOS FORMAT이 포맷).")
                .setItems(sizes, (d, which) -> createPc98BlankHdd(file, disks, PC98_HDD_SIZES[which])).setNegativeButton("취소", null).show();
    }

    private void createPc98BlankHdd(File file, List<File> disks, int megabytes) {
        File dir = file.getParentFile();
        String base = file.getName().replaceAll("\\.[^.]+$", "");
        File hdd = uniqueFile(dir, sanitizeFileName(base + " HDD") + ".hdi");
        int heads = 8;
        int sectors = 17;
        int sectorSize = 512;
        long cylinders = (long) megabytes * 15;
        long size = cylinders * heads * sectors * sectorSize;
        byte[] header = new byte[4096];
        int[] fields = {0, 0, 4096, (int) size, sectorSize, sectors, heads, (int) cylinders};
        for (int k = 0; k < fields.length; k++) {
            int v = fields[k];
            header[k * 4] = (byte) v;
            header[k * 4 + 1] = (byte) (v >> 8);
            header[k * 4 + 2] = (byte) (v >> 16);
            header[k * 4 + 3] = (byte) (v >> 24);
        }
        try (java.io.RandomAccessFile out = new java.io.RandomAccessFile(hdd, "rw")) {
            out.write(header);
            out.setLength(4096 + size);
        } catch (IOException e) {
            hdd.delete();
            showError("하드디스크를 만들지 못했어요: " + e.getMessage());
            return;
        }
        List<File> all = new ArrayList<>();
        all.add(hdd);
        all.addAll(disks);
        boolean group = file.getName().toLowerCase(Locale.ROOT).endsWith(".cmd");
        File cmd = group ? file : new File(dir, base + ".cmd");
        if (!group && cmd.exists()) {
            hdd.delete();
            showError("같은 이름의 .cmd 파일이 이미 있어요: " + cmd.getName());
            return;
        }
        String text = pc98CmdText(all, true);
        if (text == null) {
            hdd.delete();
            showError("디스크가 너무 많거나 이름이 길어서 묶을 수 없어요.");
            return;
        }
        try (FileOutputStream out = new FileOutputStream(cmd)) {
            out.write(text.getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            hdd.delete();
            showError("디스크 묶음을 쓰지 못했어요: " + e.getMessage());
            return;
        }
        refreshLibrary();
        showMessage(megabytes + "MB 하드디스크 " + hdd.getName() + "을(를) 만들어 이 게임과 묶었어요.\n켜서 설치 프로그램을 실행하세요. 설치가 끝나면 길게 누르기 → 하드디스크로만 켜기.");
    }

    private void pickPc98FilePatch(File game) {
        settingsPrefs().edit().putString(PREF_PENDING_PC98_PATCH, game.getAbsolutePath()).apply();
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("*/*");
        try {
            startActivityForResult(intent, REQUEST_PC98_FILE_PATCH);
        } catch (Exception e) {
            showError("파일을 고르는 화면을 열 수 없어요.");
        }
    }

    private volatile Pc98PatchFile pc98PatchFont;   // a font .bmp in the patch zip

    private static final class Pc98PatchFile {
        String name;
        byte[] data;
    }

    private static final class Pc98PatchHit {
        File disk;
        String inside;
        Pc98PatchFile file;
    }

    // The files of a patch .zip (names in UTF-8, else Shift-JIS as Japanese tools wrote them).
    private List<Pc98PatchFile> readPc98PatchZip(Uri uri) throws IOException {
        for (Charset charset : new Charset[]{StandardCharsets.UTF_8, Pc98Fat.SJIS}) {
            List<Pc98PatchFile> files = new ArrayList<>();
            long total = 0;
            try (InputStream in = getContentResolver().openInputStream(uri)) {
                if (in == null) throw new IOException("파일을 열 수 없어요");
                try (ZipInputStream zip = new ZipInputStream(new java.io.BufferedInputStream(in), charset)) {
                    ZipEntry entry;
                    while ((entry = zip.getNextEntry()) != null) {
                        if (entry.isDirectory()) continue;
                        Pc98PatchFile f = new Pc98PatchFile();
                        f.name = entry.getName();
                        f.data = readLimited(zip, 32 * 1024 * 1024);
                        total += f.data.length;
                        if (total > 256L * 1024 * 1024) throw new IOException("패치가 너무 커요");
                        files.add(f);
                    }
                }
                return files;
            } catch (IllegalArgumentException e) {
                // a name that is not UTF-8: read again as Shift-JIS
            }
        }
        throw new IOException("zip 안의 파일 이름을 읽지 못했어요");
    }

    private void onPc98FilePatchPicked(Intent data) {
        String path = settingsPrefs().getString(PREF_PENDING_PC98_PATCH, null);
        settingsPrefs().edit().remove(PREF_PENDING_PC98_PATCH).apply();
        if (data == null || data.getData() == null || path == null || !new File(path).isFile()) {
            return;
        }
        final File game = new File(path);
        final Uri uri = data.getData();
        final String patchName = displayNameFor(uri);
        if (!patchName.toLowerCase(Locale.ROOT).endsWith(".zip")) {
            showError("패치 파일을 담은 .zip을 골라 주세요. (xdelta · IPS 패치는 \"한글 패치 적용\"으로)");
            return;
        }
        Toast.makeText(this, "디스크 안의 파일을 찾는 중…", Toast.LENGTH_SHORT).show();
        this.pc98PatchFont = null;
        new Thread(() -> {
            String error = null;
            List<Pc98PatchHit> hits = new ArrayList<>();
            List<String> lines = new ArrayList<>();
            try {
                List<Pc98PatchFile> files = readPc98PatchZip(uri);
                List<File> disks = game.getName().toLowerCase(Locale.ROOT).endsWith(".cmd") ? pc98CmdDisks(game) : java.util.Collections.singletonList(game);
                boolean[] used = new boolean[files.size()];
                for (File disk : disks) {
                    try (Pc98Fat fs = Pc98Fat.open(disk, false)) {
                        List<Pc98Fat.Entry> entries = fs.files();
                        for (int k = 0; k < files.size(); k++) {
                            Pc98Fat.Entry e = Pc98Fat.match(entries, files.get(k).name);
                            if (e == null) continue;
                            Pc98PatchHit hit = new Pc98PatchHit();
                            hit.disk = disk;
                            hit.inside = e.path;
                            hit.file = files.get(k);
                            hits.add(hit);
                            used[k] = true;
                            lines.add("✓ " + e.path + " — " + pc98DiskShort(disk) + (e.size == hit.file.data.length ? " · 같은 크기" : " · " + formatSize(e.size) + " → " + formatSize(hit.file.data.length)));
                        }
                    } catch (IOException e) {
                        lines.add("· " + pc98DiskShort(disk) + ": " + e.getMessage());
                    }
                }
                for (int k = 0; k < files.size(); k++) {
                    if (used[k]) continue;
                    Pc98PatchFile f = files.get(k);
                    if (f.name.toLowerCase(Locale.ROOT).endsWith(".bmp") && pc98FontBytes(f.data) != null && this.pc98PatchFont == null) {
                        this.pc98PatchFont = f;
                        lines.add("✓ " + f.name + " — 한글 글꼴 · 이 게임의 글꼴로 써요");
                    } else {
                        lines.add("– " + f.name + " — 디스크에 없음 · 건너뜀");
                    }
                }
            } catch (IOException e) {
                error = "패치를 읽지 못했어요: " + e.getMessage();
            }
            final String why = error;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                if (why != null) {
                    showError(why);
                    return;
                }
                showPc98FilePatchPlan(game, patchName, hits, lines);
            });
        }, "pc98-patch-scan").start();
    }

    private static String pc98DiskShort(File disk) {
        java.util.regex.Matcher m = PC98_SPLIT_DISK.matcher(disk.getName());
        return m.matches() ? "Disk " + m.group(2).toUpperCase(Locale.ROOT) : pc98IsHdd(disk) ? "하드디스크" : disk.getName();
    }

    private void showPc98FilePatchPlan(File game, String patchName, List<Pc98PatchHit> hits, List<String> lines) {
        StringBuilder text = new StringBuilder("패치: " + patchName + "\n\n");
        for (String line : lines) text.append(line).append('\n');
        if (hits.isEmpty() && this.pc98PatchFont != null) {
            Pc98PatchFile font = this.pc98PatchFont;
            new AppDialog.Builder(this).setTitle("한글패치 · 글꼴만").setMessage(text.toString() + "\n디스크에서 바꿀 파일은 없고, 한글 글꼴이 들어 있어요. 이 게임의 글꼴로 쓸까요?")
                    .setNegativeButton("취소", null).setPositiveButton("글꼴로 쓰기", (d, w) -> {
                        try {
                            String error = setPc98GameFont(game, font.data);
                            if (error != null) showError(error);
                            else showMessage("이 게임은 " + font.name + " 글꼴로 켜요.");
                        } catch (IOException e) {
                            showError("글꼴을 넣지 못했어요: " + e.getMessage());
                        }
                    }).show();
            return;
        }
        if (hits.isEmpty()) {
            text.append("\n디스크 안에서 바꿀 파일을 찾지 못했어요. 패치 설명서가 이 방식(파일 덮어쓰기)인지, 디스크가 MS-DOS 형식인지 확인해 주세요.");
            new AppDialog.Builder(this).setTitle("한글패치 덮어쓰기").setMessage(text.toString()).setPositiveButton("닫기", null).show();
            return;
        }
        text.append("\n원래 디스크는 그대로 두고, 바뀐 디스크를 새로 만들어 묶음에서 그 디스크 자리를 바꿔요 (한 장짜리 게임은 새 게임으로 추가).");
        new AppDialog.Builder(this).setTitle("한글패치 덮어쓰기 · " + hits.size() + "개").setMessage(text.toString()).setNegativeButton("취소", null)
                .setPositiveButton(hits.size() + "개 덮어쓰기", (d, w) -> applyPc98FilePatch(game, patchName, hits)).show();
    }

    private void applyPc98FilePatch(File game, String patchName, List<Pc98PatchHit> hits) {
        Toast.makeText(this, "디스크에 덮어쓰는 중…", Toast.LENGTH_SHORT).show();
        new Thread(() -> {
            Map<File, List<Pc98PatchHit>> byDisk = new java.util.LinkedHashMap<>();
            for (Pc98PatchHit hit : hits) {
                List<Pc98PatchHit> list = byDisk.get(hit.disk);
                if (list == null) byDisk.put(hit.disk, list = new ArrayList<>());
                list.add(hit);
            }
            Map<File, File> made = new java.util.LinkedHashMap<>();
            String error = null;
            for (Map.Entry<File, List<Pc98PatchHit>> entry : byDisk.entrySet()) {
                File disk = entry.getKey();
                String name = disk.getName();
                int dot = name.lastIndexOf('.');
                File out = uniqueFile(disk.getParentFile(), name.substring(0, dot) + " (한글)" + name.substring(dot));
                try {
                    if (!copyFile(disk, out)) throw new IOException("디스크를 복사하지 못했어요 (저장 공간 확인)");
                    try (Pc98Fat fs = Pc98Fat.open(out, true)) {
                        Map<String, Pc98Fat.Entry> files = Pc98Fat.byPath(fs.files());
                        for (Pc98PatchHit hit : entry.getValue()) {
                            Pc98Fat.Entry e = files.get(hit.inside);
                            if (e == null) throw new IOException(hit.inside + "을(를) 다시 찾지 못했어요");
                            fs.replace(e, hit.file.data);
                        }
                    }
                    made.put(disk, out);
                } catch (IOException e) {
                    out.delete();
                    error = pc98DiskShort(disk) + ": " + e.getMessage();
                    break;
                }
            }
            if (error != null) {
                for (File f : made.values()) f.delete();
                made.clear();
            }
            final String why = error;
            runOnUiThread(() -> {
                if (why != null) {
                    showError("덮어쓰지 못했어요 — " + why);
                    return;
                }
                SharedPreferences.Editor edit = romPrefs().edit();
                for (Map.Entry<File, File> e : made.entrySet()) {
                    edit.putString("patched_from:" + e.getValue().getName(), e.getKey().getName())
                            .putString("patched:" + e.getValue().getName(), e.getKey().getName())
                            .putString("patched_note:" + e.getValue().getName(), "파일 덮어쓰기 · " + patchName);
                }
                boolean group = game.getName().toLowerCase(Locale.ROOT).endsWith(".cmd");
                if (!group) {
                    File out = made.get(game);
                    edit.putString("title:" + out.getName(), displayGameNameFor(game) + " (한글)");
                }
                edit.apply();
                List<String> log = new ArrayList<>();
                for (Pc98PatchHit hit : hits) log.add(hit.inside + " → " + pc98DiskShort(hit.disk));
                if (group && pc98CmdAdded(game)) {
                    // A group the app keeps as made: the patched disks take their places in it.
                    List<File> disks = pc98CmdDisks(game);
                    for (int k = 0; k < disks.size(); k++) {
                        File now = made.get(disks.get(k));
                        if (now != null) disks.set(k, now);
                    }
                    String text = pc98CmdText(disks, true);
                    if (text != null) {
                        try (FileOutputStream out = new FileOutputStream(game)) {
                            out.write(text.getBytes(StandardCharsets.UTF_8));
                        } catch (IOException ignored) {
                        }
                        settingsPrefs().edit().putBoolean("fresh_start:" + saveBaseNameFor(game), true).apply();
                    }
                }
                for (File out : made.values()) recordPatch(out, "파일 덮어쓰기 (" + patchName + ")", log);
                Pc98PatchFile font = this.pc98PatchFont;
                if (font != null) {
                    try {
                        setPc98GameFont(group ? game : made.get(game), font.data);
                    } catch (IOException ignored) {
                    }
                }
                refreshLibrary();
                showMessage("파일 " + hits.size() + "개를 디스크 " + made.size() + "장에 덮어썼어요."
                        + (group ? "\n묶음이 바뀐 디스크로 켜져요 (빠른 저장은 처음부터)." : "\n\"" + displayGameNameFor(game) + " (한글)\"로 추가했어요."));
            });
        }, "pc98-patch").start();
    }

    // ---- .hfe / .scp: converted to a sector image (0.0.320) ----
    private boolean pc98FluxShowing;
    private final java.util.Set<String> pc98FluxDeclined = new java.util.HashSet<>();

    // New .hfe / .scp files in the PC-98 list: asked about one at a time.
    private void promptPc98FluxImports() {
        if (this.pc98FluxShowing || !MODE_PC98.equals(this.currentMode) || isFinishing()) return;
        File[] files = romDirFor(MODE_PC98).listFiles();
        if (files == null) return;
        java.util.Arrays.sort(files);
        for (File file : files) {
            if (!Pc98Flux.isFluxImage(file.getName().toLowerCase(Locale.ROOT)) || this.pc98FluxDeclined.contains(file.getName())) continue;
            if (romPrefs().getString("pc98_flux_done:" + file.getName(), null) != null) continue;
            showPc98FluxPrompt(file);
            return;
        }
    }

    private TextView pc98Option(String title, String note) {
        TextView view = new TextView(this);
        view.setText(android.text.Html.fromHtml("<b>" + android.text.TextUtils.htmlEncode(title) + "</b><br><small>" + android.text.TextUtils.htmlEncode(note) + "</small>", 0));
        view.setTextSize(13f);
        view.setTextColor(Theme.text(Color.rgb(31, 41, 51)));
        view.setPadding(dp(12), dp(9), dp(12), dp(9));
        return view;
    }

    private void markPc98Option(TextView view, boolean on) {
        int teal = MODE_COLORS[modeIndex(MODE_PC98)];
        android.graphics.drawable.GradientDrawable shape = new android.graphics.drawable.GradientDrawable();
        shape.setCornerRadius(dp(12));
        shape.setColor(Theme.bg(on ? Color.rgb(240, 253, 250) : Color.rgb(246, 247, 249)));
        if (on) shape.setStroke(dp(2), teal);
        view.setBackground(shape);
    }

    private void showPc98FluxPrompt(File file) {
        Pc98Flux.Info info;
        try {
            info = Pc98Flux.probe(file);
        } catch (IOException e) {
            this.pc98FluxDeclined.add(file.getName());
            showError(file.getName() + ": " + e.getMessage());
            return;
        }
        this.pc98FluxShowing = true;
        int teal = MODE_COLORS[modeIndex(MODE_PC98)];
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        cardHeader(panel, RoundIconView.IMPORT, teal, "변환해서 넣을까요?", file.getName() + " · " + formatSize(file.length()));
        panel.addView(noteBox(".hfe(HxC) · .scp(SuperCard Pro)는 디스크의 자기 신호를 그대로 담은 파일이라 엔진이 바로 못 읽어요. 앱이 섹터를 읽어 내서 엔진이 읽는 디스크로 바꿔 넣어요.",
                Color.rgb(240, 253, 250), Color.rgb(17, 94, 89)), spaced(10));
        panel.addView(noteBox("형식: " + info.format + "\n디스크: " + info.cylinders + "트랙 × " + info.heads + "면" + (info.rpm > 0 ? " · " + info.rpm + "rpm" : ""),
                Color.rgb(246, 247, 249), Color.rgb(55, 65, 81)), spaced(8));
        final boolean[] d88 = {true};
        final boolean[] keep = {true};
        TextView optD88 = pc98Option(".d88로 (추천)", "섹터 번호 · 크기가 특이한 트랙도 그대로 · 삭제 표시 · 오류 표시 유지");
        TextView optHdm = pc98Option(".hdm으로", "보통 2HD 디스크만 · 모든 트랙이 같은 모양일 때 (아니면 .d88로)");
        TextView optKeep = pc98Option("원본도 남겨 두기: 켬", "다시 변환할 수 있게 · 끄면 변환 후 원본을 지워요 (🔗 연결이면 연결만)");
        Runnable paint = () -> {
            markPc98Option(optD88, d88[0]);
            markPc98Option(optHdm, !d88[0]);
            markPc98Option(optKeep, keep[0]);
            optKeep.setText(android.text.Html.fromHtml("<b>원본도 남겨 두기: " + (keep[0] ? "켬" : "끔") + "</b><br><small>다시 변환할 수 있게 · 끄면 변환 후 원본을 지워요 (🔗 연결이면 연결만)</small>", 0));
        };
        optD88.setOnClickListener(v -> { d88[0] = true; paint.run(); });
        optHdm.setOnClickListener(v -> { d88[0] = false; paint.run(); });
        optKeep.setOnClickListener(v -> { keep[0] = !keep[0]; paint.run(); });
        paint.run();
        panel.addView(optD88, spaced(10));
        panel.addView(optHdm, spaced(6));
        panel.addView(optKeep, spaced(10));
        LinearLayout buttons = new LinearLayout(this);
        TextView cancel = sheetButton("취소", Color.rgb(241, 242, 244), Color.rgb(75, 85, 99));
        cancel.setOnClickListener(v -> {
            this.pc98FluxDeclined.add(file.getName());
            dialog.dismiss();
        });
        TextView go = sheetButton("변환해서 넣기", teal, Color.WHITE);
        go.setOnClickListener(v -> {
            dialog.dismiss();
            convertPc98Flux(file, d88[0], keep[0], null);
        });
        buttons.addView(cancel, new LinearLayout.LayoutParams(0, dp(48), 1f));
        LinearLayout.LayoutParams goParams = new LinearLayout.LayoutParams(0, dp(48), 1.6f);
        goParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(go, goParams);
        panel.addView(buttons, spaced(14));
        dialog.setOnDismissListener(d -> {
            if (!this.pc98FluxConverting) this.pc98FluxShowing = false;
        });
        dialog.show();
    }

    private boolean pc98FluxConverting;

    // The tracks as small squares: read, odd, unreadable, not yet.
    private static final class TrackGridView extends View {
        int[] states = new int[0];
        private final android.graphics.Paint paint = new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);

        TrackGridView(android.content.Context context) {
            super(context);
        }

        @Override
        protected void onDraw(android.graphics.Canvas canvas) {
            int columns = 22;
            float gap = getResources().getDisplayMetrics().density * 2;
            float size = (getWidth() - gap * (columns - 1)) / columns;
            for (int i = 0; i < states.length; i++) {
                int s = states[i];
                paint.setColor(s == Pc98Flux.TRACK_OK ? Color.rgb(20, 184, 166) : s == Pc98Flux.TRACK_ODD ? Color.rgb(245, 158, 11)
                        : s == Pc98Flux.TRACK_ERROR ? Color.rgb(225, 29, 72) : s == Pc98Flux.TRACK_EMPTY ? Color.rgb(203, 213, 225) : Color.rgb(229, 231, 235));
                float x = (i % columns) * (size + gap);
                float y = (i / columns) * (size + gap);
                canvas.drawRoundRect(x, y, x + size, y + size, size / 5, size / 5, paint);
            }
        }

        @Override
        protected void onMeasure(int widthSpec, int heightSpec) {
            int width = MeasureSpec.getSize(widthSpec);
            int columns = 22;
            float gap = getResources().getDisplayMetrics().density * 2;
            float size = (width - gap * (columns - 1)) / columns;
            int rows = Math.max(1, (states.length + columns - 1) / columns);
            setMeasuredDimension(width, (int) (rows * (size + gap)));
        }
    }

    // replace: the disk an earlier conversion made (다시 변환), or null.
    private void convertPc98Flux(File source, boolean d88, boolean keep, File replace) {
        int teal = MODE_COLORS[modeIndex(MODE_PC98)];
        this.pc98FluxConverting = true;
        this.pc98FluxShowing = true;
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        dialog.setCancelable(false);
        cardHeader(panel, RoundIconView.SWAP, teal, "변환하는 중…", source.getName() + " → " + (d88 ? ".d88" : ".hdm"));
        TextView status = new TextView(this);
        status.setTextSize(12f);
        status.setTextColor(Theme.text(Color.rgb(51, 65, 85)));
        status.setText("트랙을 읽는 중…");
        panel.addView(status, spaced(10));
        TrackGridView grid = new TrackGridView(this);
        panel.addView(grid, spaced(8));
        panel.addView(noteBox(source.getName().toLowerCase(Locale.ROOT).endsWith(".scp")
                        ? ".scp는 한 트랙을 여러 바퀴 떠 놓아서, 바퀴마다 읽어 보고 오류 검사(CRC)가 맞는 쪽을 골라요. 몇 초 ~ 수십 초 걸려요."
                        : "트랙마다 섹터 표시(A1 A1 A1)를 찾아 섹터를 읽어 내요.",
                Color.rgb(248, 250, 252), Color.rgb(71, 85, 105)), spaced(10));
        dialog.show();
        new Thread(() -> {
            Pc98Flux.Result result = null;
            String error = null;
            File out = null;
            try {
                result = Pc98Flux.read(source, (index, count, state) -> runOnUiThread(() -> {
                    if (grid.states.length != count) {
                        grid.states = new int[count];
                        grid.requestLayout();
                    }
                    grid.states[index] = state;
                    status.setText("트랙 " + (index + 1) + " / " + count);
                    grid.invalidate();
                }));
                String base = source.getName().replaceAll("\\.[^.]+$", "");
                File dir = source.getParentFile();
                out = replace != null ? new File(dir, replace.getName().replaceAll("\\.[^.]+$", "") + (d88 ? ".d88" : ".hdm"))
                        : uniqueFile(dir, base + (d88 ? ".d88" : ".hdm"));
                File part = new File(dir, out.getName() + ".part");
                if (d88) {
                    Pc98Flux.writeD88(result, part, base);
                } else {
                    Pc98Flux.writeHdm(result, part);
                }
                if (out.exists() && !out.delete()) throw new IOException("이전 디스크를 지우지 못했어요");
                if (!part.renameTo(out)) throw new IOException("디스크를 저장하지 못했어요");
            } catch (IOException | OutOfMemoryError e) {
                error = e instanceof OutOfMemoryError ? "메모리가 부족해요" : e.getMessage();
            }
            final Pc98Flux.Result done = result;
            final String why = error;
            final File made = out;
            runOnUiThread(() -> {
                this.pc98FluxConverting = false;
                this.pc98FluxShowing = false;
                dialog.dismiss();
                if (isFinishing() || isDestroyed()) return;
                if (why != null) {
                    this.pc98FluxDeclined.add(source.getName());
                    showError("변환하지 못했어요 — " + why);
                    return;
                }
                if (replace != null && !replace.getName().equals(made.getName())) {
                    // 다시 변환 into the other format: the old disk goes, and a group the app keeps
                    // as made points at the new one.
                    replace.delete();
                    File[] cmds = source.getParentFile().listFiles((d, n) -> n.toLowerCase(Locale.ROOT).endsWith(".cmd"));
                    for (File cmd : cmds == null ? new File[0] : cmds) {
                        List<File> disks = pc98CmdDisks(cmd);
                        if (!pc98CmdAdded(cmd)) continue;
                        boolean changed = false;
                        for (int k = 0; k < disks.size(); k++) {
                            if (disks.get(k).getName().equals(replace.getName())) {
                                disks.set(k, made);
                                changed = true;
                            }
                        }
                        String text = changed ? pc98CmdText(disks, true) : null;
                        if (text != null) {
                            try (FileOutputStream o = new FileOutputStream(cmd)) {
                                o.write(text.getBytes(StandardCharsets.UTF_8));
                            } catch (IOException ignored) {
                            }
                        }
                    }
                    romPrefs().edit().remove("pc98_flux:" + replace.getName()).apply();
                }
                String record = source.getName() + "\n" + done.info.format + "\n" + Pc98Flux.summaryLine(done) + "\n" + System.currentTimeMillis()
                        + "\n" + android.text.TextUtils.join("\n", done.notes.subList(0, Math.min(40, done.notes.size())));
                romPrefs().edit().putString("pc98_flux:" + made.getName(), record).putString("pc98_flux_done:" + source.getName(), made.getName()).apply();
                if (!keep) {
                    source.delete();
                }
                refreshLibrary();
                showPc98FluxResult(made, done);
            });
        }, "pc98-flux").start();
    }

    private void showPc98FluxResult(File made, Pc98Flux.Result r) {
        int teal = MODE_COLORS[modeIndex(MODE_PC98)];
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        cardHeader(panel, RoundIconView.STAR, teal, "변환 끝", made.getName() + " · " + formatSize(made.length()));
        int used = r.ok + r.odd + r.errors;
        panel.addView(noteBox("정상 트랙 " + r.ok + " / " + used + "\n특이한 트랙 " + r.odd + "개\n읽기 오류 트랙 " + r.errors + "개 (섹터 " + r.badSectors + "개)",
                Color.rgb(246, 247, 249), Color.rgb(31, 41, 51)), spaced(10));
        if (r.odd > 0) {
            panel.addView(noteBox("특이한 트랙은 복사 방지일 수 있어요. .d88은 그 모양을 그대로 담지만, 엔진(NP2kai)이 흉내 내지 못하는 보호도 있어서 게임이 \"디스크가 다르다\"며 멈출 수 있어요.",
                    Color.rgb(255, 251, 235), Color.rgb(146, 64, 14)), spaced(8));
        }
        if (r.errors > 0) {
            panel.addView(noteBox("읽기 오류는 원래 디스크가 상했거나 덤프가 불완전한 곳이에요. 그 부분을 읽는 장면에서 멈출 수 있어요 — 다른 덤프가 있으면 그걸로.",
                    Color.rgb(255, 241, 242), Color.rgb(159, 18, 57)), spaced(8));
        }
        LinearLayout buttons = new LinearLayout(this);
        TextView log = sheetButton("기록 보기", Color.rgb(241, 242, 244), Color.rgb(75, 85, 99));
        log.setOnClickListener(v -> showPc98FluxRecord(made));
        TextView run = sheetButton("실행", teal, Color.WHITE);
        run.setOnClickListener(v -> {
            dialog.dismiss();
            File group = pc98GroupOf(made);
            launchGame(group != null ? group : made);
        });
        buttons.addView(log, new LinearLayout.LayoutParams(0, dp(48), 1f));
        LinearLayout.LayoutParams runParams = new LinearLayout.LayoutParams(0, dp(48), 1.4f);
        runParams.setMargins(dp(10), 0, 0, 0);
        buttons.addView(run, runParams);
        panel.addView(buttons, spaced(14));
        dialog.setOnDismissListener(d -> this.romList.post(this::promptPc98FluxImports));
        dialog.show();
    }

    // The app's group a disk is in, if any.
    private File pc98GroupOf(File disk) {
        File[] cmds = disk.getParentFile().listFiles((d, n) -> n.toLowerCase(Locale.ROOT).endsWith(".cmd"));
        for (File cmd : cmds == null ? new File[0] : cmds) {
            for (File f : pc98CmdDisks(cmd)) {
                if (f.getName().equals(disk.getName())) return cmd;
            }
        }
        return null;
    }

    private void showPc98FluxRecord(File made) {
        String record = romPrefs().getString("pc98_flux:" + made.getName(), null);
        if (record == null) return;
        String[] lines = record.split("\n");
        StringBuilder text = new StringBuilder();
        text.append("원본: ").append(lines[0]).append('\n');
        if (lines.length > 1) text.append("형식: ").append(lines[1]).append('\n');
        if (lines.length > 2) text.append(lines[2]).append('\n');
        if (lines.length > 3) {
            try {
                text.append("변환한 때: ").append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.KOREA).format(new java.util.Date(Long.parseLong(lines[3])))).append('\n');
            } catch (NumberFormatException ignored) {
            }
        }
        for (int k = 4; k < lines.length; k++) text.append("· ").append(lines[k]).append('\n');
        new AppDialog.Builder(this).setTitle("변환 기록 · " + made.getName()).setMessage(text.toString().trim()).setPositiveButton("닫기", null).show();
    }

    // Long press: the disks this game was converted into, and 다시 변환 while the source is there.
    private void addPc98FluxRecordRows(LinearLayout panel, Dialog menu, List<File> disks) {
        for (File disk : disks) {
            String record = romPrefs().getString("pc98_flux:" + disk.getName(), null);
            if (record == null) continue;
            String[] lines = record.split("\n");
            File source = new File(disk.getParentFile(), lines[0]);
            String summary = lines.length > 2 ? lines[2] : "";
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, dp(52));
            params.setMargins(0, dp(8), 0, 0);
            panel.addView(createMenuActionRow(menu, RoundIconView.SWAP, MODE_COLORS[modeIndex(MODE_PC98)],
                    pc98DiskShort(disk) + " · " + lines[0] + " → " + disk.getName().substring(disk.getName().lastIndexOf('.')) + " · " + summary
                            + (source.isFile() ? " (누르면 다시 변환)" : " (원본 없음 · 기록만)"),
                    () -> {
                        if (!source.isFile()) {
                            showPc98FluxRecord(disk);
                            return;
                        }
                        boolean nowD88 = disk.getName().toLowerCase(Locale.ROOT).endsWith(".d88");
                        CharSequence[] kinds = {".d88로 다시 변환" + (nowD88 ? " (지금과 같음)" : ""), ".hdm으로 다시 변환" + (nowD88 ? "" : " (지금과 같음)"), "기록만 보기"};
                        new AppDialog.Builder(this).setTitle("다시 변환 · " + disk.getName())
                                .setMessage("게임이 이 디스크에 저장한 내용은 사라져요 (원본 " + lines[0] + "에서 새로 만들어요).")
                                .setItems(kinds, (d, which) -> {
                                    if (which == 2) {
                                        showPc98FluxRecord(disk);
                                    } else {
                                        convertPc98Flux(source, which == 0, true, disk);
                                    }
                                }).setNegativeButton("취소", null).show();
                    }), params);
        }
    }

    private void showPc98BlankDiskDialog(File file) {
        CharSequence[] kinds = {"포맷된 디스크 (.hdm) — 대부분의 게임", "포맷 안 된 디스크 (.d88) — 게임이 직접 포맷할 때"};
        new AppDialog.Builder(this).setTitle("빈 세이브 디스크 만들기 (2HD 1.2MB)")
                .setItems(kinds, (d, which) -> createPc98BlankDisk(file, which == 0)).setNegativeButton("취소", null).show();
    }

    private void createPc98BlankDisk(File file, boolean formatted) {
        File dir = file.getParentFile();
        String ext = formatted ? ".hdm" : ".d88";
        boolean group = file.getName().toLowerCase(Locale.ROOT).endsWith(".cmd");
        List<File> disks = group ? pc98CmdDisks(file) : new ArrayList<>(java.util.Collections.singletonList(file));
        if (disks.isEmpty()) {
            showError("이 게임에는 디스크를 더할 수 없어요.");
            return;
        }
        // Named like the game's disks when they are numbered ("Disk C" after A and B), so the
        // group takes it in; otherwise "(세이브 디스크 n)" in a group of its own.
        String base = file.getName().replaceAll("\\.[^.]+$", "");
        java.util.regex.Matcher last = PC98_SPLIT_DISK.matcher(splitSourceName(disks.get(disks.size() - 1)));
        File disk;
        boolean named = group && !pc98CmdAdded(file) && last.matches();
        if (named) {
            String label = last.group(2);
            int next = pc98DiskNumber(label) + 1;
            boolean letters = Character.isLetter(label.charAt(0));
            if (letters && next > 26) {
                named = false;
                disk = null;
            } else {
                String nextLabel = letters ? String.valueOf((char) ((Character.isUpperCase(label.charAt(0)) ? 'A' : 'a') + next - 1)) : String.valueOf(next);
                disk = new File(dir, last.group(1).trim() + " (Disk " + nextLabel + ")" + (last.group(3).trim().isEmpty() ? "" : " " + last.group(3).trim()) + ext);
            }
        } else {
            disk = null;
        }
        if (disk == null) {
            int n = 1;
            do {
                disk = new File(dir, base + " (세이브 디스크 " + n + ")" + ext);
                n++;
            } while (disk.exists());
        }
        if (disk.exists()) {
            showError("같은 이름의 디스크가 이미 있어요: " + disk.getName());
            return;
        }
        try (FileOutputStream out = new FileOutputStream(disk)) {
            if (formatted) {
                byte[] track = new byte[8 * 1024];
                Arrays.fill(track, (byte) 0xE5);
                for (int t = 0; t < 77 * 2; t++) out.write(track);
            } else {
                byte[] header = new byte[0x2B0];
                byte[] title = "MINI EMULATOR".getBytes(StandardCharsets.US_ASCII);
                System.arraycopy(title, 0, header, 0, title.length);
                header[0x1B] = 0x20;   // 2HD
                header[0x1C] = (byte) 0xB0;
                header[0x1D] = 0x02;   // disk size: the header alone
                out.write(header);
            }
        } catch (IOException e) {
            disk.delete();
            showError("빈 디스크를 만들지 못했어요: " + e.getMessage());
            return;
        }
        if (!named) {
            // A group of the game's disks and the new one, kept as it is from now on.
            List<File> all = new ArrayList<>(disks);
            all.add(disk);
            File cmd = group ? file : new File(dir, base + ".cmd");
            if (!group && cmd.exists()) {
                disk.delete();
                showError("같은 이름의 .cmd 파일이 이미 있어요: " + cmd.getName());
                return;
            }
            String text = pc98CmdText(all, true);
            if (text == null) {
                disk.delete();
                showError("디스크가 너무 많거나 이름이 길어서 묶을 수 없어요.");
                return;
            }
            try (FileOutputStream out = new FileOutputStream(cmd)) {
                out.write(text.getBytes(StandardCharsets.UTF_8));
            } catch (IOException e) {
                disk.delete();
                showError("디스크 묶음을 쓰지 못했어요: " + e.getMessage());
                return;
            }
        }
        refreshLibrary();
        showMessage(disk.getName() + "을(를) 만들었어요.\n게임 중 메뉴 → 디스크 바꾸기에서 드라이브(보통 FDD2)에 넣어 주세요."
                + (!group ? "\n원래 디스크와 새 디스크가 한 게임(.cmd)으로 묶였어요. 빠른 저장은 묶음 쪽에 따로 남아요." : ""));
    }

    static final String XBIOS_EXAMPLES_NAME = "XBIOS 예제 디스크.dsk";

    // ---- MSX games split over several disks ("Name (Disk 1 of 5).dsk" ...): one game ----
    // The disks are listed in an .m3u the app writes next to them; the list shows only it,
    // and the game's menu (디스크 바꾸기) moves to the next disk.
    private static final String MSX_PLAYLIST_MARK = "# Mini Emulator: split disks";
    private static final java.util.regex.Pattern MSX_SPLIT_DISK = java.util.regex.Pattern.compile(
            "^(.*?)\\s*[(\\[]\\s*(?:disk|disc|디스크)\\s*(\\d+)(?:\\s*(?:of|/)\\s*\\d+)?\\s*[)\\]](.*)\\.dsk$",
            java.util.regex.Pattern.CASE_INSENSITIVE);

    // Dreamcast games on several discs (0.0.303): "Name (Disc 1).gdi" ... (.gdi / .chd / .cdi),
    // grouped the same way; Flycast swaps them through its disk control.
    private static final java.util.regex.Pattern DC_SPLIT_DISK = java.util.regex.Pattern.compile(
            "^(.*?)\\s*[(\\[]\\s*(?:disk|disc|디스크)\\s*(\\d+)(?:\\s*(?:of|/)\\s*\\d+)?\\s*[)\\]](.*)\\.(?:gdi|chd|cdi|cue|iso|ccd|mds|gcm|rvz|wia|gcz|ciso|wbfs)$",
            java.util.regex.Pattern.CASE_INSENSITIVE);

    // Consoles whose games on several discs are grouped (0.0.303 Dreamcast; 0.0.314 PS1,
    // 세가 새턴, 메가CD, PC엔진 CD): their engines swap discs through libretro's disk control.
    static boolean discGroupMode(String mode) {
        return MODE_DC.equals(mode) || MODE_PS1.equals(mode) || MODE_SS.equals(mode) || MODE_MCD.equals(mode) || MODE_PCE.equals(mode)
                || MODE_GC.equals(mode);   // 0.0.315: Dolphin's libretro build reads .m3u and swaps discs
    }

    private static java.util.regex.Matcher splitDiskMatcher(String fileName) {
        java.util.regex.Matcher m = MSX_SPLIT_DISK.matcher(fileName);
        if (m.matches()) return m;
        m = DC_SPLIT_DISK.matcher(fileName);
        return m.matches() ? m : PC98_SPLIT_DISK.matcher(fileName);
    }

    // The game's name a split disk belongs to, or null.
    private static String msxSplitGameName(String fileName) {
        java.util.regex.Matcher m = splitDiskMatcher(fileName);
        if (!m.matches()) return null;
        String name = (m.group(1).trim() + " " + m.group(3).trim()).trim().replaceAll("\\s+", " ");
        return name.isEmpty() ? null : name;
    }

    private static int msxSplitNumber(String fileName) {
        java.util.regex.Matcher m = splitDiskMatcher(fileName);
        return m.matches() ? pc98DiskNumber(m.group(2)) : 0;
    }

    // A disc patched in the app stands in for the disc it was made from (patched_from).
    // Followed back to the first disc, through patches made on patched discs (Track 3, then
    // Track 6 on that).
    private String splitSourceName(File file) {
        String name = file.getName();
        for (int k = 0; k < 16; k++) {
            String from = romPrefs().getString("patched_from:" + name, null);
            if (from == null || from.equals(name) || msxSplitGameName(from) == null) {
                break;
            }
            name = from;
        }
        return name;
    }

    private int discRank(File disc) {
        if (!splitSourceName(disc).equals(disc.getName())) {
            return 2;   // patched in the app
        }
        String lower = disc.getName().toLowerCase(Locale.ROOT);
        return lower.endsWith(".gdi") || lower.endsWith(".cue") ? 1 : 0;   // unpacked: patchable as it is
    }

    private boolean isGroupedMsxDisk(File file) {
        String game = msxSplitGameName(splitSourceName(file));
        return game != null && !msxPlaylistDisks(new File(file.getParentFile(), game + ".m3u")).isEmpty();
    }

    // The disks of a playlist the app wrote (empty for anything else).
    static List<File> msxPlaylistDisks(File file) {
        List<File> disks = new ArrayList<>();
        if (file.getName().toLowerCase(Locale.ROOT).endsWith(".cmd")) {
            return pc98CmdDisks(file);
        }
        if (!file.getName().toLowerCase(Locale.ROOT).endsWith(".m3u") || !file.isFile() || file.length() > 16384) return disks;
        try (java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(new FileInputStream(file), StandardCharsets.UTF_8))) {
            String first = in.readLine();
            if (first == null || !first.startsWith(MSX_PLAYLIST_MARK)) return disks;
            String line;
            while ((line = in.readLine()) != null) {
                line = line.trim();
                if (!line.isEmpty() && !line.startsWith("#")) disks.add(new File(file.getParentFile(), line));
            }
        } catch (IOException e) {
            disks.clear();
        }
        return disks;
    }

    // Writes (or brings up to date) the playlists for the split disks in the MSX or Dreamcast
    // folder. For Dreamcast a disc patched in the app takes its original's place.
    private void groupSplitDisks(String mode) {
        File dir = romDirFor(mode);
        File[] files = dir.listFiles();
        if (files == null) return;
        boolean dc = discGroupMode(mode);   // discs of a CD-type console (not MSX disks)
        java.util.Set<String> made = new java.util.HashSet<>();
        Map<String, List<File>> games = new java.util.TreeMap<>();
        for (File file : files) {
            String name = file.getName();
            boolean ours = dc ? DC_SPLIT_DISK.matcher(splitSourceName(file)).matches() : MSX_SPLIT_DISK.matcher(name).matches();
            String game = ours && file.exists() ? msxSplitGameName(splitSourceName(file)) : null;
            if (game != null) {
                List<File> list = games.get(game);
                if (list == null) games.put(game, list = new ArrayList<>());
                list.add(file);
            }
        }
        for (Map.Entry<String, List<File>> entry : games.entrySet()) {
            List<File> disks = entry.getValue();
            if (dc) {
                // One file per disc: a patched one first, then one unpacked to GDI (it can be
                // patched without unpacking again), then the CHD / CDI; the newest of a kind.
                Map<Integer, File> byNumber = new java.util.TreeMap<>();
                for (File disk : disks) {
                    int number = msxSplitNumber(splitSourceName(disk));
                    File had = byNumber.get(number);
                    int rank = discRank(disk);
                    if (had == null || rank > discRank(had) || (rank == discRank(had) && disk.lastModified() > had.lastModified())) {
                        byNumber.put(number, disk);
                    }
                }
                disks = new ArrayList<>(byNumber.values());
            }
            File playlist = new File(dir, entry.getKey() + ".m3u");
            if (disks.size() < 2 || disks.size() > 10 || (playlist.exists() && msxPlaylistDisks(playlist).isEmpty())) {
                continue;  // one disk, more than the engine takes, or the player's own playlist
            }
            disks.sort((a, b) -> msxSplitNumber(splitSourceName(a)) != msxSplitNumber(splitSourceName(b))
                    ? Integer.compare(msxSplitNumber(splitSourceName(a)), msxSplitNumber(splitSourceName(b))) : a.getName().compareToIgnoreCase(b.getName()));
            StringBuilder text = new StringBuilder(MSX_PLAYLIST_MARK).append(" (").append(disks.size()).append(")\n");
            for (File disk : disks) text.append(disk.getName()).append('\n');
            made.add(playlist.getName());
            if (playlist.isFile() && text.toString().equals(readSmallTextFull(playlist))) continue;
            if (dc && playlist.isFile()) {
                // Other discs (a patched one) now: the scene saved with the old ones would come
                // back with their contents, so this game starts afresh once (in-game saves stay).
                settingsPrefs().edit().putBoolean("fresh_start:" + saveBaseNameFor(playlist), true).apply();
            }
            try (FileOutputStream out = new FileOutputStream(playlist)) {
                out.write(text.toString().getBytes(StandardCharsets.UTF_8));
            } catch (IOException ignored) {
            }
        }
        // Dreamcast: a playlist the app made for discs that now belong to another group (a
        // patched disc counted as its own game before 0.0.310) goes; its discs stay.
        if (dc) {
            for (File file : files) {
                String name = file.getName();
                if (name.toLowerCase(Locale.ROOT).endsWith(".m3u") && !made.contains(name) && !msxPlaylistDisks(file).isEmpty()) {
                    file.delete();
                }
            }
        }
    }

    private static String readSmallTextFull(File file) {
        try {
            return new String(java.nio.file.Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
        } catch (IOException | RuntimeException e) {
            return null;
        }
    }

    // Puts XBIOS's example disk into the MSX games (once; again when asked from the game menu).
    static boolean copyXbiosExamples(android.content.Context context, boolean force) {
        android.content.SharedPreferences prefs = sharedSettings(context);
        if (!force && prefs.getBoolean("msx_xbios_examples_added", false)) return true;
        File dir = new File(context.getFilesDir(), "roms_msx");
        File target = new File(dir, XBIOS_EXAMPLES_NAME);
        if (!dir.isDirectory() && !dir.mkdirs()) return false;
        try (ZipInputStream zip = new ZipInputStream(context.getAssets().open("msx_xbios.zip"))) {
            ZipEntry entry;
            while ((entry = zip.getNextEntry()) != null) {
                if (!"XBIOS/examples.dsk".equals(entry.getName())) continue;
                File part = new File(dir, XBIOS_EXAMPLES_NAME + ".part");
                try (FileOutputStream out = new FileOutputStream(part)) {
                    byte[] buffer = new byte[65536];
                    int n;
                    while ((n = zip.read(buffer)) > 0) out.write(buffer, 0, n);
                }
                if (!part.renameTo(target)) {
                    part.delete();
                    return false;
                }
                prefs.edit().putBoolean("msx_xbios_examples_added", true).apply();
                return true;
            }
        } catch (IOException e) {
            return false;
        }
        return false;
    }

    // Unpacks a zip from the assets into a system folder, again whenever the app version changes.
    private boolean unpackSystemAsset(String asset, File dir) {
        return unpackSystemAsset(asset, dir, new File(dir, ".mini_emulator_version"));
    }

    private boolean unpackSystemAsset(String asset, File dir, File marker) {
        String version;
        try {
            version = String.valueOf(getPackageManager().getPackageInfo(getPackageName(), 0).versionCode);
        } catch (Exception e) {
            version = "0";
        }
        if (marker.isFile() && version.equals(readSmallText(marker))) {
            return true;
        }
        try (ZipInputStream zip = new ZipInputStream(getAssets().open(asset))) {
            String root = dir.getCanonicalPath() + File.separator;
            ZipEntry entry;
            while ((entry = zip.getNextEntry()) != null) {
                File target = new File(dir, entry.getName());
                if (!target.getCanonicalPath().startsWith(root)) {
                    continue;
                }
                if (entry.isDirectory()) {
                    target.mkdirs();
                    continue;
                }
                File parent = target.getParentFile();
                if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                    return false;
                }
                try (FileOutputStream out = new FileOutputStream(target)) {
                    copy(zip, out);
                }
            }
            try (FileOutputStream out = new FileOutputStream(marker)) {
                out.write(version.getBytes(StandardCharsets.UTF_8));
            }
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    private static String readSmallText(File file) {
        byte[] data = readHead(file, (int) Math.min(file.length(), 64));
        return data == null ? "" : new String(data, StandardCharsets.UTF_8).trim();
    }

    // PCSX2 keeps PS2 memory cards in <system>/pcsx2/memcards (Mcd001.ps2 in slot 1,
    // Mcd002.ps2 in slot 2), shared by every PS2 game; a PS2 game's backup carries them.
    private File pcsx2MemcardDir() {
        return new File(new File(systemDir(), "pcsx2"), "memcards");
    }

    private List<File> pcsx2MemoryCardsFor(File rom) {
        List<File> cards = new ArrayList<>();
        if (!CORE_PCSX2.equals(coreFor(rom))) {
            return cards;
        }
        File[] files = pcsx2MemcardDir().listFiles(f -> f.isFile() && f.getName().toLowerCase(Locale.US).endsWith(".ps2"));
        if (files != null) {
            Arrays.sort(files);
            cards.addAll(Arrays.asList(files));
        }
        return cards;
    }

    private void startSaveExport(File file) {
        if (MODE_PS3.equals(modeForFile(file))) {
            ps3SaveExport(file);
            return;
        }
        migrateSaveFileIfNeeded(file);
        File saveFileFor = saveFileFor(file);
        File stateFileFor = stateFileFor(file);
        if (!saveFileFor.exists() && !stateFileFor.exists() && pcsx2MemoryCardsFor(file).isEmpty() && quickSaveFilesFor(file).length == 0) {
            showError("이 ROM의 세이브 파일이 없습니다.");
            return;
        }
        this.pendingSaveRom = file;
        this.pendingSaveFile = saveFileFor;
        if (android.os.Build.VERSION.SDK_INT >= 29) {
            // Straight into Download/Mini Emulator, no picker.
            exportSaveToDownloads(displayGameNameFor(file) + " 세이브 백업.zip");
            return;
        }
        Intent intent = new Intent("android.intent.action.CREATE_DOCUMENT");
        intent.addCategory("android.intent.category.OPENABLE");
        intent.setType("application/zip");
        intent.putExtra("android.intent.extra.TITLE", displayGameNameFor(file) + " 세이브 백업.zip");
        startActivityForResult(intent, 1002);
    }

    private void startSaveImport(File file) {
        if (MODE_PS3.equals(modeForFile(file))) {
            ps3SaveImport(file);
            return;
        }
        migrateSaveFileIfNeeded(file);
        this.pendingSaveRom = file;
        this.pendingSaveFile = saveFileFor(file);
        Intent intent = new Intent("android.intent.action.OPEN_DOCUMENT");
        intent.addCategory("android.intent.category.OPENABLE");
        intent.setType("*/*");
        if (android.os.Build.VERSION.SDK_INT >= 26) {
            // Open the picker in Download/Mini Emulator, where exports go.
            intent.putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI,
                    android.provider.DocumentsContract.buildDocumentUri("com.android.externalstorage.documents", "primary:" + Environment.DIRECTORY_DOWNLOADS + "/" + DOWNLOAD_FOLDER));
        }
        startActivityForResult(intent, 1003);
    }

    // Master System and Game Gear games used to sit in the Mega Drive mode; they have a mode
    // of their own now. Same engine, so their saves stay where they are.
    private void moveMasterSystemRoms() {
        File[] files = romDirFor(MODE_MD).listFiles((dir, name) -> {
            String lower = name.toLowerCase(Locale.US);
            return lower.endsWith(".sms") || lower.endsWith(".gg") || lower.endsWith(".sg");
        });
        if (files == null || files.length == 0) {
            return;
        }
        File target = romDirFor(MODE_SMS);
        if (!target.isDirectory() && !target.mkdirs()) {
            return;
        }
        for (File file : files) {
            File moved = new File(target, file.getName());
            if (!moved.exists()) {
                file.renameTo(moved);
            }
        }
    }

    // Save backups go to Download/Mini Emulator, which the app makes on first start.
    static final String DOWNLOAD_FOLDER = "Mini Emulator";

    @android.annotation.TargetApi(29)
    private Uri createDownload(String name, String mimeType) {
        android.content.ContentValues values = new android.content.ContentValues();
        values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME, name);
        values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE, mimeType);
        values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS + "/" + DOWNLOAD_FOLDER + "/");
        values.put(android.provider.MediaStore.MediaColumns.IS_PENDING, 1);
        return getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI, values);
    }

    @android.annotation.TargetApi(29)
    private void finishDownload(Uri uri) {
        android.content.ContentValues values = new android.content.ContentValues();
        values.put(android.provider.MediaStore.MediaColumns.IS_PENDING, 0);
        getContentResolver().update(uri, values, null, null);
    }

    // The name the file really got (Android adds " (1)" when the name is taken).
    private String downloadName(Uri uri, String fallback) {
        try (android.database.Cursor cursor = getContentResolver().query(uri, new String[]{android.provider.MediaStore.MediaColumns.DISPLAY_NAME}, null, null, null)) {
            if (cursor != null && cursor.moveToFirst() && cursor.getString(0) != null) {
                return cursor.getString(0);
            }
        } catch (RuntimeException ignored) {
            // Use the requested name.
        }
        return fallback;
    }

    @android.annotation.TargetApi(29)
    private void exportSaveToDownloads(String name) {
        Uri uri;
        try {
            uri = createDownload(name, "application/zip");
        } catch (RuntimeException e) {
            uri = null;
        }
        if (uri == null) {
            showError("세이브 내보내기 실패: 다운로드 폴더에 파일을 만들 수 없습니다");
            return;
        }
        if (exportSave(uri)) {
            finishDownload(uri);
            String saved = downloadName(uri, name);
            String cards = this.lastExportCards == 0 ? "" : "\nPS2 메모리카드 " + this.lastExportCards + "개(모든 PS2 게임 공용)도 들어 있어요.";
            showMessage("다운로드/" + DOWNLOAD_FOLDER + "/" + saved + "에 저장했어요." + cards);
        } else {
            getContentResolver().delete(uri, null, null);
        }
    }

    // Makes Download/Mini Emulator on first start: a folder only stays with a file in it,
    // so it gets a short note about what goes there.
    private void ensureDownloadFolder() {
        if (android.os.Build.VERSION.SDK_INT < 29 || settingsPrefs().getBoolean("download_folder_made", false)) {
            return;
        }
        new Thread(() -> {
            try {
                Uri uri = createDownload("안내.txt", "text/plain");
                if (uri == null) {
                    return;
                }
                try (OutputStream out = getContentResolver().openOutputStream(uri)) {
                    if (out != null) {
                        out.write(("Mini Emulator 세이브 백업 폴더\n\n"
                                + "ROM을 길게 눌러 \"세이브 내보내기\"를 하면 백업(.zip)이 이 폴더에 저장돼요.\n"
                                + "\"세이브 가져오기\"를 누르면 이 폴더가 먼저 열려요.\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));
                    }
                }
                finishDownload(uri);
                settingsPrefs().edit().putBoolean("download_folder_made", true).apply();
            } catch (IOException | RuntimeException ignored) {
                // Tried again next start.
            }
        }, "download-folder").start();
    }

    private int lastExportCards;

    // Writes the backup zip; true when it was written. Shows its own message unless the
    // file goes to the Download folder (the caller then says where).
    private boolean exportSave(Uri uri) {
        File file = this.pendingSaveRom;
        if (file == null) {
            showError("세이브 내보내기 실패: 선택된 세이브가 없습니다");
            return false;
        }
        File saveFileFor = saveFileFor(file);
        File stateFileFor = stateFileFor(this.pendingSaveRom);
        List<File> cards = pcsx2MemoryCardsFor(file);
        File[] quickSaves = quickSaveFilesFor(file);
        if (!saveFileFor.exists() && !stateFileFor.exists() && cards.isEmpty() && quickSaves.length == 0) {
            showError("세이브 내보내기 실패: 세이브 파일이 없습니다");
            return false;
        }
        try (OutputStream openOutputStream = getContentResolver().openOutputStream(uri);
             ZipOutputStream zipOutputStream = openOutputStream == null ? null : new ZipOutputStream(openOutputStream)) {
            if (zipOutputStream == null) {
                throw new IOException("저장할 위치를 열 수 없습니다");
            }
            if (saveFileFor.exists()) {
                writeZipEntry(zipOutputStream, saveFileFor, saveFileFor.getName());
            }
            if (stateFileFor.exists()) {
                writeZipEntry(zipOutputStream, stateFileFor, stateFileFor.getName());
            }
            for (File card : cards) {
                writeZipEntry(zipOutputStream, card, "memcards/" + card.getName());
            }
            for (File quick : quickSaves) {
                writeZipEntry(zipOutputStream, quick, "quicksaves/" + quick.getName());
            }
            this.lastExportCards = cards.size();
            if (android.os.Build.VERSION.SDK_INT < 29) {
                showMessage(cards.isEmpty() ? "세이브 백업을 내보냈습니다." : "세이브 백업을 내보냈습니다. PS2 메모리카드 " + cards.size() + "개(모든 PS2 게임 공용)도 들어 있어요.");
            }
            return true;
        } catch (IOException e) {
            showError("세이브 내보내기 실패: " + e.getMessage());
            return false;
        }
    }

    private void importSave(Uri uri) {
        File file = this.pendingSaveFile;
        if (file == null) {
            showError("세이브 가져오기 실패: 선택된 ROM이 없습니다");
            return;
        }
        File parentFile = file.getParentFile();
        if (parentFile != null && !parentFile.exists() && !parentFile.mkdirs()) {
            showError("세이브 가져오기 실패: 세이브 폴더를 만들 수 없습니다");
            return;
        }
        if (displayNameFor(uri).toLowerCase(Locale.US).endsWith(".zip")) {
            importSaveBackup(uri);
            return;
        }
        if (this.pendingSaveRom != null && CORE_PCSX2.equals(coreFor(this.pendingSaveRom)) && displayNameFor(uri).toLowerCase(Locale.US).endsWith(".ps2")) {
            importPcsx2MemoryCard(uri);
            return;
        }
        try (InputStream openInputStream = getContentResolver().openInputStream(uri);
             FileOutputStream fileOutputStream = new FileOutputStream(this.pendingSaveFile)) {
            if (openInputStream == null) {
                throw new IOException("선택한 세이브 파일을 열 수 없습니다");
            }
            copy(openInputStream, fileOutputStream);
            showMessage("게임 내 세이브를 가져왔습니다.");
            refreshLibrary();
        } catch (IOException e) {
            showError("세이브 가져오기 실패: " + e.getMessage());
        }
    }

    // A single .ps2 memory card goes into the slot it is named for (Mcd001.ps2 / Mcd002.ps2),
    // otherwise into slot 1; the card it replaces is kept as .bak.
    private void importPcsx2MemoryCard(Uri uri) {
        String name = displayNameFor(uri);
        File card = new File(pcsx2MemcardDir(), "Mcd002.ps2".equalsIgnoreCase(name) ? "Mcd002.ps2" : "Mcd001.ps2");
        File incoming = new File(pcsx2MemcardDir(), ".incoming");
        try {
            File dir = pcsx2MemcardDir();
            if (!dir.isDirectory() && !dir.mkdirs()) {
                throw new IOException("메모리카드 폴더를 만들 수 없습니다");
            }
            try (InputStream in = getContentResolver().openInputStream(uri);
                 FileOutputStream out = new FileOutputStream(incoming)) {
                if (in == null) {
                    throw new IOException("선택한 파일을 열 수 없습니다");
                }
                copy(in, out);
            }
            if (card.isFile()) {
                File old = new File(card.getPath() + ".bak");
                old.delete();
                card.renameTo(old);
            }
            if (!incoming.renameTo(card)) {
                throw new IOException("메모리카드를 저장할 수 없습니다");
            }
            showMessage("PS2 메모리카드를 " + (card.getName().startsWith("Mcd002") ? "2번" : "1번") + " 슬롯에 넣었어요 (모든 PS2 게임 공용, 이전 카드는 .bak으로 보관).");
        } catch (IOException e) {
            incoming.delete();
            showError("메모리카드 가져오기 실패: " + e.getMessage());
        }
    }

    private void importSaveBackup(Uri uri) {
        File file2 = this.pendingSaveRom;
        if (file2 == null) {
            showError("세이브 가져오기 실패: 선택된 ROM이 없습니다");
            return;
        }
        File saveFileFor = saveFileFor(file2);
        File stateFileFor = stateFileFor(this.pendingSaveRom);
        boolean pcsx2 = CORE_PCSX2.equals(coreFor(file2));
        int cards = 0;
        File quickDir = quickSaveDirFor(file2);
        boolean quickCleared = false;
        try (InputStream openInputStream = getContentResolver().openInputStream(uri);
             ZipInputStream zipInputStream = openInputStream == null ? null : new ZipInputStream(openInputStream)) {
            if (zipInputStream == null) {
                throw new IOException("선택한 백업 파일을 열 수 없습니다");
            }
            int i = 0;
            while (true) {
                ZipEntry nextEntry = zipInputStream.getNextEntry();
                if (nextEntry == null) {
                    break;
                }
                if (nextEntry.isDirectory()) {
                    continue;
                }
                String lowerCase = new File(nextEntry.getName()).getName().toLowerCase(Locale.US);
                File file;
                String entryName = nextEntry.getName().replace('\\', '/');
                if (entryName.startsWith("quicksaves/")) {
                    // The backup's quick save slots replace the game's.
                    file = isQuickSaveFileName(lowerCase) ? new File(quickDir, lowerCase) : null;
                    if (file != null && !quickCleared) {
                        deleteQuickSaves(quickDir);
                        quickCleared = true;
                    }
                } else if (lowerCase.endsWith(".sav")) {
                    file = saveFileFor;
                } else if (pcsx2 && lowerCase.endsWith(".ps2")) {
                    // A memory card is shared by all PS2 games: keep the one it replaces.
                    String name = new File(nextEntry.getName()).getName().replaceAll("[^A-Za-z0-9._ -]", "_");
                    file = new File(pcsx2MemcardDir(), name.startsWith(".") ? "_" + name : name);
                    if (file.isFile()) {
                        File old = new File(file.getPath() + ".bak");
                        old.delete();
                        if (!file.renameTo(old)) {
                            throw new IOException(file.getName() + " 메모리카드를 바꿀 수 없습니다");
                        }
                    }
                    cards++;
                } else {
                    file = lowerCase.endsWith(".state") ? stateFileFor : null;
                }
                if (file != null) {
                    File parentFile = file.getParentFile();
                    if (parentFile != null && !parentFile.exists() && !parentFile.mkdirs()) {
                        throw new IOException("세이브 폴더를 만들 수 없습니다");
                    }
                    try (FileOutputStream fileOutputStream = new FileOutputStream(file)) {
                        copy(zipInputStream, fileOutputStream);
                    }
                    i++;
                }
            }
            if (i == 0) {
                throw new IOException("백업 안에 .sav, .state" + (pcsx2 ? ", .ps2" : "") + " 파일이 없습니다");
            }
            showMessage(cards == 0 ? "세이브 백업을 가져왔습니다." : "세이브 백업을 가져왔습니다. PS2 메모리카드 " + cards + "개를 바꿨어요 (모든 PS2 게임 공용, 이전 카드는 .bak으로 보관).");
            refreshLibrary();
        } catch (IOException e) {
            showError("세이브 가져오기 실패: " + e.getMessage());
        }
    }

    private void confirmDeleteSave(final File file) {
        new AppDialog.Builder(this).setTitle("세이브를 삭제할까요?").setMessage("이 ROM의 .sav 파일과 빠른 저장 파일을 삭제합니다.").setNegativeButton(17039360, (DialogInterface.OnClickListener) null).setPositiveButton(17039370, (dialogInterface, i) -> deleteSave(file)).show();
    }

    private void deleteSave(File file) {
        migrateSaveFileIfNeeded(file);
        File saveFileFor = saveFileFor(file);
        File stateFileFor = stateFileFor(file);
        File quickDir = quickSaveDirFor(file);
        if (!saveFileFor.exists() && !stateFileFor.exists() && !quickDir.exists()) {
            showMessage("삭제할 세이브가 없습니다.");
            return;
        }
        deleteQuickSaves(quickDir);
        boolean z = !saveFileFor.exists() || saveFileFor.delete();
        boolean z2 = !stateFileFor.exists() || stateFileFor.delete();
        if (z && z2) {
            showMessage("세이브를 삭제했습니다.");
            refreshLibrary();
        } else {
            showError("세이브를 삭제할 수 없습니다.");
        }
    }

    private void toggleFavorite(File file) {
        boolean z = !isFavorite(file);
        romPrefs().edit().putBoolean("favorite:" + file.getName(), z).apply();
        showMessage(z ? "즐겨찾기에 추가했습니다." : "즐겨찾기에서 해제했습니다.");
        refreshLibrary();
    }

    private void renameGameAndSave(final File file) {
        final EditText editText = new EditText(this);
        editText.setSingleLine(true);
        editText.setInputType(8193);
        editText.setText(displayGameNameFor(file));
        editText.setSelectAllOnFocus(true);
        new AppDialog.Builder(this).setTitle("게임/세이브 이름").setView(editText).setNegativeButton(17039360, (DialogInterface.OnClickListener) null).setPositiveButton(17039370, (dialogInterface, i) -> applyRename(editText, file, dialogInterface, i)).show();
    }

    private void applyRename(EditText editText, File file, DialogInterface dialogInterface, int i) {
        String trim = editText.getText().toString().trim();
        String sanitizeSaveBaseName = sanitizeSaveBaseName(trim);
        if (trim.isEmpty()) {
            showError("이름을 비워둘 수 없습니다.");
            return;
        }
        File saveFileFor = saveFileFor(file);
        File stateFileFor = stateFileFor(file);
        // Saves live in a per-core folder; see saveFileFor().
        File file2 = new File(saveDir(), coreFor(file));
        File file3 = new File(file2, sanitizeSaveBaseName + ".sav");
        File file4 = new File(file2, sanitizeSaveBaseName + ".state");
        if ((!saveFileFor.equals(file3) && file3.exists()) || (!stateFileFor.equals(file4) && file4.exists())) {
            showError("같은 이름의 세이브가 이미 있습니다.");
            return;
        }
        File oldQuickDir = quickSaveDirFor(file);
        File newQuickDir = new File(new File(file2, "quicksaves"), sanitizeSaveBaseName);
        SharedPreferences.Editor edit = romPrefs().edit();
        edit.putString("title:" + file.getName(), trim);
        edit.putString("save:" + file.getName(), sanitizeSaveBaseName);
        edit.apply();
        migrateNamedSave(saveFileFor, file3);
        migrateNamedSave(stateFileFor, file4);
        if (!oldQuickDir.equals(newQuickDir) && oldQuickDir.isDirectory() && !newQuickDir.exists()) {
            oldQuickDir.renameTo(newQuickDir);
        }
        showMessage("세이브 이름: " + sanitizeSaveBaseName + ".sav");
        refreshLibrary();
    }

    private void migrateNamedSave(File file, File file2) {
        if (file.equals(file2) || !file.exists()) {
            return;
        }
        File parentFile = file2.getParentFile();
        if ((parentFile == null || parentFile.exists() || parentFile.mkdirs()) && !file.renameTo(file2) && copyFile(file, file2) && !file.delete()) {
            file.deleteOnExit();
        }
    }

    public int compareRomsForLibrary(File file, File file2) {
        boolean isFavorite = isFavorite(file);
        if (isFavorite != isFavorite(file2)) {
            return isFavorite ? -1 : 1;
        }
        long lastPlayedAt = lastPlayedAt(file);
        long lastPlayedAt2 = lastPlayedAt(file2);
        if (lastPlayedAt != lastPlayedAt2) {
            return Long.compare(lastPlayedAt2, lastPlayedAt);
        }
        return file.getName().toLowerCase(Locale.US).compareTo(file2.getName().toLowerCase(Locale.US));
    }

    private boolean isFavorite(File file) {
        return romPrefs().getBoolean("favorite:" + file.getName(), false);
    }

    private long lastPlayedAt(File file) {
        return romPrefs().getLong("recent:" + file.getName(), 0L);
    }

    private void markRecentlyPlayed(File file) {
        romPrefs().edit().putLong("recent:" + file.getName(), System.currentTimeMillis()).apply();
    }

    private String formatTimestamp(long j) {
        return new SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.US).format(new Date(j));
    }

