    // Saves a picked System Card BIOS as <system>/syscard3.pce. Dumps come with a 512-byte
    // copier header and padded to 384 KB at times; the card itself is the first 256 KB, which
    // must carry the "PC Engine CD-ROM SYSTEM" signature.
    private void importPceBios(Uri uri) {
        try (InputStream in = getContentResolver().openInputStream(uri)) {
            if (in == null) {
                throw new IOException("선택한 파일을 열 수 없습니다");
            }
            java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();
            byte[] chunk = new byte[65536];
            int n;
            while ((n = in.read(chunk)) > 0) {
                buffer.write(chunk, 0, n);
                if (buffer.size() > 4 * 1024 * 1024) {
                    throw new IOException("System Card BIOS가 아니에요 (파일이 너무 큼).");
                }
            }
            byte[] data = buffer.toByteArray();
            int start = data.length % 8192 == 512 ? 512 : 0;
            int length = Math.min(data.length - start, 262144);
            byte[] card = java.util.Arrays.copyOfRange(data, start, start + Math.max(0, length));
            if (card.length < 131072 || !new String(card, StandardCharsets.ISO_8859_1).contains("PC Engine CD-ROM SYSTEM")) {
                throw new IOException("System Card BIOS가 아니에요. 보통 syscard3.pce (256KB) 파일이에요.");
            }
            File dir = systemDir();
            if (!dir.isDirectory() && !dir.mkdirs()) {
                throw new IOException("BIOS 폴더를 만들 수 없습니다");
            }
            try (FileOutputStream out = new FileOutputStream(pceBiosFile())) {
                out.write(card);
            }
            String version = pceBiosVersion(card);
            showMessage("PC엔진 CD BIOS를 가져왔습니다" + (version != null ? ": " + version : "") + ".\nCD-ROM² 게임을 실행할 수 있어요.");
            updateHomeStatusCards();
        } catch (IOException e) {
            showError("PC엔진 CD BIOS 가져오기 실패: " + e.getMessage());
        }
    }



    // ---- Saturn BIOS (YabaSanshiro): <system>/saturn_bios.bin, 512 KB ----
    private File saturnBiosFile() {
        return new File(systemDir(), "saturn_bios.bin");
    }

    // Beetle Saturn's names: the Japanese BIOS and the North American / European one.
    static final String SS_BIOS_JP = "sega_101.bin";
    static final String SS_BIOS_US = "mpr-17933.bin";
    private static final java.util.Set<String> SS_BIOS_US_MD5 = new java.util.HashSet<>(java.util.Arrays.asList(
            "3240872c70984b6cbfda1586cab68dbe"));   // mpr-17933 (v1.00, NA / EU)

    private static String md5Of(byte[] data) {
        try {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("MD5");
            StringBuilder hex = new StringBuilder();
            for (byte b : md.digest(data)) hex.append(String.format(Locale.ROOT, "%02x", b & 0xFF));
            return hex.toString();
        } catch (java.security.NoSuchAlgorithmException e) {
            return "";
        }
    }

    // A BIOS file under the name of its region (a known NA/EU dump; anything else counts as
    // Japanese, the BIOS most Saturn players have). Returns the file written.
    private File storeSaturnRegionBios(byte[] data) throws IOException {
        File target = new File(systemDir(), SS_BIOS_US_MD5.contains(md5Of(data)) ? SS_BIOS_US : SS_BIOS_JP);
        try (FileOutputStream out = new FileOutputStream(target)) {
            out.write(data);
        }
        return target;
    }

    // A BIOS imported before 0.0.404 (saturn_bios.bin only) also under its region's name.
    private void syncSaturnRegionBios() {
        File bios = saturnBiosFile();
        if (!bios.isFile() || bios.length() != 524288) return;
        try {
            byte[] data = java.nio.file.Files.readAllBytes(bios.toPath());
            File target = new File(systemDir(), SS_BIOS_US_MD5.contains(md5Of(data)) ? SS_BIOS_US : SS_BIOS_JP);
            if (!target.isFile()) storeSaturnRegionBios(data);
        } catch (IOException | RuntimeException ignored) {
            // Beetle Saturn says so when it starts.
        }
    }

