    private void confirmVitaReinstall(File game, String id) {
        LinearLayout panel = new LinearLayout(this);
        final Dialog dialog = cardDialog(panel);
        cardHeader(panel, RoundIconView.RESET, Color.rgb(100, 116, 139), "게임 다시 설치", displayGameNameFor(game) + " (" + id + ")");
        panel.addView(noteBox("설치된 게임 파일을 지우고, 다음에 켤 때 원본 파일(" + game.getName() + ")에서 새로 설치해요. 한글패치(코드 패치 · 백업 포함)와 업데이트도 같이 지워져요 — 필요하면 다시 넣으세요.\n세이브와 DLC는 그대로예요.",
                Color.rgb(241, 245, 249), Color.rgb(51, 65, 85)), spaced(10));
        overlayConfirmButtons(panel, dialog, "지우고 다시 설치", Color.rgb(100, 116, 139), () -> {
            dialog.dismiss();
            final Dialog busy = progressCard(RoundIconView.RESET, Color.rgb(100, 116, 139), "지우는 중", id);
            new Thread(() -> {
                deleteTree(vitaAppDir(id));
                deleteTree(new File(vitaPrefDir(), "ux0/patch/" + id));
                vitaKoRecord(id).delete();
                deleteTree(vitaKoBackupDir(id));
                new File(vitaCodeDir(), id + ".txt").delete();
                new File(new File(vitaPrefDir(), "pkg_installed"), game.getName() + ".txt").delete();
                StringBuilder keep = new StringBuilder();
                for (String[] line : vitaAddonLines(id)) {
                    if ("ok".equals(line[0]) && !line[1].startsWith("gp")) {
                        keep.append(String.join(" ", line)).append('\n');
                    }
                }
                try (FileOutputStream out = new FileOutputStream(vitaAddonLog(id))) {
                    out.write(keep.toString().getBytes(StandardCharsets.UTF_8));
                } catch (IOException ignored) {
                }
                runOnUiThread(() -> {
                    busy.dismiss();
                    refreshLibrary();
                    Toast.makeText(this, "지웠어요 · 다음에 켤 때 새로 설치해요", Toast.LENGTH_LONG).show();
                });
            }, "vita-reinstall").start();
        });
        dialog.show();
    }

    private void onVitaFirmwarePicked(Intent data) {
        int k = this.pendingVitaFirmware;
        this.pendingVitaFirmware = -1;
        if (data == null || data.getData() == null || k < 0 || k >= VITA_FIRMWARE.length) {
            return;
        }
        final Uri uri = data.getData();
        final File target = new File(vitaPrefDir(), VITA_FIRMWARE[k][0]);
        Toast.makeText(this, "펌웨어 파일을 넣는 중…", Toast.LENGTH_SHORT).show();
        new Thread(() -> {
            String error = null;
            File part = new File(target.getParentFile(), target.getName() + ".part");
            try {
                target.getParentFile().mkdirs();
                copyUriToFile(uri, part);
                byte[] head = readHead(part, 4);
                // PUP files start with "SCEUF".
                if (head == null || head[0] != 'S' || head[1] != 'C' || head[2] != 'E' || head[3] != 'U') {
                    part.delete();
                    error = "PS Vita 펌웨어(.PUP) 파일이 아니에요.";
                } else if (!part.renameTo(target)) {
                    part.delete();
                    error = "파일을 넣지 못했어요.";
                }
            } catch (IOException e) {
                part.delete();
                error = "파일을 넣지 못했어요. 저장 공간을 확인해 주세요.";
            }
            final String why = error;
            runOnUiThread(() -> {
                if (why != null) {
                    showError(why);
                } else {
                    Toast.makeText(this, VITA_FIRMWARE[k][0] + "을(를) 넣었어요 · 게임을 처음 켤 때 설치돼요", Toast.LENGTH_LONG).show();
                }
                refreshLibrary();
                showVitaFirmwareSheet();
            });
        }, "vita-firmware").start();
    }

    private boolean cemuShipped() {
        return new File(getApplicationInfo().nativeLibraryDir, "libcemu_libretro_android.so").isFile();
    }

